+          active: this.favorited,
+          itemName: this.itemName
+        };
+        this.dispatchEvent(new CustomEvent('favorite-toggle', {
+          detail,
+          bubbles: true,
+          composed: true
+        }));
+        this.dispatchEvent(new CustomEvent('change', {
+          detail,
+          bubbles: true,
+          composed: true
+        }));
+        return this.favorited;
+      }
