+      };
+      timer = setTimeout(stop, 300);
+      submenu.addEventListener('pointermove', extend);
+      submenu.addEventListener('toggle', stop, { once: true });
+    }
+
+    // Submenu triggers & menu item interactions
+    const submenuTriggers = triggers.filter(t => !rootTriggers.includes(t));
+    let submenuPreviewTimer = null;
+
+    submenuTriggers.forEach(subTrigger => {
+      const submenu = menuFor(subTrigger);
+      const subGroup = submenu.querySelector('[focusgroup~="menu"]');
+
+      subTrigger.addEventListener('focus', () => {
+        if (windowBlurred || returningFromMenu === submenu) return;
+        clearTimeout(submenuPreviewTimer);
+        submenuPreviewTimer = setTimeout(() => {
+          if (document.activeElement === subTrigger && !isOpen(submenu)) {
+            previewedMenus.add(submenu);
+            showMenu(submenu, subTrigger);
+          }
+        }, 80);
+      });
+
+      subTrigger.addEventListener('blur', event => {
+        clearTimeout(submenuPreviewTimer);
+        if (previewedMenus.has(submenu) && !submenu.contains(event.relatedTarget)) {
+          previewedMenus.delete(submenu);
+          if (isOpen(submenu)) submenu.hidePopover();
+        }
+      });
+
+      subTrigger.addEventListener('pointerleave', event => {
+        startBridge(submenu, event);
+      });
+
+      subTrigger.addEventListener('keydown', event => {
+        if (event.key === 'ArrowRight') {
+          event.preventDefault();
+          event.stopPropagation();
+          if (!isOpen(submenu)) {
+            showMenu(submenu, subTrigger);
+          }
+          previewedMenus.delete(submenu);
+          getEnabledItems(subGroup)[0]?.focus({ preventScroll: true });
+        }
+      });
+    });
+
+    // Menu container keyboard, pointer, and command activation
+    document.querySelectorAll('[focusgroup~="menu"]').forEach(group => {
+      const popover = group.closest('[popover]');
+      const ownerTrigger = triggerFor(popover);
+      const isTopLevelMenu = rootTriggers.includes(ownerTrigger);
+      const rootMenu = isTopLevelMenu ? popover : popover.parentElement.closest('[popover]');
+      const rootTrigger = triggerFor(rootMenu);
+
+      group.addEventListener('pointermove', event => {
+        const item = event.target.closest('button, a[href]');
+        if (!item || item.closest('[focusgroup]') !== group) return;
+        const hit = document.elementFromPoint(event.clientX, event.clientY);
+        if (!hit || !item.contains(hit)) return;
+        if (document.activeElement !== item) {
+          item.focus({ preventScroll: true, focusVisible: false });
+        }
+      });
+
+      group.addEventListener('keydown', event => {
+        const activeItem = document.activeElement;
+        if (!activeItem || activeItem.closest('[focusgroup]') !== group) return;
+
+        if (event.key === 'Home' || event.key === 'End') {
+          event.preventDefault();
+          const items = getEnabledItems(group);
+          const target = event.key === 'Home' ? items[0] : items[items.length - 1];
+          target?.focus({ preventScroll: true });
+        } else if (event.key === 'Escape') {
+          event.preventDefault();
+          event.stopPropagation();
+          closeAndRestore(popover);
+        } else if (event.key === 'ArrowLeft') {
+          event.preventDefault();
+          event.stopPropagation();
+          if (isTopLevelMenu) {
+            moveToRootTrigger(ownerTrigger, -1);
+          } else {
+            closeAndRestore(popover);
+          }
+        } else if (event.key === 'ArrowRight') {
+          if (activeItem.hasAttribute('commandfor')) return; // Handled by submenu trigger listener
+          event.preventDefault();
+          event.stopPropagation();
+          moveToRootTrigger(rootTrigger, 1);
+        } else if (event.key === 'Tab') {
+          closeAllRootMenus();
+        } else if (event.key === ' ' && activeItem.getAttribute('role') === 'menuitemcheckbox') {
+          // Space on a checkbox toggles and stays open (APG)
+          event.preventDefault();
+          const checked = activeItem.getAttribute('aria-checked') === 'true';
+          activeItem.setAttribute('aria-checked', String(!checked));
+          if (announcer) announcer.textContent = `${activeItem.textContent.trim()} ${!checked ? 'checked' : 'unchecked'}`;
+        }
+      });
+
+      group.addEventListener('click', event => {
+        const item = event.target.closest('button:not([commandfor])');
+        if (!item || item.closest('[focusgroup]') !== group) return;
+        const fromPointer = event.detail !== 0;
+        const role = item.getAttribute('role');
+
+        if (role === 'menuitemcheckbox') {
+          const checked = item.getAttribute('aria-checked') === 'true';
+          item.setAttribute('aria-checked', String(!checked));
+          if (announcer) announcer.textContent = `${item.textContent.trim()} ${!checked ? 'checked' : 'unchecked'}`;
+          setTimeout(() => {
+            closeAndRestore(rootMenu, { fromPointer });
+          }, 300);
+        } else if (role === 'menuitemradio') {
+          const radioGroup = item.closest('[role="group"]');
+          radioGroup?.querySelectorAll('[role="menuitemradio"]').forEach(radio => {
+            radio.setAttribute('aria-checked', String(radio === item));
+          });
+          if (announcer) announcer.textContent = `${item.textContent.trim()} selected`;
+          setTimeout(() => {
+            closeAndRestore(rootMenu, { fromPointer });
+          }, 300);
+        } else {
+          if (announcer) announcer.textContent = `${item.textContent.trim()} activated`;
+          closeAndRestore(rootMenu, { fromPointer });
+        }
+      });
+    });
+
+    // Outside focus closes every open menu
+    document.addEventListener('focusin', event => {
+      if (!menubar.contains(event.target)) {
+        closeAllRootMenus();
+      }
+    });
+  </script>
 </body>

