+       * Formats an ISO 8601 plain calendar date string ("YYYY-MM-DD")
+       * purely via string parsing without constructing a Date object,
+       * preventing UTC-to-local midnight off-by-one day shifts across time zones.
+       */
+      function formatPlainDate(plainDateStr) {
+        if (!plainDateStr || typeof plainDateStr !== 'string') return '';
+        const parts = plainDateStr.trim().split('-');
+        if (parts.length !== 3) return plainDateStr;
+        const year = parts[0];
+        const monthIndex = parseInt(parts[1], 10) - 1;
+        const day = parseInt(parts[2], 10);
+        if (monthIndex < 0 || monthIndex > 11 || isNaN(day)) return plainDateStr;
+        return `${MONTHS[monthIndex]} ${day}, ${year} (${plainDateStr.trim()})`;
+      }
+
+      function renderSummary(plainTime, plainDate) {
+        displayTime.textContent = formatPlainTime(plainTime);
+        displayDate.textContent = formatPlainDate(plainDate);
+        displayTime.setAttribute('data-plain-time', plainTime);
+        displayDate.setAttribute('data-plain-date', plainDate);
+      }
+
+      function loadPreferences() {
+        let savedTime = DEFAULT_TIME;
+        let savedDate = DEFAULT_DATE;
+        try {
+          const storedTime = localStorage.getItem(STORAGE_KEY_TIME);
+          const storedDate = localStorage.getItem(STORAGE_KEY_DATE);
+          if (storedTime && /^\d{2}:\d{2}/.test(storedTime)) {
+            savedTime = storedTime.slice(0, 5);
+          }
+          if (storedDate && /^\d{4}-\d{2}-\d{2}$/.test(storedDate)) {
+            savedDate = storedDate;
+          }
+        } catch (e) {
+          // Ignore storage errors in restricted environments
+        }
+        timeInput.value = savedTime;
+        dateInput.value = savedDate;
+        renderSummary(savedTime, savedDate);
+      }
+
+      function savePreferences(plainTime, plainDate) {
+        try {
+          localStorage.setItem(STORAGE_KEY_TIME, plainTime);
+          localStorage.setItem(STORAGE_KEY_DATE, plainDate);
+        } catch (e) {
+          // Ignore storage errors
+        }
+        renderSummary(plainTime, plainDate);
+      }
+
+      // Live update as user changes inputs so it remains immediately synchronized
+      timeInput.addEventListener('change', function () {
+        if (timeInput.value) {
+          savePreferences(timeInput.value.slice(0, 5), dateInput.value);
+        }
+      });
+
+      dateInput.addEventListener('change', function () {
+        if (dateInput.value) {
+          savePreferences(timeInput.value.slice(0, 5), dateInput.value);
+        }
+      });
+
+      form.addEventListener('submit', function (event) {
+        event.preventDefault();
+        const plainTime = (timeInput.value || DEFAULT_TIME).slice(0, 5);
+        const plainDate = dateInput.value || DEFAULT_DATE;
+        savePreferences(plainTime, plainDate);
+        statusToast.style.display = 'block';
+        setTimeout(function () {
+          statusToast.style.display = 'none';
+        }, 3000);
+      });
+
+      loadPreferences();
+    })();
+  </script>
