+        const janMs = Date.UTC(year, 0, 1, 12, 0, 0);
+        const julMs = Date.UTC(year, 6, 1, 12, 0, 0);
+        const janOffset = getOffsetMinutes(janMs, timeZone);
+        const julOffset = getOffsetMinutes(julMs, timeZone);
