+        let shortName = '';
+        let longName = '';
+        try {
+          const shortParts = new Intl.DateTimeFormat('en-US', {
+            timeZone: timeZone,
+            timeZoneName: 'short'
+          }).formatToParts(new Date(epochMs));
+          const longParts = new Intl.DateTimeFormat('en-US', {
+            timeZone: timeZone,
+            timeZoneName: 'long'
+          }).formatToParts(new Date(epochMs));
+
+          const sPart = shortParts.find(function (p) { return p.type === 'timeZoneName'; });
+          const lPart = longParts.find(function (p) { return p.type === 'timeZoneName'; });
+          if (sPart) shortName = sPart.value;
+          if (lPart) longName = lPart.value;
+        } catch (e) {
+          shortName = formatUtcOffset(currentOffset);
+        }
+
+        return {
+          isDst: isDst,
+          observesDst: observesDst,
+          offsetMinutes: currentOffset,
+          offsetLabel: formatUtcOffset(currentOffset),
+          shortName: shortName,
+          longName: longName
+        };
+      }
+
+      /**
+       * Parse and validate a wall-clock date & time in the specified host timezone.
+       * Rejects non-existent local times during spring-forward DST transitions!
+       */
+      function resolveHostInstant(dateStr, timeStr, hostTz) {
+        if (!dateStr || !timeStr || !hostTz) {
+          return {
+            valid: false,
+            reason: 'Missing input: Please provide a valid event date, start time, and host timezone.'
+          };
+        }
+
+        const dateMatch = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr.trim());
+        const timeMatch = /^(\d{2}):(\d{2})(?::(\d{2}))?$/.exec(timeStr.trim());
+
+        if (!dateMatch || !timeMatch) {
+          return {
+            valid: false,
+            reason: 'Invalid format: Please enter a valid date (YYYY-MM-DD) and time (HH:MM).'
+          };
+        }
+
+        const year = parseInt(dateMatch[1], 10);
+        const month = parseInt(dateMatch[2], 10);
+        const day = parseInt(dateMatch[3], 10);
+        const hour = parseInt(timeMatch[1], 10);
+        const minute = parseInt(timeMatch[2], 10);
+
+        // Validate calendar date existence (e.g. Feb 30)
+        const testCal = new Date(Date.UTC(year, month - 1, day));
+        if (
+          testCal.getUTCFullYear() !== year ||
+          testCal.getUTCMonth() + 1 !== month ||
+          testCal.getUTCDate() !== day ||
+          hour < 0 || hour > 23 || minute < 0 || minute > 59
+        ) {
+          return {
+            valid: false,
+            reason: 'Invalid calendar date or time values provided.'
+          };
+        }
+
+        // Verify timezone identifier is supported
+        try {
+          new Intl.DateTimeFormat('en-US', { timeZone: hostTz });
+        } catch (err) {
+          return {
+            valid: false,
+            reason: 'Unsupported or invalid host timezone: ' + hostTz
+          };
+        }
+
+        const targetAsUtc = Date.UTC(year, month - 1, day, hour, minute, 0);
+
+        // Probe offsets around the target wall-clock time (-36h to +36h)
+        // to capture both before and after any DST transition.
+        const probeOffsets = [
+          -36 * 3600000,
+          -18 * 3600000,
+          -6 * 3600000,
+          0,
+          6 * 3600000,
+          18 * 3600000,
+          36 * 3600000
+        ];
+
+        const candidateInstants = [];
+        const seenInstants = new Set();
+
+        for (let i = 0; i < probeOffsets.length; i++) {
+          const probeEpoch = targetAsUtc + probeOffsets[i];
+          const offsetMin = getOffsetMinutes(probeEpoch, hostTz);
+          const candidateMs = targetAsUtc - offsetMin * 60000;
+
+          if (!seenInstants.has(candidateMs)) {
+            seenInstants.add(candidateMs);
+            const actual = getWallClockParts(candidateMs, hostTz);
+            if (
+              actual.year === year &&
+              actual.month === month &&
+              actual.day === day &&
+              actual.hour === hour &&
+              actual.minute === minute
+            ) {
+              candidateInstants.push(candidateMs);
+            }
+          }
+        }
+
+        // If no instant maps back to the requested local wall-clock time,
+        // the requested time falls inside a non-existent Daylight Saving Time spring-forward gap!
+        if (candidateInstants.length === 0) {
+          const beforeOffset = getOffsetMinutes(targetAsUtc - 6 * 3600000, hostTz);
+          const afterOffset = getOffsetMinutes(targetAsUtc + 6 * 3600000, hostTz);
+          return {
+            valid: false,
+            isDstGap: true,
+            reason:
+              'Invalid Local Time (Daylight Saving Time Transition): ' +
+              dateStr + ' ' + timeStr +
+              ' does not exist in ' + hostTz +
+              ' because clocks spring forward from ' +
+              formatUtcOffset(beforeOffset) + ' to ' + formatUtcOffset(afterOffset) +
+              '. Please choose a valid time outside the DST transition gap.'
+          };
+        }
+
+        candidateInstants.sort(function (a, b) { return a - b; });
+        const isAmbiguousOverlap = candidateInstants.length > 1;
+
+        return {
+          valid: true,
+          epochMs: candidateInstants[0],
+          isAmbiguousOverlap: isAmbiguousOverlap,
+          hostParts: { year: year, month: month, day: day, hour: hour, minute: minute }
+        };
+      }
+
+      /**
+       * Compute day difference (+1 day, -1 day, Same day) between target zone and host zone.
+       */
+      function getDayDifferenceLabel(hostParts, targetParts) {
+        const hostUtcMidnight = Date.UTC(hostParts.year, hostParts.month - 1, hostParts.day);
+        const targetUtcMidnight = Date.UTC(targetParts.year, targetParts.month - 1, targetParts.day);
+        const diffDays = Math.round((targetUtcMidnight - hostUtcMidnight) / 86400000);
+        if (diffDays === 0) return 'Same Day';
+        if (diffDays === 1) return '+1 Day (Next Day)';
+        if (diffDays === -1) return '-1 Day (Previous Day)';
+        return (diffDays > 0 ? '+' : '') + diffDays + ' Days';
+      }
+
+      /**
+       * Classify local hour for tasting suitability.
+       */
+      function getTastingWindowStatus(hour) {
+        if (hour >= 8 && hour < 18) {
+          return { label: 'Optimal Cupping Hours', className: 'status-optimal' };
+        }
+        if ((hour >= 6 && hour < 8) || (hour >= 18 && hour < 22)) {
+          return { label: 'Extended Roastery Hours', className: 'status-extended' };
+        }
+        return { label: 'Off-Hours / Night Roast', className: 'status-late' };
+      }
+
+      /**
+       * Render all timezone cards or DST validation error state in #grid.
+       */
+      function updateSchedule() {
+        const dateStr = dateInput.value;
+        const timeStr = timeInput.value;
+        const hostTz = hostTzSelect.value;
+
+        const resolution = resolveHostInstant(dateStr, timeStr, hostTz);
+
+        if (!resolution.valid) {
+          statusBanner.className = 'status-banner invalid';
+          statusMessage.textContent = resolution.reason;
+          utcDisplay.textContent = 'Invalid Time';
+
+          grid.innerHTML = '';
+          const errorCard = document.createElement('div');
+          errorCard.className = 'card error-card';
+          errorCard.setAttribute('data-status', 'invalid-time');
+          errorCard.innerHTML =
+            '<h3>Invalid Time Selected — Daylight Saving Transition Conflict</h3>' +
+            '<p style="margin-top: 8px;">' + resolution.reason + '</p>';
+          grid.appendChild(errorCard);
+          return;
+        }
+
+        const epochMs = resolution.epochMs;
+        const hostDst = getDstInfo(epochMs, hostTz);
+
+        // Format UTC reference time
+        const utcFormatter = new Intl.DateTimeFormat('en-US', {
+          timeZone: 'UTC',
+          year: 'numeric',
+          month: 'short',
+          day: '2-digit',
+          hour: '2-digit',
+          minute: '2-digit',
+          hourCycle: 'h23'
+        });
+        utcDisplay.textContent = 'UTC: ' + utcFormatter.format(new Date(epochMs));
+
+        statusBanner.className = 'status-banner valid';
+        let statusText =
+          'Host Session: ' + dateStr + ' at ' + timeStr + ' (' + hostTz + ', ' +
