+          zonesToRender.unshift({
+            city: cityLabel,
+            region: 'Host Region',
+            tz: hostTz,
+            roastery: 'Host Cupping Headquarters',
+            bean: 'Signature Host Flight'
+          });
+        }
+
+        grid.innerHTML = '';
+
+        zonesToRender.forEach(function (zone) {
+          const isHost = zone.tz === hostTz;
+          const parts = getWallClockParts(epochMs, zone.tz);
