+            day: 'numeric',
+            year: 'numeric'
+          }).format(new Date(epochMs));
+
+          const diffFromHostMin = dstInfo.offsetMinutes - hostDst.offsetMinutes;
+          const diffSign = diffFromHostMin >= 0 ? '+' : '-';
+          const diffAbsHrs = Math.floor(Math.abs(diffFromHostMin) / 60);
+          const diffAbsMins = Math.abs(diffFromHostMin) % 60;
+          const relOffsetLabel = isHost
+            ? 'Host Timezone (0h)'
+            : diffSign + diffAbsHrs + (diffAbsMins ? ':' + String(diffAbsMins).padStart(2, '0') : '') + 'h vs Host';
+
+          const dstBadgeText = dstInfo.isDst
+            ? 'DST Active'
+            : (dstInfo.observesDst ? 'Standard Time' : 'No DST');
+          const dstBadgeClass = dstInfo.isDst ? 'badge-dst' : 'badge-std';
+
+          const card = document.createElement('article');
+          card.className = 'card' + (isHost ? ' is-host' : '');
