+          card.setAttribute('data-city', zone.city);
+          card.setAttribute('data-dst', dstInfo.isDst ? 'true' : 'false');
+
+          card.innerHTML =
+            '<div>' +
+              '<div class="card-top">' +
+                '<div class="city-info">' +
+                  '<h3>' + zone.city + ' <span style="font-weight:400; font-size:0.85rem; color:var(--text-muted);">(' + zone.region + ')</span></h3>' +
+                  '<div class="tz-identifier">' + zone.tz + ' • ' + dstInfo.offsetLabel + '</div>' +
+                '</div>' +
+                '<div class="badge-group">' +
+                  (isHost ? '<span class="badge badge-host">Host</span>' : '') +
+                  '<span class="badge ' + dstBadgeClass + '">' + dstBadgeText + '</span>' +
+                '</div>' +
+              '</div>' +
+              '<div class="converted-time" data-time-24="' + timeFormatted24 + '">' +
+                timeFormatted24 + ' <span style="font-size: 1.05rem; font-weight: 500; color: var(--text-muted);">(' + timeFormatted12 + ')</span>' +
+              '</div>' +
+              '<div class="converted-date">' +
