+
+      // Quick preset buttons for convenient testing of summer/winter/DST transitions
+      const presetSummerBtn = document.getElementById('presetSummerBtn');
+      const presetWinterBtn = document.getElementById('presetWinterBtn');
+      const presetSpringGapBtn = document.getElementById('presetSpringGapBtn');
+
+      if (presetSummerBtn) {
+        presetSummerBtn.addEventListener('click', function () {
