+
+let wasmPromise = null;
+
+function getWasm() {
+  if (!wasmPromise) {
+    wasmPromise = initSmallpt();
+  }
+  return wasmPromise;
+}
+
+self.addEventListener('message', async (event) => {
+  const { width = 320, height = 240, samples = 16, seed = 0, colors = null, reset = false, requestId = 0 } = event.data || {};
+  const startTime = performance.now();
+
+  try {
+    const wasm = await getWasm();
