+      const statTime = document.getElementById('stat-time');
+      const progressFill = document.getElementById('progress-fill');
+      const randomizeBtn = document.getElementById('randomize-btn');
+      const resetBtn = document.getElementById('reset-btn');
+      const resolutionSelect = document.getElementById('resolution-select');
+      const passesRange = document.getElementById('passes-range');
+      const passesLabel = document.getElementById('passes-label');
+      const spheresList = document.getElementById('spheres-list');
+
+      const SPHERE_METADATA = [
+        { idx: 0, name: 'Left Wall (DIFF)' },
+        { idx: 1, name: 'Right Wall (DIFF)' },
+        { idx: 2, name: 'Back Wall (DIFF)' },
+        { idx: 4, name: 'Floor (DIFF)' },
+        { idx: 5, name: 'Ceiling (DIFF)' },
+        { idx: 6, name: 'Mirror Sphere (SPEC)' },
+        { idx: 7, name: 'Glass Sphere (REFR)' },
+        { idx: 8, name: 'Area Light (DIFF)' }
