+
+      let wasmReady = false;
+      let renderJobId = 0;
+      let width = 320;
+      let height = 240;
+      let targetPasses = 4;
+
+      function toCssRgb(r, g, b) {
+        const ir = Math.min(255, Math.max(0, Math.round(Math.pow(Math.max(0, Math.min(1, r)), 1 / 2.2) * 255)));
+        const ig = Math.min(255, Math.max(0, Math.round(Math.pow(Math.max(0, Math.min(1, g)), 1 / 2.2) * 255)));
+        const ib = Math.min(255, Math.max(0, Math.round(Math.pow(Math.max(0, Math.min(1, b)), 1 / 2.2) * 255)));
+        return `rgb(${ir}, ${ig}, ${ib})`;
+      }
+
+      function updateSphereSwatches() {
+        if (!wasmReady) return;
+        spheresList.innerHTML = '';
+        for (const item of SPHERE_METADATA) {
+          let r = Module._get_sphere_color_r(item.idx);
+          let g = Module._get_sphere_color_g(item.idx);
+          let b = Module._get_sphere_color_b(item.idx);
+          const isLight = item.idx === 8;
+          const cssColor = isLight ? '#ffffff' : toCssRgb(r, g, b);
+          const rgbText = isLight
+            ? 'Emit (400, 400, 400)'
+            : `(${r.toFixed(2)}, ${g.toFixed(2)}, ${b.toFixed(2)})`;
+
+          const chip = document.createElement('div');
+          chip.className = 'sphere-chip';
+          chip.innerHTML = `
