+        canvas.height = height;
+        statRes.innerHTML = `${width} &times; ${height}`;
+      }
+
+      function startRender(resetBuffer = true) {
+        if (!wasmReady) return;
+        renderJobId++;
+        const currentJob = renderJobId;
+
+        parseResolution();
+        targetPasses = parseInt(passesRange.value, 10) || 4;
+        if (resetBuffer) {
+          Module._init_buffer(width, height);
