+        let completedPasses = 0;
+        let totalElapsedMs = 0;
+        const baseSeed = Math.floor(Math.random() * 1000000) + 1;
+
+        function runNextPass() {
+          if (currentJob !== renderJobId) return;
+
+          const t0 = performance.now();
+          const sampsPerSubpixel = 1; // 4 samples per pixel per pass (2x2 subpixels)
+          const ptr = Module._render_pass(width, height, sampsPerSubpixel, baseSeed + completedPasses * 31);
+          const elapsed = performance.now() - t0;
+          totalElapsedMs += elapsed;
+          completedPasses++;
