+<script>
+  interface CommandEventInit extends EventInit {
+    source?: Element | null;
+    command?: string;
+  }
+
+  // Fallback for Invoker Commands API (commandfor / command attributes)
+  if (!('CommandEvent' in globalThis)) {
+    class CustomCommandEvent extends Event {
+      source: Element | null;
+      command: string;
+      constructor(type: string, { source = null, command = '', ...options }: CommandEventInit = {}) {
+        super(type, options);
+        this.source = source;
+        this.command = command;
+      }
+    }
+    (globalThis as unknown as { CommandEvent: typeof CustomCommandEvent }).CommandEvent = CustomCommandEvent;
+
+    document.addEventListener('click', (event) => {
+      const button = event
+        .composedPath()
+        .find((el): el is HTMLButtonElement => el instanceof HTMLElement && el.matches('button[commandfor]'));
+      if (!button) return;
+
+      const targetId = button.getAttribute('commandfor');
+      const command = button.getAttribute('command');
+      const target = targetId ? document.getElementById(targetId) : null;
+
+      if (target && command) {
+        target.dispatchEvent(new CustomCommandEvent('command', { command, source: button }));
+      }
+    });
+  }
+
+  function setupSmallptTracer() {
+    const container = document.getElementById('smallpt-tracer');
+    const canvas = document.getElementById('smallpt-canvas') as HTMLCanvasElement | null;
+    if (!container || !canvas || container.dataset.initialized === 'true') return;
+    container.dataset.initialized = 'true';
+
+    const ctx = canvas.getContext('2d');
+    const statusText = document.getElementById('smallpt-status-text');
+    const statsBadge = document.getElementById('smallpt-render-stats');
+    const statusDot = document.getElementById('smallpt-status-dot');
+    const renderCountEl = document.getElementById('smallpt-render-count');
+    const samplesSelect = document.getElementById('smallpt-samples') as HTMLSelectElement | null;
+    const actionButtons = container.querySelectorAll<HTMLButtonElement>('button[commandfor="smallpt-tracer"]');
+
+    const worker = new Worker(new URL('../wasm/smallpt.worker.ts', import.meta.url), {
+      type: 'module',
+    });
+
+    let isRendering = false;
+    let requestId = 0;
+    let renderCount = 0;
+
+    function setButtonsBusy(busy: boolean) {
+      isRendering = busy;
+      actionButtons.forEach((btn) => {
+        btn.setAttribute('aria-disabled', busy ? 'true' : 'false');
+      });
+      if (statusDot) {
+        statusDot.classList.toggle('animate-ping', busy);
+      }
+    }
+
+    function updateSwatches(colors: string[]) {
+      if (!Array.isArray(colors)) return;
+      colors.forEach((hex, index) => {
+        const swatch = container?.querySelector<HTMLElement>(`[data-swatch="${index}"]`);
+        if (swatch) {
+          swatch.style.backgroundColor = hex;
+        }
+      });
+    }
+
+    function triggerRender(mode: 'render' | 'randomize' | 'reset') {
+      if (isRendering) return;
+      const width = canvas!.width;
+      const height = canvas!.height;
+      const samples = Number(samplesSelect?.value || 1);
+      requestId += 1;
+
+      // Update UI synchronously before offloading to Web Worker
+      setButtonsBusy(true);
+      if (statusText) {
+        statusText.textContent =
+          mode === 'randomize'
+            ? 'Tracing scene with randomized sphere colors...'
+            : 'Tracing scene in WebAssembly worker...';
+      }
+      if (statsBadge) {
+        statsBadge.textContent = `Rendering (${samples * 4} spp)...`;
+      }
+
+      worker.postMessage({
+        type: mode,
+        width,
+        height,
+        samples,
+        seed: (Date.now() ^ (requestId * 2654435761)) >>> 0,
+        requestId,
+      });
+    }
+
+    worker.addEventListener('message', (event: MessageEvent) => {
+      const data = event.data;
+      if (!data) return;
+
+      if (data.type === 'rendered' && ctx) {
+        const { pixels, width, height, samplesPerPixel, durationMs, sphereColors } = data;
+        const clamped =
+          pixels instanceof Uint8ClampedArray ? pixels : new Uint8ClampedArray(pixels);
+        const imageData = new ImageData(clamped, width, height);
+        ctx.putImageData(imageData, 0, 0);
+
+        renderCount += 1;
+        updateSwatches(sphereColors);
+        setButtonsBusy(false);
+
+        if (statusText) {
+          statusText.textContent = `Rendered ${width}×${height} path-traced frame in ${durationMs} ms`;
+        }
+        if (statsBadge) {
+          statsBadge.textContent = `${width}×${height} • ${samplesPerPixel} spp • ${durationMs} ms`;
+        }
+        if (renderCountEl) {
+          renderCountEl.textContent = `Pass #${renderCount}`;
+        }
+        canvas.dataset.renderCount = String(renderCount);
+      } else if (data.type === 'error') {
+        setButtonsBusy(false);
+        if (statusText) {
+          statusText.textContent = `Render error: ${data.message}`;
+        }
+      }
+    });
+
+    const commandRegistry: Record<string, () => void> = {
+      '--randomize-colors': () => triggerRender('randomize'),
+      '--reset-colors': () => triggerRender('reset'),
+    };
+
+    container.addEventListener('command', (event: Event) => {
+      const cmdEvent = event as Event & { command?: string };
+      const action = cmdEvent.command ? commandRegistry[cmdEvent.command] : undefined;
+      if (action) {
+        action();
+      }
+    });
+
+    samplesSelect?.addEventListener('change', () => {
+      triggerRender('render');
+    });
+
+    // Run initial path trace immediately on load
+    triggerRender('render');
+  }
+
+  setupSmallptTracer();
+  document.addEventListener('astro:page-load', setupSmallptTracer);
+</script>
