+
+interface SmallptModule {
+  _render_frame(outPtr: number, width: number, height: number, samps: number): void;
+  _randomize_colors(seed: number): void;
+  _reset_colors(): void;
+  _get_sphere_colors(outRgbPtr: number): void;
+  _malloc(size: number): number;
+  _free(ptr: number): void;
+  HEAPU8: Uint8Array;
+  HEAPF64: Float64Array;
+}
+
+let wasmPromise: Promise<SmallptModule> | null = null;
+
+function getWasm(): Promise<SmallptModule> {
+  if (!wasmPromise) {
+    wasmPromise = initSmallpt() as Promise<SmallptModule>;
+  }
+  return wasmPromise;
+}
+
+function readSphereColors(wasm: SmallptModule): string[] {
+  const count = 9 * 3;
+  const ptr = wasm._malloc(count * 8);
+  try {
+    wasm._get_sphere_colors(ptr);
+    const start = ptr >> 3;
+    const raw = wasm.HEAPF64.subarray(start, start + count);
+    const hexColors: string[] = [];
+    for (let i = 0; i < 9; i++) {
+      const r = Math.round(Math.pow(Math.min(1, Math.max(0, raw[i * 3])), 1 / 2.2) * 255);
+      const g = Math.round(Math.pow(Math.min(1, Math.max(0, raw[i * 3 + 1])), 1 / 2.2) * 255);
+      const b = Math.round(Math.pow(Math.min(1, Math.max(0, raw[i * 3 + 2])), 1 / 2.2) * 255);
+      hexColors.push(
+        `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`,
+      );
+    }
+    return hexColors;
+  } finally {
+    wasm._free(ptr);
+  }
+}
+
+self.addEventListener('message', async (event: MessageEvent) => {
+  const {
+    type = 'render',
+    width = 320,
+    height = 240,
+    samples = 1,
+    seed = Date.now(),
+    requestId = 0,
+  } = event.data || {};
+
+  try {
+    const wasm = await getWasm();
+
+    if (type === 'randomize') {
+      wasm._randomize_colors(seed >>> 0);
+    } else if (type === 'reset') {
+      wasm._reset_colors();
+    }
+
+    const sphereColors = readSphereColors(wasm);
+    const byteLength = width * height * 4;
+    const ptr = wasm._malloc(byteLength);
+
+    try {
+      const startTime = performance.now();
+      wasm._render_frame(ptr, width, height, samples);
+      const durationMs = Math.round(performance.now() - startTime);
+
+      const pixels = new Uint8ClampedArray(
+        wasm.HEAPU8.buffer,
+        ptr,
+        byteLength,
+      ).slice();
+
+      self.postMessage(
+        {
+          type: 'rendered',
+          requestId,
+          pixels,
+          width,
+          height,
+          samplesPerPixel: samples * 4,
+          durationMs,
+          sphereColors,
+        },
+        [pixels.buffer],
+      );
+    } finally {
+      wasm._free(ptr);
+    }
+  } catch (error) {
+    self.postMessage({
+      type: 'error',
+      requestId,
+      message: error instanceof Error ? error.message : String(error),
+    });
