+        bubbles: true,
+        composed: true,
+        detail: { card: this },
+      })
+    );
+  }
+
+  adoptedCallback(oldDocument, newDocument) {
+    this._render();
+    this.dispatchEvent(
+      new CustomEvent('coffee-card-adopted', {
+        bubbles: true,
+        composed: true,
+        detail: { oldDocument, newDocument, card: this },
+      })
+    );
+  }
+
+  attributeChangedCallback(name, oldValue, newValue) {
+    if (oldValue === newValue) {
+      return;
+    }
+    this._render();
+    if (this._isConnected) {
+      this.dispatchEvent(
+        new CustomEvent('coffee-card-change', {
+          bubbles: true,
+          composed: true,
+          detail: { attribute: name, oldValue, newValue, card: this },
+        })
+      );
+    }
+  }
+
+  // =========================================================================
+  // String Attribute / Property Reflection
+  // =========================================================================
+
+  get name() {
+    return this.getAttribute('name') ?? '';
+  }
+
+  set name(value) {
+    this._reflectStringAttribute('name', value);
+  }
+
+  get description() {
+    return this.getAttribute('description') ?? '';
+  }
+
+  set description(value) {
+    this._reflectStringAttribute('description', value);
+  }
+
+  get href() {
+    return this.getAttribute('href') ?? '#';
+  }
+
+  set href(value) {
+    this._reflectStringAttribute('href', value);
+  }
+
+  get roast() {
+    return this.getAttribute('roast') ?? '';
+  }
+
+  set roast(value) {
+    this._reflectStringAttribute('roast', value);
+  }
+
+  get image() {
+    return this.getAttribute('image') ?? '';
+  }
+
+  set image(value) {
+    this._reflectStringAttribute('image', value);
+  }
+
+  get ctaText() {
+    return this.getAttribute('cta-text') || 'View Details';
+  }
+
+  set ctaText(value) {
+    this._reflectStringAttribute('cta-text', value);
+  }
+
+  // =========================================================================
+  // Numeric Attribute / Property Reflection
+  // =========================================================================
+
+  get price() {
+    return this._readNumericAttribute('price', 0);
+  }
+
+  set price(value) {
+    this._reflectNumericAttribute('price', value);
+  }
+
+  get intensity() {
+    return this._readNumericAttribute('intensity', 0);
+  }
+
+  set intensity(value) {
+    if (value === null || value === undefined || value === '') {
+      this.removeAttribute('intensity');
+      return;
+    }
+    const num = Number(value);
+    if (Number.isNaN(num)) {
+      this.removeAttribute('intensity');
+      return;
+    }
+    const clamped = Math.max(0, Math.min(5, Math.round(num)));
+    this.setAttribute('intensity', String(clamped));
+  }
+
+  get caffeine() {
+    return this._readNumericAttribute('caffeine', 0);
+  }
+
+  set caffeine(value) {
+    this._reflectNumericAttribute('caffeine', value);
+  }
+
+  get calories() {
+    return this._readNumericAttribute('calories', 0);
+  }
+
+  set calories(value) {
+    this._reflectNumericAttribute('calories', value);
+  }
+
+  // =========================================================================
+  // Boolean Attribute / Property Reflection
+  // =========================================================================
+
+  get featured() {
+    return this.hasAttribute('featured');
+  }
+
+  set featured(value) {
+    this.toggleAttribute('featured', Boolean(value));
+  }
+
+  get seasonal() {
+    return this.hasAttribute('seasonal');
+  }
+
+  set seasonal(value) {
+    this.toggleAttribute('seasonal', Boolean(value));
+  }
+
+  get iced() {
+    return this.hasAttribute('iced');
+  }
+
+  set iced(value) {
+    this.toggleAttribute('iced', Boolean(value));
+  }
+
+  get organic() {
+    return this.hasAttribute('organic');
+  }
+
+  set organic(value) {
+    this.toggleAttribute('organic', Boolean(value));
+  }
+
+  get soldOut() {
+    return this.hasAttribute('sold-out');
+  }
+
+  set soldOut(value) {
+    this.toggleAttribute('sold-out', Boolean(value));
+  }
+
+  // =========================================================================
+  // Internal Reflection & Lifecycle Helpers
+  // =========================================================================
+
+  _upgradeProperty(prop) {
+    if (Object.prototype.hasOwnProperty.call(this, prop)) {
+      const value = this[prop];
+      delete this[prop];
+      this[prop] = value;
+    }
+  }
+
+  _reflectStringAttribute(attrName, value) {
+    if (value === null || value === undefined) {
+      this.removeAttribute(attrName);
+    } else {
+      this.setAttribute(attrName, String(value));
+    }
+  }
+
+  _readNumericAttribute(attrName, fallback = 0) {
+    if (!this.hasAttribute(attrName)) {
+      return fallback;
+    }
+    const raw = this.getAttribute(attrName);
+    if (raw === null || raw.trim() === '') {
+      return fallback;
+    }
+    const parsed = Number(raw);
+    return Number.isFinite(parsed) ? parsed : fallback;
+  }
+
+  _reflectNumericAttribute(attrName, value) {
+    if (value === null || value === undefined || value === '') {
+      this.removeAttribute(attrName);
+      return;
+    }
+    const parsed = Number(value);
+    if (!Number.isFinite(parsed)) {
+      this.removeAttribute(attrName);
+      return;
+    }
+    this.setAttribute(attrName, String(parsed));
+  }
+
+  _setupListeners() {
+    this._teardownListeners();
+    this._abortController = new AbortController();
+    const { signal } = this._abortController;
+
+    this._els.ctaButton.addEventListener(
+      'click',
+      (event) => {
+        if (this.soldOut) {
+          event.preventDefault();
+          return;
+        }
+        const selectEvent = new CustomEvent('coffee-select', {
+          bubbles: true,
+          composed: true,
+          cancelable: true,
+          detail: {
+            name: this.name,
+            price: this.price,
+            roast: this.roast,
+            intensity: this.intensity,
+            caffeine: this.caffeine,
+            calories: this.calories,
+            featured: this.featured,
+            seasonal: this.seasonal,
+            iced: this.iced,
+            organic: this.organic,
+            soldOut: this.soldOut,
+            href: this.href,
+          },
+        });
+        const proceed = this.dispatchEvent(selectEvent);
+        if (!proceed) {
+          event.preventDefault();
+        }
+      },
+      { signal }
+    );
+  }
+
+  _teardownListeners() {
+    if (this._abortController) {
+      this._abortController.abort();
+      this._abortController = null;
+    }
+  }
+
+  _render() {
+    if (!this._els) return;
+
+    // 1. String attributes
+    const name = this.name;
+    const description = this.description;
+    const href = this.href;
+    const roast = this.roast;
+    const image = this.image;
+    const ctaText = this.ctaText;
+
+    this._els.title.textContent = name;
+    this._els.description.textContent = description;
+
+    if (roast) {
+      this._els.roastLabel.textContent = roast;
+      this._els.roastLabel.hidden = false;
+    } else {
+      this._els.roastLabel.textContent = '';
+      this._els.roastLabel.hidden = true;
+    }
+
+    if (image) {
+      this._els.image.src = image;
+      this._els.image.alt = name || 'Coffee image';
+      this._els.mediaWrapper.hidden = false;
+    } else {
+      this._els.image.removeAttribute('src');
+      this._els.image.alt = '';
+      this._els.mediaWrapper.hidden = true;
+    }
+
+    // 2. Numeric attributes
+    const hasPrice = this.hasAttribute('price') && this.price > 0;
+    if (hasPrice) {
+      this._els.priceTag.textContent = `$${this.price.toFixed(2)}`;
+      this._els.priceTag.hidden = false;
+    } else {
+      this._els.priceTag.textContent = '';
+      this._els.priceTag.hidden = true;
+    }
+
+    const intensity = Math.max(0, Math.min(5, Math.round(this.intensity)));
+    const hasIntensity = this.hasAttribute('intensity') && intensity > 0;
+    if (hasIntensity) {
+      this._els.intensityDots.innerHTML = '';
+      for (let i = 1; i <= 5; i++) {
+        const dot = document.createElement('span');
+        dot.className = i <= intensity ? 'dot filled' : 'dot';
+        this._els.intensityDots.appendChild(dot);
+      }
+      this._els.intensityValue.textContent = `${intensity}/5`;
+      this._els.intensityItem.hidden = false;
+    } else {
+      this._els.intensityDots.innerHTML = '';
+      this._els.intensityValue.textContent = '';
+      this._els.intensityItem.hidden = true;
+    }
+
+    const hasCaffeine = this.hasAttribute('caffeine') && this.caffeine >= 0;
+    if (hasCaffeine) {
+      this._els.caffeineItem.textContent = `${this.caffeine}mg caffeine`;
+      this._els.caffeineItem.hidden = false;
+    } else {
+      this._els.caffeineItem.textContent = '';
+      this._els.caffeineItem.hidden = true;
+    }
+
+    const hasCalories = this.hasAttribute('calories') && this.calories >= 0;
+    if (hasCalories) {
+      this._els.caloriesItem.textContent = `${this.calories} cal`;
+      this._els.caloriesItem.hidden = false;
+    } else {
+      this._els.caloriesItem.textContent = '';
+      this._els.caloriesItem.hidden = true;
+    }
+
+    this._els.metaRow.hidden = !(hasIntensity || hasCaffeine || hasCalories);
+
+    // 3. Boolean attributes
+    this._els.badgeFeatured.hidden = !this.featured;
+    this._els.badgeSeasonal.hidden = !this.seasonal;
+    this._els.badgeIced.hidden = !this.iced;
+    this._els.badgeOrganic.hidden = !this.organic;
+    this._els.badgeSoldOut.hidden = !this.soldOut;
+
+    if (this.soldOut) {
+      this._els.ctaButton.textContent = 'Sold Out';
+      this._els.ctaButton.setAttribute('aria-disabled', 'true');
+      this._els.ctaButton.removeAttribute('href');
+    } else {
+      this._els.ctaButton.textContent = ctaText;
+      this._els.ctaButton.removeAttribute('aria-disabled');
+      this._els.ctaButton.setAttribute('href', href);
+    }
+  }
+}
+
+if (!customElements.get('coffee-card')) {
+  customElements.define('coffee-card', CoffeeCard);
+}
+
+if (typeof window !== 'undefined') {
+  window.CoffeeCard = CoffeeCard;
+}
