+  <script>
+    document.addEventListener("DOMContentLoaded", () => {
+      if (!CSS.supports("appearance", "base-select")) {
+        return;
+      }
+
+      const picker = document.getElementById("roast-picker");
+      if (!picker) return;
+
+      picker.addEventListener("keydown", (event) => {
+        if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
+        if (!picker.matches(":open")) return;
+
+        const options = Array.from(picker.querySelectorAll("option"));
+        const active = document.activeElement;
+        const current = options.includes(active)
+          ? active
+          : picker.querySelector("option:checked") || options[0];
+        if (!current) return;
+
+        const currentRect = current.getBoundingClientRect();
+        const dir = event.key === "ArrowRight" ? 1 : -1;
+
+        let nearest = null;
+        let minDistance = Infinity;
+
+        for (const option of options) {
+          if (option === current) continue;
+          const rect = option.getBoundingClientRect();
+          const dx = (rect.left - currentRect.left) * dir;
+          if (dx > 0) {
+            const dy = Math.abs(rect.top - currentRect.top);
+            const distance = Math.hypot(dx, dy);
+            if (distance < minDistance) {
+              minDistance = distance;
+              nearest = option;
+            }
+          }
+        }
+
+        if (nearest) {
+          event.preventDefault();
+          nearest.focus();
+        }
+      });
+    });
