+    (function () {
+      const toggleBtn = document.getElementById('theme-toggle');
+      const themeIcon = document.getElementById('theme-icon');
+      const themeLabel = document.getElementById('theme-label');
+      const root = document.documentElement;
+      const body = document.body;
+      const mediaQuery = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;
+
+      function getSavedTheme() {
+        try {
+          return localStorage.getItem('theme');
+        } catch (e) {
+          return null;
+        }
+      }
+
+      function saveTheme(theme) {
+        try {
+          localStorage.setItem('theme', theme);
+        } catch (e) {
+          // Ignore storage errors
+        }
+      }
+
+      function getEffectiveTheme() {
+        const saved = getSavedTheme();
+        if (saved === 'dark' || saved === 'light') {
+          return saved;
+        }
+        if (root.getAttribute('data-theme') === 'dark' || root.getAttribute('data-theme') === 'light') {
+          return root.getAttribute('data-theme');
+        }
+        return mediaQuery && mediaQuery.matches ? 'dark' : 'light';
+      }
+
+      function applyTheme(theme) {
+        const isDark = theme === 'dark';
+        root.setAttribute('data-theme', theme);
+        body.setAttribute('data-theme', theme);
+        body.classList.toggle('dark-mode', isDark);
+        body.classList.toggle('light-mode', !isDark);
+
+        if (toggleBtn) {
+          toggleBtn.setAttribute('aria-pressed', String(isDark));
+          toggleBtn.setAttribute('aria-label', isDark ? 'Switch to light mode' : 'Switch to dark mode');
+        }
+        if (themeIcon) {
+          themeIcon.textContent = isDark ? '☀️' : '🌙';
+        }
+        if (themeLabel) {
+          themeLabel.textContent = isDark ? 'Light Mode' : 'Dark Mode';
+        }
+      }
+
+      // Initialize theme on load
+      applyTheme(getEffectiveTheme());
+
+      // Toggle manually between light and dark, overriding system preference
+      if (toggleBtn) {
+        toggleBtn.addEventListener('click', function () {
+          const current = getEffectiveTheme();
+          const next = current === 'dark' ? 'light' : 'dark';
+          saveTheme(next);
+          applyTheme(next);
+        });
+      }
+
+      // Listen for system theme changes only if user hasn't manually overridden
+      if (mediaQuery && typeof mediaQuery.addEventListener === 'function') {
+        mediaQuery.addEventListener('change', function (e) {
+          if (!getSavedTheme()) {
+            applyTheme(e.matches ? 'dark' : 'light');
+          }
+        });
+      }
+    })();
+  </script>
