+  <pre id="output" aria-live="polite"></pre>
+
+  <script>
+    const button = document.getElementById('load-btn');
+    const output = document.getElementById('output');
+
+    button.addEventListener('click', () => {
+      // Mission-critical request prioritized with priority: 'high'
+      const dataPromise = fetch('/api/data', {
+        method: 'GET',
+        priority: 'high',
+        headers: {
+          'Accept': 'application/json'
+        }
+      });
+
+      // Concurrent non-critical analytics POST prioritized with priority: 'low' and keepalive: true
+      const analyticsPromise = fetch('/api/analytics', {
+        method: 'POST',
+        priority: 'low',
+        keepalive: true,
+        headers: {
+          'Content-Type': 'application/json'
+        },
+        body: JSON.stringify({ click: 1 })
+      });
+
+      dataPromise
+        .then(res => (res.ok ? res.text() : Promise.reject(new Error(`HTTP ${res.status}`))))
+        .then(text => {
+          output.textContent = text;
+        })
+        .catch(err => {
+          output.textContent = `Error: ${err.message}`;
+        });
+
+      analyticsPromise.catch(() => {});
+    });
+  </script>
+</body>
+</html>

