+<script>
+  function initTopStoriesCarousels() {
+    const carousels = document.querySelectorAll<HTMLElement>('[data-top-stories-carousel]');
+
+    carousels.forEach((carousel) => {
+      if (carousel.dataset.initialized === 'true') return;
+      carousel.dataset.initialized = 'true';
+
+      const viewport = carousel.querySelector<HTMLElement>('[data-carousel-viewport]');
+      const slides = Array.from(carousel.querySelectorAll<HTMLElement>('[data-carousel-slide]'));
+      const prevBtn = carousel.querySelector<HTMLButtonElement>('[data-carousel-prev]');
+      const nextBtn = carousel.querySelector<HTMLButtonElement>('[data-carousel-next]');
+
+      if (!viewport || slides.length <= 1) return;
+
+      let currentIndex = 0;
+
+      const updateSlideDOM = (nextIndex: number) => {
+        slides.forEach((slide, idx) => {
+          const isActive = idx === nextIndex;
+          slide.classList.toggle('hidden', !isActive);
+          slide.setAttribute('aria-hidden', isActive ? 'false' : 'true');
+        });
+        currentIndex = nextIndex;
+      };
+
+      const navigate = (direction: 'forward' | 'backward') => {
+        const delta = direction === 'forward' ? 1 : -1;
+        const nextIndex = (currentIndex + delta + slides.length) % slides.length;
+        const updateDOM = () => updateSlideDOM(nextIndex);
+
+        const scopedViewport = viewport as HTMLElement & {
+          startViewTransition?: (callbackOptions: (() => void) | { update: () => void; types?: string[] }) => { ready: Promise<void> };
+        };
+
+        // Prefer element-scoped View Transitions so external fixed/popover elements and concurrent transitions are unaffected
+        if ('startViewTransition' in Element.prototype && typeof scopedViewport.startViewTransition === 'function') {
+          const transition = scopedViewport.startViewTransition({
+            update: updateDOM,
+            types: [direction],
+          });
+          transition.ready.catch(() => {});
+          return;
+        }
+
+        // Fallback to document-scoped View Transitions with active-view-transition-type
+        const docWithVT = document as Document & {
+          startViewTransition?: (callbackOptions: (() => void) | { update: () => void; types?: string[] }) => { ready: Promise<void>; finished: Promise<void> };
+        };
+
+        if (typeof docWithVT.startViewTransition === 'function') {
+          try {
+            viewport.dataset.vtFallback = 'true';
+            const transition = docWithVT.startViewTransition({
+              update: updateDOM,
+              types: [direction],
+            });
+            transition.ready.catch(() => {});
+            transition.finished.finally(() => {
+              delete viewport.dataset.vtFallback;
+            });
+            return;
+          } catch {
+            delete viewport.dataset.vtFallback;
+          }
+        }
+
+        // Progressive enhancement fallback: update DOM immediately without animation
+        updateDOM();
+      };
+
+      prevBtn?.addEventListener('click', () => navigate('backward'));
+      nextBtn?.addEventListener('click', () => navigate('forward'));
+    });
+  }
+
+  initTopStoriesCarousels();
+  document.addEventListener('astro:page-load', initTopStoriesCarousels);
+</script>
