+import React, { useState } from 'react';
+import { ChevronLeftIcon, ChevronRightIcon } from '@heroicons/react/24/outline';
+
+export interface StoryItem {
+  id: string;
+  title: string;
+  date: string;
+  href: string;
+  category?: string;
+  summary?: string;
+}
+
+interface TopStoriesCarouselProps {
+  stories: StoryItem[];
+}
+
+export default function TopStoriesCarousel({ stories }: TopStoriesCarouselProps) {
+  const [currentIndex, setCurrentIndex] = useState(0);
+  const [direction, setDirection] = useState<'next' | 'prev' | null>(null);
+  const [step, setStep] = useState(0);
+
+  if (!stories || stories.length === 0) {
+    return null;
+  }
+
+  const handlePrevious = () => {
+    setDirection('prev');
+    setStep((s) => s + 1);
+    setCurrentIndex((prevIndex) => (prevIndex - 1 + stories.length) % stories.length);
+  };
+
+  const handleNext = () => {
+    setDirection('next');
+    setStep((s) => s + 1);
+    setCurrentIndex((prevIndex) => (prevIndex + 1) % stories.length);
+  };
+
+  const currentStory = stories[currentIndex];
+  const animationClass =
+    direction === 'next'
+      ? 'slide-in-right'
+      : direction === 'prev'
+        ? 'slide-in-left'
+        : '';
+
+  return (
+    <div
+      className="flex items-center justify-between gap-4"
+      role="region"
+      aria-roledescription="carousel"
+      aria-label="Top Stories"
+    >
+      <button
+        type="button"
+        onClick={handlePrevious}
+        aria-label="Previous"
+        className="flex items-center gap-1 px-3 py-1.5 text-sm font-medium text-gray-700 bg-gray-100 hover:bg-amber-400 hover:text-gray-900 rounded transition-colors cursor-pointer shrink-0"
+      >
+        <ChevronLeftIcon className="w-4 h-4" />
+        <span>Previous</span>
+      </button>
+
+      <div className="flex-1 overflow-hidden relative" aria-live="polite">
+        <div
+          key={`${currentStory.id}-${step}`}
+          data-direction={direction ?? undefined}
+          className={`text-center px-2 ${animationClass}`}
+        >
+          <a href={currentStory.href}>
+            <h3 className="font-bold text-gray-900 hover:text-amber-400 cursor-pointer">
