+        if (cartBadge) {
+          cartBadge.textContent = `${totalItems} ${totalItems === 1 ? 'item' : 'items'}`;
+        }
+        if (cartTotal) {
+          cartTotal.textContent = `$${totalPrice.toFixed(2)}`;
+        }
+        if (placeOrderBtn) {
+          placeOrderBtn.disabled = totalItems === 0;
+        }
+      }
+
+      draggable.querySelectorAll('[data-qty-delta]').forEach((btn) => {
+        btn.addEventListener('click', () => {
+          const delta = parseInt(btn.getAttribute('data-qty-delta') || '0', 10);
