+  <script>
+    (function () {
+      const grid = document.getElementById('seasonal-grid');
+      const sortButtons = document.querySelectorAll('.sort-btn');
+
+      if (!grid || !sortButtons.length) return;
+
+      function sortCards(sortType) {
+        const cards = Array.from(grid.querySelectorAll('.card'));
+
+        // 1. FIRST: Record current visual positions before DOM reordering
+        const firstRects = new Map();
+        cards.forEach((card) => {
+          firstRects.set(card, card.getBoundingClientRect());
+        });
+
+        // Compute new card order
+        const sortedCards = [...cards].sort((a, b) => {
+          const nameA = (a.dataset.name || a.querySelector('h3').textContent).trim();
+          const nameB = (b.dataset.name || b.querySelector('h3').textContent).trim();
+          const priceA = parseFloat(a.dataset.price || '0');
+          const priceB = parseFloat(b.dataset.price || '0');
+          const orderA = parseInt(a.dataset.order || '0', 10);
+          const orderB = parseInt(b.dataset.order || '0', 10);
+
+          switch (sortType) {
+            case 'name-asc':
+              return nameA.localeCompare(nameB);
+            case 'name-desc':
+              return nameB.localeCompare(nameA);
+            case 'price-asc':
+              return priceA - priceB;
+            case 'price-desc':
+              return priceB - priceA;
+            case 'featured':
+            default:
+              return orderA - orderB;
+          }
+        });
+
