+          if (card._flipTimeout) {
+            clearTimeout(card._flipTimeout);
+            card._flipTimeout = null;
+          }
+          card.style.transition = 'none';
+          card.style.transform = '';
+          card.classList.remove('card-moving');
+          grid.appendChild(card);
+        });
+
+        // Force layout calculation for target positions
+        void grid.offsetHeight;
+
+        // 2. LAST & INVERT: Measure target positions and invert via transform
+        sortedCards.forEach((card) => {
+          const firstRect = firstRects.get(card);
+          const lastRect = card.getBoundingClientRect();
+          const deltaX = firstRect.left - lastRect.left;
+          const deltaY = firstRect.top - lastRect.top;
+
+          if (Math.abs(deltaX) > 0.5 || Math.abs(deltaY) > 0.5) {
+            card.style.transform = `translate3d(${deltaX}px, ${deltaY}px, 0) scale(0.97)`;
+            card.classList.add('card-moving');
+          } else {
+            card.style.transform = 'translate3d(0, -4px, 0) scale(0.98)';
+          }
+        });
+
+        // Commit inverted state before starting transition
+        void grid.offsetHeight;
+
+        // 3. PLAY: Animate cards smoothly into their new positions
+        sortedCards.forEach((card, index) => {
+          const staggerMs = index * 30;
+          card.style.transition = `transform 480ms cubic-bezier(0.22, 1, 0.36, 1) ${staggerMs}ms, box-shadow 300ms ease`;
+          card.style.transform = 'translate3d(0, 0, 0) scale(1)';
+
+          card._flipTimeout = setTimeout(() => {
+            card.style.transition = '';
+            card.style.transform = '';
+            card.classList.remove('card-moving');
+            card._flipTimeout = null;
+          }, 520 + staggerMs);
+        });
+      }
