+        const nextViewEl = getOrCreateView(normalizedView);
+
+        // Preserve all other views offscreen in the DOM instead of removing or destroying them
+        viewCache.forEach((viewEl, name) => {
+          if (name === normalizedView) {
+            viewEl.hidden = false;
+            viewEl.classList.remove('offscreen');
+            viewEl.classList.add('active');
+            viewEl.dataset.state = 'active';
+            viewEl.setAttribute('aria-hidden', 'false');
+          } else {
+            viewEl.hidden = true;
+            viewEl.classList.remove('active');
+            viewEl.classList.add('offscreen');
+            viewEl.dataset.state = 'offscreen';
+            viewEl.setAttribute('aria-hidden', 'true');
+          }
+        });
+
+        // Update nav active states
+        navLinks.forEach(link => {
+          const isMatch = link.dataset.view === normalizedView;
+          link.classList.toggle('active', isMatch);
+          if (isMatch) {
+            link.setAttribute('aria-current', 'page');
+          } else {
+            link.removeAttribute('aria-current');
+          }
+        });
+
+        // Optional category shortcut from home cards
+        if (normalizedView === 'menu' && categoryFilter) {
+          const filterBtn = nextViewEl.querySelector(`.filter-btn[data-category="${categoryFilter}"]`);
+          if (filterBtn) filterBtn.click();
+        }
+
+        currentViewName = normalizedView;
+        document.title = VIEW_TITLES[normalizedView];
+
+        if (pushState) {
+          const nextPath = normalizedView === 'home' ? '/' : `/${normalizedView}`;
+          try {
+            if (window.location.pathname !== nextPath) {
+              window.history.pushState({ view: normalizedView }, '', nextPath);
+            }
+          } catch (_) {
+            window.location.hash = normalizedView;
+          }
+        }
+
+        const savedScroll = scrollCache.get(normalizedView) || 0;
+        window.scrollTo(0, savedScroll);
+      }
+
+      // Intercept clicks on any SPA navigation link or element with data-view
+      document.addEventListener('click', (e) => {
+        const trigger = e.target.closest('[data-view], a[href^="/"]');
+        if (!trigger) return;
+
+        if (trigger.dataset.action === 'logout' || trigger.getAttribute('href') === '/logout') {
+          e.preventDefault();
+          switchToView('home');
+          return;
+        }
+
+        const targetView = trigger.dataset.view || resolveRoute(trigger.getAttribute('href'));
+        if (targetView) {
+          e.preventDefault();
+          switchToView(targetView, {
+            pushState: true,
+            categoryFilter: trigger.dataset.category || null
+          });
+        }
+      });
+
+      // Keyboard navigation on logo
+      const logoEl = document.querySelector('.logo');
+      if (logoEl) {
+        logoEl.addEventListener('keydown', (e) => {
+          if (e.key === 'Enter' || e.key === ' ') {
+            e.preventDefault();
+            switchToView('home');
+          }
+        });
+      }
+
+      // Handle browser Back/Forward navigation
+      window.addEventListener('popstate', (e) => {
+        const targetView = (e.state && e.state.view) || resolveRoute(window.location.hash || window.location.pathname);
+        switchToView(targetView, { pushState: false });
+      });
+
+      window.addEventListener('hashchange', () => {
+        const targetView = resolveRoute(window.location.hash);
+        switchToView(targetView, { pushState: false });
+      });
+
+      // Expose SPA state for programmatic inspection
+      window.__dailyGrindSPA = {
+        viewCache,
+        renderCounts,
+        switchToView,
+        getCurrentView: () => currentViewName
+      };
+
+      // Handle initial route if loaded on a non-home path or hash
+      const initialRoute = resolveRoute(window.location.hash || window.location.pathname);
+      if (initialRoute !== 'home') {
+        switchToView(initialRoute, { pushState: false });
+      }
+    })();
+  </script>
 </body>

 </html>

