+<script>
+    function switchToView(viewId: string, options: { href?: string; pushState?: boolean; moveFocus?: boolean } = {}) {
+        const container = document.getElementById('spa-views-container');
+        if (!container) return;
+
+        const targetView = document.getElementById(`view-${viewId}`);
+        if (!targetView) return;
+
+        // Hide all views while preserving their cached DOM and rendering state
+        container.querySelectorAll<HTMLElement>('.spa-view').forEach(view => {
+            view.classList.add('inactive');
+            view.setAttribute('aria-hidden', 'true');
+            view.setAttribute('inert', 'inert');
+        });
+
+        // Show the target view
+        targetView.classList.remove('inactive');
+        targetView.setAttribute('aria-hidden', 'false');
+        targetView.removeAttribute('inert');
+
+        // Update document title
+        const viewTitle = targetView.getAttribute('data-view-title');
+        if (viewTitle) {
+            document.title = viewTitle;
+        }
+
+        // Update browser URL history if requested
+        if (options.pushState && options.href) {
+            window.history.pushState({ spaViewId: viewId }, '', options.href);
+        }
+
+        // Move focus to the new view to ensure a logical tab-order
+        if (options.moveFocus !== false) {
+            targetView.focus({ preventScroll: true });
+        }
+
+        // Notify navigation components
+        window.dispatchEvent(new CustomEvent('spa-view-changed', {
+            detail: { viewId }
+        }));
+    }
+
+    function resolveViewFromUrl(): string {
+        const path = window.location.pathname;
+        const params = new URLSearchParams(window.location.search);
+        const sectionParam = params.get('section');
+
+        if (path.endsWith('/multimedia') || path.endsWith('/multimedia/')) {
+            return 'multimedia';
+        }
+        if (path.endsWith('/reports') || path.endsWith('/reports/')) {
+            return 'reports';
+        }
+        if (sectionParam && document.getElementById(`view-${sectionParam}`)) {
+            return sectionParam;
+        }
+        return 'all';
+    }
+
+    function initSpaNavigation() {
+        const container = document.getElementById('spa-views-container');
+        if (!container) return;
+
+        // Sync initial view if URL query parameter or path specifies one
+        const initialUrlView = resolveViewFromUrl();
+        const serverView = container.getAttribute('data-initial-view') || 'all';
+        if (initialUrlView !== serverView) {
+            switchToView(initialUrlView, { moveFocus: false });
+        }
+    }
+
+    // Listen for custom navigation events from BottomNav or other triggers
+    window.addEventListener('spa-navigate', ((e: CustomEvent<{ viewId: string; href?: string; pushState?: boolean }>) => {
+        if (e.detail?.viewId) {
+            switchToView(e.detail.viewId, {
+                href: e.detail.href,
+                pushState: e.detail.pushState ?? true,
+                moveFocus: true,
+            });
+        }
+    }) as EventListener);
+
+    // Handle browser back/forward navigation
+    window.addEventListener('popstate', (e: PopStateEvent) => {
+        const viewId = e.state?.spaViewId || resolveViewFromUrl();
+        switchToView(viewId, { pushState: false, moveFocus: true });
+    });
+
+    // Initialize on load and after Astro page transitions
+    initSpaNavigation();
+    document.addEventListener('astro:page-load', initSpaNavigation);
+</script>
