+function getSectionFromUrl(baseUrl: string, fallback: SectionId): SectionId {
+  if (typeof window === 'undefined') return fallback;
+  const params = new URLSearchParams(window.location.search);
+  const querySection = params.get('section') as SectionId | null;
+  if (querySection && MAIN_SECTIONS.some((s) => s.id === querySection)) {
+    return querySection;
+  }
+
+  const hash = window.location.hash.replace(/^#/, '') as SectionId;
+  if (hash && MAIN_SECTIONS.some((s) => s.id === hash)) {
+    return hash;
+  }
+
+  const path = window.location.pathname;
+  if (path.endsWith('/multimedia') || path.endsWith('/multimedia/')) {
+    return 'multimedia';
+  }
+  if (path.endsWith('/reports') || path.endsWith('/reports/')) {
+    return 'reports';
+  }
+  if (path.includes('/category/politics')) {
+    return 'politics';
+  }
+  if (path.includes('/category/world')) {
+    return 'world';
+  }
+
+  return fallback;
+}
