+
+      if (typeof window !== 'undefined') {
+        window.dispatchEvent(
+          new CustomEvent('spa:section-changed', { detail: { section } })
+        );
+
+        if (pushHistory) {
+          let targetUrl = baseUrl;
+          if (section === 'multimedia') {
+            targetUrl = `${baseUrl}multimedia`;
+          } else if (section === 'reports') {
+            targetUrl = `${baseUrl}reports`;
+          } else if (section !== 'top-news') {
+            targetUrl = `${baseUrl}?section=${section}`;
+          }
+          if (window.location.pathname + window.location.search !== targetUrl) {
+            window.history.pushState({ section }, '', targetUrl);
+          }
+        }
+      }
