+
+  return (
+    <div data-spa-views-root="true">
+      {/* Top News View */}
+      {visitedSections['top-news'] && (
+        <Activity mode={activeSection === 'top-news' ? 'visible' : 'hidden'} name="top-news">
+          <div
+            data-view-section="top-news"
+            aria-hidden={activeSection !== 'top-news'}
+          >
+            {/* Top Stories Bar */}
+            <div className="bg-white border-b border-gray-300">
