@@ -0,0 +1,117 @@
+import type { CollectionEntry } from 'astro:content';
+import { getCollection } from 'astro:content';
+import { getArticleImage } from './images';
+import type { ArticleData, ReportData, MultimediaData } from '../components/SectionSPA';
+
+export async function serializeArticle(
+  article: CollectionEntry<'articles'> | any
+): Promise<ArticleData> {
+  const img = await getArticleImage(article);
+  const imageSrc = typeof img === 'string' ? img : img.src;
+  const dateStr =
+    article.data.date instanceof Date
+      ? article.data.date.toISOString()
+      : String(article.data.date);
+
+  return {
+    id: article.id,
+    slug: article.slug ?? article.id,
+    imageSrc,
+    data: {
+      title: article.data.title,
+      summary: article.data.summary,
+      author: article.data.author,
+      date: dateStr,
+      category: article.data.category,
+      image: article.data.image,
+      image_caption: article.data.image_caption,
+      readingTime: article.data.readingTime,
+    },
+  };
+}
+
+export async function getSectionSPAData() {
+  const articles = await getCollection('articles');
+  articles.sort((a, b) => b.data.date.valueOf() - a.data.date.valueOf());
+
+  const topArticleRaw = articles[0];
+  const topStoriesRaw = articles.slice(1, 4);
+  const topNewsArticlesRaw = articles.slice(4, 8);
+  const worldNewsArticlesRaw = articles.slice(8, 11);
+  const politicsArticlesRaw: any[] = articles.slice(11, 15);
+
+  // Preserve the fake "What's new in DevTools" post in Politics
+  politicsArticlesRaw[2] = {
+    id: 'public-transit-overhaul',
+    data: {
+      title: "What's new in DevTools",
+      summary:
+        'Learn about what is new in Chrome DevTools 144: from request conditions to performance debugging, we got you covered.',
+      author: 'Chrome DevTools Team',
+      date: new Date('2025-09-16T00:00:00.000Z'),
+      category: 'Web Development',
+      image:
+        'https://cinemai-1026410574114.us-central1.run.app/cinemai/_next/image?url=%2Fcinemai%2F_next%2Fstatic%2Fmedia%2Fthumbnail-wndt-139-141.45ba64a6.jpg&w=3840&q=75',
+      image_caption: '',
+      readingTime: 3,
+    },
+    body: '',
+    collection: 'articles',
+    slug: 'public-transit-overhaul',
+  };
+
+  const [
+    topArticle,
+    topStories,
+    topNewsArticles,
+    worldNewsArticles,
+    politicsArticles,
+    allArticles,
+    rawReports,
+    rawMultimedia,
+  ] = await Promise.all([
+    serializeArticle(topArticleRaw),
+    Promise.all(topStoriesRaw.map(serializeArticle)),
+    Promise.all(topNewsArticlesRaw.map(serializeArticle)),
+    Promise.all(worldNewsArticlesRaw.map(serializeArticle)),
+    Promise.all(politicsArticlesRaw.map(serializeArticle)),
+    Promise.all(articles.map(serializeArticle)),
+    getCollection('reports'),
+    getCollection('multimedia'),
+  ]);
+
+  const reports: ReportData[] = rawReports.map((r: any) => ({
+    id: r.id,
+    slug: r.slug ?? r.id,
+    body: r.body,
+    data: {
+      title: r.data.title,
+      description: r.data.description,
+      publishDate: r.data.publishDate,
+      category: r.data.category,
+    },
+  }));
+
+  const multimedia: MultimediaData[] = rawMultimedia.map((m: any) => ({
+    id: m.id,
+    slug: m.slug ?? m.id,
+    body: m.body,
+    data: {
+      title: m.data.title,
+      description: m.data.description,
+      publishDate: m.data.publishDate,
+      category: m.data.category,
+    },
+  }));
+
+  return {
+    topArticle,
+    topStories,
+    topNewsArticles,
+    worldNewsArticles,
+    politicsArticles,
+    allArticles,
+    reports,
+    multimedia,
+  };
+}

