+  <script>
+    (function () {
+      const wrappers = document.querySelectorAll('.hovercard-wrapper');
+
+      wrappers.forEach((wrapper) => {
+        let hideTimer = null;
+        const priceEl = wrapper.querySelector('[data-price]');
+        const caffeineEl = wrapper.querySelector('[data-caffeine]');
+        const caloriesEl = wrapper.querySelector('[data-calories]');
+        const sizeButtons = wrapper.querySelectorAll('.hovercard-size-btn');
+
+        const openCard = () => {
+          clearTimeout(hideTimer);
+          wrapper.classList.add('is-open');
+        };
+
+        const closeCard = () => {
+          hideTimer = setTimeout(() => {
+            wrapper.classList.remove('is-open');
+          }, 120);
+        };
+
+        wrapper.addEventListener('mouseenter', openCard);
+        wrapper.addEventListener('mouseleave', closeCard);
+        wrapper.addEventListener('focusin', openCard);
+        wrapper.addEventListener('focusout', (e) => {
+          if (!wrapper.contains(e.relatedTarget)) {
+            closeCard();
+          }
+        });
+
+        sizeButtons.forEach((btn) => {
+          btn.addEventListener('click', (e) => {
+            e.preventDefault();
+            e.stopPropagation();
+            sizeButtons.forEach((b) => b.classList.remove('active'));
+            btn.classList.add('active');
+            if (priceEl && btn.dataset.price) priceEl.textContent = btn.dataset.price;
+            if (caffeineEl && btn.dataset.caffeine) caffeineEl.textContent = btn.dataset.caffeine;
+            if (caloriesEl && btn.dataset.calories) caloriesEl.textContent = btn.dataset.calories;
+          });
+        });
+      });
+
+      document.addEventListener('keydown', (e) => {
+        if (e.key === 'Escape') {
+          wrappers.forEach((w) => w.classList.remove('is-open'));
+        }
+      });
+    })();
+  </script>
