+          }
+          return a.featuredRank - b.featuredRank;
+        };
+
+        const sorted = typeof filtered.toSorted === 'function'
+          ? filtered.toSorted(compareFn)
+          : [...filtered].sort(compareFn);
+
+        const finalItems = state.reverse
+          ? (typeof sorted.toReversed === 'function' ? sorted.toReversed() : [...sorted].reverse())
+          : sorted;
+
+        return finalItems;
+      }
+
+      function createCardElement(item) {
+        const card = document.createElement('article');
+        card.className = 'card menu-card';
+        card.dataset.id = item.id;
+        card.dataset.category = item.category;
+        card.dataset.price = String(item.price);
+        card.style.viewTransitionName = `card-${item.id}`;
+
+        const top = document.createElement('div');
+        top.className = 'card-top';
+
+        const header = document.createElement('div');
+        header.className = 'card-header';
+
+        const title = document.createElement('h3');
+        title.textContent = item.name;
+
+        const price = document.createElement('span');
+        price.className = 'price-tag card-price';
+        price.dataset.priceValue = String(item.price);
+        price.textContent = formatPrice(item.price);
+
+        header.append(title, price);
+
+        const badge = document.createElement('span');
+        badge.className = 'category-pill';
+        badge.textContent = CATEGORY_LABELS[item.category] || item.category;
+
+        const desc = document.createElement('p');
+        desc.textContent = item.description;
+
