+          countBadge.dataset.categoryCount = cat.id;
+          countBadge.textContent = '0 items';
+
+          header.append(heading, countBadge);
+
+          const emptyMsg = document.createElement('p');
+          emptyMsg.className = 'empty-category-message';
+          emptyMsg.textContent = `No matching drinks in ${cat.label} (0 items).`;
+          emptyMsg.hidden = true;
+
+          const groupGrid = document.createElement('div');
+          groupGrid.className = 'grid category-group-grid';
+
+          section.append(header, emptyMsg, groupGrid);
+          menuGrouped.append(section);
+
+          categorySectionNodes.set(cat.id, {
+            section,
