+            emptyMsg,
+            groupGrid
+          });
+        }
+      }
+
+      // Move existing DOM nodes cleanly in place using moveBefore when available
+      function reorderNodesInContainer(container, orderedNodes) {
+        const orderedSet = new Set(orderedNodes);
+        for (const child of [...container.children]) {
+          if (!orderedSet.has(child)) {
+            child.remove();
+          }
+        }
+        const move = Object.hasOwn(Element.prototype, 'moveBefore')
+          ? (node) => {
