+        }
+      }
+
+      function renderMenu(state, visibleItems) {
+        const performUpdate = () => {
+          if (!state.group) {
+            menuGrouped.hidden = true;
+            menuGrid.hidden = false;
+            const orderedCards = visibleItems.map((item) => cardNodesById.get(item.id));
+            reorderNodesInContainer(menuGrid, orderedCards);
+          } else {
+            menuGrid.hidden = true;
+            menuGrouped.hidden = false;
+
+            const groupedMap = typeof Object.groupBy === 'function'
