+
+            for (const cat of CATEGORIES) {
+              const itemsForCat = groupedMap[cat.id] || [];
+              const count = itemsForCat.length;
+              const groupEntry = categorySectionNodes.get(cat.id);
+
+              groupEntry.heading.textContent = `${cat.label} (${count})`;
+              groupEntry.countBadge.textContent = `${count} ${count === 1 ? 'item' : 'items'}`;
+              groupEntry.section.dataset.itemCount = String(count);
+
+              const orderedCards = itemsForCat.map((item) => cardNodesById.get(item.id));
+              reorderNodesInContainer(groupEntry.groupGrid, orderedCards);
