+    const sentimentBtn = document.getElementById('sentiment-btn');
+    const sentimentResult = document.getElementById('sentiment-result');
+
+    const cloneBtn = document.getElementById('clone-btn');
+    const cleanupBtn = document.getElementById('cleanup-btn');
+    const contextUsageEl = document.getElementById('context-usage');
+    const branchStatusEl = document.getElementById('branch-status');
+
+    function updateContextUsage(session) {
+      if (!session) {
+        contextUsageEl.textContent = 'Context Usage: No active session';
+        return;
+      }
+      const usage = session.inputUsage ?? 0;
+      const quota = session.inputQuota ?? 0;
+      contextUsageEl.textContent = `Context Usage: ${usage} / ${quota} tokens (Cloned branches: ${clonedSessions.length})`;
+    }
+
+    async function checkModelAvailability() {
+      if (typeof LanguageModel === 'undefined') {
+        throw new Error('Built-in LanguageModel API is not supported in this browser.');
+      }
+      const availability = await LanguageModel.availability();
+      if (availability === 'unavailable') {
+        throw new Error('The built-in AI model is currently unavailable on this device.');
+      }
+      return availability;
+    }
+
+    async function createBaristaSession() {
+      const availability = await checkModelAvailability();
+      if (availability === 'downloadable' || availability === 'downloading') {
+        progressDisplay.textContent = 'Preparing local AI model...';
+      }
+
+      const session = await LanguageModel.create({
+        initialPrompts: [
+          {
+            role: 'system',
+            content: SYSTEM_PROMPT
+          }
+        ],
+        monitor(m) {
+          m.addEventListener('downloadprogress', (e) => {
+            const percent = Math.round((e.loaded || 0) * 100);
+            progressDisplay.textContent = `Downloading AI model: ${percent}%`;
+          });
+        }
+      });
+
+      progressDisplay.textContent = 'Model ready.';
+      updateContextUsage(session);
+      return session;
+    }
+
+    async function ensureActiveSession() {
+      if (!activeSession) {
+        activeSession = await createBaristaSession();
+      }
+      return activeSession;
+    }
+
+    function cleanupUnneededSessions() {
+      while (clonedSessions.length > 0) {
+        const oldSession = clonedSessions.pop();
+        if (oldSession && typeof oldSession.destroy === 'function') {
+          oldSession.destroy();
+        }
+      }
+      updateContextUsage(activeSession);
+    }
+
+    // Ask the Barista - Streaming Response
+    askButton.addEventListener('click', async () => {
+      const question = questionInput.value.trim() || 'Tell me about the Maple Oat Latte and Cold Brew.';
+      baristaAnswer.textContent = '';
+
+      try {
+        const session = await ensureActiveSession();
+
+        // Check context quota and clean up / recreate if near limit
+        if (session.inputQuota && session.inputUsage >= session.inputQuota * 0.9) {
+          session.destroy();
+          activeSession = await createBaristaSession();
+        }
+
+        const stream = activeSession.promptStreaming(question);
+        for await (const chunk of stream) {
+          baristaAnswer.textContent += chunk;
+        }
+        updateContextUsage(activeSession);
+      } catch (error) {
+        baristaAnswer.textContent = `Error: ${error.message}`;
+      }
+    });
+
+    // Customer Feedback Analyzer - Structured JSON output with responseConstraint
+    sentimentBtn.addEventListener('click', async () => {
+      const feedbackText = feedbackInput.value.trim() || 'The Maple Oat Latte and Cold Brew were fantastic!';
+
+      let analysisSession = null;
+      try {
+        await checkModelAvailability();
+        analysisSession = await LanguageModel.create({
+          initialPrompts: [
+            {
+              role: 'system',
+              content: 'You are a customer feedback sentiment analyzer for The Daily Grind coffee shop. Respond strictly with JSON containing a numerical score (from 0 to 10) and a sentiment category.'
+            }
+          ],
+          monitor(m) {
+            m.addEventListener('downloadprogress', (e) => {
+              const percent = Math.round((e.loaded || 0) * 100);
+              progressDisplay.textContent = `Downloading AI model: ${percent}%`;
+            });
+          }
+        });
+
+        const schema = {
+          type: 'object',
+          properties: {
+            score: {
+              type: 'number',
+              description: 'Sentiment score from 0 (most negative) to 10 (most positive)'
+            },
+            category: {
+              type: 'string',
+              enum: ['positive', 'neutral', 'negative'],
+              description: 'Overall sentiment category'
+            }
+          },
+          required: ['score', 'category'],
+          additionalProperties: false
+        };
+
+        const rawResponse = await analysisSession.prompt(
+          `Analyze the sentiment of the following customer feedback: "${feedbackText}"`,
+          { responseConstraint: schema }
+        );
+
+        const parsed = typeof rawResponse === 'string' ? JSON.parse(rawResponse) : rawResponse;
+        sentimentResult.textContent = JSON.stringify(parsed, null, 2);
+      } catch (error) {
+        sentimentResult.textContent = `Error: ${error.message}`;
+      } finally {
+        if (analysisSession && typeof analysisSession.destroy === 'function') {
+          analysisSession.destroy();
+        }
+      }
+    });
+
+    // Conversation Branching - Cloning Sessions, Tracking Context Usage, and Cleaning Up
+    cloneBtn.addEventListener('click', async () => {
+      try {
+        const baseSession = await ensureActiveSession();
+        const clonedSession = await baseSession.clone();
+
+        // Clean up previous/unneeded sessions to free resources
+        cleanupUnneededSessions();
+        if (baseSession && typeof baseSession.destroy === 'function') {
+          baseSession.destroy();
+        }
+
+        activeSession = clonedSession;
+        clonedSessions.push(clonedSession);
+
+        const usage = clonedSession.inputUsage ?? 0;
+        const quota = clonedSession.inputQuota ?? 0;
+        updateContextUsage(clonedSession);
+        branchStatusEl.textContent =
+          `Cloned active session successfully. Context usage: ${usage} / ${quota} tokens.`;
+      } catch (error) {
+        branchStatusEl.textContent = `Error cloning session: ${error.message}`;
+      }
+    });
+
+    cleanupBtn.addEventListener('click', () => {
+      cleanupUnneededSessions();
+      branchStatusEl.textContent = 'Cleaned up all unneeded branched sessions.';
+    });
+
+    window.addEventListener('pagehide', () => {
+      cleanupUnneededSessions();
+      if (activeSession && typeof activeSession.destroy === 'function') {
+        activeSession.destroy();
+        activeSession = null;
+      }
+    });
+  </script>
 </body>

