+import React, { useState, useEffect, useCallback } from 'react';
+import type { AddressSpace, LocalNetworkPermissionName } from '../../global';
+
+export type PermissionStateValue =
+  | PermissionState
+  | 'checking'
+  | 'unsupported';
+
+export type ConnectionState =
+  | 'idle'
+  | 'connecting'
+  | 'connected'
+  | 'error';
+
+export interface DiagnosticsTelemetry {
+  deviceName: string;
+  firmwareOrVersion: string;
+  addressSpace: AddressSpace;
+  permissionName: LocalNetworkPermissionName;
+  endpoint: string;
+  latencyMs: number;
+  metrics: Record<string, string | number>;
+  timestamp: string;
+}
+
+export interface DiagnosticsLogEntry {
+  id: string;
+  timestamp: string;
+  target: 'lan' | 'loopback';
+  endpoint: string;
+  targetAddressSpace: AddressSpace;
+  permissionName: LocalNetworkPermissionName;
+  permissionState: PermissionStateValue;
+  level: 'info' | 'success' | 'warning' | 'error';
+  message: string;
+}
+
+interface Props {
+  compact?: boolean;
+}
+
+/**
+ * Infers the appropriate LNA targetAddressSpace ('local' | 'loopback' | 'public')
+ * and granular permission name ('local-network' | 'loopback-network') for a URL.
+ */
+export function resolveTargetAddressSpace(
+  urlStr: string,
+  fallbackSpace: AddressSpace
+): {
+  addressSpace: AddressSpace;
+  permissionName: LocalNetworkPermissionName;
+} {
+  try {
+    const parsed = new URL(urlStr);
+    const host = parsed.hostname.toLowerCase();
+
+    if (
+      host === '127.0.0.1' ||
+      host === 'localhost' ||
+      host === '[::1]' ||
+      host === '::1' ||
+      host.endsWith('.localhost') ||
+      /^127\.\d{1,3}\.\d{1,3}\.\d{1,3}$/.test(host)
+    ) {
+      return {
+        addressSpace: 'loopback',
+        permissionName: 'loopback-network',
+      };
+    }
+
+    if (
+      host.endsWith('.local') ||
+      /^192\.168\.\d{1,3}\.\d{1,3}$/.test(host) ||
+      /^10\.\d{1,3}\.\d{1,3}\.\d{1,3}$/.test(host) ||
+      /^172\.(1[6-9]|2\d|3[0-1])\.\d{1,3}\.\d{1,3}$/.test(host) ||
+      /^169\.254\.\d{1,3}\.\d{1,3}$/.test(host)
+    ) {
+      return {
+        addressSpace: 'local',
+        permissionName: 'local-network',
+      };
+    }
+  } catch {
+    // Fall back to the provided target space if URL is still being edited
+  }
+
+  return {
+    addressSpace: fallbackSpace,
+    permissionName:
+      fallbackSpace === 'loopback' ? 'loopback-network' : 'local-network',
+  };
+}
+
+/**
+ * Queries a granular Local Network Access permission ('local-network' or 'loopback-network'),
+ * falling back to the legacy 'local-network-access' alias if needed.
+ */
+async function queryLnaPermission(
+  permissionName: 'local-network' | 'loopback-network',
+  onUpdate: (state: PermissionStateValue) => void
+): Promise<(() => void) | undefined> {
+  if (typeof navigator === 'undefined' || !navigator.permissions?.query) {
+    onUpdate('unsupported');
+    return undefined;
+  }
+
+  try {
+    const status =
+      permissionName === 'loopback-network'
+        ? await navigator.permissions.query({ name: 'loopback-network' })
+        : await navigator.permissions.query({ name: 'local-network' });
+    onUpdate(status.state);
+    const handleChange = () => onUpdate(status.state);
+    status.addEventListener?.('change', handleChange);
+    return () => status.removeEventListener?.('change', handleChange);
+  } catch {
+    // Fallback for browsers that still use the unified 'local-network-access' permission name
+    try {
+      const fallbackStatus = await navigator.permissions.query({
+        name: 'local-network-access',
+      });
+      onUpdate(fallbackStatus.state);
+      const handleFallbackChange = () => onUpdate(fallbackStatus.state);
+      fallbackStatus.addEventListener?.('change', handleFallbackChange);
+      return () =>
+        fallbackStatus.removeEventListener?.('change', handleFallbackChange);
+    } catch {
+      onUpdate('unsupported');
+      return undefined;
+    }
+  }
+}
+
+export default function DeveloperDiagnosticsWidget({ compact = false }: Props) {
+  const [isExpanded, setIsExpanded] = useState(!compact);
+
+  // 1. Hardware Test Device on Private Wi-Fi LAN (targetAddressSpace: 'local', permission: 'local-network')
