+import React, { useState } from 'react';
+import DeveloperDiagnosticsWidget from './DeveloperDiagnosticsWidget';
+
+export default function DiagnosticsHeaderButton() {
+  const [isModalOpen, setIsModalOpen] = useState(false);
+
+  const handleClick = () => {
+    const inlineWidget = document.getElementById('developer-diagnostics');
+    if (inlineWidget) {
+      inlineWidget.scrollIntoView({ behavior: 'smooth', block: 'start' });
+    } else {
+      setIsModalOpen(true);
+    }
+  };
+
+  return (
+    <>
+      <button
+        type="button"
+        onClick={handleClick}
+        className="inline-flex items-center gap-1.5 text-xs font-semibold px-2.5 py-1.5 rounded bg-slate-900 text-amber-300 hover:bg-slate-800 border border-slate-700 transition cursor-pointer"
+        title="Open Developer Diagnostics (LAN 192.168.1.x & Loopback 127.0.0.1)"
+      >
+        <span className="w-2 h-2 rounded-full bg-amber-400" />
+        <span>Dev Diagnostics (LAN / 127.0.0.1)</span>
+      </button>
+
+      {isModalOpen && (
+        <div
+          className="fixed inset-0 bg-black/50 backdrop-blur-xs z-[99999] flex justify-center items-start p-4 pt-[8vh] overflow-y-auto"
+          onClick={() => setIsModalOpen(false)}
+        >
+          <div
+            className="w-full max-w-5xl relative"
+            onClick={(e) => e.stopPropagation()}
+          >
+            <button
+              type="button"
+              onClick={() => setIsModalOpen(false)}
+              className="absolute -top-2 -right-2 bg-slate-900 text-slate-200 rounded-full p-1.5 shadow-lg border border-slate-700 hover:text-amber-400 z-10 cursor-pointer"
+              aria-label="Close Developer Diagnostics"
+            >
+              <svg
+                xmlns="http://www.w3.org/2000/svg"
+                className="h-5 w-5"
+                fill="none"
+                viewBox="0 0 24 24"
+                stroke="currentColor"
+                strokeWidth={2}
+              >
+                <path
+                  strokeLinecap="round"
+                  strokeLinejoin="round"
+                  d="M6 18L18 6M6 6l12 12"
+                />
+              </svg>
+            </button>
+            <DeveloperDiagnosticsWidget />
+          </div>
+        </div>
+      )}
+    </>
+  );
+}
