+    (function () {
+      const STORAGE_KEY = 'daily_grind_user_config';
+      const OLD_ORIGIN = 'https://old.dailygrind.example.com';
+      const NEW_ORIGIN = 'https://app.dailygrind.example.com';
+
+      const defaultConfig = {
+        roast: 'maple-oat',
+        milk: 'oat',
+        notifications: true,
+        updatedAt: Date.now()
+      };
+
+      const roastSelect = document.getElementById('default-roast');
+      const milkSelect = document.getElementById('milk-choice');
+      const notificationsCheckbox = document.getElementById('order-notifications');
+      const syncStatus = document.getElementById('migration-sync-status');
+      const transferLink = document.getElementById('migration-transfer-link');
+      const dismissBtn = document.getElementById('migration-dismiss-btn');
+      const banner = document.getElementById('origin-migration-banner');
+
+      function loadConfig() {
+        try {
+          // 1. Check if configuration was transferred via URL parameter during origin migration
+          const params = new URLSearchParams(window.location.search);
+          const migratedData = params.get('migrated_config');
+          if (migratedData) {
+            const parsed = JSON.parse(atob(migratedData));
+            localStorage.setItem(STORAGE_KEY, JSON.stringify(parsed));
+            if (syncStatus) {
+              syncStatus.textContent = 'Configuration Migrated from Previous Origin';
+            }
+            // Clean up URL parameter without reloading
+            const cleanUrl = new URL(window.location.href);
+            cleanUrl.searchParams.delete('migrated_config');
+            window.history.replaceState({}, document.title, cleanUrl.toString());
+            return { ...defaultConfig, ...parsed };
+          }
+
+          // 2. Otherwise read from localStorage
+          const raw = localStorage.getItem(STORAGE_KEY);
+          if (raw) {
+            return { ...defaultConfig, ...JSON.parse(raw) };
+          }
+        } catch (err) {
+          console.warn('Unable to read or migrate user configuration:', err);
+        }
+        return { ...defaultConfig };
+      }
+
+      function saveConfig(config) {
+        try {
+          const payload = { ...config, updatedAt: Date.now() };
+          localStorage.setItem(STORAGE_KEY, JSON.stringify(payload));
+          updateTransferLink(payload);
+          if (syncStatus) {
+            syncStatus.textContent = 'Configuration Saved & Ready for Origin Transfer';
+          }
+        } catch (err) {
+          console.warn('Unable to save user configuration:', err);
+        }
+      }
+
+      function encodeConfigPayload(config) {
+        try {
+          return btoa(JSON.stringify(config));
+        } catch {
+          return '';
+        }
+      }
+
+      function updateTransferLink(config) {
+        if (!transferLink) return;
+        const encoded = encodeConfigPayload(config);
+        const targetUrl = new URL(NEW_ORIGIN + '/');
+        if (encoded) {
+          targetUrl.searchParams.set('migrated_config', encoded);
+        }
+        transferLink.href = targetUrl.toString();
+      }
+
