+        if (roastSelect) roastSelect.value = config.roast;
+        if (milkSelect) milkSelect.value = config.milk;
+        if (notificationsCheckbox) notificationsCheckbox.checked = Boolean(config.notifications);
+        updateTransferLink(config);
+      }
+
+      const currentConfig = loadConfig();
+      applyConfigToUI(currentConfig);
+
+      function handleConfigChange() {
+        const nextConfig = {
+          roast: roastSelect ? roastSelect.value : defaultConfig.roast,
+          milk: milkSelect ? milkSelect.value : defaultConfig.milk,
+          notifications: notificationsCheckbox ? notificationsCheckbox.checked : defaultConfig.notifications
