+          imageAlt: 'Spiced Cardamom Cortado served in a warm glass',
+          description: 'Equal parts rich double espresso and silky micro-foamed milk infused with freshly crushed green cardamom pods and a whisper of orange blossom honey.',
+          caffeine: '145 mg',
+          calories: '110 kcal',
+          roast: 'Medium Espresso',
+          notes: ['Crushed Green Cardamom', 'Orange Blossom Honey', 'Silky Microfoam', 'Warm Spice'],
+          href: '/menu/cortado'
+        },
+        'toasted-hazelnut-mocha': {
+          title: 'Toasted Hazelnut Mocha',
+          badge: 'Barista Reserve',
+          price: '$6.10',
+          image: 'https://images.unsplash.com/photo-1572442388796-11668a67e53d?auto=format&fit=crop&w=900&q=80',
+          imageAlt: 'Toasted Hazelnut Mocha topped with cocoa dusting',
+          description: 'Single-origin 70% dark chocolate ganache melted directly into fresh espresso, layered with roasted Oregon hazelnut praline and topped with cocoa-dusted whipped cream.',
+          caffeine: '155 mg',
+          calories: '260 kcal',
+          roast: 'Medium-Dark',
+          notes: ['70% Dark Ganache', 'Oregon Hazelnut Praline', 'Espresso Forte', 'Cocoa Dusting'],
+          href: '/menu/mocha'
+        }
+      };
+
+      /* --- Horizontal Swipe & Keyboard Carousel --- */
+      const carousel = document.getElementById('seasonal-carousel');
+      const cards = Array.from(carousel.querySelectorAll('.card'));
+      const prevBtn = document.getElementById('carousel-prev');
+      const nextBtn = document.getElementById('carousel-next');
+      const dotsContainer = document.getElementById('carousel-dots');
+      let activeCardIndex = 0;
+
+      // Build pagination dots
+      const dots = cards.map((card, index) => {
+        const dot = document.createElement('button');
+        dot.type = 'button';
+        dot.className = 'carousel-dot' + (index === 0 ? ' is-active' : '');
+        dot.setAttribute('role', 'tab');
+        dot.setAttribute('aria-selected', index === 0 ? 'true' : 'false');
+        const title = card.querySelector('h3')?.textContent || `Drink ${index + 1}`;
+        dot.setAttribute('aria-label', `Slide to ${title}`);
+        dot.addEventListener('click', () => scrollToCard(index));
+        dotsContainer.appendChild(dot);
+        return dot;
+      });
+
+      function scrollToCard(index) {
+        const clamped = Math.max(0, Math.min(cards.length - 1, index));
+        const target = cards[clamped];
+        if (!target) return;
+        const left = target.offsetLeft - carousel.offsetLeft - 6;
+        carousel.scrollTo({ left, behavior: 'smooth' });
+        setActiveIndicator(clamped);
+      }
+
+      function setActiveIndicator(index) {
+        activeCardIndex = index;
+        dots.forEach((dot, idx) => {
+          const isCurrent = idx === index;
+          dot.classList.toggle('is-active', isCurrent);
+          dot.setAttribute('aria-selected', isCurrent ? 'true' : 'false');
+        });
+        const maxScrollLeft = carousel.scrollWidth - carousel.clientWidth;
+        prevBtn.disabled = carousel.scrollLeft <= 8 && index === 0;
+        nextBtn.disabled = carousel.scrollLeft >= maxScrollLeft - 8 && index >= cards.length - 1;
+      }
+
+      function updateActiveFromScroll() {
+        const scrollCenter = carousel.scrollLeft + carousel.clientWidth * 0.35;
+        let closestIndex = 0;
+        let minDistance = Infinity;
+        cards.forEach((card, idx) => {
+          const cardStart = card.offsetLeft - carousel.offsetLeft;
+          const dist = Math.abs(cardStart - scrollCenter);
+          if (dist < minDistance) {
+            minDistance = dist;
+            closestIndex = idx;
+          }
+        });
+        setActiveIndicator(closestIndex);
+      }
+
+      carousel.addEventListener('scroll', () => {
+        window.requestAnimationFrame(updateActiveFromScroll);
+      }, { passive: true });
+
+      prevBtn.addEventListener('click', () => {
+        scrollToCard(activeCardIndex - 1);
+      });
+
+      nextBtn.addEventListener('click', () => {
+        scrollToCard(activeCardIndex + 1);
+      });
+
+      // Keyboard operability on carousel track and cards
+      carousel.addEventListener('keydown', (e) => {
+        if (e.key === 'ArrowRight') {
+          e.preventDefault();
+          scrollToCard(activeCardIndex + 1);
+        } else if (e.key === 'ArrowLeft') {
+          e.preventDefault();
+          scrollToCard(activeCardIndex - 1);
+        } else if (e.key === 'Home') {
+          e.preventDefault();
+          scrollToCard(0);
+        } else if (e.key === 'End') {
+          e.preventDefault();
+          scrollToCard(cards.length - 1);
+        }
+      });
+
+      // Pointer / Mouse / Touch Drag-to-Swipe Support
+      let isPointerDown = false;
+      let hasDragged = false;
+      let startX = 0;
+      let startScrollLeft = 0;
+
+      carousel.addEventListener('pointerdown', (e) => {
+        if (e.pointerType === 'mouse' && e.button !== 0) return;
+        if (e.target.closest('a, button')) return;
+        isPointerDown = true;
+        hasDragged = false;
+        startX = e.clientX;
+        startScrollLeft = carousel.scrollLeft;
+        carousel.classList.add('is-dragging');
+        carousel.setPointerCapture(e.pointerId);
+      });
+
+      carousel.addEventListener('pointermove', (e) => {
+        if (!isPointerDown) return;
+        const deltaX = e.clientX - startX;
+        if (Math.abs(deltaX) > 5) {
+          hasDragged = true;
+        }
+        carousel.scrollLeft = startScrollLeft - deltaX;
+      });
+
+      function endPointerDrag(e) {
+        if (!isPointerDown) return;
+        isPointerDown = false;
+        carousel.classList.remove('is-dragging');
+        if (e && e.pointerId !== undefined && carousel.hasPointerCapture(e.pointerId)) {
+          carousel.releasePointerCapture(e.pointerId);
+        }
+        updateActiveFromScroll();
+      }
+
+      carousel.addEventListener('pointerup', endPointerDrag);
+      carousel.addEventListener('pointercancel', endPointerDrag);
+
+      updateActiveFromScroll();
+      window.addEventListener('resize', updateActiveFromScroll);
+
+      /* --- Expander Detail View Morphing Right Out of the Triggering Button --- */
+      const expander = document.getElementById('detail-expander');
+      const backdrop = document.getElementById('detail-backdrop');
+      const closeBtn = document.getElementById('detail-close-btn');
+      const dismissBtn = document.getElementById('detail-dismiss-btn');
+      const orderLink = document.getElementById('detail-order-link');
+      const sizeBtns = Array.from(expander.querySelectorAll('.size-btn'));
+      const triggers = Array.from(document.querySelectorAll('.view-details-trigger'));
+
+      let activeTrigger = null;
+      let isExpanded = false;
+      let closeTimer = null;
+
+      function getTargetModalBox() {
+        const vw = window.innerWidth;
+        const vh = window.innerHeight;
+        const width = Math.min(540, vw - 32);
+        const height = Math.min(620, vh - 40);
+        const left = Math.round((vw - width) / 2);
+        const top = Math.round((vh - height) / 2);
+        return { top, left, width, height };
+      }
+
+      function applyBox(rect, borderRadius, bgColor) {
+        expander.style.top = `${rect.top}px`;
+        expander.style.left = `${rect.left}px`;
+        expander.style.width = `${rect.width}px`;
+        expander.style.height = `${rect.height}px`;
+        expander.style.borderRadius = borderRadius;
+        if (bgColor) {
+          expander.style.backgroundColor = bgColor;
+        }
+      }
+
+      function populateDetails(drinkId) {
+        const data = DRINK_DATA[drinkId] || DRINK_DATA['maple-oat-latte'];
+        document.getElementById('detail-title').textContent = data.title;
+        document.getElementById('detail-badge').textContent = data.badge;
+        document.getElementById('detail-price').textContent = data.price;
+        const img = document.getElementById('detail-image');
+        img.src = data.image;
+        img.alt = data.imageAlt;
+        document.getElementById('detail-desc').textContent = data.description;
+        document.getElementById('detail-caffeine').textContent = data.caffeine;
+        document.getElementById('detail-calories').textContent = data.calories;
+        document.getElementById('detail-roast').textContent = data.roast;
+        orderLink.href = data.href;
+        orderLink.textContent = `Order ${data.title}`;
+
+        const notesList = document.getElementById('detail-notes');
+        notesList.innerHTML = '';
+        data.notes.forEach((note) => {
+          const li = document.createElement('li');
+          li.textContent = note;
+          notesList.appendChild(li);
+        });
+      }
+
+      function openDetailsFromButton(buttonEl) {
+        if (closeTimer) {
+          clearTimeout(closeTimer);
+          closeTimer = null;
+        }
+
+        const drinkId = buttonEl.getAttribute('data-drink-id');
+        populateDetails(drinkId);
+
+        if (activeTrigger && activeTrigger !== buttonEl) {
+          activeTrigger.setAttribute('aria-expanded', 'false');
+        }
+
+        activeTrigger = buttonEl;
+        activeTrigger.setAttribute('aria-expanded', 'true');
+        isExpanded = true;
+
+        // 1. Measure the exact coordinates of the button that triggered it
+        const btnRect = buttonEl.getBoundingClientRect();
+        const computedBtn = window.getComputedStyle(buttonEl);
+
+        // 2. Snap expander to the exact button geometry without transition
+        expander.classList.add('no-transition');
+        expander.classList.remove('is-open', 'is-closing');
+        expander.classList.add('is-animating');
+        expander.setAttribute('aria-hidden', 'false');
+        backdrop.setAttribute('aria-hidden', 'false');
+
+        applyBox(
+          {
+            top: btnRect.top,
+            left: btnRect.left,
+            width: btnRect.width,
+            height: btnRect.height
+          },
+          computedBtn.borderRadius || '8px',
+          '#4e342e'
+        );
+
+        // Force synchronous reflow so the browser registers the starting button box
+        void expander.offsetWidth;
+
+        // 3. Smoothly transition from the button rect out into the expanded detail card
+        expander.classList.remove('no-transition');
+        backdrop.classList.add('is-open');
+        const targetBox = getTargetModalBox();
+        applyBox(targetBox, '18px', '#ffffff');
+        expander.classList.add('is-open');
+
+        // Move keyboard focus into the expanded dialog
+        setTimeout(() => {
+          if (isExpanded) {
+            closeBtn.focus({ preventScroll: true });
+          }
+        }, 120);
+      }
+
+      function closeDetailsToButton() {
+        if (!isExpanded) return;
+        isExpanded = false;
+
+        expander.classList.add('is-closing');
+        expander.classList.remove('is-open');
+        backdrop.classList.remove('is-open');
+        expander.setAttribute('aria-hidden', 'true');
+        backdrop.setAttribute('aria-hidden', 'true');
+
+        if (activeTrigger) {
+          activeTrigger.setAttribute('aria-expanded', 'false');
+          const btnRect = activeTrigger.getBoundingClientRect();
+          const computedBtn = window.getComputedStyle(activeTrigger);
+          applyBox(
+            {
+              top: btnRect.top,
+              left: btnRect.left,
+              width: btnRect.width,
+              height: btnRect.height
+            },
+            computedBtn.borderRadius || '8px',
+            '#4e342e'
+          );
+        }
+
+        const triggerToFocus = activeTrigger;
+        closeTimer = setTimeout(() => {
+          expander.classList.remove('is-animating', 'is-closing');
+          if (triggerToFocus && typeof triggerToFocus.focus === 'function') {
+            triggerToFocus.focus({ preventScroll: true });
+          }
+        }, 420);
+      }
+
+      triggers.forEach((btn) => {
+        btn.addEventListener('click', (e) => {
+          e.preventDefault();
+          openDetailsFromButton(btn);
+        });
+
+        // Allow Spacebar activation in addition to Enter since role="button"
+        btn.addEventListener('keydown', (e) => {
+          if (e.key === ' ' || e.key === 'Spacebar') {
+            e.preventDefault();
+            btn.classList.add('is-pressed');
+            openDetailsFromButton(btn);
+          }
+        });
+
+        btn.addEventListener('keyup', (e) => {
+          if (e.key === ' ' || e.key === 'Spacebar') {
+            btn.classList.remove('is-pressed');
+          }
+        });
+      });
+
+      closeBtn.addEventListener('click', closeDetailsToButton);
+      dismissBtn.addEventListener('click', closeDetailsToButton);
+      backdrop.addEventListener('click', closeDetailsToButton);
+
+      // Size selection buttons with ARIA pressed feedback
+      sizeBtns.forEach((btn) => {
+        btn.addEventListener('click', () => {
+          sizeBtns.forEach((b) => b.setAttribute('aria-pressed', b === btn ? 'true' : 'false'));
+        });
+      });
+
+      // Reposition expanded detail view on viewport resize
+      window.addEventListener('resize', () => {
+        if (!isExpanded) return;
+        expander.classList.add('no-transition');
+        applyBox(getTargetModalBox(), '18px', '#ffffff');
+        void expander.offsetWidth;
+        expander.classList.remove('no-transition');
+      });
+
+      // Keyboard Escape & Focus Trap inside expanded detail dialog
+      document.addEventListener('keydown', (e) => {
+        if (!isExpanded) return;
+        if (e.key === 'Escape') {
+          e.preventDefault();
+          closeDetailsToButton();
+          return;
+        }
+        if (e.key === 'Tab') {
+          const focusables = Array.from(
+            expander.querySelectorAll('button, [href], [tabindex]:not([tabindex="-1"])')
+          ).filter((el) => !el.disabled);
+          if (focusables.length === 0) return;
+          const first = focusables[0];
+          const last = focusables[focusables.length - 1];
+          if (e.shiftKey && document.activeElement === first) {
+            e.preventDefault();
+            last.focus();
+          } else if (!e.shiftKey && document.activeElement === last) {
+            e.preventDefault();
+            first.focus();
+          }
+        }
+      });
+    })();
+  </script>
