+      id: 'Y3JlZC1nb29nbGUtMDI',
+      passkeyUserId: DEFAULT_USER_ID,
+      credentialPublicKey: 'pQECAyYgASFYIJV8Z2RhaWx5LWdyaW5kLXB1YmxpYy1rZXktMDJYIlggZGFpbHktZ3JpbmQ',
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+      name: 'Google Password Manager',
+      transports: ['internal', 'hybrid'],
+      registeredAt: 1778803200000,
+      lastUsedAt: 1794139200000,
+      counter: 8,
+    },
+    {
+      id: 'Y3JlZC0xcGFzc3dvcmQtMDM',
+      passkeyUserId: DEFAULT_USER_ID,
+      credentialPublicKey: 'pQECAyYgASFYIJV8Z2RhaWx5LWdyaW5kLXB1YmxpYy1rZXktMDNYIlggZGFpbHktZ3JpbmQ',
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: 'bada5566-a7aa-401f-bd96-45619a55120d',
+      name: '1Password — Personal Vault',
+      transports: ['internal', 'hybrid'],
+      registeredAt: 1784073600000,
+      lastUsedAt: 1792065600000,
+      counter: 3,
+    },
+  ],
+};
+
+const deletedIds = new Set();
+const renamedMap = new Map();
+const addedCredentials = [];
+let userState = { ...SEED_DATA.user };
+let currentServerRpId = RP_ID;
+let currentServerUserId = DEFAULT_USER_ID;
+
+function jsonResponse(payload, status = 200) {
+  return new Response(JSON.stringify(payload), {
+    status,
+    headers: { 'Content-Type': 'application/json' },
+  });
+}
+
+function applyLocalState(data) {
+  const rpId = data.rpId || RP_ID;
+  const userId = data.userId || DEFAULT_USER_ID;
+  currentServerRpId = rpId;
+  currentServerUserId = userId;
+
+  const baseCredentials = Array.isArray(data.credentials) ? data.credentials : SEED_DATA.credentials;
+  const mergedCredentials = baseCredentials
+    .filter((cred) => !deletedIds.has(cred.id))
+    .map((cred) => ({
+      ...cred,
+      name: renamedMap.has(cred.id) ? renamedMap.get(cred.id) : cred.name,
+    }));
+
+  for (const added of addedCredentials) {
+    if (!deletedIds.has(added.id) && !mergedCredentials.some((c) => c.id === added.id)) {
+      mergedCredentials.push({
+        ...added,
+        name: renamedMap.has(added.id) ? renamedMap.get(added.id) : added.name,
+      });
+    }
+  }
+
+  return {
+    rpId,
+    userId,
+    user: {
+      ...(data.user || userState),
+      name: userState.name,
+      displayName: userState.displayName,
+    },
+    credentials: mergedCredentials,
+  };
+}
+
+export async function listFetch() {
+  try {
+    const response = await fetch('/api/credentials', {
+      headers: { Accept: 'application/json' },
+    });
+    if (response.ok) {
+      const data = await response.json();
+      return jsonResponse(applyLocalState(data), 200);
+    }
+  } catch {
+    // Fallback to local state when static server is unreachable
+  }
+  return jsonResponse(applyLocalState(SEED_DATA), 200);
+}
+
+export async function renameCredentialFetch(credentialId, { name }) {
+  renamedMap.set(credentialId, name);
+  try {
+    const response = await fetch(`/api/credential/${encodeURIComponent(credentialId)}`, {
+      method: 'PUT',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ name }),
+    });
+    if (response.ok) {
+      return response;
+    }
+  } catch {
+    // Fallback for static server
+  }
+  return jsonResponse({ id: credentialId, passkeyUserId: currentServerUserId, name }, 200);
+}
+
+export async function deleteFetch(credentialId) {
+  deletedIds.add(credentialId);
+  try {
+    const response = await fetch(`/api/credential/${encodeURIComponent(credentialId)}`, {
+      method: 'DELETE',
+    });
+    if (response.ok) {
+      return response;
+    }
+  } catch {
+    // Fallback for static server
+  }
+  return jsonResponse({ success: true }, 200);
+}
+
+export async function updateUserFetch({ name, displayName }) {
+  userState = {
+    ...userState,
+    name,
+    displayName,
+  };
+  try {
+    const response = await fetch('/api/user', {
+      method: 'PUT',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ name, displayName }),
+    });
+    if (response.ok) {
+      return response;
+    }
+  } catch {
+    // Fallback for static server
+  }
+  return jsonResponse(
+    {
+      ...userState,
+      rpId: currentServerRpId,
+      userId: currentServerUserId,
+    },
+    200
+  );
+}
+
+export async function optionsFetch({ promotion = false } = {}) {
+  try {
+    const response = await fetch('/api/register/options', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ promotion }),
+    });
+    if (response.ok) {
+      return await response.json();
+    }
+  } catch {
+    // Fallback for static server
+  }
+
+  const currentData = applyLocalState(SEED_DATA);
+  const challengeBytes = new Uint8Array(32);
+  if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
+    crypto.getRandomValues(challengeBytes);
+  }
+  let binary = '';
+  for (let i = 0; i < challengeBytes.length; i++) {
+    binary += String.fromCharCode(challengeBytes[i]);
+  }
+  const challenge = btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+
+  return {
+    challenge,
+    rp: {
+      id: currentData.rpId,
+      name: 'The Daily Grind Coffee Co.',
+    },
+    user: {
+      id: currentData.userId,
+      name: userState.name,
+      displayName: userState.displayName,
+    },
+    pubKeyCredParams: [
+      { type: 'public-key', alg: -7 },
+      { type: 'public-key', alg: -257 },
+    ],
+    excludeCredentials: currentData.credentials.map((cred) => ({
+      type: 'public-key',
+      id: cred.id,
+      transports: cred.transports,
+    })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+      ...(promotion && { authenticatorAttachment: 'platform' }),
+    },
+  };
+}
+
+export async function registerVerifyFetch(encodedResponse) {
+  const response = await fetch('/api/register/verify', {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify(encodedResponse),
+  });
+
+  if (response.ok) {
+    const newCred = await response.json();
+    if (newCred && newCred.id) {
+      addedCredentials.push(newCred);
+    }
+    return response;
+  }
+
+  // If static server returned 404 or 405 (no backend route), synthesize verification
+  if (response.status === 404 || response.status === 405) {
+    const aaguid = encodedResponse.aaguid || 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd';
+    let name = 'Unknown passkey provider';
+    let providerIcon = undefined;
+    if (aaguid !== '00000000-0000-0000-0000-000000000000') {
+      const provider = aaguids[aaguid];
+      name = provider?.name || 'Unknown passkey provider';
+      providerIcon = provider?.icon_light;
+    }
+
+    const createdCredential = {
+      id: encodedResponse.id || 'Y3JlZC1uZXctcGFzc2tleQ',
+      passkeyUserId: currentServerUserId,
+      credentialPublicKey: 'pQECAyYgASFYIJV8Z2RhaWx5LWdyaW5kLXB1YmxpYy1rZXktMDRYIlggZGFpbHktZ3JpbmQ',
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid,
+      name,
+      providerIcon,
+      transports: encodedResponse.response?.transports || ['internal', 'hybrid'],
+      registeredAt: Date.now(),
+      lastUsedAt: Date.now(),
+      counter: 0,
+    };
+    addedCredentials.push(createdCredential);
+    return jsonResponse(createdCredential, 200);
+  }
+
+  return response;
+}
