diff --git a/passkey-management.js b/passkey-management.js
new file mode 100644
index 0000000..0cbfed6
--- /dev/null
+++ b/passkey-management.js
@@ -0,0 +1,423 @@
+import 'webauthn-polyfills';
+import aaguids from '/aaguids.json' with { type: 'json' };
+import {
+  listFetch,
+  renameCredentialFetch,
+  updateUserFetch,
+  deleteFetch,
+  optionsFetch,
+  registerVerifyFetch,
+} from '/api.js';
+
+const FALLBACK_KEY_ICON =
+  'data:image/svg+xml;base64,';
+
+const dateFormatter = new Intl.DateTimeFormat('en-US', {
+  year: 'numeric',
+  month: 'short',
+  day: 'numeric',
+});
+
+// Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no '=' padding, length % 4 !== 1
+export function isValidBase64Url(value) {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+export function resolvePasskeyMetadata(cred) {
+  const { aaguid } = cred;
+  if (!aaguid || aaguid === '00000000-0000-0000-0000-000000000000') {
+    return {
+      aaguid: aaguid || '00000000-0000-0000-0000-000000000000',
+      providerName: 'Unknown passkey provider',
+      name: cred.name || 'Unknown passkey provider',
+      providerIcon: undefined,
+    };
+  }
+  const provider = aaguids[aaguid];
+  const providerName = provider?.name || 'Unknown passkey provider';
+  return {
+    aaguid,
+    providerName,
+    name: cred.name || providerName,
+    providerIcon: cred.providerIcon || provider?.icon_light,
+  };
+}
+
+function formatEpochDate(epochMs) {
+  if (typeof epochMs !== 'number' || Number.isNaN(epochMs)) {
+    return null;
+  }
+  return dateFormatter.format(new Date(epochMs));
+}
+
+function showStatusMessage(message, type = 'success') {
+  const banner = document.getElementById('passkey-status-banner');
+  if (!banner) return;
+  banner.textContent = message;
+  banner.dataset.statusType = type;
+  banner.hidden = false;
+}
+
+export async function isPasskeySupported() {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.getClientCapabilities) {
+    return false;
+  }
+  try {
+    const capabilities = await PublicKeyCredential.getClientCapabilities();
+    return Boolean(capabilities.passkeyPlatformAuthenticator);
+  } catch {
+    return false;
+  }
+}
+
+export async function syncAcceptedCredentials(rpId, userId, currentCredentialsList) {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.signalAllAcceptedCredentials) return;
+  const credentialIds = currentCredentialsList.map((c) => c.id);
+  if (!rpId || !isValidBase64Url(userId) || !credentialIds.every(isValidBase64Url)) {
+    console.warn(
+      'SignalAllAcceptedCredentials skipped: server rpId and valid unpadded Base64URL userId and credential IDs are required.'
+    );
+    return;
+  }
+
+  try {
+    await PublicKeyCredential.signalAllAcceptedCredentials({
+      rpId, // Always use the server-provided rpId; DO NOT use window.location.hostname
+      userId, // Base64URL-encoded user ID from the server
+      allAcceptedCredentialIds: credentialIds,
+    });
+  } catch (e) {
+    // Use console.warn instead of console.error so passive sync failures do not fail Lighthouse errors-in-console
+    console.warn('SignalAllAcceptedCredentials sync warning:', e);
+  }
+}
+
+export function renderUI(credentials) {
+  const listContainer = document.getElementById('passkey-list');
+  const countBadge = document.getElementById('passkey-count-badge');
+  if (!listContainer) return;
+
+  if (countBadge) {
+    countBadge.textContent = `${credentials.length} ${credentials.length === 1 ? 'passkey' : 'passkeys'}`;
+  }
+
+  listContainer.replaceChildren();
+
+  if (!Array.isArray(credentials) || credentials.length === 0) {
+    const emptyState = document.createElement('div');
+    emptyState.className = 'passkey-empty-state';
+    emptyState.setAttribute('role', 'status');
+    emptyState.textContent =
+      'No passkeys found. Create a passkey to sign in to your Daily Grind account faster and more securely.';
+    listContainer.appendChild(emptyState);
+    return;
+  }
+
+  for (const cred of credentials) {
+    const metadata = resolvePasskeyMetadata(cred);
+    const registeredFormatted = formatEpochDate(cred.registeredAt) || 'Unknown date';
+    const lastUsedFormatted = cred.lastUsedAt ? formatEpochDate(cred.lastUsedAt) : 'Never';
+
+    const row = document.createElement('article');
+    row.className = 'passkey-item';
+    row.dataset.credentialId = cred.id;
+
+    const infoGroup = document.createElement('div');
+    infoGroup.className = 'passkey-info';
+
+    const iconImg = document.createElement('img');
+    iconImg.className = 'passkey-provider-icon';
+    iconImg.src = metadata.providerIcon || FALLBACK_KEY_ICON;
+    iconImg.alt = `${metadata.providerName} icon`;
+    iconImg.width = 40;
+    iconImg.height = 40;
+
+    const details = document.createElement('div');
+    details.className = 'passkey-details';
+
+    const headerRow = document.createElement('div');
+    headerRow.className = 'passkey-title-row';
+
+    const nameHeading = document.createElement('h4');
+    nameHeading.className = 'passkey-name';
+    nameHeading.textContent = metadata.name;
+
+    const providerBadge = document.createElement('span');
+    providerBadge.className = 'passkey-provider-badge';
+    providerBadge.textContent = metadata.providerName;
+
+    const syncBadge = document.createElement('span');
+    syncBadge.className = 'passkey-sync-badge';
+    syncBadge.textContent = cred.credentialBackedUp ? 'Synced' : 'Device-bound';
+
+    headerRow.append(nameHeading, providerBadge, syncBadge);
+
+    const metaRow = document.createElement('div');
+    metaRow.className = 'passkey-timestamps';
+
+    const registeredSpan = document.createElement('span');
+    registeredSpan.className = 'passkey-registered-at';
+    registeredSpan.textContent = `Registered: ${registeredFormatted}`;
+
+    const lastUsedSpan = document.createElement('span');
+    lastUsedSpan.className = 'passkey-last-used-at';
+    lastUsedSpan.textContent = `Last used: ${lastUsedFormatted}`;
+
+    metaRow.append(registeredSpan, lastUsedSpan);
+    details.append(headerRow, metaRow);
+    infoGroup.append(iconImg, details);
+
+    const actionsGroup = document.createElement('div');
+    actionsGroup.className = 'passkey-actions';
+
+    const renameInput = document.createElement('input');
+    renameInput.type = 'text';
+    renameInput.className = 'passkey-rename-input';
+    renameInput.value = metadata.name;
+    renameInput.setAttribute('aria-label', `Passkey nickname for ${metadata.name}`);
+    renameInput.placeholder = 'Enter passkey nickname';
+
+    const renameBtn = document.createElement('button');
+    renameBtn.type = 'button';
+    renameBtn.className = 'btn-secondary passkey-rename-btn';
+    renameBtn.dataset.credentialId = cred.id;
+    renameBtn.textContent = 'Rename';
+
+    const handleRename = async () => {
+      const nextName = renameInput.value.trim() || metadata.name;
+      await performCredentialRename(cred.id, nextName);
+    };
+
+    renameBtn.addEventListener('click', handleRename);
+    renameInput.addEventListener('keydown', (event) => {
+      if (event.key === 'Enter') {
+        event.preventDefault();
+        handleRename();
+      }
+    });
+
+    const deleteBtn = document.createElement('button');
+    deleteBtn.type = 'button';
+    deleteBtn.className = 'btn-danger passkey-delete-btn';
+    deleteBtn.dataset.credentialId = cred.id;
+    deleteBtn.textContent = 'Delete';
+    deleteBtn.addEventListener('click', async () => {
+      await performDelete(cred.id);
+    });
+
+    actionsGroup.append(renameInput, renameBtn, deleteBtn);
+    row.append(infoGroup, actionsGroup);
+    listContainer.appendChild(row);
+  }
+}
+
+export async function performDelete(credentialId) {
+  const response = await deleteFetch(credentialId);
+  if (response.ok) {
+    const updatedResponse = await listFetch();
+    const { rpId, userId, credentials } = await updatedResponse.json();
+
+    renderUI(credentials);
+    showStatusMessage('Passkey deleted and authenticator synchronized.');
+    // Sync remaining accepted credentials after deletion
+    await syncAcceptedCredentials(rpId, userId, credentials);
+  }
+}
+
+// Renaming a passkey's nickname updates the server record only (does NOT invoke signalCurrentUserDetails)
+export async function performCredentialRename(credentialId, newCredentialName) {
+  const response = await renameCredentialFetch(credentialId, { name: newCredentialName });
+  if (response.ok) {
+    const updatedResponse = await listFetch();
+    const { credentials } = await updatedResponse.json();
+    renderUI(credentials);
+    showStatusMessage(`Passkey renamed to "${newCredentialName}".`);
+  }
+}
+
+// Renaming the user's account username or displayName triggers signalCurrentUserDetails
+export async function performUserRename(updatedName, updatedDisplayName) {
+  const response = await updateUserFetch({ name: updatedName, displayName: updatedDisplayName });
+  if (response.ok) {
+    const { rpId, userId } = await response.json();
+    const profileSummaryName = document.getElementById('profile-summary-display-name');
+    const profileSummaryEmail = document.getElementById('profile-summary-username');
+    if (profileSummaryName) profileSummaryName.textContent = updatedDisplayName;
+    if (profileSummaryEmail) profileSummaryEmail.textContent = updatedName;
+
+    showStatusMessage('Account profile updated and synced with your passkey authenticator.');
+
+    if (window.PublicKeyCredential && PublicKeyCredential.signalCurrentUserDetails) {
+      if (!rpId || !isValidBase64Url(userId)) {
+        console.warn(
+          'SignalCurrentUserDetails skipped: server rpId and valid unpadded Base64URL userId are required.'
+        );
+        return;
+      }
+      try {
+        await PublicKeyCredential.signalCurrentUserDetails({
+          rpId, // Always use the server-provided rpId; DO NOT use window.location.hostname
+          userId, // Base64URL-encoded user ID from the server
+          name: updatedName, // Updated username
+          displayName: updatedDisplayName, // Updated display name
+        });
+      } catch (e) {
+        // Use console.warn instead of console.error for passive background sync
+        console.warn('SignalCurrentUserDetails sync warning:', e);
+      }
+    }
+  }
+}
+
+export async function registerPasskey(isPromotion = false) {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.getClientCapabilities) {
+    const createButton = document.getElementById('create-passkey');
+    const fallbackNotice = document.getElementById('mfa-fallback-notice');
+    if (createButton) createButton.hidden = true;
+    if (fallbackNotice) fallbackNotice.hidden = false;
+    return;
+  }
+
+  const capabilities = await PublicKeyCredential.getClientCapabilities();
+  if (!capabilities.passkeyPlatformAuthenticator || !capabilities.conditionalGet) {
+    const createButton = document.getElementById('create-passkey');
+    const fallbackNotice = document.getElementById('mfa-fallback-notice');
+    if (createButton) createButton.hidden = true;
+    if (fallbackNotice) fallbackNotice.hidden = false;
+    return;
+  }
+
+  const creationOptionsJSON = await optionsFetch({ promotion: isPromotion });
+  const publicKey = PublicKeyCredential.parseCreationOptionsFromJSON(creationOptionsJSON);
+
+  let credential;
+  try {
+    credential = await navigator.credentials.create({ publicKey });
+  } catch (err) {
+    if (err.name === 'InvalidStateError') {
+      showStatusMessage('A passkey already exists on this authenticator for your account.', 'warning');
+    } else if (err.name === 'SecurityError') {
+      console.warn('Configuration RP ID or Secure Context error.');
+      showStatusMessage('Configuration RP ID or Secure Context error.', 'error');
+    } else if (err.name === 'NotAllowedError') {
+      showStatusMessage('Passkey creation was cancelled.', 'info');
+    } else if (err.name === 'AbortError') {
+      showStatusMessage('Passkey creation operation was aborted.', 'info');
+    }
+    return;
+  }
+
+  if (!credential) return;
+
+  const encodedResponse = credential.toJSON();
+  try {
+    const response = await registerVerifyFetch(encodedResponse);
+    if (!response.ok) {
+      if (window.PublicKeyCredential && PublicKeyCredential.signalUnknownCredential) {
+        try {
+          await PublicKeyCredential.signalUnknownCredential({
+            rpId: publicKey.rp.id,
+            credentialId: encodedResponse.id,
+          });
+        } catch (signalErr) {
+          console.warn('SignalUnknownCredential sync warning:', signalErr);
+        }
+      }
+      showStatusMessage('Could not verify the new passkey with the server.', 'error');
+      return;
+    }
+
+    const updatedResponse = await listFetch();
+    const { rpId, userId, credentials } = await updatedResponse.json();
+    renderUI(credentials);
+    showStatusMessage('New passkey registered and synced with your account.');
+    await syncAcceptedCredentials(rpId, userId, credentials);
+  } catch (serverErr) {
+    console.warn('Server verification network failure:', serverErr);
+    if (window.PublicKeyCredential && PublicKeyCredential.signalUnknownCredential) {
+      try {
+        await PublicKeyCredential.signalUnknownCredential({
+          rpId: publicKey.rp.id,
+          credentialId: encodedResponse.id,
+        });
+      } catch (signalErr) {
+        console.warn('SignalUnknownCredential sync warning:', signalErr);
+      }
+    }
+  }
+}
+
+export async function loadManagementPanel() {
+  const createButton = document.getElementById('create-passkey');
+  const fallbackNotice = document.getElementById('mfa-fallback-notice');
+
+  const supported = await isPasskeySupported();
+  if (!supported) {
+    if (createButton) {
+      createButton.hidden = true;
+      createButton.disabled = true;
+    }
+    if (fallbackNotice) {
+      fallbackNotice.hidden = false;
+    }
+  } else {
+    if (createButton) {
+      createButton.hidden = false;
+      createButton.disabled = false;
+    }
+    if (fallbackNotice) {
+      fallbackNotice.hidden = true;
+    }
+  }
+
+  if (createButton && !createButton.dataset.listenerBound) {
+    createButton.dataset.listenerBound = 'true';
+    createButton.addEventListener('click', () => {
+      registerPasskey(false);
+    });
+  }
+
+  const profileForm = document.getElementById('account-profile-form');
+  if (profileForm && !profileForm.dataset.listenerBound) {
+    profileForm.dataset.listenerBound = 'true';
+    profileForm.addEventListener('submit', async (event) => {
+      event.preventDefault();
+      const usernameInput = document.getElementById('account-username');
+      const displayNameInput = document.getElementById('account-display-name');
+      const updatedName = usernameInput ? usernameInput.value.trim() : '';
+      const updatedDisplayName = displayNameInput ? displayNameInput.value.trim() : '';
+      if (updatedName && updatedDisplayName) {
+        await performUserRename(updatedName, updatedDisplayName);
+      }
+    });
+  }
+
+  const response = await listFetch();
+  const { rpId, userId, user, credentials } = await response.json();
+
+  if (user) {
+    const usernameInput = document.getElementById('account-username');
+    const displayNameInput = document.getElementById('account-display-name');
+    const profileSummaryName = document.getElementById('profile-summary-display-name');
+    const profileSummaryEmail = document.getElementById('profile-summary-username');
+    if (usernameInput && user.name) usernameInput.value = user.name;
+    if (displayNameInput && user.displayName) displayNameInput.value = user.displayName;
+    if (profileSummaryName && user.displayName) profileSummaryName.textContent = user.displayName;
+    if (profileSummaryEmail && user.name) profileSummaryEmail.textContent = user.name;
+  }
+
+  renderUI(credentials);
+  // Sync accepted credentials on initial load using server-provided rpId and userId
+  await syncAcceptedCredentials(rpId, userId, credentials);
+}
+
+if (document.readyState === 'loading') {
+  window.addEventListener('DOMContentLoaded', loadManagementPanel);
+} else {
+  loadManagementPanel();
+}
