+// WebAuthn polyfills for PublicKeyCredential JSON serialization and getClientCapabilities
+function base64UrlToUint8Array(base64Url) {
+  const padding = '='.repeat((4 - (base64Url.length % 4)) % 4);
+  const base64 = (base64Url + padding).replace(/-/g, '+').replace(/_/g, '/');
+  const rawData = atob(base64);
+  const outputArray = new Uint8Array(rawData.length);
+  for (let i = 0; i < rawData.length; ++i) {
+    outputArray[i] = rawData.charCodeAt(i);
+  }
+  return outputArray;
+}
+
+function bufferToBase64Url(buffer) {
+  if (!buffer) return undefined;
+  const bytes = new Uint8Array(buffer);
+  let binary = '';
+  for (let i = 0; i < bytes.byteLength; i++) {
+    binary += String.fromCharCode(bytes[i]);
+  }
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+if (typeof window !== 'undefined' && window.PublicKeyCredential) {
+  if (!PublicKeyCredential.getClientCapabilities) {
+    PublicKeyCredential.getClientCapabilities = async function getClientCapabilities() {
+      let uvpaa = false;
+      let conditionalMediation = false;
+      try {
+        if (PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable) {
+          uvpaa = await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
+        }
+      } catch {
+        uvpaa = false;
+      }
+      try {
+        if (PublicKeyCredential.isConditionalMediationAvailable) {
+          conditionalMediation = await PublicKeyCredential.isConditionalMediationAvailable();
+        }
+      } catch {
+        conditionalMediation = false;
+      }
+      return {
+        conditionalCreate: false,
+        conditionalGet: Boolean(conditionalMediation),
+        hybridTransport: true,
+        passkeyPlatformAuthenticator: Boolean(uvpaa),
+        relatedOrigins: true,
+        signalAllAcceptedCredentials: Boolean(PublicKeyCredential.signalAllAcceptedCredentials),
+        signalCurrentUserDetails: Boolean(PublicKeyCredential.signalCurrentUserDetails),
+        signalUnknownCredential: Boolean(PublicKeyCredential.signalUnknownCredential),
+        userVerifyingPlatformAuthenticator: Boolean(uvpaa),
+      };
+    };
+  }
+
+  if (!PublicKeyCredential.parseCreationOptionsFromJSON) {
+    PublicKeyCredential.parseCreationOptionsFromJSON = function parseCreationOptionsFromJSON(optionsJSON) {
+      const excludeCredentials = Array.isArray(optionsJSON.excludeCredentials)
+        ? optionsJSON.excludeCredentials.map((cred) => ({
+            ...cred,
+            id: base64UrlToUint8Array(cred.id).buffer,
+          }))
+        : [];
+      return {
+        ...optionsJSON,
+        challenge: base64UrlToUint8Array(optionsJSON.challenge).buffer,
+        user: {
+          ...optionsJSON.user,
+          id: base64UrlToUint8Array(optionsJSON.user.id).buffer,
+        },
+        excludeCredentials,
+      };
+    };
+  }
+
+  if (!PublicKeyCredential.parseRequestOptionsFromJSON) {
+    PublicKeyCredential.parseRequestOptionsFromJSON = function parseRequestOptionsFromJSON(optionsJSON) {
+      const allowCredentials = Array.isArray(optionsJSON.allowCredentials)
+        ? optionsJSON.allowCredentials.map((cred) => ({
+            ...cred,
+            id: base64UrlToUint8Array(cred.id).buffer,
+          }))
+        : [];
+      return {
+        ...optionsJSON,
+        challenge: base64UrlToUint8Array(optionsJSON.challenge).buffer,
+        allowCredentials,
+      };
+    };
+  }
+
+  if (!PublicKeyCredential.prototype.toJSON) {
+    PublicKeyCredential.prototype.toJSON = function toJSON() {
+      const response = this.response;
+      const serializedResponse = {
+        clientDataJSON: bufferToBase64Url(response.clientDataJSON),
+      };
+      if ('attestationObject' in response) {
+        serializedResponse.attestationObject = bufferToBase64Url(response.attestationObject);
+        if (typeof response.getTransports === 'function') {
+          serializedResponse.transports = response.getTransports();
+        }
+      }
+      if ('authenticatorData' in response) {
+        serializedResponse.authenticatorData = bufferToBase64Url(response.authenticatorData);
+      }
+      if ('signature' in response) {
+        serializedResponse.signature = bufferToBase64Url(response.signature);
+      }
+      if ('userHandle' in response && response.userHandle) {
+        serializedResponse.userHandle = bufferToBase64Url(response.userHandle);
+      }
+      return {
+        id: this.id,
+        rawId: bufferToBase64Url(this.rawId),
+        type: this.type,
+        authenticatorAttachment: this.authenticatorAttachment || undefined,
+        response: serializedResponse,
+        clientExtensionResults:
+          typeof this.getClientExtensionResults === 'function' ? this.getClientExtensionResults() : {},
+      };
+    };
+  }
+}

