+            if (window.crypto && window.crypto.getRandomValues) {
+              window.crypto.getRandomValues(challenge);
+            }
+            const excludeCredentials = state.passkeys.map(function (pk) {
+              return {
+                id: base64UrlToUint8Array(pk.credentialId),
+                type: 'public-key'
+              };
+            });
+
+            const cred = await navigator.credentials.create({
+              publicKey: {
+                challenge: challenge,
+                rp: {
+                  id: getRpId(),
+                  name: 'The Daily Grind'
+                },
+                user: {
+                  id: base64UrlToUint8Array(state.user.userId),
+                  name: state.user.name,
+                  displayName: state.user.displayName
+                },
+                pubKeyCredParams: [
+                  { type: 'public-key', alg: -7 },
+                  { type: 'public-key', alg: -257 }
+                ],
+                authenticatorSelection: {
+                  residentKey: 'required',
+                  userVerification: 'preferred'
+                },
+                excludeCredentials: excludeCredentials
+              }
+            });
+
+            if (cred && cred.id) {
+              credentialId = cred.id;
+            } else if (cred && cred.rawId) {
+              credentialId = bytesToBase64Url(cred.rawId);
+            }
+          } catch (err) {
+            // Fall back to generating a local credential ID if authenticator ceremony was not completed
+          }
+        }
+
+        if (!credentialId) {
+          const randomBytes = new Uint8Array(18);
+          if (window.crypto && window.crypto.getRandomValues) {
+            window.crypto.getRandomValues(randomBytes);
+          } else {
+            for (let i = 0; i < randomBytes.length; i++) {
+              randomBytes[i] = Math.floor(Math.random() * 256);
+            }
+          }
+          credentialId = bytesToBase64Url(randomBytes);
+        }
+
+        const today = new Date().toLocaleDateString('en-US', {
+          month: 'short',
+          day: '2-digit',
+          year: 'numeric'
+        });
+
+        const newPasskey = {
+          id: 'pk-' + Date.now(),
+          credentialId: credentialId,
+          name: defaultName,
+          aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+          providerName: 'Browser Authenticator',
+          createdAt: today,
+          lastUsedAt: 'Just now',
+          backedUp: true
+        };
