+        saveState();
+        renderPasskeys();
+        await signalAcceptedCredentialsToAuthenticator();
+        showToast('Added "' + newPasskey.name + '" and synced with your browser authenticator.');
+        return newPasskey;
+      }
+
+      function setupEventListeners() {
+        const listEl = document.getElementById('passkey-list');
+        if (listEl) {
+          listEl.addEventListener('click', function (e) {
