+            }
+          });
+
+          listEl.addEventListener('keydown', function (e) {
+            if (e.key === 'Escape' && editingCredentialId) {
+              editingCredentialId = null;
+              renderPasskeys();
+            }
+          });
+        }
+
+        const addBtn = document.getElementById('add-passkey-btn');
+        if (addBtn) {
