+              e.preventDefault();
+              try {
+                window.history.pushState({}, '', '/account');
+              } catch (_) {}
+              accountSection.scrollIntoView({ behavior: 'smooth' });
+              signalAcceptedCredentialsToAuthenticator();
+            }
+          });
+        }
+      }
+
+      // Expose passkey manager API for programmatic inspection/testing
+      window.passkeyManager = {
+        getState: function () {
+          return state;
+        },
+        getPasskeys: function () {
+          return state.passkeys.slice();
+        },
+        getUser: function () {
