+        },
+        renamePasskey: renamePasskey,
+        deletePasskey: deletePasskey,
+        registerNewPasskey: registerNewPasskey,
+        syncAuthenticator: signalAcceptedCredentialsToAuthenticator,
+        syncUserDetails: signalUserDetailsToAuthenticator
+      };
+
+      function init() {
+        renderProfile();
+        renderPasskeys();
+        setupEventListeners();
+        signalAcceptedCredentialsToAuthenticator();
+      }
+
+      if (document.readyState === 'loading') {
+        document.addEventListener('DOMContentLoaded', init);
+      } else {
+        init();
+      }
+    })();
+  </script>
+</body>
+
