+      async function renamePasskey(credentialId, newName) {
+        const trimmed = String(newName || '').trim();
+        if (!trimmed) return false;
+
+        const target = state.passkeys.find(function (pk) {
+          return pk.credentialId === credentialId || pk.id === credentialId;
+        });
+        if (!target) return false;
+
+        target.name = trimmed;
+        editingCredentialId = null;
+        saveState();
+        renderPasskeys();
+        showToast('Passkey renamed to "' + trimmed + '".');
+        return true;
+      }
+
+      async function deletePasskey(credentialId) {
+        const index = state.passkeys.findIndex(function (pk) {
+          return pk.credentialId === credentialId || pk.id === credentialId;
+        });
+        if (index === -1) return false;
+
+        const removed = state.passkeys.splice(index, 1)[0];
+        if (editingCredentialId === removed.credentialId) {
+          editingCredentialId = null;
+        }
+        saveState();
+        renderPasskeys();
+
+        await signalAcceptedCredentialsToAuthenticator(removed.credentialId);
