+            const cred = await navigator.credentials.create({
+              publicKey: {
+                challenge: challenge,
+                rp: {
+                  id: getRpId(),
+                  name: 'The Daily Grind'
+                },
+                user: {
+                  id: base64UrlToUint8Array(state.user.userId),
