+      {statusMessage && (
+        <div
+          role="status"
+          aria-live="polite"
+          className={`p-4 rounded-lg border text-sm flex items-start justify-between gap-3 ${
+            statusMessage.type === 'success'
+              ? 'bg-green-50 border-green-200 text-green-800'
+              : statusMessage.type === 'error'
+              ? 'bg-red-50 border-red-200 text-red-800'
+              : 'bg-blue-50 border-blue-200 text-blue-800'
+          }`}
+        >
+          <span>{statusMessage.text}</span>
+          <button
+            type="button"
+            onClick={() => setStatusMessage(null)}
+            className="text-xs font-semibold underline hover:opacity-80"
+          >
+            Dismiss
+          </button>
+        </div>
+      )}
+
+      {/* Reader Profile & Authenticator User Details Sync */}
+      <section
+        aria-labelledby="reader-profile-heading"
+        className="bg-white border border-gray-200 rounded-lg shadow-sm p-6"
+      >
+        <div className="mb-4">
+          <h2
+            id="reader-profile-heading"
+            className="text-xl font-bold text-gray-900"
+          >
+            Reader Profile
+          </h2>
+          <p className="text-sm text-gray-600 mt-1">
+            Updating your reader username or display name keeps your saved passkey entries in your browser authenticator up to date.
+          </p>
+        </div>
+
+        <form onSubmit={handleUserProfileRename} className="space-y-4">
+          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
+            <div>
+              <label
+                htmlFor="account-display-name"
+                className="block text-xs font-semibold uppercase tracking-wider text-gray-700 mb-1"
+              >
+                Display Name
+              </label>
+              <input
+                id="account-display-name"
+                name="displayName"
+                type="text"
+                required
+                value={accountDisplayName}
+                onChange={(e) => setAccountDisplayName(e.target.value)}
+                className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-gray-900"
+              />
+            </div>
+
+            <div>
+              <label
+                htmlFor="account-username"
+                className="block text-xs font-semibold uppercase tracking-wider text-gray-700 mb-1"
+              >
+                Username / Email
+              </label>
+              <input
+                id="account-username"
+                name="name"
+                type="text"
+                required
+                value={accountName}
+                onChange={(e) => setAccountName(e.target.value)}
+                className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-gray-900"
+              />
+            </div>
+          </div>
+
+          <div className="flex justify-end">
+            <button
+              type="submit"
+              disabled={profileSaving}
+              className="px-4 py-2 bg-gray-900 text-white text-xs font-semibold uppercase tracking-wider rounded hover:bg-gray-800 disabled:opacity-60 cursor-pointer"
+            >
+              {profileSaving ? 'Saving Profile...' : 'Update Profile'}
+            </button>
+          </div>
+        </form>
+      </section>
+
+      {/* Passkey Management Section */}
+      <section
+        id="passkey-management"
+        aria-labelledby="passkeys-heading"
+        className="bg-white border border-gray-200 rounded-lg shadow-sm p-6"
+      >
+        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 pb-5 border-b border-gray-200">
+          <div>
+            <h2
+              id="passkeys-heading"
+              className="text-xl font-bold text-gray-900"
+            >
+              Passkeys
+            </h2>
+            <p className="text-sm text-gray-600 mt-1">
+              Manage the passkeys registered to your DevTools Times account. Changes are automatically synchronized with your browser authenticator.
+            </p>
+          </div>
+
+          <div>
+            <button
+              id="create-passkey"
+              type="button"
+              hidden={!isPasskeySupported}
+              disabled={creatingPasskey || !isPasskeySupported}
+              onClick={handleCreatePasskey}
+              className="inline-flex items-center gap-2 px-4 py-2.5 bg-gray-900 text-white text-xs font-semibold uppercase tracking-wider rounded hover:bg-gray-800 disabled:opacity-60 cursor-pointer whitespace-nowrap"
+            >
+              <svg
+                className="w-4 h-4"
+                fill="none"
+                stroke="currentColor"
+                viewBox="0 0 24 24"
+                aria-hidden="true"
+              >
+                <path
+                  strokeLinecap="round"
+                  strokeLinejoin="round"
+                  strokeWidth={2}
+                  d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z"
+                />
+              </svg>
+              {creatingPasskey ? 'Registering...' : 'Create passkey'}
+            </button>
+          </div>
+        </div>
+
+        {/* Fallback notice if platform passkeys are not supported */}
+        {capabilitiesChecked && !isPasskeySupported && (
+          <div className="mt-4 p-3 bg-amber-50 border border-amber-200 rounded-md text-xs text-amber-900">
+            Passkey creation is not supported on this device or browser. You can still rename or remove existing passkeys below, or configure standard multi-factor authentication (MFA) for your account.
+          </div>
+        )}
+
+        {/* Passkeys List */}
+        <div className="mt-6">
+          {loading ? (
+            <p className="text-sm text-gray-500 py-6 text-center">
+              Loading your registered passkeys...
+            </p>
+          ) : credentials.length === 0 ? (
+            <div className="text-center py-10 border border-dashed border-gray-300 rounded-lg">
+              <p className="text-base font-semibold text-gray-800">
+                No passkeys found
+              </p>
+              <p className="text-sm text-gray-500 mt-1">
+                You have no registered passkeys on your account.
+              </p>
+            </div>
+          ) : (
+            <ul className="divide-y divide-gray-200" data-testid="passkey-list">
+              {credentials.map((cred) => {
+                // Check for zeroed AAGUID before looking up in the local AAGUID registry
+                const providerInfo =
+                  cred.aaguid === ZERO_AAGUID
+                    ? {
+                        name: 'Unknown passkey provider',
+                        providerIcon: undefined,
+                      }
+                    : resolveAaguidProvider(cred.aaguid);
+
+                const iconSrc = cred.providerIcon || providerInfo.providerIcon;
+                const displayName = cred.name || providerInfo.name;
+                const isCustomNamed =
+                  Boolean(cred.name) && cred.name !== providerInfo.name;
+                const isEditing = editingCredentialId === cred.id;
+
+                return (
+                  <li
+                    key={cred.id}
+                    data-credential-id={cred.id}
+                    className="py-5 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4"
+                  >
+                    <div className="flex items-start gap-4 flex-grow">
+                      {/* Provider Icon */}
+                      <div className="w-10 h-10 rounded-lg bg-gray-100 border border-gray-200 flex items-center justify-center flex-shrink-0">
+                        {iconSrc ? (
+                          <img
+                            src={iconSrc}
+                            alt={`${providerInfo.name} icon`}
+                            className="w-6 h-6 object-contain"
+                          />
+                        ) : (
+                          <svg
+                            className="w-5 h-5 text-gray-600"
+                            fill="none"
+                            stroke="currentColor"
+                            viewBox="0 0 24 24"
+                            aria-hidden="true"
+                          >
+                            <path
+                              strokeLinecap="round"
+                              strokeLinejoin="round"
+                              strokeWidth={2}
+                              d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z"
+                            />
+                          </svg>
+                        )}
+                      </div>
+
+                      {/* Passkey Name & Metadata */}
+                      <div className="flex-grow">
+                        {isEditing ? (
+                          <form
+                            onSubmit={(e) =>
+                              handleSaveCredentialRename(e, cred.id)
+                            }
+                            className="flex flex-wrap items-center gap-2"
+                          >
+                            <label
+                              htmlFor={`rename-input-${cred.id}`}
+                              className="sr-only"
+                            >
+                              Passkey Display Name
+                            </label>
+                            <input
+                              id={`rename-input-${cred.id}`}
+                              type="text"
+                              required
+                              value={editingCredentialName}
+                              onChange={(e) =>
+                                setEditingCredentialName(e.target.value)
+                              }
+                              className="px-3 py-1.5 border border-gray-300 rounded text-sm focus:outline-none focus:ring-2 focus:ring-gray-900"
+                            />
+                            <button
+                              type="submit"
+                              disabled={savingCredentialId === cred.id}
+                              className="px-3 py-1.5 bg-gray-900 text-white text-xs font-semibold rounded hover:bg-gray-800 cursor-pointer"
+                            >
+                              {savingCredentialId === cred.id
+                                ? 'Saving...'
+                                : 'Save'}
+                            </button>
+                            <button
+                              type="button"
+                              onClick={handleCancelRename}
+                              className="px-3 py-1.5 border border-gray-300 text-gray-700 text-xs font-semibold rounded hover:bg-gray-100 cursor-pointer"
+                            >
+                              Cancel
+                            </button>
+                          </form>
+                        ) : (
+                          <div className="flex flex-wrap items-center gap-2">
+                            <h3 className="text-base font-bold text-gray-900">
+                              {displayName}
+                            </h3>
+                            {isCustomNamed && (
+                              <span className="text-xs px-2 py-0.5 bg-gray-100 text-gray-600 rounded border border-gray-200">
+                                {providerInfo.name}
+                              </span>
+                            )}
+                            {cred.credentialBackedUp && (
+                              <span className="text-xs px-2 py-0.5 bg-green-50 text-green-700 rounded border border-green-200">
+                                Synced
+                              </span>
+                            )}
+                          </div>
+                        )}
+
+                        <div className="mt-1.5 flex flex-wrap gap-x-4 gap-y-1 text-xs text-gray-500">
+                          <span>
+                            Registered:{' '}
+                            <time
+                              dateTime={new Date(
+                                cred.registeredAt
+                              ).toISOString()}
+                              className="font-medium text-gray-700"
+                            >
+                              {formatEpochDate(cred.registeredAt)}
+                            </time>
+                          </span>
+                          <span>
+                            Last used:{' '}
+                            {cred.lastUsedAt ? (
+                              <time
+                                dateTime={new Date(
+                                  cred.lastUsedAt
+                                ).toISOString()}
+                                className="font-medium text-gray-700"
+                              >
+                                {formatEpochDate(cred.lastUsedAt)}
+                              </time>
+                            ) : (
+                              <span className="font-medium text-gray-700">
+                                Never used
+                              </span>
+                            )}
+                          </span>
+                        </div>
+                      </div>
+                    </div>
+
+                    {/* Action Buttons: Rename & Delete */}
+                    {!isEditing && (
+                      <div className="flex items-center gap-2 self-end sm:self-center">
+                        <button
+                          type="button"
+                          onClick={() => handleStartRename(cred)}
+                          className="px-3 py-1.5 border border-gray-300 rounded text-xs font-semibold text-gray-700 hover:bg-gray-100 cursor-pointer"
+                        >
+                          Rename
+                        </button>
+                        <button
+                          type="button"
+                          disabled={deletingCredentialId === cred.id}
+                          onClick={() => handleDeleteCredential(cred)}
+                          className="px-3 py-1.5 border border-red-200 bg-red-50 rounded text-xs font-semibold text-red-700 hover:bg-red-100 disabled:opacity-60 cursor-pointer"
+                        >
+                          {deletingCredentialId === cred.id
+                            ? 'Removing...'
+                            : 'Delete'}
+                        </button>
+                      </div>
+                    )}
+                  </li>
+                );
+              })}
+            </ul>
+          )}
+        </div>
+      </section>
+    </div>
+  );
+}
