+++ b/src/pages/api/credential/[id].ts
@@ -0,0 +1,71 @@
+import type { APIRoute } from 'astro';
+import {
+  deleteCredential,
+  findCredentialById,
+  getCurrentUser,
+  saveCredential,
+} from '../../../utils/passkey-store';
+
+export const PUT: APIRoute = async ({ params, request }) => {
+  const id = params.id;
+  if (!id) {
+    return new Response(JSON.stringify({ error: 'Credential ID is required.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const body = await request.json().catch(() => ({}));
+  const name = typeof body.name === 'string' ? body.name.trim() : '';
+  if (!name) {
+    return new Response(JSON.stringify({ error: 'Display name is required.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const user = await getCurrentUser();
+  const cred = await findCredentialById(id);
+  if (!cred || cred.passkeyUserId !== user.passkeyUserId) {
+    return new Response(JSON.stringify({ error: 'Credential not found.' }), {
+      status: 404,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  cred.name = name;
+  const saved = await saveCredential(cred);
+
+  return new Response(JSON.stringify(saved), {
+    status: 200,
+    headers: { 'Content-Type': 'application/json' },
+  });
+};
+
+export const PATCH: APIRoute = PUT;
+
+export const DELETE: APIRoute = async ({ params }) => {
+  const id = params.id;
+  if (!id) {
+    return new Response(JSON.stringify({ error: 'Credential ID is required.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const user = await getCurrentUser();
+  const cred = await findCredentialById(id);
+  if (!cred || cred.passkeyUserId !== user.passkeyUserId) {
+    return new Response(JSON.stringify({ error: 'Credential not found.' }), {
+      status: 404,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  await deleteCredential(id);
+
+  return new Response(JSON.stringify({ success: true }), {
+    status: 200,
+    headers: { 'Content-Type': 'application/json' },
+  });
+};
diff --git a/src/pages/api/credentials.ts b/src/pages/api/credentials.ts
