+import type { APIRoute } from 'astro';
+import {
+  findCredentialsByUserId,
+  getCurrentUser,
+  getServerRpId,
+} from '../../utils/passkey-store';
+
+export const GET: APIRoute = async ({ url }) => {
+  const user = await getCurrentUser();
+  const credentials = await findCredentialsByUserId(user.passkeyUserId);
+  const rpId = getServerRpId(url);
+
+  return new Response(
+    JSON.stringify({
+      rpId,
+      userId: user.passkeyUserId,
+      user,
+      credentials,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
