@@ -0,0 +1,49 @@
+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import {
+  findCredentialsByUserId,
+  getCurrentUser,
+  getServerRpId,
+  RP_NAME,
+  setCurrentChallenge,
+} from '../../../../utils/passkey-store';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const body = await request.json().catch(() => ({}));
+  const isPromotionFlow = Boolean(body?.promotion);
+
+  const user = await getCurrentUser();
+  const existingCredentials = await findCredentialsByUserId(user.passkeyUserId);
+  const rpId = getServerRpId(url);
+
+  const options = await generateRegistrationOptions({
+    rpName: RP_NAME,
+    rpID: rpId,
+    userID: new Uint8Array(Buffer.from(user.passkeyUserId, 'base64url')),
+    userName: user.name,
+    userDisplayName: user.displayName,
+    attestationType: 'none',
+    excludeCredentials: existingCredentials.map((cred) => ({
+      id: cred.id,
+      transports: cred.transports,
+    })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+      ...(isPromotionFlow ? { authenticatorAttachment: 'platform' } : {}),
+    },
+  });
+
+  await setCurrentChallenge(options.challenge);
+  if (session) {
+    await session.set('currentChallenge', options.challenge);
+  }
+
+  return new Response(JSON.stringify(options), {
+    status: 200,
+    headers: { 'Content-Type': 'application/json' },
+  });
+};
+
+export const GET: APIRoute = POST;
