@@ -0,0 +1,109 @@
+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse } from '@simplewebauthn/server';
+import {
+  buildCredentialFromRegistration,
+  getCurrentChallenge,
+  getCurrentUser,
+  getServerRpId,
+  saveCredential,
+  setCurrentChallenge,
+} from '../../../../utils/passkey-store';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const body = await request.json().catch(() => null);
+  if (!body || !body.id) {
+    return new Response(
+      JSON.stringify({ error: 'Invalid registration response payload.' }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  const sessionChallenge = session
+    ? ((await session.get('currentChallenge')) as string | undefined)
+    : undefined;
+  const expectedChallenge = sessionChallenge || (await getCurrentChallenge());
+
+  if (!expectedChallenge) {
+    return new Response(
+      JSON.stringify({ error: 'Registration challenge expired or missing.' }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  const rpId = getServerRpId(url);
+  const expectedOrigin = url.origin;
+
+  try {
+    const verification = await verifyRegistrationResponse({
+      response: body,
+      expectedChallenge,
+      expectedOrigin,
+      expectedRPID: rpId,
+      requireUserPresence: true,
+      requireUserVerification: false,
+    });
+
+    if (!verification.verified || !verification.registrationInfo) {
+      return new Response(
+        JSON.stringify({ error: 'Passkey verification failed.' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const { registrationInfo } = verification;
+    const user = await getCurrentUser();
+
+    const newCredential = buildCredentialFromRegistration({
+      id: registrationInfo.credential.id,
+      passkeyUserId: user.passkeyUserId,
+      credentialPublicKey: Buffer.from(
+        registrationInfo.credential.publicKey
+      ).toString('base64url'),
+      credentialDeviceType: registrationInfo.credentialDeviceType,
+      credentialBackedUp: registrationInfo.credentialBackedUp,
+      aaguid: registrationInfo.aaguid,
+      transports:
+        registrationInfo.credential.transports ||
+        body.response?.transports ||
+        ['internal'],
+      counter: registrationInfo.credential.counter,
+    });
+
+    const saved = await saveCredential(newCredential);
+
+    await setCurrentChallenge(null);
+    if (session) {
+      await session.set('currentChallenge', null);
+    }
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        credential: saved,
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({
+        error: err?.message || 'Failed to verify registration response.',
+      }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};
