+import type { APIRoute } from 'astro';
+import {
+  getCurrentUser,
+  getServerRpId,
+  updateUser,
+} from '../../utils/passkey-store';
+
+export const GET: APIRoute = async ({ url }) => {
+  const user = await getCurrentUser();
+  const rpId = getServerRpId(url);
+
+  return new Response(
+    JSON.stringify({
+      ...user,
+      rpId,
+      userId: user.passkeyUserId,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
+
+export const PUT: APIRoute = async ({ request, url }) => {
+  const body = await request.json().catch(() => ({}));
+  const name = typeof body.name === 'string' ? body.name.trim() : undefined;
+  const displayName =
+    typeof body.displayName === 'string' ? body.displayName.trim() : undefined;
+
+  if (!name && !displayName) {
+    return new Response(
+      JSON.stringify({ error: 'Name or displayName is required.' }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  const currentUser = await getCurrentUser();
+  const updatedUser = await updateUser(currentUser.id, { name, displayName });
+  const rpId = getServerRpId(url);
+
+  return new Response(
+    JSON.stringify({
+      ...updatedUser,
+      rpId,
+      userId: updatedUser.passkeyUserId,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
+
+export const PATCH: APIRoute = PUT;
+export const POST: APIRoute = PUT;
