+import aaguidsData from '../data/aaguids.json';
+
+export interface AaguidEntry {
+  name: string;
+  icon_light?: string;
+  icon_dark?: string;
+}
+
+const aaguids: Record<string, AaguidEntry> = aaguidsData;
+
+export const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+export function resolveAaguidProvider(aaguid?: string): {
+  name: string;
+  providerIcon?: string;
+  providerIconDark?: string;
+} {
+  if (!aaguid || aaguid === ZERO_AAGUID) {
+    return {
+      name: 'Unknown passkey provider',
+      providerIcon: undefined,
+      providerIconDark: undefined,
+    };
+  }
+
+  const provider = aaguids[aaguid.toLowerCase()];
+  return {
+    name: provider?.name || 'Unknown passkey provider',
+    providerIcon: provider?.icon_light,
+    providerIconDark: provider?.icon_dark,
+  };
+}
