+import { resolveAaguidProvider, ZERO_AAGUID } from './aaguid';
+
+export interface StoredPasskeyCredential {
+  id: string; // Base64URL-encoded credential ID (unique lookup key)
+  passkeyUserId: string; // Associated application user ID (Base64URL-encoded)
+  credentialPublicKey: string; // Base64URL-encoded public key used to verify assertion signatures
+  credentialType: 'public-key';
+  credentialDeviceType: 'singleDevice' | 'multiDevice'; // Helps distinguish device-bound vs cloud-synced passkeys
+  credentialBackedUp: boolean; // Boolean backup state reported by the authenticator
+  aaguid: string; // Authenticator Attestation GUID
+  providerIcon?: string; // Provider icon derived from the AAGUID registry
+  name: string; // Provider name derived from AAGUID registry or custom user nickname
+  transports: string[]; // Array of transport names (e.g. 'internal', 'hybrid')
+  lastUsedAt?: number; // Optional epoch timestamp of last sign-in
+  registeredAt: number; // Registration epoch timestamp
+  counter: number; // Authenticator sign-in signature counter
+}
+
+export interface ReaderProfile {
+  id: string;
+  passkeyUserId: string; // Valid unpadded Base64URL string
+  name: string; // Account username / email
+  displayName: string; // Reader display name
+  subscriptionTier: string;
+}
+
+export const RP_ID = process.env.RP_ID || 'localhost';
+export const RP_NAME = 'The DevTools Times';
+
+export function getServerRpId(requestUrl?: URL): string {
+  if (process.env.RP_ID) {
+    return process.env.RP_ID;
+  }
+  if (requestUrl?.hostname) {
+    return requestUrl.hostname;
+  }
+  return RP_ID;
+}
+
+export function isValidBase64Url(value: unknown): value is string {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+const DEFAULT_PASSKEY_USER_ID = Buffer.from('reader-alex-rivera-01').toString('base64url');
+
+const initialUser: ReaderProfile = {
+  id: DEFAULT_PASSKEY_USER_ID,
+  passkeyUserId: DEFAULT_PASSKEY_USER_ID,
+  name: 'alex.rivera@devtoolstimes.dev',
+  displayName: 'Alex Rivera',
+  subscriptionTier: 'Digital All-Access Subscriber',
+};
+
+function createInitialCredentials(passkeyUserId: string): StoredPasskeyCredential[] {
+  const gpmMeta = resolveAaguidProvider('ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4');
+  const icloudMeta = resolveAaguidProvider('fbfc3007-154e-4ecc-8c0b-6e020557d7bd');
+  const onePasswordMeta = resolveAaguidProvider('bada5566-a7aa-401f-bd96-45619a55120d');
+
+  return [
+    {
+      id: Buffer.from('cred-gpm-pixel-9-pro-01').toString('base64url'),
+      passkeyUserId,
+      credentialPublicKey: Buffer.from('pubkey-gpm-pixel-9-pro-01').toString('base64url'),
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+      providerIcon: gpmMeta.providerIcon,
+      name: gpmMeta.name,
+      transports: ['internal', 'hybrid'],
+      registeredAt: 1757894400000,
+      lastUsedAt: 1763121600000,
+      counter: 8,
+    },
+    {
+      id: Buffer.from('cred-icloud-macbook-02').toString('base64url'),
+      passkeyUserId,
+      credentialPublicKey: Buffer.from('pubkey-icloud-macbook-02').toString('base64url'),
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd',
+      providerIcon: icloudMeta.providerIcon,
+      name: icloudMeta.name,
+      transports: ['internal', 'hybrid'],
+      registeredAt: 1755216000000,
+      lastUsedAt: 1762473600000,
+      counter: 14,
+    },
+    {
+      id: Buffer.from('cred-1password-work-03').toString('base64url'),
+      passkeyUserId,
+      credentialPublicKey: Buffer.from('pubkey-1password-work-03').toString('base64url'),
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: 'bada5566-a7aa-401f-bd96-45619a55120d',
+      providerIcon: onePasswordMeta.providerIcon,
+      name: 'Work Vault (1Password)',
+      transports: ['internal'],
+      registeredAt: 1752537600000,
+      lastUsedAt: 1759104000000,
+      counter: 3,
+    },
+  ];
+}
+
+// Global singleton store to persist across API route invocations in the same process
+const globalState = globalThis as unknown as {
+  __devtoolsTimesPasskeyStore?: {
+    user: ReaderProfile;
+    credentials: StoredPasskeyCredential[];
+    currentChallenge: string | null;
+  };
+};
+
+if (!globalState.__devtoolsTimesPasskeyStore) {
+  globalState.__devtoolsTimesPasskeyStore = {
+    user: { ...initialUser },
+    credentials: createInitialCredentials(initialUser.passkeyUserId),
+    currentChallenge: null,
+  };
+}
+
+function getStore() {
+  return globalState.__devtoolsTimesPasskeyStore!;
+}
+
+export async function getCurrentUser(): Promise<ReaderProfile> {
+  return { ...getStore().user };
+}
+
+export async function updateUser(
+  userId: string,
+  updates: { name?: string; displayName?: string }
+): Promise<ReaderProfile> {
+  const store = getStore();
+  if (store.user.id === userId || store.user.passkeyUserId === userId) {
+    if (typeof updates.name === 'string' && updates.name.trim()) {
+      store.user.name = updates.name.trim();
+    }
+    if (typeof updates.displayName === 'string' && updates.displayName.trim()) {
+      store.user.displayName = updates.displayName.trim();
+    }
+  }
+  return { ...store.user };
+}
+
+export async function findCredentialsByUserId(
+  userId: string
+): Promise<StoredPasskeyCredential[]> {
+  const store = getStore();
+  return store.credentials
+    .filter((cred) => cred.passkeyUserId === userId)
+    .map((cred) => ({ ...cred }));
+}
+
+export async function findCredentialById(
+  id: string
+): Promise<StoredPasskeyCredential | undefined> {
+  const store = getStore();
+  const found = store.credentials.find((cred) => cred.id === id);
+  return found ? { ...found } : undefined;
+}
+
+export async function saveCredential(
+  credential: StoredPasskeyCredential
+): Promise<StoredPasskeyCredential> {
+  const store = getStore();
+  const existingIndex = store.credentials.findIndex((c) => c.id === credential.id);
+  if (existingIndex >= 0) {
+    store.credentials[existingIndex] = { ...credential };
+  } else {
+    store.credentials.unshift({ ...credential });
+  }
+  return { ...credential };
+}
+
+export async function deleteCredential(id: string): Promise<boolean> {
+  const store = getStore();
+  const initialLength = store.credentials.length;
+  store.credentials = store.credentials.filter((cred) => cred.id !== id);
+  return store.credentials.length < initialLength;
+}
+
+export async function setCurrentChallenge(challenge: string | null): Promise<void> {
+  getStore().currentChallenge = challenge;
+}
+
+export async function getCurrentChallenge(): Promise<string | null> {
+  return getStore().currentChallenge;
+}
+
+export function buildCredentialFromRegistration(params: {
+  id: string;
+  passkeyUserId: string;
+  credentialPublicKey: string;
+  credentialDeviceType: 'singleDevice' | 'multiDevice';
+  credentialBackedUp: boolean;
+  aaguid?: string;
+  transports?: string[];
+  counter?: number;
+  customName?: string;
+}): StoredPasskeyCredential {
+  const aaguid = params.aaguid || ZERO_AAGUID;
+  let name = params.customName?.trim() || 'Unknown passkey provider';
+  let providerIcon: string | undefined = undefined;
+
+  if (aaguid === ZERO_AAGUID) {
+    name = params.customName?.trim() || 'Unknown passkey provider';
+    providerIcon = undefined;
+  } else {
+    const provider = resolveAaguidProvider(aaguid);
+    name = params.customName?.trim() || provider.name || 'Unknown passkey provider';
+    providerIcon = provider.providerIcon;
+  }
+
+  return {
+    id: params.id,
+    passkeyUserId: params.passkeyUserId,
+    credentialPublicKey: params.credentialPublicKey,
+    credentialType: 'public-key',
+    credentialDeviceType: params.credentialDeviceType,
+    credentialBackedUp: params.credentialBackedUp,
+    aaguid,
+    providerIcon,
+    name,
+    transports: params.transports || ['internal'],
+    registeredAt: Date.now(),
+    lastUsedAt: undefined,
+    counter: params.counter ?? 0,
+  };
+}

