+import React, { useEffect, useState } from 'react';
+import {
+  DEFAULT_PASSKEYS,
+  DEFAULT_READER_ACCOUNT,
+  decodeBase64UrlToUint8Array,
+  encodeBase64Url,
+  type PasskeyCredential,
+  type ReaderAccount,
+} from '../utils/passkeys';
+
+interface SignalEventLog {
+  id: string;
+  timestamp: string;
+  method:
+    | 'signalAllAcceptedCredentials'
+    | 'signalCurrentUserDetails'
+    | 'signalUnknownCredential';
+  status: 'synced' | 'simulated';
+  summary: string;
+  payload: Record<string, unknown>;
+}
+
+interface AccountSettingsProps {
+  initialUser?: ReaderAccount;
+  initialPasskeys?: PasskeyCredential[];
+}
+
+export default function AccountSettings({
+  initialUser = DEFAULT_READER_ACCOUNT,
+  initialPasskeys = DEFAULT_PASSKEYS,
+}: AccountSettingsProps) {
+  const [user, setUser] = useState<ReaderAccount>(initialUser);
+  const [passkeys, setPasskeys] =
+    useState<PasskeyCredential[]>(initialPasskeys);
+  const [loading, setLoading] = useState(false);
+
+  // Reader account display name form state
+  const [accountDisplayName, setAccountDisplayName] = useState(
+    initialUser.displayName
+  );
+  const [accountUsername, setAccountUsername] = useState(initialUser.name);
+  const [savingAccount, setSavingAccount] = useState(false);
+
+  // Per-passkey inline display name editing state
+  const [editingPasskeyId, setEditingPasskeyId] = useState<string | null>(null);
+  const [editingDisplayName, setEditingDisplayName] = useState('');
+  const [savingPasskeyId, setSavingPasskeyId] = useState<string | null>(null);
+  const [removingPasskeyId, setRemovingPasskeyId] = useState<string | null>(
+    null
+  );
+
+  // Register new passkey state
+  const [newPasskeyName, setNewPasskeyName] = useState('');
+  const [newPasskeyDeviceType, setNewPasskeyDeviceType] = useState<
+    'laptop' | 'phone' | 'security-key'
+  >('laptop');
+  const [registeringPasskey, setRegisteringPasskey] = useState(false);
+
+  // Status banner and WebAuthn Signal API log
+  const [statusMessage, setStatusMessage] = useState<{
+    type: 'success' | 'info' | 'error';
+    text: string;
+  } | null>(null);
+  const [signalLogs, setSignalLogs] = useState<SignalEventLog[]>([]);
+  const [signalCapabilities, setSignalCapabilities] = useState({
+    signalAllAcceptedCredentials: false,
+    signalCurrentUserDetails: false,
+    signalUnknownCredential: false,
+  });
+
+  const apiUrl = `${import.meta.env.BASE_URL}api/passkeys.json`;
+
+  const getRpId = () => {
+    if (typeof window !== 'undefined' && window.location?.hostname) {
+      return window.location.hostname;
+    }
+    return 'localhost';
+  };
+
+  const appendSignalLog = (
+    method: SignalEventLog['method'],
+    status: SignalEventLog['status'],
+    summary: string,
+    payload: Record<string, unknown>
+  ) => {
+    setSignalLogs((prev) => [
+      {
+        id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
+        timestamp: new Date().toLocaleTimeString(),
+        method,
+        status,
+        summary,
+        payload,
+      },
+      ...prev.slice(0, 9),
+    ]);
+  };
+
+  /**
+   * Synchronize all accepted credential IDs with the browser authenticator
+   * via PublicKeyCredential.signalAllAcceptedCredentials()
+   */
+  const syncAcceptedCredentialsWithAuthenticator = async (
+    targetUserId: string,
+    acceptedCredentialIds: string[],
+    reason: string
+  ) => {
+    const rpId = getRpId();
+    const payload = {
+      rpId,
+      userId: targetUserId,
+      allAcceptedCredentialIds: acceptedCredentialIds,
+    };
+
+    if (
+      typeof window !== 'undefined' &&
+      'PublicKeyCredential' in window &&
+      typeof PublicKeyCredential.signalAllAcceptedCredentials === 'function'
+    ) {
+      try {
+        await PublicKeyCredential.signalAllAcceptedCredentials(payload);
+        appendSignalLog(
+          'signalAllAcceptedCredentials',
+          'synced',
+          `${reason} (${acceptedCredentialIds.length} active passkey${acceptedCredentialIds.length === 1 ? '' : 's'})`,
+          payload
+        );
+        return true;
+      } catch (err) {
+        appendSignalLog(
+          'signalAllAcceptedCredentials',
+          'simulated',
+          `${reason} (signal dispatched with fallback)`,
+          payload
+        );
+        return false;
+      }
+    } else {
+      appendSignalLog(
+        'signalAllAcceptedCredentials',
+        'simulated',
+        `${reason} (${acceptedCredentialIds.length} active passkey${acceptedCredentialIds.length === 1 ? '' : 's'})`,
+        payload
+      );
+      return false;
+    }
+  };
+
+  /**
+   * Synchronize updated user display name / username with the browser authenticator
+   * via PublicKeyCredential.signalCurrentUserDetails()
+   */
+  const syncUserDetailsWithAuthenticator = async (
+    targetUser: ReaderAccount,
+    reason: string
+  ) => {
+    const rpId = getRpId();
+    const payload = {
+      rpId,
+      userId: targetUser.userId,
+      name: targetUser.name,
+      displayName: targetUser.displayName,
+    };
+
+    if (
+      typeof window !== 'undefined' &&
+      'PublicKeyCredential' in window &&
+      typeof PublicKeyCredential.signalCurrentUserDetails === 'function'
+    ) {
+      try {
+        await PublicKeyCredential.signalCurrentUserDetails(payload);
+        appendSignalLog(
+          'signalCurrentUserDetails',
+          'synced',
+          `${reason}: "${targetUser.displayName}" (${targetUser.name})`,
+          payload
+        );
+        return true;
+      } catch {
+        appendSignalLog(
+          'signalCurrentUserDetails',
+          'simulated',
+          `${reason}: "${targetUser.displayName}" (${targetUser.name})`,
+          payload
+        );
+        return false;
+      }
+    } else {
+      appendSignalLog(
+        'signalCurrentUserDetails',
+        'simulated',
+        `${reason}: "${targetUser.displayName}" (${targetUser.name})`,
+        payload
+      );
+      return false;
+    }
+  };
+
+  /**
+   * Signal to the browser authenticator that a removed credential ID is no longer recognized
+   * via PublicKeyCredential.signalUnknownCredential()
+   */
+  const syncUnknownCredentialWithAuthenticator = async (
+    removedCredentialId: string,
+    reason: string
+  ) => {
+    const rpId = getRpId();
+    const payload = {
+      rpId,
+      credentialId: removedCredentialId,
+    };
