+                              {passkey.authenticatorName}
+                            </span>
+                            {passkey.backedUp ? (
+                              <span className="text-xs font-medium px-2 py-0.5 rounded bg-blue-50 text-blue-700 border border-blue-200">
+                                Synced Passkey
+                              </span>
+                            ) : (
+                              <span className="text-xs font-medium px-2 py-0.5 rounded bg-amber-50 text-amber-800 border border-amber-200">
