+              >
+                {registeringPasskey ? 'Registering...' : '+ Add Passkey'}
+              </button>
+            </form>
+          </div>
+        </section>
+
+        {/* Section 3: Browser Authenticator Synchronization Status (WebAuthn Signal API) */}
+        <section
+          aria-labelledby="authenticator-sync-heading"
+          className="bg-white border border-gray-200 rounded-lg shadow-xs overflow-hidden"
+        >
+          <div className="px-6 py-4 bg-gray-50 border-b border-gray-200 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
+            <div>
+              <h2
+                id="authenticator-sync-heading"
+                className="text-sm font-bold uppercase tracking-wider text-gray-800"
+              >
+                Browser Authenticator Synchronization Log
+              </h2>
+              <p className="text-xs text-gray-600">
+                Real-time WebAuthn Signal API synchronization events keeping
+                your local passkey vault aligned with The DevTools Times.
+              </p>
+            </div>
+            <div className="flex flex-wrap gap-1.5 text-[11px] font-mono">
+              <span
+                className={`px-2 py-0.5 rounded border ${
+                  signalCapabilities.signalAllAcceptedCredentials
+                    ? 'bg-green-50 text-green-800 border-green-200'
+                    : 'bg-gray-100 text-gray-600 border-gray-200'
+                }`}
+              >
+                signalAllAcceptedCredentials
+              </span>
+              <span
+                className={`px-2 py-0.5 rounded border ${
+                  signalCapabilities.signalCurrentUserDetails
+                    ? 'bg-green-50 text-green-800 border-green-200'
+                    : 'bg-gray-100 text-gray-600 border-gray-200'
+                }`}
+              >
+                signalCurrentUserDetails
+              </span>
+              <span
+                className={`px-2 py-0.5 rounded border ${
+                  signalCapabilities.signalUnknownCredential
+                    ? 'bg-green-50 text-green-800 border-green-200'
+                    : 'bg-gray-100 text-gray-600 border-gray-200'
+                }`}
+              >
+                signalUnknownCredential
+              </span>
+            </div>
+          </div>
+
+          <div className="p-6">
+            {signalLogs.length === 0 ? (
+              <p className="text-xs text-gray-500">
+                No authenticator signal events recorded yet.
+              </p>
+            ) : (
+              <ul className="space-y-2.5 text-xs">
+                {signalLogs.map((log) => (
+                  <li
+                    key={log.id}
+                    className="p-3 rounded-md bg-gray-50 border border-gray-200 flex flex-col sm:flex-row sm:items-center justify-between gap-2"
+                  >
+                    <div className="space-y-0.5">
+                      <div className="flex items-center gap-2">
+                        <span className="font-mono font-semibold text-gray-900">
+                          PublicKeyCredential.{log.method}()
+                        </span>
+                        <span className="text-gray-400">&middot;</span>
+                        <span className="text-gray-500">{log.timestamp}</span>
+                      </div>
+                      <p className="text-gray-700">{log.summary}</p>
+                    </div>
+                    <code className="text-[11px] font-mono text-gray-600 bg-white px-2 py-1 rounded border border-gray-200 overflow-x-auto max-w-full sm:max-w-xs">
+                      {JSON.stringify(log.payload)}
+                    </code>
+                  </li>
+                ))}
+              </ul>
+            )}
+          </div>
+        </section>
+      </div>
+    </div>
+  );
+}
