diff --git a/src/pages/api/passkeys.json.ts b/src/pages/api/passkeys.json.ts
new file mode 100644
index 0000000..bac269a
--- /dev/null
+++ b/src/pages/api/passkeys.json.ts
@@ -0,0 +1,324 @@
+import type { APIRoute } from 'astro';
+import {
+  DEFAULT_PASSKEYS,
+  DEFAULT_READER_ACCOUNT,
+  encodeBase64Url,
+  getFallbackState,
+  setFallbackState,
+  type PasskeyCredential,
+  type ReaderAccount,
+} from '../../utils/passkeys';
+
+async function loadState(session: any): Promise<{
+  user: ReaderAccount;
+  passkeys: PasskeyCredential[];
+}> {
+  const fallback = getFallbackState();
+  const sessionUser = (await session?.get('accountUser')) as
+    | ReaderAccount
+    | undefined;
+  const sessionPasskeys = (await session?.get('passkeys')) as
+    | PasskeyCredential[]
+    | undefined;
+
+  return {
+    user: sessionUser ? { ...sessionUser } : fallback.user,
+    passkeys: sessionPasskeys
+      ? sessionPasskeys.map((pk) => ({ ...pk }))
+      : fallback.passkeys,
+  };
+}
+
+async function saveState(
+  session: any,
+  user: ReaderAccount,
+  passkeys: PasskeyCredential[]
+): Promise<void> {
+  setFallbackState(user, passkeys);
+  await session?.set('accountUser', user);
+  await session?.set('passkeys', passkeys);
+}
+
+export const GET: APIRoute = async ({ session }) => {
+  const { user, passkeys } = await loadState(session);
+  const allAcceptedCredentialIds = passkeys.map((pk) => pk.credentialId);
+
+  return new Response(
+    JSON.stringify({
+      user,
+      passkeys,
+      allAcceptedCredentialIds,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
+
+export const POST: APIRoute = async ({ request, session }) => {
+  let body: any = {};
+  try {
+    body = await request.json();
+  } catch {
+    return new Response(JSON.stringify({ error: 'Invalid JSON payload' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  let { user, passkeys } = await loadState(session);
+  const action = body.action;
+
+  if (action === 'update-user' || action === 'update-display-name') {
+    const newDisplayName = (body.displayName ?? '').trim();
+    const newName = (body.name ?? user.name).trim();
+    if (!newDisplayName) {
+      return new Response(
+        JSON.stringify({ error: 'Display name is required' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    user = {
+      ...user,
+      displayName: newDisplayName,
+      name: newName || user.name,
+    };
+
+    await saveState(session, user, passkeys);
+    return new Response(
+      JSON.stringify({
+        user,
+        passkeys,
+        allAcceptedCredentialIds: passkeys.map((pk) => pk.credentialId),
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  if (action === 'rename' || action === 'update-passkey') {
+    const targetId = body.credentialId || body.id;
+    const newDisplayName = (body.displayName ?? '').trim();
+    if (!targetId || !newDisplayName) {
+      return new Response(
+        JSON.stringify({
+          error: 'Credential ID and new display name are required',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    let updatedPasskey: PasskeyCredential | null = null;
+    passkeys = passkeys.map((pk) => {
+      if (pk.credentialId === targetId || pk.id === targetId) {
+        updatedPasskey = { ...pk, displayName: newDisplayName };
+        return updatedPasskey;
+      }
+      return pk;
+    });
+
+    if (!updatedPasskey) {
+      return new Response(JSON.stringify({ error: 'Passkey not found' }), {
+        status: 404,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    await saveState(session, user, passkeys);
+    return new Response(
+      JSON.stringify({
+        user,
+        passkeys,
+        passkey: updatedPasskey,
+        allAcceptedCredentialIds: passkeys.map((pk) => pk.credentialId),
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  if (action === 'remove' || action === 'delete') {
+    const targetId = body.credentialId || body.id;
+    if (!targetId) {
+      return new Response(
+        JSON.stringify({ error: 'Credential ID is required' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    passkeys = passkeys.filter(
+      (pk) => pk.credentialId !== targetId && pk.id !== targetId
+    );
+
+    await saveState(session, user, passkeys);
+    return new Response(
+      JSON.stringify({
+        user,
+        passkeys,
+        removedCredentialId: targetId,
+        allAcceptedCredentialIds: passkeys.map((pk) => pk.credentialId),
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  if (action === 'add' || action === 'register') {
+    const rawId =
+      body.credentialId ||
+      encodeBase64Url(`passkey_cred_${Date.now().toString(36).padEnd(11, '0')}`);
+    const newPasskey: PasskeyCredential = {
+      id: rawId,
+      credentialId: rawId,
+      displayName:
+        (body.displayName ?? '').trim() || `Browser Passkey (${passkeys.length + 1})`,
+      deviceType: body.deviceType || 'laptop',
+      authenticatorName: body.authenticatorName || 'Browser Authenticator',
+      createdAt: new Date().toISOString(),
+      lastUsedAt: new Date().toISOString(),
+      transports: body.transports || ['internal', 'hybrid'],
+      backedUp: body.backedUp ?? true,
+    };
+
+    passkeys = [newPasskey, ...passkeys];
+    await saveState(session, user, passkeys);
+    return new Response(
+      JSON.stringify({
+        user,
+        passkeys,
+        passkey: newPasskey,
+        allAcceptedCredentialIds: passkeys.map((pk) => pk.credentialId),
+      }),
+      {
+        status: 201,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  if (action === 'reset') {
+    user = { ...DEFAULT_READER_ACCOUNT };
+    passkeys = DEFAULT_PASSKEYS.map((pk) => ({ ...pk }));
+    await saveState(session, user, passkeys);
+    return new Response(
+      JSON.stringify({
+        user,
+        passkeys,
+        allAcceptedCredentialIds: passkeys.map((pk) => pk.credentialId),
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  return new Response(JSON.stringify({ error: 'Unsupported action' }), {
+    status: 400,
+    headers: { 'Content-Type': 'application/json' },
+  });
+};
+
+export const PATCH: APIRoute = async ({ request, session }) => {
+  let body: any = {};
+  try {
+    body = await request.json();
+  } catch {
+    return new Response(JSON.stringify({ error: 'Invalid JSON payload' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  let { user, passkeys } = await loadState(session);
+  const targetId = body.credentialId || body.id;
+
+  if (targetId && body.displayName) {
+    passkeys = passkeys.map((pk) =>
+      pk.credentialId === targetId || pk.id === targetId
+        ? { ...pk, displayName: body.displayName.trim() }
+        : pk
+    );
+  } else if (body.displayName || body.name) {
+    user = {
+      ...user,
+      displayName: body.displayName ? body.displayName.trim() : user.displayName,
+      name: body.name ? body.name.trim() : user.name,
+    };
+  }
+
+  await saveState(session, user, passkeys);
+  return new Response(
+    JSON.stringify({
+      user,
+      passkeys,
+      allAcceptedCredentialIds: passkeys.map((pk) => pk.credentialId),
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
+
+export const PUT: APIRoute = PATCH;
+
+export const DELETE: APIRoute = async ({ request, url, session }) => {
+  let targetId =
+    url.searchParams.get('credentialId') || url.searchParams.get('id');
+
+  if (!targetId) {
+    try {
+      const body = await request.json();
+      targetId = body.credentialId || body.id;
+    } catch {
+      // Ignore empty body
+    }
+  }
+
+  if (!targetId) {
+    return new Response(
+      JSON.stringify({ error: 'Credential ID is required' }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  let { user, passkeys } = await loadState(session);
+  passkeys = passkeys.filter(
+    (pk) => pk.credentialId !== targetId && pk.id !== targetId
+  );
+
+  await saveState(session, user, passkeys);
+  return new Response(
+    JSON.stringify({
+      user,
+      passkeys,
+      removedCredentialId: targetId,
+      allAcceptedCredentialIds: passkeys.map((pk) => pk.credentialId),
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
