+export interface ReaderAccount {
+  userId: string; // Base64URL-encoded user handle
+  name: string; // Username or email address
+  displayName: string; // Reader's human-friendly display name
+  subscriptionTier: string;
+  memberSince: string;
+}
+
+export interface PasskeyCredential {
+  id: string; // Base64URL-encoded credential ID
+  credentialId: string; // Base64URL-encoded credential ID
+  displayName: string; // Friendly display name of the passkey
+  deviceType: 'laptop' | 'phone' | 'security-key';
+  authenticatorName: string;
+  createdAt: string;
+  lastUsedAt: string | null;
+  transports: string[];
+  backedUp: boolean;
+}
+
+export const DEFAULT_READER_ACCOUNT: ReaderAccount = {
+  // "reader_id_01" (12 bytes) -> Base64URL without padding
+  userId: 'cmVhZGVyX2lkXzAx',
+  name: 'alex.rivera@devtoolstimes.com',
+  displayName: 'Alex Rivera',
+  subscriptionTier: 'Digital All-Access Subscriber',
+  memberSince: 'March 2024',
+};
+
+export const DEFAULT_PASSKEYS: PasskeyCredential[] = [
+  {
+    // "passkey_cred_macbook_001" (24 bytes) -> Base64URL without padding
+    id: 'cGFzc2tleV9jcmVkX21hY2Jvb2tfMDAx',
+    credentialId: 'cGFzc2tleV9jcmVkX21hY2Jvb2tfMDAx',
+    displayName: 'MacBook Pro (Touch ID)',
+    deviceType: 'laptop',
+    authenticatorName: 'iCloud Keychain',
+    createdAt: '2026-08-14T10:30:00Z',
+    lastUsedAt: '2026-11-14T19:45:00Z',
+    transports: ['internal', 'hybrid'],
+    backedUp: true,
+  },
+  {
+    // "passkey_cred_pixel_phone" (24 bytes) -> Base64URL without padding
+    id: 'cGFzc2tleV9jcmVkX3BpeGVsX3Bob25l',
+    credentialId: 'cGFzc2tleV9jcmVkX3BpeGVsX3Bob25l',
+    displayName: 'Pixel 9 Pro',
+    deviceType: 'phone',
+    authenticatorName: 'Google Password Manager',
+    createdAt: '2026-09-02T14:15:00Z',
+    lastUsedAt: '2026-11-10T08:12:00Z',
+    transports: ['internal', 'hybrid'],
+    backedUp: true,
+  },
+  {
+    // "passkey_cred_yubikey_nfc" (24 bytes) -> Base64URL without padding
+    id: 'cGFzc2tleV9jcmVkX3l1YmlrZXlfbmZj',
+    credentialId: 'cGFzc2tleV9jcmVkX3l1YmlrZXlfbmZj',
+    displayName: 'YubiKey 5 NFC (Backup Key)',
+    deviceType: 'security-key',
+    authenticatorName: 'Hardware Security Key',
+    createdAt: '2026-05-20T09:00:00Z',
+    lastUsedAt: '2026-07-01T16:20:00Z',
+    transports: ['usb', 'nfc'],
+    backedUp: false,
+  },
+];
+
+// Server-side fallback state in case session storage is not persisted by a client
+let fallbackAccount: ReaderAccount = { ...DEFAULT_READER_ACCOUNT };
+let fallbackPasskeys: PasskeyCredential[] = DEFAULT_PASSKEYS.map((pk) => ({ ...pk }));
+
+export function getFallbackState(): {
+  user: ReaderAccount;
+  passkeys: PasskeyCredential[];
+} {
+  return {
+    user: { ...fallbackAccount },
+    passkeys: fallbackPasskeys.map((pk) => ({ ...pk })),
+  };
+}
+
+export function setFallbackState(
+  user: ReaderAccount,
+  passkeys: PasskeyCredential[]
+): void {
+  fallbackAccount = { ...user };
+  fallbackPasskeys = passkeys.map((pk) => ({ ...pk }));
+}
+
+export function encodeBase64Url(input: string | Uint8Array): string {
+  const bytes =
+    typeof input === 'string' ? new TextEncoder().encode(input) : input;
+  let binary = '';
+  for (let i = 0; i < bytes.byteLength; i++) {
+    binary += String.fromCharCode(bytes[i]);
+  }
+  const base64 =
+    typeof btoa === 'function'
+      ? btoa(binary)
+      : Buffer.from(bytes).toString('base64');
+  return base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function decodeBase64UrlToUint8Array(base64url: string): Uint8Array {
+  const base64 = base64url.replace(/-/g, '+').replace(/_/g, '/');
+  const padLength = (4 - (base64.length % 4)) % 4;
+  const padded = base64 + '='.repeat(padLength);
+  if (typeof atob === 'function') {
+    const binary = atob(padded);
+    const bytes = new Uint8Array(binary.length);
+    for (let i = 0; i < binary.length; i++) {
+      bytes[i] = binary.charCodeAt(i);
+    }
+    return bytes;
+  }
+  return new Uint8Array(Buffer.from(padded, 'base64'));
+}

