+              ? 'Updating your password requires confirming your identity with a passkey or your current password.'
+              : 'Your account is currently passwordless. You can optionally configure a fallback password after verifying with your passkey.'}
+          </p>
+
+          <form onSubmit={handlePasswordSubmit} className="space-y-4">
+            <div>
+              <label htmlFor="settings-new-password" className="block text-xs font-medium text-gray-700 mb-1">
+                New Password
+              </label>
+              <input
+                id="settings-new-password"
+                type="password"
+                autoComplete="new-password"
+                value={newPassword}
+                onChange={(e) => setNewPassword(e.target.value)}
+                placeholder="At least 8 characters with a number"
+                required
+                className="w-full px-3 py-2 text-sm border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-gray-900"
+              />
+            </div>
+
+            <button
+              type="submit"
+              disabled={savingPassword}
+              data-testid="change-password-btn"
+              className="w-full py-2 px-4 rounded-md text-xs font-semibold text-gray-900 bg-white border border-gray-300 hover:bg-gray-50 disabled:opacity-60"
+            >
+              {savingPassword
+                ? 'Updating Password...'
+                : user.hasPassword
+                ? 'Verify & Update Password'
+                : 'Verify & Set Password'}
+            </button>
+          </form>
+        </section>
+      </div>
+
+      {/* Reauthentication Modal */}
+      <ReauthenticateModal
+        isOpen={reauthModalOpen}
+        user={user}
+        actionDescription={reauthActionLabel}
+        onSuccess={handleReauthSuccess}
+        onClose={() => {
+          setReauthModalOpen(false);
+          setPendingAction(null);
+        }}
+      />
+    </div>
+  );
+}
