diff --git a/src/components/HeaderAuthNav.tsx b/src/components/HeaderAuthNav.tsx
new file mode 100644
index 0000000..3c1b650
--- /dev/null
+++ b/src/components/HeaderAuthNav.tsx
@@ -0,0 +1,85 @@
+import React, { useState, useEffect } from 'react';
+import { KeyIcon, UserCircleIcon } from '@heroicons/react/24/outline';
+import {
+  fetchCurrentSession,
+  signOutUser,
+  AUTH_STATE_CHANGED_EVENT,
+  getBaseUrl,
+  type ClientUserSession,
+} from '../utils/webauthn-client';
+
+export default function HeaderAuthNav() {
+  const [user, setUser] = useState<ClientUserSession | null>(null);
+  const baseUrl = getBaseUrl();
+
+  useEffect(() => {
+    fetchCurrentSession().then((u) => {
+      if (u) setUser(u);
+    });
+
+    const handleAuthChange = (e: Event) => {
+      const custom = e as CustomEvent;
+      setUser(custom.detail?.user || null);
+    };
+
+    window.addEventListener(AUTH_STATE_CHANGED_EVENT, handleAuthChange);
+    return () => {
+      window.removeEventListener(AUTH_STATE_CHANGED_EVENT, handleAuthChange);
+    };
+  }, []);
+
+  const handleSignOut = async () => {
+    await signOutUser();
+    setUser(null);
+  };
+
+  return (
+    <div className="flex items-center space-x-3">
+      {user ? (
+        <>
+          <a
+            href={`${baseUrl}account`}
+            data-skip-tracking="true"
+            className="inline-flex items-center space-x-1.5 bg-gray-900 text-white text-xs font-semibold py-2 px-3 rounded whitespace-nowrap hover:bg-gray-800"
+          >
+            <KeyIcon className="w-3.5 h-3.5 text-amber-400" />
+            <span>Account ({user.username})</span>
+          </a>
+          <button
+            type="button"
+            onClick={handleSignOut}
+            data-skip-tracking="true"
+            className="bg-gray-200 text-gray-800 text-xs font-semibold py-2 px-3 rounded whitespace-nowrap hover:bg-gray-300"
+          >
+            Sign out
+          </button>
+        </>
+      ) : (
+        <>
+          <a
+            href={`${baseUrl}account`}
+            data-skip-tracking="true"
+            className="inline-flex items-center space-x-1 text-gray-700 hover:text-gray-900 text-xs font-semibold py-2 px-2.5 rounded hover:bg-gray-100 whitespace-nowrap"
+          >
+            <UserCircleIcon className="w-4 h-4 text-gray-600" />
+            <span>Account Settings</span>
+          </a>
+          <a
+            href={`${baseUrl}signup`}
+            data-skip-tracking="true"
+            className="bg-gray-800 text-white text-xs font-semibold py-2 px-3 rounded whitespace-nowrap hover:bg-gray-700"
+          >
+            Sign up
+          </a>
+          <a
+            href={`${baseUrl}signin`}
+            data-skip-tracking="true"
+            className="bg-gray-500 text-white text-xs font-semibold py-2 px-3 rounded hover:bg-gray-400 whitespace-nowrap"
+          >
+            Sign in
+          </a>
+        </>
+      )}
+    </div>
+  );
+}
diff --git a/src/components/ReauthenticateModal.tsx b/src/components/ReauthenticateModal.tsx
new file mode 100644
index 0000000..598f835
--- /dev/null
+++ b/src/components/ReauthenticateModal.tsx
@@ -0,0 +1,281 @@
+import React, { useState } from 'react';
+import {
+  KeyIcon,
+  ShieldCheckIcon,
+  LockClosedIcon,
+  XMarkIcon,
+  CheckCircleIcon,
+  ExclamationTriangleIcon,
+} from '@heroicons/react/24/outline';
+import {
+  authenticateWithPasskey,
+  getBaseUrl,
+  getAuthHeaders,
+  saveClientAuthState,
+  getStoredToken,
+  type ClientUserSession,
+} from '../utils/webauthn-client';
+
+interface ReauthenticateModalProps {
+  isOpen: boolean;
+  user: ClientUserSession;
+  actionDescription?: string;
+  onSuccess: (updatedUser: ClientUserSession, method: 'passkey' | 'password') => void;
+  onClose: () => void;
+}
+
+export default function ReauthenticateModal({
+  isOpen,
+  user,
+  actionDescription = 'perform this security-sensitive action',
+  onSuccess,
+  onClose,
+}: ReauthenticateModalProps) {
+  const hasPasskeys = user.passkeys && user.passkeys.length > 0;
+  const [mode, setMode] = useState<'passkey' | 'password'>(
+    hasPasskeys ? 'passkey' : 'password'
+  );
+  const [password, setPassword] = useState('');
+  const [loading, setLoading] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const [verifiedBanner, setVerifiedBanner] = useState<string | null>(null);
+
+  if (!isOpen) return null;
+
+  const handlePasskeyReauth = async () => {
+    setError(null);
+    setLoading(true);
+    try {
+      const result = await authenticateWithPasskey({
+        username: user.username,
+        purpose: 'reauthenticate',
+      });
+      setVerifiedBanner(`Verified with passkey "${result.passkey.name}"`);
+      setTimeout(() => {
+        setVerifiedBanner(null);
+        onSuccess(result.user, 'passkey');
+      }, 450);
+    } catch (err: any) {
+      setError(err?.message || 'Passkey verification failed. Please try again.');
+    } finally {
+      setLoading(false);
+    }
+  };
+
+  const handlePasswordReauth = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setError(null);
+    setLoading(true);
+    try {
+      const baseUrl = getBaseUrl();
+      const res = await fetch(`${baseUrl}api/auth/reauthenticate`, {
+        method: 'POST',
+        headers: getAuthHeaders(),
+        body: JSON.stringify({ password }),
+      });
+      const data = await res.json();
+      if (!res.ok) {
+        setError(data.error || 'Password verification failed.');
+      } else {
+        saveClientAuthState(getStoredToken(), data.user);
+        setPassword('');
+        setVerifiedBanner('Verified with password');
+        setTimeout(() => {
+          setVerifiedBanner(null);
+          onSuccess(data.user, 'password');
+        }, 450);
+      }
+    } catch {
+      setError('An unexpected error occurred during verification.');
+    } finally {
+      setLoading(false);
+    }
+  };
+
+  return (
+    <div
+      className="fixed inset-0 bg-black/50 backdrop-blur-xs z-[99999] flex items-center justify-center p-4"
+      role="dialog"
+      aria-modal="true"
+      aria-labelledby="reauth-modal-title"
+      data-testid="reauth-modal"
+      onClick={onClose}
+    >
+      <div
+        className="bg-white rounded-xl shadow-2xl border border-gray-200 w-full max-w-md overflow-hidden"
+        onClick={(e) => e.stopPropagation()}
+      >
+        {/* Header */}
+        <div className="bg-gray-900 text-white px-6 py-4 flex items-center justify-between">
+          <div className="flex items-center space-x-2.5">
+            <ShieldCheckIcon className="w-6 h-6 text-amber-400" />
+            <h3 id="reauth-modal-title" className="text-lg font-bold">
+              Confirm Your Identity
+            </h3>
+          </div>
+          <button
+            type="button"
+            onClick={onClose}
+            aria-label="Close reauthentication dialog"
+            className="text-gray-400 hover:text-white p-1 rounded-md transition-colors"
+          >
+            <XMarkIcon className="w-5 h-5" />
+          </button>
+        </div>
+
+        {/* Body */}
+        <div className="p-6">
+          <p className="text-sm text-gray-600 mb-4">
+            For your security, please reauthenticate as{' '}
+            <span className="font-semibold text-gray-900">{user.username}</span> to{' '}
+            <span className="font-medium text-gray-800">{actionDescription}</span>.
+          </p>
+
+          {error && (
+            <div
+              className="mb-4 p-3 text-sm text-red-700 bg-red-50 border border-red-200 rounded-lg flex items-start space-x-2"
+              role="alert"
+            >
+              <ExclamationTriangleIcon className="w-5 h-5 text-red-600 shrink-0 mt-0.5" />
+              <span>{error}</span>
+            </div>
+          )}
+
+          {verifiedBanner && (
+            <div
+              className="mb-4 p-3 text-sm text-green-800 bg-green-50 border border-green-200 rounded-lg flex items-center space-x-2"
+              role="status"
+            >
+              <CheckCircleIcon className="w-5 h-5 text-green-600 shrink-0" />
+              <span>{verifiedBanner}</span>
+            </div>
+          )}
+
+          {/* Method Switcher if user has both passkey and password options */}
+          {hasPasskeys && user.hasPassword && (
+            <div className="grid grid-cols-2 gap-2 p-1 bg-gray-100 rounded-lg mb-5">
+              <button
+                type="button"
+                onClick={() => {
+                  setMode('passkey');
+                  setError(null);
+                }}
+                className={`py-1.5 text-xs font-semibold rounded-md flex items-center justify-center space-x-1.5 transition ${
+                  mode === 'passkey'
+                    ? 'bg-white text-gray-900 shadow-xs'
+                    : 'text-gray-600 hover:text-gray-900'
+                }`}
+              >
+                <KeyIcon className="w-4 h-4" />
+                <span>Use Passkey</span>
+              </button>
+              <button
+                type="button"
+                onClick={() => {
+                  setMode('password');
+                  setError(null);
+                }}
+                className={`py-1.5 text-xs font-semibold rounded-md flex items-center justify-center space-x-1.5 transition ${
+                  mode === 'password'
+                    ? 'bg-white text-gray-900 shadow-xs'
+                    : 'text-gray-600 hover:text-gray-900'
+                }`}
+              >
+                <LockClosedIcon className="w-4 h-4" />
+                <span>Use Password</span>
+              </button>
+            </div>
+          )}
+
+          {mode === 'passkey' ? (
+            <div className="space-y-4">
+              <div className="p-4 bg-gray-50 border border-gray-200 rounded-lg text-center">
+                <div className="w-12 h-12 mx-auto mb-3 rounded-full bg-amber-100 text-amber-800 flex items-center justify-center">
+                  <KeyIcon className="w-6 h-6" />
+                </div>
+                <p className="text-sm font-medium text-gray-900 mb-1">
+                  Passkey Verification
+                </p>
+                <p className="text-xs text-gray-500">
+                  Use your fingerprint, face recognition, screen lock, or hardware security key to verify your identity.
+                </p>
+              </div>
+
+              <button
+                type="button"
+                onClick={handlePasskeyReauth}
+                disabled={loading}
+                data-testid="reauth-passkey-btn"
+                className={`w-full py-2.5 px-4 rounded-md shadow-xs text-sm font-semibold text-white bg-gray-900 hover:bg-gray-800 flex items-center justify-center space-x-2 transition ${
+                  loading ? 'opacity-75 cursor-not-allowed' : ''
+                }`}
+              >
+                <KeyIcon className="w-4 h-4" />
+                <span>{loading ? 'Verifying with passkey...' : 'Verify with passkey'}</span>
+              </button>
+
+              {user.hasPassword && (
+                <button
+                  type="button"
+                  onClick={() => {
+                    setMode('password');
+                    setError(null);
+                  }}
+                  className="w-full text-center text-xs text-gray-500 hover:text-gray-800 underline"
+                >
+                  Trouble with your passkey? Verify with password instead
+                </button>
+              )}
+            </div>
+          ) : (
+            <form onSubmit={handlePasswordReauth} className="space-y-4">
+              <div>
+                <label
+                  htmlFor="reauth-password"
