+++ b/src/pages/api/auth/account.ts
@@ -0,0 +1,102 @@
+import type { APIRoute } from 'astro';
+import {
+  extractTokenFromRequest,
+  getAuthSession,
+  isSessionRecentlyReauthenticated,
+  updateUserProfile,
+  updateUserPassword,
+  deleteUserAccount,
+  clearSessionCookieHeader,
+  serializeUserForClient,
+} from '../../../utils/auth-store';
+
+export const PATCH: APIRoute = async ({ request }) => {
+  try {
+    const token = extractTokenFromRequest(request);
+    const activeAuth = getAuthSession(token);
+    if (!activeAuth) {
+      return new Response(
+        JSON.stringify({ error: 'Authentication required.' }),
+        { status: 401, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const body = await request.json();
+    const { action, displayName, email, username, newPassword } = body;
+
+    if (action === 'change-password') {
+      if (!newPassword || newPassword.length < 8 || !/\d/.test(newPassword)) {
+        return new Response(
+          JSON.stringify({
+            error: 'New password must be at least 8 characters and contain a number.',
+          }),
+          { status: 400, headers: { 'Content-Type': 'application/json' } }
+        );
+      }
+
+      const updatedUser = updateUserPassword(activeAuth.user.id, newPassword);
+      return new Response(
+        JSON.stringify({
+          updated: true,
+          message: 'Password updated successfully.',
+          user: serializeUserForClient(updatedUser, activeAuth.session),
+        }),
+        { status: 200, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const updatedUser = updateUserProfile(activeAuth.user.id, {
+      displayName,
+      email,
+      username,
+    });
+
+    return new Response(
+      JSON.stringify({
+        updated: true,
+        message: 'Account profile updated.',
+        user: serializeUserForClient(updatedUser, activeAuth.session),
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to update account.' }),
+      { status: 400, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
+
+export const DELETE: APIRoute = async ({ request }) => {
+  const token = extractTokenFromRequest(request);
+  const activeAuth = getAuthSession(token);
+  if (!activeAuth) {
+    return new Response(
+      JSON.stringify({ error: 'Authentication required.' }),
+      { status: 401, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+
+  if (!isSessionRecentlyReauthenticated(activeAuth.session)) {
+    return new Response(
+      JSON.stringify({
+        error: 'REAUTH_REQUIRED',
+        message: 'Please reauthenticate with your passkey or password before deleting your account.',
+      }),
+      { status: 403, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+
+  deleteUserAccount(activeAuth.user.id);
+
+  return new Response(
+    JSON.stringify({ deleted: true }),
+    {
+      status: 200,
+      headers: {
+        'Content-Type': 'application/json',
+        'Set-Cookie': clearSessionCookieHeader(),
+      },
+    }
+  );
+};
