@@ -0,0 +1,93 @@
+import type { APIRoute } from 'astro';
+import {
+  findUserByUsername,
+  createUser,
+  verifyUserPassword,
+  createAuthSession,
+  createSessionCookieHeader,
+  serializeUserForClient,
+} from '../../../utils/auth-store';
+
+export const POST: APIRoute = async ({ request }) => {
+  try {
+    const body = await request.json();
+    const username: string = (body.username || '').trim();
+    const password: string = body.password || '';
+
+    if (!username || !password) {
+      return new Response(
+        JSON.stringify({ error: 'APP_ERR_2001: Username and password are required.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    let user = findUserByUsername(username);
+
+    // If user doesn't exist locally yet, check if external CDN login succeeds or create/verify locally
+    if (!user) {
+      let cdnApproved = false;
+      try {
+        const cdnRes = await fetch(
+          'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/login',
+          {
+            method: 'POST',
+            headers: { 'Content-Type': 'application/json' },
+            body: JSON.stringify({ username, password }),
+            signal: AbortSignal.timeout(2500),
+          }
+        );
+        if (cdnRes.ok) {
+          cdnApproved = true;
+        }
+      } catch {
+        // Offline or CDN unreachable
+      }
+
+      if (cdnApproved) {
+        user = createUser({ username, password });
+      } else {
+        return new Response(
+          JSON.stringify({ error: 'APP_ERR_2002: Invalid username or password.' }),
+          { status: 401, headers: { 'Content-Type': 'application/json' } }
+        );
+      }
+    } else {
+      if (!user.hasPassword) {
+        return new Response(
+          JSON.stringify({
+            error:
+              'This account uses passkey sign-in and does not have a password configured. Please sign in with your passkey.',
+          }),
+          { status: 401, headers: { 'Content-Type': 'application/json' } }
+        );
+      }
+      if (!verifyUserPassword(user, password)) {
+        return new Response(
+          JSON.stringify({ error: 'APP_ERR_2002: Invalid username or password.' }),
+          { status: 401, headers: { 'Content-Type': 'application/json' } }
+        );
+      }
+    }
+
+    const session = createAuthSession(user, 'password');
+
+    return new Response(
+      JSON.stringify({
+        token: session.token,
+        user: serializeUserForClient(user, session),
+      }),
+      {
+        status: 200,
+        headers: {
+          'Content-Type': 'application/json',
+          'Set-Cookie': createSessionCookieHeader(session.token),
+        },
+      }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Sign-in failed.' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
