@@ -0,0 +1,68 @@
+import type { APIRoute } from 'astro';
+import {
+  extractTokenFromRequest,
+  getAuthSession,
+  findUserByUsername,
+  saveChallenge,
+} from '../../../../utils/auth-store';
+import { generateChallenge } from '../../../../utils/webauthn-server';
+
+export const POST: APIRoute = async ({ request, url }) => {
+  try {
+    const body = await request.json().catch(() => ({}));
+    const purpose: 'authenticate' | 'reauthenticate' =
+      body.purpose === 'reauthenticate' ? 'reauthenticate' : 'authenticate';
+    const requestedUsername: string | undefined = body.username?.trim();
+
+    const token = extractTokenFromRequest(request);
+    const activeAuth = getAuthSession(token);
+
+    let allowCredentials: Array<{ id: string; type: 'public-key'; transports?: string[] }> = [];
+    let targetUserId: string | undefined;
+    let targetUsername: string | undefined;
+
+    if (purpose === 'reauthenticate' && activeAuth) {
+      targetUserId = activeAuth.user.id;
+      targetUsername = activeAuth.user.username;
+      allowCredentials = activeAuth.user.passkeys.map((pk) => ({
+        id: pk.id,
+        type: 'public-key' as const,
+        transports: pk.transports,
+      }));
+    } else if (requestedUsername) {
+      const user = findUserByUsername(requestedUsername);
+      if (user) {
+        targetUserId = user.id;
+        targetUsername = user.username;
+        allowCredentials = user.passkeys.map((pk) => ({
+          id: pk.id,
+          type: 'public-key' as const,
+          transports: pk.transports,
+        }));
+      }
+    }
+
+    const challenge = generateChallenge();
+    saveChallenge(challenge, purpose, targetUserId, targetUsername);
+
+    const rpId = body.rpId || url.hostname || 'localhost';
+
+    const options = {
+      challenge,
+      rpId,
+      timeout: 60000,
+      userVerification: 'preferred',
+      allowCredentials,
+    };
+
+    return new Response(JSON.stringify(options), {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to generate authentication options.' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
