+++ b/src/pages/api/auth/reauthenticate.ts
@@ -0,0 +1,56 @@
+import type { APIRoute } from 'astro';
+import {
+  extractTokenFromRequest,
+  getAuthSession,
+  verifyUserPassword,
+  markSessionReauthenticated,
+  serializeUserForClient,
+} from '../../../utils/auth-store';
+
+export const POST: APIRoute = async ({ request }) => {
+  try {
+    const token = extractTokenFromRequest(request);
+    const activeAuth = getAuthSession(token);
+    if (!activeAuth) {
+      return new Response(
+        JSON.stringify({ error: 'Authentication required.' }),
+        { status: 401, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const body = await request.json();
+    const password: string = body.password || '';
+
+    if (!activeAuth.user.hasPassword) {
+      return new Response(
+        JSON.stringify({
+          error: 'No password is set on this account. Please verify using your passkey.',
+        }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    if (!verifyUserPassword(activeAuth.user, password)) {
+      return new Response(
+        JSON.stringify({ error: 'Incorrect password. Reauthentication failed.' }),
+        { status: 401, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const updatedSession = markSessionReauthenticated(activeAuth.session.token, 'password')!;
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        reauthenticated: true,
+        user: serializeUserForClient(activeAuth.user, updatedSession),
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Reauthentication failed.' }),
+      { status: 400, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
diff --git a/src/pages/api/auth/register.ts b/src/pages/api/auth/register.ts
new file mode 100644
index 0000000..2295480
--- /dev/null
+++ b/src/pages/api/auth/register.ts
@@ -0,0 +1,70 @@
+import type { APIRoute } from 'astro';
+import {
+  findUserByUsername,
+  createUser,
+  createAuthSession,
+  createSessionCookieHeader,
+  serializeUserForClient,
+} from '../../../utils/auth-store';
+
+export const POST: APIRoute = async ({ request }) => {
+  try {
+    const body = await request.json();
+    const username: string = (body.username || '').trim();
+    const password: string = body.password || '';
+    const displayName: string = (body.displayName || '').trim();
+    const email: string = (body.email || '').trim();
+
+    if (!username) {
+      return new Response(
+        JSON.stringify({ error: 'APP_ERR_1002: Username is required.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    if (password && (password.length < 8 || !/\d/.test(password))) {
+      return new Response(
+        JSON.stringify({
+          error: 'APP_ERR_1003: Password must be at least 8 characters and contain a number.',
+        }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const existing = findUserByUsername(username);
+    if (existing) {
+      return new Response(
+        JSON.stringify({ error: 'APP_ERR_1001: Username is already taken.' }),
+        { status: 409, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const user = createUser({
+      username,
+      displayName: displayName || username,
+      email: email || undefined,
+      password: password || undefined,
+    });
+
+    const session = createAuthSession(user, 'password');
+
+    return new Response(
+      JSON.stringify({
+        token: session.token,
+        user: serializeUserForClient(user, session),
+      }),
+      {
+        status: 201,
+        headers: {
+          'Content-Type': 'application/json',
+          'Set-Cookie': createSessionCookieHeader(session.token),
+        },
+      }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Registration failed.' }),
+      { status: 400, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
