diff --git a/src/utils/auth-store.ts b/src/utils/auth-store.ts
new file mode 100644
index 0000000..c048d2e
--- /dev/null
+++ b/src/utils/auth-store.ts
@@ -0,0 +1,473 @@
+import crypto from 'node:crypto';
+import fs from 'node:fs';
+import path from 'node:path';
+import os from 'node:os';
+import { bufferToBase64URL } from './webauthn-server';
+
+export interface StoredPasskey {
+  id: string; // Credential ID (base64url)
+  name: string; // Friendly user-assigned or auto-detected name
+  publicKeySpki?: string; // SPKI DER base64url (from getPublicKey())
+  cosePublicKey?: string; // COSE CBOR base64url (from authenticatorData)
+  algorithm: number; // COSE algorithm identifier (-7 ES256, -257 RS256, -8 EdDSA)
+  transports: string[];
+  counter: number;
+  aaguid: string;
+  deviceType: 'singleDevice' | 'multiDevice';
+  backedUp: boolean;
+  createdAt: string;
+  lastUsedAt: string | null;
+}
+
+export interface StoredUser {
+  id: string; // User handle (base64url)
+  username: string;
+  displayName: string;
+  email: string;
+  passwordHash?: string; // Optional if registered passwordlessly with a passkey
+  hasPassword: boolean;
+  createdAt: string;
+  passkeys: StoredPasskey[];
+}
+
+export interface AuthSessionRecord {
+  token: string;
+  userId: string;
+  username: string;
+  authMethod: 'passkey' | 'password';
+  credentialId?: string;
+  createdAt: number;
+  lastReauthenticatedAt: number;
+  lastReauthMethod?: 'passkey' | 'password';
+}
+
+interface PendingChallenge {
+  challenge: string;
+  userId?: string;
+  username?: string;
+  purpose: 'register' | 'authenticate' | 'reauthenticate';
+  createdAt: number;
+}
+
+interface StoreData {
+  users: Record<string, StoredUser>; // keyed by userId
+  sessions: Record<string, AuthSessionRecord>; // keyed by token
+  challenges: Record<string, PendingChallenge>; // keyed by challenge string
+}
+
+const STORE_FILE = path.join(os.tmpdir(), 'devtools-times-auth-store.json');
+
+function hashPassword(password: string): string {
+  return crypto.createHash('sha256').update(`devtools-times-salt:${password}`).digest('hex');
+}
+
+function createInitialStore(): StoreData {
+  const defaultUserId = bufferToBase64URL(Buffer.from('user-editor-alex-rivera'));
+  const now = new Date().toISOString();
+  const demoUser: StoredUser = {
+    id: defaultUserId,
+    username: 'alex.rivera',
+    displayName: 'Alex Rivera',
+    email: 'alex.rivera@devtoolstimes.com',
+    passwordHash: hashPassword('password123'),
+    hasPassword: true,
+    createdAt: now,
+    passkeys: [],
+  };
+
+  return {
+    users: {
+      [defaultUserId]: demoUser,
+    },
+    sessions: {},
+    challenges: {},
+  };
+}
+
+let memoryStore: StoreData | null = null;
+
+function loadStore(): StoreData {
+  if (memoryStore) return memoryStore;
+  try {
+    if (fs.existsSync(STORE_FILE)) {
+      const raw = fs.readFileSync(STORE_FILE, 'utf-8');
+      const parsed = JSON.parse(raw) as StoreData;
+      if (parsed && parsed.users && parsed.sessions && parsed.challenges) {
+        memoryStore = parsed;
+        return memoryStore;
+      }
+    }
+  } catch {
+    // Fallback to initial store
+  }
+  memoryStore = createInitialStore();
+  saveStore(memoryStore);
+  return memoryStore;
+}
+
+function saveStore(store: StoreData): void {
+  memoryStore = store;
+  try {
+    fs.writeFileSync(STORE_FILE, JSON.stringify(store, null, 2), 'utf-8');
+  } catch {
+    // Ignore fs errors in restricted environments; memoryStore still holds state
+  }
+}
+
+// --- Challenge Operations ---
+
+export function saveChallenge(
+  challenge: string,
+  purpose: 'register' | 'authenticate' | 'reauthenticate',
+  userId?: string,
+  username?: string
+): void {
+  const store = loadStore();
+  // Clean up expired challenges (> 10 minutes)
+  const cutoff = Date.now() - 10 * 60 * 1000;
+  for (const [k, v] of Object.entries(store.challenges)) {
+    if (v.createdAt < cutoff) {
+      delete store.challenges[k];
+    }
+  }
+  store.challenges[challenge] = {
+    challenge,
+    purpose,
+    userId,
+    username,
+    createdAt: Date.now(),
+  };
+  saveStore(store);
+}
+
+export function consumeChallenge(challenge: string): PendingChallenge | null {
+  const store = loadStore();
+  const record = store.challenges[challenge];
+  if (!record) return null;
+  delete store.challenges[challenge];
+  saveStore(store);
+  return record;
+}
+
+// --- User Operations ---
+
+export function findUserByUsername(username: string): StoredUser | undefined {
+  const store = loadStore();
+  const normalized = username.trim().toLowerCase();
+  return Object.values(store.users).find(
+    (u) => u.username.toLowerCase() === normalized || u.email.toLowerCase() === normalized
+  );
+}
+
+export function findUserById(userId: string): StoredUser | undefined {
+  const store = loadStore();
+  return store.users[userId];
+}
+
+export function findUserByCredentialId(credentialId: string): {
+  user: StoredUser;
+  passkey: StoredPasskey;
+} | null {
+  const store = loadStore();
+  for (const user of Object.values(store.users)) {
+    const pk = user.passkeys.find((p) => p.id === credentialId);
+    if (pk) {
+      return { user, passkey: pk };
+    }
+  }
+  return null;
+}
+
+export function createUser(params: {
+  username: string;
+  displayName?: string;
+  email?: string;
+  password?: string;
+  userId?: string;
+}): StoredUser {
+  const store = loadStore();
+  const cleanUsername = params.username.trim();
+  const existing = findUserByUsername(cleanUsername);
+  if (existing) {
+    throw new Error('APP_ERR_1001: Username is already taken.');
+  }
+
+  const id = params.userId || bufferToBase64URL(crypto.randomBytes(16));
+  const email =
+    params.email?.trim() ||
+    (cleanUsername.includes('@') ? cleanUsername : `${cleanUsername}@devtoolstimes.com`);
+  const displayName = params.displayName?.trim() || cleanUsername;
+  const hasPassword = Boolean(params.password && params.password.length > 0);
+
+  const user: StoredUser = {
+    id,
+    username: cleanUsername,
+    displayName,
+    email,
+    passwordHash: hasPassword && params.password ? hashPassword(params.password) : undefined,
+    hasPassword,
+    createdAt: new Date().toISOString(),
+    passkeys: [],
+  };
+
+  store.users[id] = user;
+  saveStore(store);
+  return user;
+}
+
+export function ensureUserForRegistration(params: {
+  username: string;
+  displayName?: string;
+  email?: string;
+  password?: string;
+  userId?: string;
+}): StoredUser {
+  const existing = params.userId
+    ? findUserById(params.userId)
+    : findUserByUsername(params.username);
+  if (existing) {
+    return existing;
+  }
+  return createUser(params);
+}
+
+export function verifyUserPassword(user: StoredUser, password: string): boolean {
+  if (!user.hasPassword || !user.passwordHash) return false;
+  return user.passwordHash === hashPassword(password);
+}
+
+export function updateUserPassword(userId: string, newPassword: string): StoredUser {
+  const store = loadStore();
+  const user = store.users[userId];
+  if (!user) throw new Error('User not found');
+  user.passwordHash = hashPassword(newPassword);
+  user.hasPassword = true;
+  saveStore(store);
+  return user;
+}
+
+export function updateUserProfile(
+  userId: string,
+  updates: { username?: string; displayName?: string; email?: string }
+): StoredUser {
+  const store = loadStore();
+  const user = store.users[userId];
+  if (!user) throw new Error('User not found');
+
+  if (updates.username && updates.username.trim() !== user.username) {
+    const conflict = findUserByUsername(updates.username.trim());
+    if (conflict && conflict.id !== userId) {
+      throw new Error('Username is already taken by another account.');
+    }
+    user.username = updates.username.trim();
+  }
+  if (updates.displayName !== undefined) {
+    user.displayName = updates.displayName.trim() || user.username;
+  }
+  if (updates.email !== undefined) {
+    user.email = updates.email.trim();
+  }
+
+  saveStore(store);
+  return user;
+}
+
+export function deleteUserAccount(userId: string): void {
+  const store = loadStore();
+  delete store.users[userId];
+  for (const [token, sess] of Object.entries(store.sessions)) {
+    if (sess.userId === userId) {
+      delete store.sessions[token];
+    }
+  }
+  saveStore(store);
+}
+
+// --- Passkey Management Operations ---
+
+export function addPasskeyToUser(userId: string, passkey: StoredPasskey): StoredUser {
+  const store = loadStore();
+  const user = store.users[userId];
+  if (!user) throw new Error('User not found');
+
+  const existingIdx = user.passkeys.findIndex((p) => p.id === passkey.id);
+  if (existingIdx >= 0) {
+    user.passkeys[existingIdx] = passkey;
+  } else {
+    user.passkeys.push(passkey);
+  }
+
+  saveStore(store);
+  return user;
+}
+
+export function updatePasskeyUsage(
+  userId: string,
+  credentialId: string,
+  newCounter: number
+): StoredPasskey | null {
+  const store = loadStore();
+  const user = store.users[userId];
+  if (!user) return null;
+  const pk = user.passkeys.find((p) => p.id === credentialId);
+  if (!pk) return null;
+
+  if (newCounter > pk.counter) {
+    pk.counter = newCounter;
+  }
+  pk.lastUsedAt = new Date().toISOString();
+  saveStore(store);
+  return pk;
+}
+
+export function renameUserPasskey(
+  userId: string,
+  credentialId: string,
+  newName: string
+): StoredPasskey {
+  const store = loadStore();
+  const user = store.users[userId];
+  if (!user) throw new Error('User not found');
+  const pk = user.passkeys.find((p) => p.id === credentialId);
+  if (!pk) throw new Error('Passkey not found');
+
+  pk.name = newName.trim() || pk.name;
+  saveStore(store);
+  return pk;
+}
+
+export function deleteUserPasskey(userId: string, credentialId: string): StoredUser {
+  const store = loadStore();
+  const user = store.users[userId];
+  if (!user) throw new Error('User not found');
+  const idx = user.passkeys.findIndex((p) => p.id === credentialId);
+  if (idx === -1) throw new Error('Passkey not found');
+
+  user.passkeys.splice(idx, 1);
+  saveStore(store);
+  return user;
+}
+
+// --- Session & Reauthentication Operations ---
+
+export const REAUTH_WINDOW_MS = 5 * 60 * 1000; // 5 minutes sudo/reauthentication window
+
+export function createAuthSession(
+  user: StoredUser,
+  authMethod: 'passkey' | 'password',
+  credentialId?: string
+): AuthSessionRecord {
+  const store = loadStore();
+  const token = bufferToBase64URL(crypto.randomBytes(24));
+  const now = Date.now();
+  const session: AuthSessionRecord = {
+    token,
+    userId: user.id,
+    username: user.username,
+    authMethod,
+    credentialId,
+    createdAt: now,
+    lastReauthenticatedAt: now,
+    lastReauthMethod: authMethod,
+  };
+  store.sessions[token] = session;
+  saveStore(store);
+  return session;
+}
+
+export function getAuthSession(token?: string | null): {
+  session: AuthSessionRecord;
+  user: StoredUser;
+} | null {
+  if (!token) return null;
+  const store = loadStore();
+  const session = store.sessions[token];
+  if (!session) return null;
+  const user = store.users[session.userId];
+  if (!user) return null;
+  return { session, user };
+}
+
+export function markSessionReauthenticated(
+  token: string,
+  method: 'passkey' | 'password',
+  credentialId?: string
+): AuthSessionRecord | null {
+  const store = loadStore();
+  const session = store.sessions[token];
+  if (!session) return null;
+  session.lastReauthenticatedAt = Date.now();
+  session.lastReauthMethod = method;
+  if (credentialId) {
+    session.credentialId = credentialId;
+  }
+  saveStore(store);
+  return session;
+}
+
+export function isSessionRecentlyReauthenticated(session: AuthSessionRecord): boolean {
+  return Date.now() - session.lastReauthenticatedAt < REAUTH_WINDOW_MS;
+}
+
+export function destroyAuthSession(token: string): void {
+  const store = loadStore();
+  delete store.sessions[token];
+  saveStore(store);
+}
+
+export function extractTokenFromRequest(request: Request): string | null {
+  const authHeader = request.headers.get('authorization');
+  if (authHeader && authHeader.startsWith('Bearer ')) {
+    return authHeader.slice(7).trim();
+  }
+  const cookieHeader = request.headers.get('cookie') || '';
+  const match = cookieHeader.match(/(?:^|;\s*)dtt_session=([^;]+)/);
+  if (match) {
+    return decodeURIComponent(match[1]);
+  }
+  return null;
+}
+
+export function createSessionCookieHeader(token: string, maxAgeSeconds = 60 * 60 * 24 * 7): string {
+  return `dtt_session=${encodeURIComponent(token)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${maxAgeSeconds}`;
+}
+
+export function clearSessionCookieHeader(): string {
+  return `dtt_session=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0`;
+}
+
+export function serializeUserForClient(
+  user: StoredUser,
+  session?: AuthSessionRecord | null
+) {
+  return {
+    id: user.id,
+    username: user.username,
+    displayName: user.displayName,
+    email: user.email,
+    hasPassword: user.hasPassword,
+    createdAt: user.createdAt,
+    passkeys: user.passkeys.map((pk) => ({
+      id: pk.id,
+      name: pk.name,
+      transports: pk.transports,
+      counter: pk.counter,
+      aaguid: pk.aaguid,
+      deviceType: pk.deviceType,
+      backedUp: pk.backedUp,
+      createdAt: pk.createdAt,
+      lastUsedAt: pk.lastUsedAt,
+    })),
+    session: session
+      ? {
+          authMethod: session.authMethod,
+          credentialId: session.credentialId,
+          createdAt: session.createdAt,
+          lastReauthenticatedAt: session.lastReauthenticatedAt,
+          lastReauthMethod: session.lastReauthMethod,
+          isRecentlyReauthenticated: isSessionRecentlyReauthenticated(session),
+          reauthExpiresAt: session.lastReauthenticatedAt + REAUTH_WINDOW_MS,
+        }
+      : null,
+  };
+}
