+// Client-side WebAuthn / Passkey Helpers
+
+export interface ClientPasskeyInfo {
+  id: string;
+  name: string;
+  transports: string[];
+  counter: number;
+  aaguid: string;
+  deviceType: 'singleDevice' | 'multiDevice';
+  backedUp: boolean;
+  createdAt: string;
+  lastUsedAt: string | null;
+}
+
+export interface ClientUserSession {
+  id: string;
+  username: string;
+  displayName: string;
+  email: string;
+  hasPassword: boolean;
+  createdAt: string;
+  passkeys: ClientPasskeyInfo[];
+  session: {
+    authMethod: 'passkey' | 'password';
+    credentialId?: string;
+    createdAt: number;
+    lastReauthenticatedAt: number;
+    lastReauthMethod?: 'passkey' | 'password';
+    isRecentlyReauthenticated: boolean;
+    reauthExpiresAt: number;
+  } | null;
+}
+
+const AUTH_TOKEN_KEY = 'dtt_auth_token';
+const AUTH_USER_KEY = 'dtt_auth_user';
+export const AUTH_STATE_CHANGED_EVENT = 'dtt-auth-state-changed';
+
+export function getBaseUrl(): string {
+  const base = import.meta.env.BASE_URL || '/';
+  return base.endsWith('/') ? base : `${base}/`;
+}
+
+export function getStoredToken(): string | null {
+  if (typeof window === 'undefined') return null;
+  return localStorage.getItem(AUTH_TOKEN_KEY);
+}
+
+export function getStoredUser(): ClientUserSession | null {
+  if (typeof window === 'undefined') return null;
+  try {
+    const raw = localStorage.getItem(AUTH_USER_KEY);
+    return raw ? (JSON.parse(raw) as ClientUserSession) : null;
+  } catch {
+    return null;
+  }
+}
+
+export function saveClientAuthState(token: string | null, user: ClientUserSession | null): void {
+  if (typeof window === 'undefined') return;
+  if (token) {
+    localStorage.setItem(AUTH_TOKEN_KEY, token);
+  }
+  if (user) {
+    localStorage.setItem(AUTH_USER_KEY, JSON.stringify(user));
+  } else if (!token) {
+    localStorage.removeItem(AUTH_TOKEN_KEY);
+    localStorage.removeItem(AUTH_USER_KEY);
+  }
+  window.dispatchEvent(new CustomEvent(AUTH_STATE_CHANGED_EVENT, { detail: { user, token } }));
+}
+
+export function clearClientAuthState(): void {
+  if (typeof window === 'undefined') return;
+  localStorage.removeItem(AUTH_TOKEN_KEY);
+  localStorage.removeItem(AUTH_USER_KEY);
+  window.dispatchEvent(new CustomEvent(AUTH_STATE_CHANGED_EVENT, { detail: { user: null, token: null } }));
+}
+
+export function getAuthHeaders(): Record<string, string> {
+  const headers: Record<string, string> = {
+    'Content-Type': 'application/json',
+  };
+  const token = getStoredToken();
+  if (token) {
+    headers['Authorization'] = `Bearer ${token}`;
+  }
+  return headers;
+}
+
+// --- Base64URL <-> ArrayBuffer Conversions ---
+
+export function bufferToBase64URL(buffer: ArrayBuffer | Uint8Array): string {
+  const bytes = buffer instanceof Uint8Array ? buffer : new Uint8Array(buffer);
+  let binary = '';
+  for (let i = 0; i < bytes.byteLength; i++) {
+    binary += String.fromCharCode(bytes[i]);
+  }
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function base64URLToBuffer(base64url: string): ArrayBuffer {
+  const base64 = base64url.replace(/-/g, '+').replace(/_/g, '/');
+  const padLen = (4 - (base64.length % 4)) % 4;
+  const padded = base64 + '='.repeat(padLen);
+  const binary = atob(padded);
+  const bytes = new Uint8Array(binary.length);
+  for (let i = 0; i < binary.length; i++) {
+    bytes[i] = binary.charCodeAt(i);
+  }
+  return bytes.buffer;
+}
+
+// --- Feature Detection ---
+
+export interface WebAuthnCapabilities {
+  supported: boolean;
+  platformAuthenticator: boolean;
+  conditionalMediation: boolean;
+  parseCreationOptionsSupported: boolean;
+  parseRequestOptionsSupported: boolean;
+}
+
+export async function detectWebAuthnCapabilities(): Promise<WebAuthnCapabilities> {
+  if (
+    typeof window === 'undefined' ||
+    typeof window.PublicKeyCredential === 'undefined' ||
+    !navigator.credentials
+  ) {
+    return {
+      supported: false,
+      platformAuthenticator: false,
+      conditionalMediation: false,
+      parseCreationOptionsSupported: false,
+      parseRequestOptionsSupported: false,
+    };
+  }
+
+  let platformAuthenticator = false;
+  let conditionalMediation = false;
+
+  try {
+    if (typeof PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable === 'function') {
+      platformAuthenticator =
+        await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
+    }
+  } catch {
+    platformAuthenticator = false;
+  }
+
+  try {
+    if (typeof (PublicKeyCredential as any).isConditionalMediationAvailable === 'function') {
+      conditionalMediation = await (
+        PublicKeyCredential as any
+      ).isConditionalMediationAvailable();
+    }
+  } catch {
+    conditionalMediation = false;
+  }
+
+  return {
+    supported: true,
+    platformAuthenticator,
+    conditionalMediation,
+    parseCreationOptionsSupported:
+      typeof (PublicKeyCredential as any).parseCreationOptionsFromJSON === 'function',
+    parseRequestOptionsSupported:
+      typeof (PublicKeyCredential as any).parseRequestOptionsFromJSON === 'function',
+  };
+}
+
+// --- Credential Options Parsing & Serialization ---
+
+export function prepareCreationOptions(jsonOptions: any): PublicKeyCredentialCreationOptions {
+  if (
+    typeof window !== 'undefined' &&
+    typeof window.PublicKeyCredential !== 'undefined' &&
+    typeof (PublicKeyCredential as any).parseCreationOptionsFromJSON === 'function'
+  ) {
+    try {
+      return (PublicKeyCredential as any).parseCreationOptionsFromJSON(jsonOptions);
+    } catch {
+      // Fallback to manual buffer conversion below
+    }
+  }
+
+  return {
+    ...jsonOptions,
+    challenge: base64URLToBuffer(jsonOptions.challenge),
+    user: {
+      ...jsonOptions.user,
+      id: base64URLToBuffer(jsonOptions.user.id),
+    },
+    excludeCredentials: (jsonOptions.excludeCredentials || []).map((cred: any) => ({
+      ...cred,
+      id: base64URLToBuffer(cred.id),
+    })),
+  };
+}
+
+export function prepareRequestOptions(jsonOptions: any): PublicKeyCredentialRequestOptions {
+  if (
+    typeof window !== 'undefined' &&
+    typeof window.PublicKeyCredential !== 'undefined' &&
+    typeof (PublicKeyCredential as any).parseRequestOptionsFromJSON === 'function'
+  ) {
+    try {
+      return (PublicKeyCredential as any).parseRequestOptionsFromJSON(jsonOptions);
+    } catch {
+      // Fallback to manual buffer conversion below
+    }
+  }
+
+  return {
+    ...jsonOptions,
+    challenge: base64URLToBuffer(jsonOptions.challenge),
+    allowCredentials: (jsonOptions.allowCredentials || []).map((cred: any) => ({
+      ...cred,
+      id: base64URLToBuffer(cred.id),
+    })),
+  };
+}
+
+export function serializeRegistrationCredential(cred: PublicKeyCredential): any {
+  const response = cred.response as AuthenticatorAttestationResponse;
+
+  // Extract optional helper values even if toJSON() is available
+  const transports =
+    typeof response.getTransports === 'function' ? response.getTransports() : ['internal', 'hybrid'];
+  const pubKeyBuffer =
+    typeof response.getPublicKey === 'function' ? response.getPublicKey() : null;
+  const pubKeyAlg =
+    typeof response.getPublicKeyAlgorithm === 'function'
+      ? response.getPublicKeyAlgorithm()
+      : -7;
+  const authDataBuffer =
+    typeof response.getAuthenticatorData === 'function'
+      ? response.getAuthenticatorData()
+      : null;
+
+  if (typeof (cred as any).toJSON === 'function') {
+    try {
+      const json = (cred as any).toJSON();
+      return {
+        ...json,
+        response: {
+          ...json.response,
+          transports: json.response?.transports || transports,
+          publicKey:
+            json.response?.publicKey ||
+            (pubKeyBuffer ? bufferToBase64URL(pubKeyBuffer) : undefined),
+          publicKeyAlgorithm: json.response?.publicKeyAlgorithm ?? pubKeyAlg,
+          authenticatorData:
+            json.response?.authenticatorData ||
+            (authDataBuffer ? bufferToBase64URL(authDataBuffer) : undefined),
+        },
+      };
+    } catch {
+      // Fallback to manual serialization
+    }
+  }
+
+  return {
+    id: cred.id,
+    rawId: bufferToBase64URL(cred.rawId),
+    type: cred.type,
+    authenticatorAttachment: (cred as any).authenticatorAttachment || null,
+    clientExtensionResults:
+      typeof cred.getClientExtensionResults === 'function'
+        ? cred.getClientExtensionResults()
+        : {},
+    response: {
+      clientDataJSON: bufferToBase64URL(response.clientDataJSON),
+      attestationObject: bufferToBase64URL(response.attestationObject),
+      authenticatorData: authDataBuffer ? bufferToBase64URL(authDataBuffer) : undefined,
+      publicKey: pubKeyBuffer ? bufferToBase64URL(pubKeyBuffer) : undefined,
+      publicKeyAlgorithm: pubKeyAlg,
+      transports,
+    },
+  };
+}
+
+export function serializeAssertionCredential(cred: PublicKeyCredential): any {
+  const response = cred.response as AuthenticatorAssertionResponse;
+
+  if (typeof (cred as any).toJSON === 'function') {
+    try {
+      return (cred as any).toJSON();
+    } catch {
+      // Fallback to manual serialization
+    }
+  }
+
+  return {
+    id: cred.id,
+    rawId: bufferToBase64URL(cred.rawId),
+    type: cred.type,
+    authenticatorAttachment: (cred as any).authenticatorAttachment || null,
+    clientExtensionResults:
+      typeof cred.getClientExtensionResults === 'function'
+        ? cred.getClientExtensionResults()
+        : {},
+    response: {
+      clientDataJSON: bufferToBase64URL(response.clientDataJSON),
+      authenticatorData: bufferToBase64URL(response.authenticatorData),
+      signature: bufferToBase64URL(response.signature),
+      userHandle: response.userHandle ? bufferToBase64URL(response.userHandle) : null,
+    },
+  };
+}
+
+// --- High-level Registration & Authentication Workflows ---
+
+export async function registerPasskeyWithServer(params: {
+  username?: string;
+  displayName?: string;
+  email?: string;
+  password?: string;
+  passkeyName?: string;
+  authenticatorAttachment?: AuthenticatorAttachment;
+  isSignUp?: boolean;
+}): Promise<{
+  verified: boolean;
+  token: string;
+  passkey: ClientPasskeyInfo;
+  user: ClientUserSession;
+}> {
+  if (typeof window === 'undefined' || !window.PublicKeyCredential || !navigator.credentials) {
+    throw new Error('Passkeys (WebAuthn) are not supported in this browser.');
+  }
+
+  const baseUrl = getBaseUrl();
+
+  // 1. Fetch creation options from RP server
+  const optionsRes = await fetch(`${baseUrl}api/auth/passkey/register-options`, {
+    method: 'POST',
+    headers: getAuthHeaders(),
+    body: JSON.stringify({
+      username: params.username,
+      displayName: params.displayName,
+      authenticatorAttachment: params.authenticatorAttachment,
+      isSignUp: params.isSignUp,
+      rpId: window.location.hostname,
+    }),
+  });
+
+  const optionsData = await optionsRes.json();
+  if (!optionsRes.ok) {
+    throw new Error(optionsData.error || 'Failed to start passkey registration.');
+  }
+
+  // 2. Call navigator.credentials.create()
+  const publicKeyOptions = prepareCreationOptions(optionsData);
+  let credential: Credential | null = null;
+  try {
+    credential = await navigator.credentials.create({
+      publicKey: publicKeyOptions,
+    });
+  } catch (err: any) {
+    if (err?.name === 'InvalidStateError') {
+      throw new Error('A passkey is already registered on this device or authenticator for this account.');
+    }
+    if (err?.name === 'NotAllowedError') {
+      throw new Error('Passkey creation was cancelled or timed out.');
+    }
+    throw new Error(err?.message || 'Passkey creation failed.');
+  }
+
+  if (!credential) {
+    throw new Error('No passkey credential was returned by the authenticator.');
+  }
+
+  // 3. Serialize and verify with server
+  const serialized = serializeRegistrationCredential(credential as PublicKeyCredential);
+
+  const verifyRes = await fetch(`${baseUrl}api/auth/passkey/register-verify`, {
+    method: 'POST',
+    headers: getAuthHeaders(),
+    body: JSON.stringify({
+      credential: serialized,
+      username: params.username || optionsData.user?.name,
+      displayName: params.displayName || optionsData.user?.displayName,
+      email: params.email,
+      password: params.password,
+      passkeyName: params.passkeyName,
+    }),
+  });
+
+  const verifyData = await verifyRes.json();
+  if (!verifyRes.ok) {
+    throw new Error(verifyData.error || 'Server failed to verify passkey registration.');
+  }
+
+  saveClientAuthState(verifyData.token, verifyData.user);
+  return verifyData;
+}
+
+export async function authenticateWithPasskey(params?: {
+  username?: string;
+  purpose?: 'authenticate' | 'reauthenticate';
+  mediation?: CredentialMediationRequirement;
+  signal?: AbortSignal;
+}): Promise<{
+  verified: boolean;
+  reauthenticated: boolean;
+  token: string;
+  passkey: { id: string; name: string };
+  user: ClientUserSession;
+}> {
+  if (typeof window === 'undefined' || !window.PublicKeyCredential || !navigator.credentials) {
+    throw new Error('Passkeys (WebAuthn) are not supported in this browser.');
+  }
+
+  const baseUrl = getBaseUrl();
+  const purpose = params?.purpose || 'authenticate';
+
+  // 1. Fetch assertion options from RP server
+  const optionsRes = await fetch(`${baseUrl}api/auth/passkey/authenticate-options`, {
+    method: 'POST',
+    headers: getAuthHeaders(),
+    body: JSON.stringify({
+      username: params?.username,
+      purpose,
+      rpId: window.location.hostname,
+    }),
+    signal: params?.signal,
+  });
+
+  const optionsData = await optionsRes.json();
+  if (!optionsRes.ok) {
+    throw new Error(optionsData.error || 'Failed to start passkey authentication.');
+  }
+
+  // 2. Call navigator.credentials.get()
+  const publicKeyOptions = prepareRequestOptions(optionsData);
+  let credential: Credential | null = null;
+  try {
+    credential = await navigator.credentials.get({
+      publicKey: publicKeyOptions,
+      mediation: params?.mediation,
+      signal: params?.signal,
+    });
+  } catch (err: any) {
+    if (err?.name === 'AbortError') {
+      throw err;
+    }
+    if (err?.name === 'NotAllowedError') {
+      throw new Error('Passkey authentication was cancelled or no matching passkey was found on this device.');
+    }
+    throw new Error(err?.message || 'Passkey verification failed.');
+  }
+
+  if (!credential) {
+    throw new Error('No passkey assertion was returned by the authenticator.');
+  }
+
+  // 3. Serialize and verify with server
+  const serialized = serializeAssertionCredential(credential as PublicKeyCredential);
+
+  const verifyRes = await fetch(`${baseUrl}api/auth/passkey/authenticate-verify`, {
+    method: 'POST',
+    headers: getAuthHeaders(),
+    body: JSON.stringify({
+      credential: serialized,
+      purpose,
+    }),
+  });
+
+  const verifyData = await verifyRes.json();
+  if (!verifyRes.ok) {
+    throw new Error(verifyData.error || 'Server failed to verify passkey assertion.');
+  }
+
+  // Notify password manager if PublicKeyCredential.signalAllAcceptedCredentials or similar is supported
+  saveClientAuthState(verifyData.token, verifyData.user);
+  return verifyData;
+}
+
+// --- WebAuthn Signal API helpers (Chrome passkey management sync) ---
+
+export async function signalCurrentAcceptedCredentials(
+  userId: string,
+  allAcceptedCredentialIds: string[]
+): Promise<void> {
+  if (
+    typeof window !== 'undefined' &&
+    typeof window.PublicKeyCredential !== 'undefined' &&
+    typeof (PublicKeyCredential as any).signalAllAcceptedCredentials === 'function'
+  ) {
+    try {
+      await (PublicKeyCredential as any).signalAllAcceptedCredentials({
+        rpId: window.location.hostname,
+        userId,
+        allAcceptedCredentialIds,
+      });
+    } catch {
+      // Ignore if Signal API is unsupported or fails
+    }
+  }
+}
+
+export async function signalUpdatedUserDetails(
+  userId: string,
+  name: string,
+  displayName: string
+): Promise<void> {
+  if (
+    typeof window !== 'undefined' &&
+    typeof window.PublicKeyCredential !== 'undefined' &&
+    typeof (PublicKeyCredential as any).signalCurrentUserDetails === 'function'
+  ) {
+    try {
+      await (PublicKeyCredential as any).signalCurrentUserDetails({
+        rpId: window.location.hostname,
+        userId,
+        name,
+        displayName,
+      });
+    } catch {
+      // Ignore if Signal API is unsupported or fails
+    }
+  }
+}
+
+export async function fetchCurrentSession(): Promise<ClientUserSession | null> {
+  try {
+    const baseUrl = getBaseUrl();
+    const res = await fetch(`${baseUrl}api/auth/session`, {
+      method: 'GET',
+      headers: getAuthHeaders(),
+    });
+    if (!res.ok) return getStoredUser();
+    const data = await res.json();
+    if (data.authenticated && data.user) {
+      saveClientAuthState(data.token || getStoredToken(), data.user);
+      return data.user;
+    } else {
+      clearClientAuthState();
+      return null;
+    }
+  } catch {
+    return getStoredUser();
+  }
+}
+
+export async function signOutUser(): Promise<void> {
+  try {
+    const baseUrl = getBaseUrl();
+    await fetch(`${baseUrl}api/auth/logout`, {
+      method: 'POST',
+      headers: getAuthHeaders(),
+    });
+  } catch {
+    // Ignore network error on logout
+  }
+  clearClientAuthState();
+}
