+import crypto from 'node:crypto';
+
+// --- Base64URL Utilities ---
+
+export function bufferToBase64URL(buffer: ArrayBuffer | Uint8Array | Buffer): string {
+  const bytes = buffer instanceof Uint8Array ? buffer : new Uint8Array(buffer);
+  return Buffer.from(bytes)
+    .toString('base64')
+    .replace(/\+/g, '-')
+    .replace(/\//g, '_')
+    .replace(/=+$/, '');
+}
+
+export function base64URLToBuffer(base64url: string): Buffer {
+  const base64 = base64url.replace(/-/g, '+').replace(/_/g, '/');
+  const padLen = (4 - (base64.length % 4)) % 4;
+  return Buffer.from(base64 + '='.repeat(padLen), 'base64');
+}
+
+export function generateChallenge(): string {
+  return bufferToBase64URL(crypto.randomBytes(32));
+}
+
+// --- Minimal CBOR Decoder (RFC 8949) for WebAuthn attestationObject & COSE keys ---
+
+export function decodeCBORFirst(buf: Uint8Array, startOffset = 0): { value: any; offset: number } {
+  let offset = startOffset;
+
+  function readUint(additionalInfo: number): number {
+    if (additionalInfo < 24) return additionalInfo;
+    if (additionalInfo === 24) return buf[offset++];
+    if (additionalInfo === 25) {
+      const val = (buf[offset] << 8) | buf[offset + 1];
+      offset += 2;
+      return val;
+    }
+    if (additionalInfo === 26) {
+      const val =
+        buf[offset] * 0x1000000 +
+        ((buf[offset + 1] << 16) | (buf[offset + 2] << 8) | buf[offset + 3]);
+      offset += 4;
+      return val;
+    }
+    if (additionalInfo === 27) {
+      const hi =
+        buf[offset] * 0x1000000 +
+        ((buf[offset + 1] << 16) | (buf[offset + 2] << 8) | buf[offset + 3]);
+      const lo =
+        buf[offset + 4] * 0x1000000 +
+        ((buf[offset + 5] << 16) | (buf[offset + 6] << 8) | buf[offset + 7]);
+      offset += 8;
+      return hi * 0x100000000 + lo;
+    }
+    throw new Error(`Unsupported CBOR additional info: ${additionalInfo}`);
+  }
+
+  function decodeItem(): any {
+    if (offset >= buf.length) {
+      throw new Error('Unexpected end of CBOR buffer');
+    }
+    const initialByte = buf[offset++];
+    const majorType = initialByte >> 5;
+    const additionalInfo = initialByte & 0x1f;
+
+    switch (majorType) {
+      case 0: // Unsigned integer
+        return readUint(additionalInfo);
+      case 1: // Negative integer
+        return -1 - readUint(additionalInfo);
+      case 2: { // Byte string
+        const len = readUint(additionalInfo);
+        const bytes = buf.slice(offset, offset + len);
+        offset += len;
+        return bytes;
+      }
+      case 3: { // Text string
+        const len = readUint(additionalInfo);
+        const strBytes = buf.slice(offset, offset + len);
+        offset += len;
+        return new TextDecoder().decode(strBytes);
+      }
+      case 4: { // Array
+        const len = readUint(additionalInfo);
+        const arr: any[] = [];
+        for (let i = 0; i < len; i++) {
+          arr.push(decodeItem());
+        }
+        return arr;
+      }
+      case 5: { // Map
+        const len = readUint(additionalInfo);
+        const map = new Map<any, any>();
+        for (let i = 0; i < len; i++) {
+          const k = decodeItem();
+          const v = decodeItem();
+          map.set(k, v);
+        }
+        return map;
+      }
+      case 6: { // Tag
+        readUint(additionalInfo);
+        return decodeItem();
+      }
+      case 7: { // Simple / float
+        if (additionalInfo === 20) return false;
+        if (additionalInfo === 21) return true;
+        if (additionalInfo === 22) return null;
+        if (additionalInfo === 23) return undefined;
+        return readUint(additionalInfo);
+      }
+      default:
+        throw new Error(`Unsupported CBOR major type: ${majorType}`);
+    }
+  }
+
+  const value = decodeItem();
+  return { value, offset };
+}
+
+// --- Authenticator Data Parser ---
+
+export interface ParsedAuthData {
+  rpIdHash: Buffer;
+  flags: {
+    up: boolean; // User Present (bit 0)
+    uv: boolean; // User Verified (bit 2)
+    be: boolean; // Backup Eligibility (bit 3)
+    bs: boolean; // Backup State (bit 4)
+    at: boolean; // Attested Credential Data (bit 6)
+    ed: boolean; // Extension Data (bit 7)
+    raw: number;
+  };
+  signCount: number;
+  aaguid?: string;
+  credentialId?: Buffer;
+  credentialPublicKeyBytes?: Uint8Array;
+  cosePublicKey?: Map<any, any>;
+}
+
+export function formatAAGUID(bytes: Uint8Array): string {
+  const hex = Buffer.from(bytes).toString('hex');
+  if (hex.length !== 32) return '00000000-0000-0000-0000-000000000000';
+  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
+}
+
+export function parseAuthenticatorData(authDataBuf: Buffer): ParsedAuthData {
+  if (authDataBuf.length < 37) {
+    throw new Error('Authenticator data is too short (< 37 bytes)');
+  }
+
+  const rpIdHash = authDataBuf.subarray(0, 32);
+  const flagsByte = authDataBuf[32];
+  const flags = {
+    up: Boolean(flagsByte & 0x01),
+    uv: Boolean(flagsByte & 0x04),
+    be: Boolean(flagsByte & 0x08),
+    bs: Boolean(flagsByte & 0x10),
+    at: Boolean(flagsByte & 0x40),
+    ed: Boolean(flagsByte & 0x80),
+    raw: flagsByte,
+  };
+  const signCount = authDataBuf.readUInt32BE(33);
+
+  const result: ParsedAuthData = {
+    rpIdHash,
+    flags,
+    signCount,
+  };
+
+  if (flags.at && authDataBuf.length >= 55) {
+    const aaguidBytes = authDataBuf.subarray(37, 53);
+    result.aaguid = formatAAGUID(aaguidBytes);
+    const credIdLen = authDataBuf.readUInt16BE(53);
+    const credIdStart = 55;
+    const credIdEnd = credIdStart + credIdLen;
+    result.credentialId = authDataBuf.subarray(credIdStart, credIdEnd);
+
+    if (authDataBuf.length > credIdEnd) {
+      try {
+        const pubKeySlice = new Uint8Array(authDataBuf.subarray(credIdEnd));
+        const decoded = decodeCBORFirst(pubKeySlice, 0);
+        if (decoded.value instanceof Map) {
+          result.cosePublicKey = decoded.value;
+          result.credentialPublicKeyBytes = pubKeySlice.slice(0, decoded.offset);
+        }
+      } catch {
+        // Ignore CBOR public key parse failure if non-standard
+      }
+    }
+  }
+
+  return result;
+}
+
+// --- Convert COSE Key to Node KeyObject & Verify Signatures ---
+
+export function coseToPublicKey(coseMap: Map<any, any>): { keyObject: crypto.KeyObject; alg: number } {
+  const kty = coseMap.get(1); // 1 = OKP, 2 = EC2, 3 = RSA
+  const alg = coseMap.get(3) ?? -7;
+
+  if (kty === 2) {
+    // EC2 (e.g., ES256 / P-256)
+    const crv = coseMap.get(-1); // 1 = P-256, 2 = P-384, 3 = P-521
+    const x = coseMap.get(-2);
+    const y = coseMap.get(-3);
+    const crvName = crv === 2 ? 'P-384' : crv === 3 ? 'P-521' : 'P-256';
+    const keyObject = crypto.createPublicKey({
+      key: {
+        kty: 'EC',
+        crv: crvName,
+        x: bufferToBase64URL(x),
+        y: bufferToBase64URL(y),
+      },
+      format: 'jwk',
+    });
+    return { keyObject, alg };
+  }
+
+  if (kty === 3) {
+    // RSA (e.g., RS256)
+    const n = coseMap.get(-1);
+    const e = coseMap.get(-2);
+    const keyObject = crypto.createPublicKey({
+      key: {
+        kty: 'RSA',
+        n: bufferToBase64URL(n),
+        e: bufferToBase64URL(e),
+      },
+      format: 'jwk',
+    });
+    return { keyObject, alg };
+  }
+
+  if (kty === 1) {
+    // OKP (e.g., Ed25519)
+    const x = coseMap.get(-2);
+    const keyObject = crypto.createPublicKey({
+      key: {
+        kty: 'OKP',
+        crv: 'Ed25519',
+        x: bufferToBase64URL(x),
+      },
+      format: 'jwk',
+    });
+    return { keyObject, alg: -8 };
+  }
+
+  throw new Error(`Unsupported COSE key type: ${kty}`);
+}
+
+export function verifyWebAuthnSignature(params: {
+  publicKeySpkiBase64Url?: string;
+  cosePublicKeyBase64Url?: string;
+  algorithm: number;
+  authenticatorData: Buffer;
+  clientDataJSON: Buffer;
+  signature: Buffer;
+}): boolean {
+  const {
+    publicKeySpkiBase64Url,
+    cosePublicKeyBase64Url,
+    algorithm,
+    authenticatorData,
+    clientDataJSON,
+    signature,
+  } = params;
+
+  const clientDataHash = crypto.createHash('sha256').update(clientDataJSON).digest();
+  const signedData = Buffer.concat([authenticatorData, clientDataHash]);
+
+  let keyObject: crypto.KeyObject | null = null;
+  let alg = algorithm || -7;
+
+  if (publicKeySpkiBase64Url) {
+    try {
+      const derBuf = base64URLToBuffer(publicKeySpkiBase64Url);
+      keyObject = crypto.createPublicKey({
+        key: derBuf,
+        format: 'der',
+        type: 'spki',
+      });
+    } catch {
+      keyObject = null;
+    }
+  }
+
+  if (!keyObject && cosePublicKeyBase64Url) {
+    try {
+      const coseBuf = base64URLToBuffer(cosePublicKeyBase64Url);
+      const { value } = decodeCBORFirst(new Uint8Array(coseBuf));
+      if (value instanceof Map) {
+        const converted = coseToPublicKey(value);
+        keyObject = converted.keyObject;
+        alg = converted.alg;
+      }
+    } catch {
+      keyObject = null;
+    }
+  }
+
+  if (!keyObject) {
+    return false;
+  }
+
+  if (alg === -8) {
+    return crypto.verify(null, signedData, keyObject, signature);
+  }
+
+  const hashAlg = alg === -35 ? 'sha384' : alg === -36 ? 'sha512' : 'sha256';
+  return crypto.verify(hashAlg, signedData, keyObject, signature);
+}
+
+// --- Known Authenticator AAGUID Directory ---
+
+const KNOWN_AAGUIDS: Record<string, string> = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': 'Google Password Manager',
+  'adce0002-35bc-c60a-648b-0b25f1f05503': 'Chrome on Mac',
+  'bada5566-a7aa-401f-bd96-45619a55120d': 'Chrome on Windows',
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': 'Windows Hello',
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': 'Windows Hello',
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': 'iCloud Keychain',
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': 'iCloud Keychain',
+  '00000000-0000-0000-0000-000000000000': 'Platform Passkey',
+  'b5397666-4885-aa6b-cebf-e52262a439a2': 'Chromium Virtual Authenticator',
+  'd548826e-79b4-db40-a3d8-11116f7e8349': 'Bitwarden',
+  'bada5566-a7aa-401f-bd96-45619a55120e': '1Password',
+  '53414d53-554e-4700-0000-000000000000': 'Samsung Pass',
+};
+
+export function getDefaultPasskeyName(aaguid?: string, userAgent?: string, existingCount = 0): string {
+  if (aaguid && KNOWN_AAGUIDS[aaguid] && aaguid !== '00000000-0000-0000-0000-000000000000') {
+    return KNOWN_AAGUIDS[aaguid];
+  }
+  if (userAgent) {
+    if (userAgent.includes('Macintosh') || userAgent.includes('Mac OS X')) return 'iCloud Keychain / Mac Passkey';
+    if (userAgent.includes('Windows')) return 'Windows Hello Passkey';
+    if (userAgent.includes('Android')) return 'Google Password Manager';
+    if (userAgent.includes('iPhone') || userAgent.includes('iPad')) return 'iCloud Keychain';
+    if (userAgent.includes('Linux')) return 'Chrome Passkey (Linux)';
+  }
+  return existingCount > 0 ? `Passkey #${existingCount + 1}` : 'Primary Passkey';
+}

