+      const statusEl = document.getElementById('feedback-status');
+      const currentSectionNameEl = document.getElementById('modal-current-section');
+      const currentSectionIdEl = document.getElementById('modal-current-section-id');
+      const sections = Array.from(document.querySelectorAll('main.container > section'));
+
+      function openModal() {
+        if (!modal.matches(':modal')) {
+          if (modal.open) {
+            modal.close();
+          }
+          modal.showModal();
+        }
+      }
+
+      function syncSectionIndicators() {
+        const hostSection = modal.closest('section');
+        sections.forEach((sec, idx) => {
+          const isHost = sec === hostSection;
+          sec.classList.toggle('has-modal', isHost);
+          const badge = sec.querySelector('[data-section-badge]');
+          if (badge) {
+            badge.textContent = isHost ? 'Modal Host Section' : `Section ${idx + 1}`;
+          }
+        });
+
+        if (hostSection) {
+          const heading = hostSection.querySelector('h2');
+          currentSectionNameEl.textContent = heading ? heading.textContent : hostSection.id;
+          currentSectionIdEl.textContent = `#${hostSection.id}`;
+          modal.dataset.currentSection = hostSection.id;
+        }
+      }
+
+      function moveModalToNextSection() {
+        if (sections.length < 2) return;
+
+        // Ensure modal is open before relocating
+        openModal();
+
+        const currentSection = modal.closest('section');
+        const currentIndex = sections.indexOf(currentSection);
+        const nextIndex = (currentIndex + 1) % sections.length;
+        const nextSection = sections[nextIndex];
+
+        if (typeof nextSection.moveBefore === 'function') {
+          nextSection.moveBefore(modal, null);
+        } else {
+          const activeEl = document.activeElement;
+          const selectionStart = activeEl && 'selectionStart' in activeEl ? activeEl.selectionStart : null;
+          const selectionEnd = activeEl && 'selectionEnd' in activeEl ? activeEl.selectionEnd : null;
+
+          nextSection.appendChild(modal);
+          openModal();
+
+          if (activeEl && modal.contains(activeEl)) {
+            activeEl.focus();
+            if (selectionStart !== null && selectionEnd !== null) {
+              try {
+                activeEl.setSelectionRange(selectionStart, selectionEnd);
+              } catch (_) {}
+            }
+          }
+        }
+
+        if (!modal.contains(document.activeElement)) {
+          moveBtn.focus();
+        }
+
+        syncSectionIndicators();
+      }
+
+      moveBtn.addEventListener('click', moveModalToNextSection);
+
+      openBtn.addEventListener('click', () => {
+        statusEl.classList.remove('visible');
+        openModal();
+      });
+
+      closeBtn.addEventListener('click', () => {
+        modal.close();
+      });
+
+      closeIcon.addEventListener('click', () => {
+        modal.close();
+      });
+
+      form.addEventListener('submit', (event) => {
+        event.preventDefault();
+        statusEl.classList.add('visible');
+      });
+
+      // Open modal initially so it is active and ready for relocation
