+    'Permissions-Policy',
+    'geolocation=(self), camera=(), microphone=(), accelerometer=(), gyroscope=(), magnetometer=(), payment=(), usb=(), interest-cohort=(), browsing-topics=(), focus-without-user-activation=()'
+  );
