+  // 7. Content Security Policy (CSP)
+  // Combines strict-dynamic + nonce with explicit resource directives so both static and dynamic contexts are protected.
+  const cspDirectives = [
+    "default-src 'self'",
+    `script-src 'self' 'nonce-${nonce}' 'strict-dynamic' 'report-sample'`,
+    "style-src 'self' 'unsafe-inline'",
+    "img-src 'self' https://images.unsplash.com https://img.youtube.com data: blob:",
+    "frame-src https://www.youtube-nocookie.com",
+    "connect-src 'self'",
+    "font-src 'self'",
+    "object-src 'none'",
+    "base-uri 'none'",
+    "form-action 'self'",
+    "frame-ancestors 'none'",
+    "worker-src 'self'",
+    "require-trusted-types-for 'script'",
+    "trusted-types daily-grind-html default",
+    "report-to main-endpoint",
+  ];
+  res.setHeader('Content-Security-Policy', cspDirectives.join('; '));
