+  // 8. Outbound Connection Allowlist on document/worker destinations
+  const secFetchDest = String(req.headers['sec-fetch-dest'] || 'document').toLowerCase();
+  if (ALLOWLIST_DESTS.has(secFetchDest)) {
+    const allowlistHeader = buildConnectionAllowlistHeader({
+      allowSelf: true,
+      patterns: [
+        'https://images.unsplash.com/*',
+        'https://img.youtube.com/*',
+        'https://www.youtube-nocookie.com/*',
+        'https://x.com/*',
+        'https://bsky.app/*',
+      ],
+      reportTo: 'conn-reports',
+      redirects: 'block',
+      webrtc: 'block',
+    });
+    res.setHeader('Connection-Allowlist', allowlistHeader);
+  }
+}
