+/**
+ * Fetch Metadata Resource Isolation check.
+ * Rejects suspicious cross-site requests to non-navigational endpoints before processing.
+ */
+function passesFetchMetadataIsolation(req) {
+  const site = req.headers['sec-fetch-site'];
