+  if (
+    site === 'cross-site' &&
+    mode === 'navigate' &&
+    req.method === 'GET' &&
+    !['object', 'embed', 'iframe'].includes(dest)
+  ) {
+    return true;
+  }
+  return false;
+}
+
+const server = http.createServer((req, res) => {
+  const nonce = crypto.randomBytes(16).toString('base64');
+  applyPrivacyAndSecurityHeaders(req, res, nonce);
