+    if (pathname === '/api/session-demo') {
+      // Demonstrate HttpOnly Secure SameSite=Lax session cookie + CHIPS Partitioned preference cookie
+      res.setHeader('Set-Cookie', [
+        '__Host-session_id=ephemeral_opaque_session; Secure; HttpOnly; SameSite=Lax; Path=/',
+        'theme_pref=roast-dark; SameSite=None; Secure; Path=/; Partitioned; HttpOnly',
+      ]);
