+    if (pathname === '/api/data-rights' && req.method === 'DELETE') {
+      res.setHeader('Clear-Site-Data', '"cookies", "storage", "cache"');
+      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(
+        JSON.stringify({
+          erased: true,
+          timestamp: new Date().toISOString(),
+          message: 'All personal records and active session data have been permanently deleted.',
