+    }
+    if (ephBox) ephBox.checked = consent.ephemeralOnly !== false;
+  }
+
+  function renderStoreLocations(query = '') {
+    const grid = document.getElementById('locations-results');
+    if (!grid) return;
+    grid.textContent = '';
+
+    const normalized = sanitizeText(query, 20).toLowerCase();
+    const matches = STORE_DIRECTORY.filter((store) => {
+      if (!normalized) return true;
+      return (
+        store.zipPrefix.startsWith(normalized.slice(0, 3)) ||
+        normalized.startsWith(store.zipPrefix) ||
+        store.name.toLowerCase().includes(normalized) ||
+        store.neighborhood.toLowerCase().includes(normalized)
+      );
+    });
+
+    if (matches.length === 0) {
+      const p = document.createElement('p');
+      p.textContent = 'No cafes matched that 3-digit ZIP prefix or neighborhood. Showing all regional locations on clear.';
+      grid.appendChild(p);
+      return;
+    }
+
+    matches.forEach((store) => {
+      const card = document.createElement('article');
+      card.className = 'card location-card';
+
+      const h3 = document.createElement('h3');
+      h3.textContent = store.name;
+
+      const hood = document.createElement('p');
+      hood.className = 'location-meta';
+      hood.textContent = `${store.neighborhood} • ZIP Prefix ${store.zipPrefix}xx`;
+
+      const addr = document.createElement('p');
+      addr.textContent = `${store.address} (${store.hours})`;
+
+      const tags = document.createElement('p');
+      tags.className = 'privacy-hint';
+      tags.textContent = store.features.join(' • ');
+
+      card.appendChild(h3);
+      card.appendChild(hood);
+      card.appendChild(addr);
+      card.appendChild(tags);
+      grid.appendChild(card);
+    });
+  }
+
+  function showFeedback(elementId, message, isSuccess = true) {
+    const el = document.getElementById(elementId);
+    if (!el) return;
+    el.textContent = message;
+    el.className = isSuccess ? 'feedback-banner feedback-success' : 'feedback-banner feedback-warn';
+    el.hidden = false;
+  }
+
+  /* ==========================================================================
+   * 8. EVENT HANDLERS (ZERO INLINE HANDLERS FOR STRICT CSP)
+   * ========================================================================== */
+
+  function bindEventListeners() {
+    // 1. Store Locator filter (local, zero-network lookup)
+    const zipInput = document.getElementById('zip-prefix-input');
+    const clearZipBtn = document.getElementById('clear-zip-btn');
+    if (zipInput) {
+      zipInput.addEventListener('input', () => {
+        renderStoreLocations(zipInput.value);
+      });
+    }
+    if (clearZipBtn && zipInput) {
+      clearZipBtn.addEventListener('click', () => {
+        zipInput.value = '';
+        renderStoreLocations('');
+      });
+    }
+
+    // 2. Quick Order & Pseudonymous Rewards Form (Data Minimization)
+    const orderForm = document.getElementById('minimal-order-form');
+    if (orderForm) {
+      orderForm.addEventListener('submit', (e) => {
+        e.preventDefault();
+        const formData = new FormData(orderForm);
+        const alias = sanitizeText(String(formData.get('pickup_alias') || ''), 30);
+        const item = sanitizeText(String(formData.get('drink_item') || ''), 40);
+        const optInRewards = formData.get('opt_in_rewards') === 'yes';
+        const consent = loadConsentState();
+
+        if (!alias || !item) {
+          showFeedback('order-feedback', 'Please provide a pickup alias and beverage selection.', false);
+          return;
+        }
+
+        // Reject if user accidentally entered an email or phone number as their pickup alias
+        if (SecureStorage.containsPII(alias)) {
+          showFeedback(
+            'order-feedback',
+            'Data Minimization Guard: Please use a first name or pseudonym only (do not enter an email, phone number, or card number as your alias).',
+            false
+          );
+          return;
+        }
+
+        // Store only minimal, non-PII order token with a 15-minute TTL
+        const orderRecord = {
+          pickupAlias: alias,
+          drinkItem: item,
+          rewardsOptIn: optInRewards,
+          orderCode: 'DG-' + Math.floor(1000 + Math.random() * 9000)
+        };
+
+        SecureStorage.setItem(ORDER_KEY, orderRecord, {
+          ephemeral: consent.ephemeralOnly !== false,
+          ttlMs: TTL.ORDER_SESSION
+        });
+
+        // Clear form inputs immediately so shared-device browsers do not retain values
+        orderForm.reset();
+        renderStorageInspector();
+
+        showFeedback(
+          'order-feedback',
+          `Order ${orderRecord.orderCode} queued for "${orderRecord.pickupAlias}" (${orderRecord.drinkItem}). Stored ephemerally with a 15-minute auto-expiry TTL.`,
+          true
+        );
+      });
+    }
+
+    // 3. Menu "Quick Select" buttons prefill the minimized order drink field
+    document.querySelectorAll('[data-select-drink]').forEach((btn) => {
+      btn.addEventListener('click', () => {
+        const drink = btn.getAttribute('data-select-drink');
+        const selectEl = document.getElementById('drink-item-select');
+        if (selectEl && drink) {
+          selectEl.value = drink;
+          selectEl.focus();
+        }
+      });
+    });
+
+    // 4. Consent Management Form & Symmetric Banner Buttons
+    const saveConsentBtn = document.getElementById('save-consent-btn');
+    const essentialOnlyBtn = document.getElementById('essential-only-btn');
+    const bannerRejectBtn = document.getElementById('banner-essential-only-btn');
+    const bannerSaveBtn = document.getElementById('banner-save-prefs-btn');
+    const consentBanner = document.getElementById('privacy-consent-banner');
+
+    function applyConsentFromUI(forceEssentialOnly = false) {
+      const funcBox = document.getElementById('consent-functional');
+      const anaBox = document.getElementById('consent-analytics');
+      const ephBox = document.getElementById('consent-ephemeral');
+
+      const nextState = forceEssentialOnly
+        ? getDefaultConsent()
+        : {
+            functional: Boolean(funcBox && funcBox.checked),
+            analytics: Boolean(anaBox && anaBox.checked),
+            ephemeralOnly: ephBox ? ephBox.checked : true
+          };
+
+      const saved = saveConsentState(nextState, !nextState.ephemeralOnly);
+      syncConsentControls(saved);
+      renderStorageInspector();
+      if (consentBanner) {
+        consentBanner.hidden = true;
+      }
+      showFeedback(
+        'consent-feedback',
+        forceEssentialOnly
+          ? 'Strict Essential-Only mode enforced. Optional functional and analytics storage disabled.'
+          : 'Privacy preferences saved and enforced.',
+        true
+      );
+    }
+
+    if (saveConsentBtn) {
+      saveConsentBtn.addEventListener('click', () => applyConsentFromUI(false));
+    }
+    if (essentialOnlyBtn) {
+      essentialOnlyBtn.addEventListener('click', () => applyConsentFromUI(true));
+    }
+    if (bannerRejectBtn) {
+      bannerRejectBtn.addEventListener('click', () => applyConsentFromUI(true));
+    }
+    if (bannerSaveBtn) {
+      bannerSaveBtn.addEventListener('click', () => applyConsentFromUI(false));
+    }
+
+    // 5. Account Pseudonymous Token Mask/Reveal Toggle
+    const toggleTokenBtn = document.getElementById('toggle-session-token-btn');
+    const tokenDisplay = document.getElementById('session-token-display');
+    if (toggleTokenBtn && tokenDisplay) {
+      let revealed = false;
+      toggleTokenBtn.addEventListener('click', () => {
+        revealed = !revealed;
+        tokenDisplay.textContent = revealed ? 'anon_sess_9f4b2c81 (Ephemeral)' : '•••••••••••••••••••• (Masked)';
+        toggleTokenBtn.textContent = revealed ? 'Mask Session ID' : 'Reveal Session ID';
+        toggleTokenBtn.setAttribute('aria-pressed', String(revealed));
+      });
+    }
+
+    // 6. Data Rights: Refresh, Export JSON, Purge All Data
+    const refreshStorageBtn = document.getElementById('refresh-storage-btn');
+    const exportDataBtn = document.getElementById('export-data-btn');
+    const purgeDataBtn = document.getElementById('purge-data-btn');
+
+    if (refreshStorageBtn) {
+      refreshStorageBtn.addEventListener('click', () => {
+        renderStorageInspector();
+        showFeedback('account-feedback', 'Storage inspector refreshed and expired TTL keys purged.', true);
+      });
+    }
+
+    if (exportDataBtn) {
+      exportDataBtn.addEventListener('click', () => {
+        const exportPayload = {
+          exportedAt: new Date().toISOString(),
+          service: 'The Daily Grind Coffee Co.',
+          privacyPolicyVersion: '2026.11-PbD',
+          browserPrivacySignals: getPrivacySignals(),
+          consentPreferences: loadConsentState(),
+          storedRecords: SecureStorage.inspectAll()
+        };
+        const blob = new Blob([JSON.stringify(exportPayload, null, 2)], {
+          type: 'application/json'
+        });
+        const url = URL.createObjectURL(blob);
+        const a = document.createElement('a');
+        a.href = url;
+        a.download = 'daily-grind-privacy-export.json';
+        document.body.appendChild(a);
+        a.click();
+        a.remove();
+        URL.revokeObjectURL(url);
+        showFeedback('account-feedback', 'Portable JSON data export generated locally.', true);
+      });
+    }
+
+    if (purgeDataBtn) {
+      purgeDataBtn.addEventListener('click', () => {
+        SecureStorage.purgeAllUserData();
+        syncConsentControls(getDefaultConsent());
+        renderStorageInspector();
+        showFeedback(
+          'account-feedback',
+          'All localStorage, sessionStorage, and first-party cookies have been permanently erased.',
+          true
+        );
+      });
+    }
+
+    // 7. Secure Logout Form (POST + Client-Side State Sanitization)
+    const logoutForm = document.getElementById('secure-logout-form');
+    if (logoutForm) {
+      logoutForm.addEventListener('submit', (e) => {
+        e.preventDefault();
+        SecureStorage.purgeAllUserData();
+        sanitizeLocationUrl();
+        syncConsentControls(getDefaultConsent());
+        renderStorageInspector();
+
+        const tokenEl = document.getElementById('session-token-display');
+        if (tokenEl) {
+          tokenEl.textContent = 'Logged Out (Session Cleared)';
+        }
+        showFeedback(
+          'account-feedback',
+          'Secure logout complete: session terminated and all client-side storage sanitized.',
