+    });
+  }
+
+  /* ==========================================================================
+   * 9. INITIALIZATION
+   * ========================================================================== */
+
+  function init() {
+    sanitizeLocationUrl();
+    SecureStorage.purgeExpired();
+    installNetworkAndDOMGuards();
+
+    const currentConsent = loadConsentState();
+    renderPrivacySignalsUI();
+    syncConsentControls(currentConsent);
