+++ b/src/pages/api/logout.ts
@@ -0,0 +1,27 @@
+import type { APIRoute } from 'astro';
+
+export const POST: APIRoute = async ({ session }) => {
+  if (session) {
+    await session.delete('readingList');
+    if (typeof session.destroy === 'function') {
+      await session.destroy();
+    }
+  }
+
+  return new Response(
+    JSON.stringify({
+      cleared: true,
+      message: 'Session terminated and all local site data cleared.',
+    }),
+    {
+      status: 200,
+      headers: {
+        'Content-Type': 'application/json',
+        'Clear-Site-Data': '"cookies", "storage", "cache"',
+        'Set-Cookie':
+          '__Host-session=; Max-Age=0; Path=/; Secure; HttpOnly; SameSite=Lax, privacy_opt_out=; Max-Age=0; Path=/; Secure; SameSite=Lax',
+        'Cache-Control': 'no-store, max-age=0',
+      },
+    }
+  );
+};
