@@ -0,0 +1,338 @@
+import React, { useState, useEffect, useCallback } from 'react';
+
+export interface ConsentState {
+  essential: true;
+  analytics: boolean;
+  advertising: boolean;
+  updatedAt: string;
+}
+
+const CONSENT_STORAGE_KEY = 'devtools_times_privacy_consent';
+const ANALYTICS_SCRIPT_ID = 'dtt-consented-analytics-script';
+const ANALYTICS_SCRIPT_SRC =
+  'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/lib/analytics-client.js';
+
+interface Props {
+  disableThirdParty?: boolean;
+  privacyPolicyUrl: string;
+}
+
+function isPrivacySignalEnabled(): boolean {
+  if (typeof navigator === 'undefined') return false;
+  const gpc = (navigator as Navigator & { globalPrivacyControl?: boolean }).globalPrivacyControl === true;
+  const dnt =
+    navigator.doNotTrack === '1' ||
+    navigator.doNotTrack === 'yes' ||
+    (window as Window & { doNotTrack?: string }).doNotTrack === '1';
+  return gpc || dnt;
+}
+
+export function getStoredConsent(): ConsentState | null {
+  if (typeof window === 'undefined') return null;
+  try {
+    const raw = window.localStorage.getItem(CONSENT_STORAGE_KEY);
+    if (!raw) return null;
+    const parsed = JSON.parse(raw);
+    if (typeof parsed !== 'object' || parsed === null) return null;
+    return {
+      essential: true,
+      analytics: Boolean(parsed.analytics),
+      advertising: Boolean(parsed.advertising),
+      updatedAt: typeof parsed.updatedAt === 'string' ? parsed.updatedAt : new Date().toISOString(),
+    };
+  } catch {
+    return null;
+  }
+}
+
+export default function PrivacyPreferences({ disableThirdParty = false, privacyPolicyUrl }: Props) {
+  const [showBanner, setShowBanner] = useState(false);
+  const [showModal, setShowModal] = useState(false);
+  // Privacy by design & default: all non-essential scripts start unchecked (false)
+  const [analyticsEnabled, setAnalyticsEnabled] = useState(false);
+  const [advertisingEnabled, setAdvertisingEnabled] = useState(false);
+  const [privacySignalActive, setPrivacySignalActive] = useState(false);
+
+  const applyConsentSideEffects = useCallback(
+    (consent: ConsentState, signalActive: boolean) => {
+      if (typeof document === 'undefined') return;
+
+      const existingAnalytics = document.getElementById(ANALYTICS_SCRIPT_ID);
+      const isAuthPage =
+        disableThirdParty ||
+        window.location.pathname.endsWith('/signin') ||
+        window.location.pathname.endsWith('/signup');
+
+      // Only load analytics if explicitly consented, not on sensitive auth pages, and no GPC/DNT signal overrides
+      if (consent.analytics && !isAuthPage && !signalActive) {
+        if (!existingAnalytics) {
+          const script = document.createElement('script');
+          script.id = ANALYTICS_SCRIPT_ID;
+          script.src = ANALYTICS_SCRIPT_SRC;
+          script.defer = true;
+          script.crossOrigin = 'anonymous';
+          script.referrerPolicy = 'no-referrer';
+          document.head.appendChild(script);
+        }
+      } else if (existingAnalytics) {
+        existingAnalytics.remove();
+      }
+
+      window.dispatchEvent(
+        new CustomEvent('dtt:privacy-consent-updated', {
+          detail: {
+            ...consent,
+            analytics: consent.analytics && !isAuthPage && !signalActive,
+            advertising: consent.advertising && !isAuthPage && !signalActive,
+          },
+        })
+      );
+    },
+    [disableThirdParty]
+  );
+
+  useEffect(() => {
+    const signal = isPrivacySignalEnabled();
+    setPrivacySignalActive(signal);
+
+    const saved = getStoredConsent();
+    if (saved) {
+      const effectiveAnalytics = signal ? false : saved.analytics;
+      const effectiveAdvertising = signal ? false : saved.advertising;
+      setAnalyticsEnabled(effectiveAnalytics);
+      setAdvertisingEnabled(effectiveAdvertising);
+      applyConsentSideEffects(
+        {
+          ...saved,
+          analytics: effectiveAnalytics,
+          advertising: effectiveAdvertising,
+        },
+        signal
+      );
+      setShowBanner(false);
+    } else {
+      // Default: all non-essential tracking is disabled until explicit opt-in
+      setAnalyticsEnabled(false);
+      setAdvertisingEnabled(false);
+      setShowBanner(!signal);
+    }
+
+    const handleOpenModal = () => {
+      const latest = getStoredConsent();
+      if (latest) {
+        setAnalyticsEnabled(signal ? false : latest.analytics);
+        setAdvertisingEnabled(signal ? false : latest.advertising);
+      } else {
+        setAnalyticsEnabled(false);
+        setAdvertisingEnabled(false);
+      }
+      setShowModal(true);
+    };
+
+    window.addEventListener('dtt:open-privacy-preferences', handleOpenModal);
+    return () => {
+      window.removeEventListener('dtt:open-privacy-preferences', handleOpenModal);
+    };
+  }, [applyConsentSideEffects]);
+
+  const persistConsent = (analytics: boolean, advertising: boolean) => {
+    const nextConsent: ConsentState = {
+      essential: true,
+      analytics: privacySignalActive ? false : analytics,
+      advertising: privacySignalActive ? false : advertising,
+      updatedAt: new Date().toISOString(),
+    };
+    try {
+      window.localStorage.setItem(CONSENT_STORAGE_KEY, JSON.stringify(nextConsent));
+    } catch {
+      // Ignore storage errors in private browsing modes
+    }
+    setAnalyticsEnabled(nextConsent.analytics);
+    setAdvertisingEnabled(nextConsent.advertising);
+    applyConsentSideEffects(nextConsent, privacySignalActive);
+    setShowBanner(false);
+    setShowModal(false);
+  };
+
+  const handleRejectNonEssential = () => {
+    persistConsent(false, false);
+  };
+
+  const handleSavePreferences = (e: React.FormEvent) => {
+    e.preventDefault();
+    persistConsent(analyticsEnabled, advertisingEnabled);
+  };
+
+  return (
+    <>
+      {showBanner && !showModal && (
+        <aside
+          aria-label="Privacy and third-party script disclosure"
+          data-skip-tracking="true"
+          className="fixed bottom-0 inset-x-0 z-50 bg-white border-t border-gray-300 shadow-lg p-4"
+        >
+          <div className="max-w-6xl mx-auto flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
+            <div className="text-xs text-gray-700 space-y-1 max-w-3xl">
+              <p className="font-semibold text-gray-900 text-sm">
+                Privacy by Default: Non-Essential Third-Party Scripts Are Disabled
+              </p>
+              <p>
+                The DevTools Times practices data minimization. Third-party analytics and advertising scripts are
+                blocked by default and only run if you explicitly opt in. Essential site functionality works without
+                tracking cookies. See our{' '}
+                <a href={privacyPolicyUrl} className="underline text-gray-900 hover:text-black">
+                  Privacy Policy
+                </a>{' '}
+                for full details.
+              </p>
+            </div>
+            <div className="flex flex-wrap items-center gap-2 shrink-0">
+              <button
+                type="button"
+                onClick={handleRejectNonEssential}
+                data-skip-tracking="true"
+                className="px-3 py-2 text-xs font-semibold text-white bg-gray-900 rounded hover:bg-gray-800"
+              >
+                Keep Essential Only (Default)
+              </button>
+              <button
+                type="button"
+                onClick={() => setShowModal(true)}
+                data-skip-tracking="true"
+                className="px-3 py-2 text-xs font-semibold text-gray-800 bg-gray-100 border border-gray-300 rounded hover:bg-gray-200"
+              >
+                Manage Preferences
+              </button>
+            </div>
+          </div>
+        </aside>
+      )}
+
+      {showModal && (
+        <div
+          role="dialog"
+          aria-modal="true"
+          aria-labelledby="privacy-preferences-title"
+          data-skip-tracking="true"
+          className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4"
+        >
+          <div className="bg-white border border-gray-200 rounded-lg shadow-xl max-w-lg w-full p-6 space-y-4">
+            <div className="flex items-start justify-between">
+              <h2 id="privacy-preferences-title" className="text-lg font-bold text-gray-900">
+                Privacy &amp; Third-Party Script Preferences
+              </h2>
+              <button
+                type="button"
+                onClick={() => setShowModal(false)}
+                aria-label="Close privacy preferences"
+                data-skip-tracking="true"
+                className="text-gray-500 hover:text-gray-800 text-sm font-semibold"
+              >
+                ✕
+              </button>
+            </div>
+
+            <p className="text-xs text-gray-600">
+              Control which optional third-party scripts may run during your visit. By default, all optional tracking
+              and advertising scripts are turned off. Sign-in and sign-up pages never load third-party scripts.
+            </p>
+
+            {privacySignalActive && (
+              <div className="p-3 bg-blue-50 border border-blue-200 rounded text-xs text-blue-900">
+                <strong>Browser Privacy Signal Detected (GPC / Do Not Track):</strong> We automatically honor your
+                browser&apos;s privacy signal and have disabled all non-essential third-party tracking and advertising
+                scripts.
+              </div>
+            )}
+
+            <form onSubmit={handleSavePreferences} className="space-y-4">
+              <div className="p-3 bg-gray-50 border border-gray-200 rounded flex items-start justify-between gap-4">
+                <div>
+                  <p className="text-sm font-semibold text-gray-900">Strictly Necessary (Always Active)</p>
+                  <p className="text-xs text-gray-600 mt-1">
+                    Required for core site navigation, security headers, and your on-demand reading list when you
+                    explicitly bookmark an article. No passive session cookies are set.
+                  </p>
+                </div>
+                <input
+                  type="checkbox"
+                  checked={true}
+                  disabled
+                  aria-label="Strictly necessary features enabled"
+                  className="mt-1 h-4 w-4"
+                />
+              </div>
+
+              <div className="p-3 bg-gray-50 border border-gray-200 rounded flex items-start justify-between gap-4">
+                <div>
+                  <label htmlFor="consent-analytics" className="text-sm font-semibold text-gray-900 block">
+                    Optional Third-Party Analytics (<code className="text-xs">analytics-client.js</code>)
+                  </label>
+                  <p className="text-xs text-gray-600 mt-1">
+                    When explicitly enabled, loads our external analytics script with{' '}
+                    <code className="text-[11px]">referrerPolicy=&quot;no-referrer&quot;</code> and{' '}
+                    <code className="text-[11px]">crossOrigin=&quot;anonymous&quot;</code> to measure aggregate page
+                    usage. Never loaded on Sign In or Sign Up pages.
+                  </p>
+                </div>
+                <input
+                  id="consent-analytics"
+                  type="checkbox"
+                  checked={analyticsEnabled}
+                  disabled={privacySignalActive}
+                  onChange={(e) => setAnalyticsEnabled(e.target.checked)}
+                  data-skip-tracking="true"
+                  className="mt-1 h-4 w-4 text-gray-900 border-gray-300 rounded"
+                />
+              </div>
+
+              <div className="p-3 bg-gray-50 border border-gray-200 rounded flex items-start justify-between gap-4">
+                <div>
+                  <label htmlFor="consent-advertising" className="text-sm font-semibold text-gray-900 block">
+                    Optional Contextual Advertising Slots (<code className="text-xs">ad-client.js</code>)
+                  </label>
+                  <p className="text-xs text-gray-600 mt-1">
+                    Disabled by default. When off, ad slots remain inert and no third-party ad network scripts or
+                    requests are initialized.
+                  </p>
+                </div>
+                <input
+                  id="consent-advertising"
+                  type="checkbox"
+                  checked={advertisingEnabled}
+                  disabled={privacySignalActive}
+                  onChange={(e) => setAdvertisingEnabled(e.target.checked)}
+                  data-skip-tracking="true"
+                  className="mt-1 h-4 w-4 text-gray-900 border-gray-300 rounded"
+                />
+              </div>
+
+              <div className="flex flex-wrap items-center justify-between gap-2 pt-2 border-t border-gray-200">
+                <a href={privacyPolicyUrl} className="text-xs underline text-gray-700 hover:text-black">
+                  Read Full Privacy Policy
+                </a>
+                <div className="flex items-center gap-2">
+                  <button
+                    type="button"
+                    onClick={handleRejectNonEssential}
+                    data-skip-tracking="true"
+                    className="px-3 py-2 text-xs font-semibold text-gray-800 bg-gray-100 border border-gray-300 rounded hover:bg-gray-200"
+                  >
+                    Essential Only
+                  </button>
+                  <button
+                    type="submit"
+                    data-skip-tracking="true"
+                    className="px-3 py-2 text-xs font-semibold text-white bg-gray-900 rounded hover:bg-gray-800"
+                  >
+                    Save Preferences
+                  </button>
+                </div>
+              </div>
+            </form>
+          </div>
+        </div>
+      )}
+    </>
+  );
+}
