+            labelEl.textContent = 'Reward Tier Progress: 100 / 100 Beans (Reward Unlocked!)';
+            badgeEl.textContent = '100% Complete';
+          } else {
+            const remaining = 100 - numericVal;
+            customTrack.setAttribute('aria-valuetext', numericVal + '% complete — ' + remaining + ' beans away from a free handcrafted drink');
+            labelEl.textContent = 'Reward Tier Progress: ' + numericVal + ' / 100 Beans';
+            badgeEl.textContent = numericVal + '% Complete';
+          }
+
+          steps.forEach((step) => {
+            const threshold = Number(step.getAttribute('data-threshold')) || 0;
+            const baseText = step.textContent.replace(/^[\u2713\u25CB\u27F3]\s*/, '');
+            if (numericVal >= threshold) {
+              step.classList.add('completed');
+              step.textContent = '\u2713 ' + baseText;
+            } else {
+              step.classList.remove('completed');
+              step.textContent = '\u25CB ' + baseText;
+            }
+          });
+        }
+      }
+
+      buttons.forEach((btn) => {
