+            'Content-Type': 'application/json',
+            Accept: 'application/json',
+          },
+          body: JSON.stringify({ email: emailInput.value.trim() }),
+        });
+
+        if (result.ok) {
+          form.reset();
+          setFieldError('');
+        }
+      } finally {
+        submitBtn.disabled = false;
+      }
+    });
+
+    window.fetchWithPolicyHandling = fetchWithPolicyHandling;
+  </script>
