+import http from 'node:http';
+import fs from 'node:fs';
+import path from 'node:path';
+import crypto from 'node:crypto';
+import { fileURLToPath } from 'node:url';
+
+const __filename = fileURLToPath(import.meta.url);
+const __dirname = path.dirname(__filename);
+
+export const ALLOWLIST_DESTS = new Set([
+  'document',
+  'iframe',
+  'worker',
+  'sharedworker',
+  'serviceworker',
+]);
+
+export const DEFAULT_ALLOWED_PATTERNS = ['https://images.unsplash.com'];
+export const REPORT_ENDPOINT_NAME = 'conn-reports';
+
+const subscribers = new Set();
+
+export function normalizeAllowlistPattern(rawPattern) {
+  const trimmed = String(rawPattern).trim().replace(/^ws(s?):\/\//i, 'http$1://');
+  if (!/^https?:\/\//i.test(trimmed)) {
+    throw new Error(`Pattern must include an http:// or https:// scheme: ${rawPattern}`);
+  }
+  if (/[\s,]/.test(trimmed)) {
+    throw new Error(`Pattern must be a single URLPattern without spaces or commas: ${rawPattern}`);
+  }
+  if (/[()]/.test(trimmed)) {
+    throw new Error(`Custom regex groups are rejected by Connection-Allowlist: ${rawPattern}`);
+  }
+  return trimmed.replace(/^(https?:\/\/[^/?#]+)\/$/i, '$1');
+}
+
+export function buildConnectionAllowlistHeader({
+  allowSelf = true,
+  patterns = DEFAULT_ALLOWED_PATTERNS,
+  reportTo = REPORT_ENDPOINT_NAME,
+  redirects = 'block',
+  webrtc = 'block',
+} = {}) {
+  const items = allowSelf ? ['response-origin'] : [];
+  for (const pattern of patterns) {
+    const raw = String(pattern).trim();
+    if (raw === 'response-origin') {
+      if (!items.includes('response-origin')) items.push('response-origin');
+      continue;
+    }
+    const normalized = normalizeAllowlistPattern(raw);
+    items.push(`"${normalized.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`);
+  }
+  let header = `(${items.join(' ')})`;
+  if (redirects === 'allow') header += '; redirects=allow';
+  if (webrtc === 'allow') header += '; webrtc=allow';
+  if (reportTo) {
+    const endpointToken = String(reportTo).trim().replace(/^"+|"+$/g, '');
+    header += `; report-to=${endpointToken}`;
+  }
+  return header;
+}
+
+export function setConnectionAllowlistHeaders(res, options = {}) {
+  const {
+    secFetchDest = 'document',
+    patterns = DEFAULT_ALLOWED_PATTERNS,
+    reportOnlyPatterns,
+    reportEndpointName = REPORT_ENDPOINT_NAME,
+    reportEndpointUrl = 'http://localhost:11222/api/security-reports',
+    redirects = 'block',
+    webrtc = 'block',
+    reportOnly = false,
+  } = options;
+
+  const setHeader = (name, value) =>
+    typeof res.setHeader === 'function' ? res.setHeader(name, value) : res.headers.set(name, value);
+
+  if (typeof res.appendHeader === 'function') {
+    res.appendHeader('Vary', 'Sec-Fetch-Dest');
+  } else if (typeof res.headers?.append === 'function') {
+    res.headers.append('Vary', 'Sec-Fetch-Dest');
+  } else {
+    setHeader('Vary', 'Sec-Fetch-Dest');
+  }
+
+  if (secFetchDest && !ALLOWLIST_DESTS.has(String(secFetchDest).toLowerCase())) return;
+
+  setHeader('Reporting-Endpoints', `${reportEndpointName}="${reportEndpointUrl}"`);
+  setHeader(
+    reportOnly ? 'Connection-Allowlist-Report-Only' : 'Connection-Allowlist',
+    buildConnectionAllowlistHeader({
+      allowSelf: true,
+      patterns,
+      reportTo: reportEndpointName,
+      redirects,
+      webrtc,
+    }),
+  );
+
+  if (!reportOnly && Array.isArray(reportOnlyPatterns)) {
+    setHeader(
+      'Connection-Allowlist-Report-Only',
+      buildConnectionAllowlistHeader({
+        allowSelf: true,
+        patterns: reportOnlyPatterns,
+        reportTo: reportEndpointName,
+        redirects,
+        webrtc,
+      }),
+    );
+  }
+}
+
+export function buildContentSecurityPolicy({
+  scriptHash,
+  reportEndpointName = REPORT_ENDPOINT_NAME,
+} = {}) {
+  const scriptSrc = scriptHash
+    ? `script-src 'self' '${scriptHash}' 'report-sample'`
+    : "script-src 'self' 'report-sample'";
+
+  return [
+    "default-src 'self'",
+    "connect-src 'self'",
+    'img-src \'self\' https://images.unsplash.com data: blob:',
+    "style-src 'self' 'unsafe-inline'",
+    scriptSrc,
+    "form-action 'self'",
+    "worker-src 'self'",
+    "object-src 'none'",
+    "base-uri 'self'",
+    "frame-ancestors 'none'",
+    `report-to ${reportEndpointName}`,
+  ].join('; ');
+}
+
+function getInlineScriptHash(html) {
+  const match = html.match(/<script>([\s\S]*?)<\/script>/);
+  if (!match) return null;
+  return `sha256-${crypto.createHash('sha256').update(match[1], 'utf8').digest('base64')}`;
+}
+
+function setCompanionSecurityHeaders(res, { scriptHash, reportEndpointName = REPORT_ENDPOINT_NAME } = {}) {
+  res.setHeader('Content-Security-Policy', buildContentSecurityPolicy({ scriptHash, reportEndpointName }));
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('X-Frame-Options', 'DENY');
+  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  res.setHeader('Cross-Origin-Opener-Policy', 'same-origin-allow-popups');
+  res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
+  res.setHeader(
+    'Permissions-Policy',
+    'camera=(), geolocation=(), microphone=(), focus-without-user-activation=()',
+  );
+}
+
+function readRequestBody(req, maxBytes = 64 * 1024) {
+  return new Promise((resolve, reject) => {
+    const chunks = [];
+    let total = 0;
+    req.on('data', (chunk) => {
+      total += chunk.length;
+      if (total > maxBytes) {
+        reject(new Error('Payload too large'));
+        req.destroy();
+        return;
+      }
+      chunks.push(chunk);
+    });
+    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+  });
+}
+
+function parseEmailFromBody(rawBody, contentType = '') {
+  if (!rawBody) return '';
+  if (contentType.includes('application/json')) {
+    const parsed = JSON.parse(rawBody);
+    return typeof parsed?.email === 'string' ? parsed.email.trim() : '';
+  }
+  const params = new URLSearchParams(rawBody);
+  return (params.get('email') || '').trim();
+}
+
+export async function handleRequest(req, res) {
+  const port = Number(process.env.PORT) || 11222;
+  const host = req.headers.host || `localhost:${port}`;
+  const proto = req.headers['x-forwarded-proto'] === 'https' ? 'https' : 'http';
+  const reportEndpointUrl = `${proto}://${host}/api/security-reports`;
+  const url = new URL(req.url || '/', `${proto}://${host}`);
+  const pathname = url.pathname;
+
+  const indexHtmlPath = path.join(__dirname, 'index.html');
+  const html = fs.readFileSync(indexHtmlPath, 'utf8');
+  const scriptHash = getInlineScriptHash(html);
+
+  setConnectionAllowlistHeaders(res, {
+    secFetchDest: req.headers['sec-fetch-dest'] || 'document',
+    patterns: DEFAULT_ALLOWED_PATTERNS,
+    reportEndpointName: REPORT_ENDPOINT_NAME,
+    reportEndpointUrl,
+  });
+  setCompanionSecurityHeaders(res, { scriptHash, reportEndpointName: REPORT_ENDPOINT_NAME });
+
+  if (req.method === 'GET' && (pathname === '/' || pathname === '/index.html')) {
+    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
+    res.end(html);
+    return;
+  }
+
+  if (
+    req.method === 'POST' &&
+    (pathname === '/api/newsletter' || pathname === '/newsletter' || pathname === '/subscribe')
+  ) {
+    try {
+      const rawBody = await readRequestBody(req);
+      const email = parseEmailFromBody(rawBody, req.headers['content-type'] || '');
+      if (!email || email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
+        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+        res.end(JSON.stringify({ ok: false, message: 'Please enter a valid email address.' }));
+        return;
+      }
+
+      subscribers.add(email.toLowerCase());
+      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(
+        JSON.stringify({
+          ok: true,
+          message: 'Thanks for subscribing to The Daily Grind newsletter!',
+        }),
+      );
+      return;
+    } catch {
+      res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(JSON.stringify({ ok: false, message: 'Invalid newsletter signup request.' }));
+      return;
+    }
+  }
+
+  if (req.method === 'POST' && pathname === '/api/security-reports') {
+    await readRequestBody(req).catch(() => {});
+    res.writeHead(204);
+    res.end();
+    return;
+  }
+
+  if (req.method === 'GET' && pathname === '/logout') {
+    res.setHeader('Clear-Site-Data', '"cookies", "storage", "cache"');
+    res.writeHead(200, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Signed out.');
+    return;
+  }
+
+  res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
+  res.end(JSON.stringify({ ok: false, message: 'Not found' }));
+}
+
+export const server = http.createServer(handleRequest);
+
+const isMainModule =
+  process.argv[1] && path.resolve(process.argv[1]) === path.resolve(__filename);
+
+if (isMainModule) {
+  const port = Number(process.env.PORT) || 11222;
+  server.listen(port, () => {
+    console.log(`Daily Grind server listening on http://localhost:${port}`);
+  });
+}

