+const http = require('http');
+const fs = require('fs');
+const path = require('path');
+
+const PORT = process.env.PORT || 11222;
+const subscribers = [];
+
+const CSP_HEADER = [
+  "default-src 'self'",
+  "connect-src 'self'",
+  "img-src 'self' https://images.unsplash.com",
+  "script-src 'self' 'unsafe-inline'",
+  "style-src 'self' 'unsafe-inline'",
+  "font-src 'self'",
+  "form-action 'self'",
+  "base-uri 'self'",
+  "frame-ancestors 'self'",
+  "object-src 'none'"
+].join('; ');
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.js': 'text/javascript; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.svg': 'image/svg+xml',
+  '.ico': 'image/x-icon'
+};
+
+function parseEmail(rawBody, contentType) {
+  if (!rawBody) return '';
+  const trimmed = rawBody.trim();
+  if (contentType.includes('application/json') || trimmed.startsWith('{')) {
+    try {
+      const parsed = JSON.parse(trimmed);
+      return (parsed.email || '').trim();
+    } catch {
+      // fall through
+    }
+  }
+  if (contentType.includes('application/x-www-form-urlencoded') || trimmed.includes('=')) {
+    const params = new URLSearchParams(trimmed);
+    if (params.has('email')) {
+      return (params.get('email') || '').trim();
+    }
+  }
+  return trimmed;
+}
+
+const server = http.createServer((req, res) => {
+  res.setHeader('Content-Security-Policy', CSP_HEADER);
+
+  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
+  const pathname = url.pathname;
+
+  // Handle newsletter signup POST requests
+  if (
+    req.method === 'POST' &&
+    ['/newsletter', '/api/newsletter', '/subscribe', '/api/subscribe', '/signup', '/api/signup'].includes(pathname)
+  ) {
+    let body = '';
+    req.on('data', (chunk) => {
+      body += chunk.toString();
+    });
+    req.on('end', () => {
+      const contentType = (req.headers['content-type'] || '').toLowerCase();
+      const email = parseEmail(body, contentType);
+
+      if (!email || !email.includes('@')) {
+        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+        res.end(JSON.stringify({ ok: false, error: 'Please provide a valid email address.' }));
+        return;
+      }
+
+      subscribers.push({ email, subscribedAt: new Date().toISOString() });
+      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(
+        JSON.stringify({
+          ok: true,
+          email,
+          message: 'Thanks for subscribing to The Daily Grind newsletter!'
+        })
+      );
+    });
+    return;
+  }
+
+  // Serve homepage and static files
+  if (req.method === 'GET' || req.method === 'HEAD') {
+    const relativePath = pathname === '/' ? 'index.html' : pathname.replace(/^\/+/, '');
+    const safePath = path.normalize(relativePath).replace(/^(\.\.(\/|\\|$))+/, '');
+    const filePath = path.join(__dirname, safePath);
+
+    if (!filePath.startsWith(__dirname)) {
+      res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
+      res.end('Forbidden');
+      return;
+    }
+
+    fs.readFile(filePath, (err, content) => {
+      if (err) {
+        if (err.code === 'ENOENT') {
+          res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+          res.end('Not Found');
+        } else {
+          res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
+          res.end('Internal Server Error');
+        }
+        return;
+      }
+
+      const ext = path.extname(filePath).toLowerCase();
+      const mimeType = MIME_TYPES[ext] || 'application/octet-stream';
+      res.writeHead(200, { 'Content-Type': mimeType });
+      if (req.method === 'HEAD') {
+        res.end();
+      } else {
+        res.end(content);
+      }
+    });
+    return;
+  }
+
+  res.writeHead(405, { 'Content-Type': 'text/plain; charset=utf-8' });
+  res.end('Method Not Allowed');
+});
+
+if (require.main === module) {
+  server.listen(PORT, () => {
+    console.log(`Server listening on http://localhost:${PORT}`);
+  });
+}
+
+module.exports = server;

