+        if (!statusPill) return;
+        const heading = targetEl.querySelector('h1, h2');
+        const label = heading ? heading.textContent.trim() : targetEl.id;
+        statusPill.textContent = 'Arrived at ' + label;
+        statusPill.classList.add('visible');
+        if (statusHideTimer) clearTimeout(statusHideTimer);
+        statusHideTimer = setTimeout(() => {
+          statusPill.classList.remove('visible');
+        }, 2200);
+      }
+
+      function applyPostScrollEffects(targetEl) {
+        clearSectionEffects();
+        updateActiveNavLink(targetEl.id);
+
+        // Restart arrival animation cleanly if re-triggered
+        void targetEl.offsetWidth;
+        targetEl.classList.add(
+          'scroll-settled',
+          'scroll-arrived',
+          'is-highlighted',
+          'scroll-animating-arrival'
+        );
+        targetEl.setAttribute('data-scroll-state', 'arrived');
+
+        // Move focus to the target section only after scrolling has finished,
+        // preventing any abrupt browser scroll jump.
+        if (!targetEl.hasAttribute('tabindex')) {
+          targetEl.setAttribute('tabindex', '-1');
+        }
+        targetEl.focus({ preventScroll: true });
+
+        // Update URL hash without triggering an instant jump
+        if (history.replaceState) {
+          history.replaceState(null, '', '#' + targetEl.id);
+        }
+
+        showArrivalStatus(targetEl);
+
+        targetEl.dispatchEvent(
+          new CustomEvent('smoothscrollcomplete', {
+            bubbles: true,
+            detail: { targetId: targetEl.id, target: targetEl }
+          })
+        );
+      }
+
+      function waitForSmoothScrollCompletion(targetY, onComplete) {
+        // Cancel any previous pending scroll watcher
+        if (activeScrollController) {
+          activeScrollController.cancel();
+        }
+
+        let finished = false;
+        let idleTimeoutId = null;
+        let maxTimeoutId = null;
+        let rafId = null;
+        let lastY = window.pageYOffset;
+        let stableFrames = 0;
+
+        function cleanup() {
+          window.removeEventListener('scrollend', handleScrollEnd);
+          window.removeEventListener('scroll', handleScroll, { passive: true });
+          if (idleTimeoutId) clearTimeout(idleTimeoutId);
+          if (maxTimeoutId) clearTimeout(maxTimeoutId);
+          if (rafId) cancelAnimationFrame(rafId);
+        }
+
+        function finish() {
+          if (finished) return;
+          finished = true;
+          cleanup();
+          activeScrollController = null;
+          onComplete();
+        }
+
+        function cancel() {
+          if (finished) return;
+          finished = true;
+          cleanup();
+          activeScrollController = null;
+        }
+
+        function handleScrollEnd() {
+          finish();
+        }
+
+        function handleScroll() {
+          if (idleTimeoutId) clearTimeout(idleTimeoutId);
+          const currentY = window.pageYOffset;
+          const dist = Math.abs(currentY - targetY);
+          // If very close to targetY, settle quickly after scroll events stop;
+          // otherwise wait slightly longer for smooth scroll momentum to finish.
+          const waitTime = dist <= 3 ? 60 : 140;
+          idleTimeoutId = setTimeout(finish, waitTime);
+        }
+
+        const initialDistance = Math.abs(window.pageYOffset - targetY);
+
+        // If we are already at the target scroll position (no scroll needed),
+        // complete on the next frame so it remains asynchronous and consistent.
+        if (initialDistance <= 2) {
+          rafId = requestAnimationFrame(finish);
+          activeScrollController = { cancel };
+          return;
+        }
+
+        window.addEventListener('scrollend', handleScrollEnd, { once: true });
+        window.addEventListener('scroll', handleScroll, { passive: true });
+
+        // Frame-based position monitor in case scroll events are throttled
+        function checkPosition() {
+          if (finished) return;
+          const currentY = window.pageYOffset;
+          const dist = Math.abs(currentY - targetY);
+          const delta = Math.abs(currentY - lastY);
+          lastY = currentY;
+
+          if (dist <= 2 && delta < 0.5) {
+            stableFrames += 1;
+            if (stableFrames >= 3) {
+              finish();
+              return;
+            }
+          } else {
+            stableFrames = 0;
+          }
+          rafId = requestAnimationFrame(checkPosition);
+        }
+
+        rafId = requestAnimationFrame(checkPosition);
+
+        // Safety fallback timeout so completion always fires even in environments
+        // with instant/mocked scrolling or reduced-motion settings.
+        maxTimeoutId = setTimeout(finish, 1200);
