+      function scrollToTargetSection(targetEl) {
+        // Clear previous post-scroll state before starting a new smooth scroll
+        // so visual effects/focus changes only appear after the scroll finishes.
+        clearSectionEffects();
+        targetEl.setAttribute('data-scroll-state', 'scrolling');
+
+        const targetY = computeTargetScrollTop(targetEl);
+
+        waitForSmoothScrollCompletion(targetY, () => {
+          applyPostScrollEffects(targetEl);
+        });
+
+        window.scrollTo({
+          top: targetY,
+          behavior: 'smooth'
+        });
+      }
