+      allScrollTriggers.forEach((trigger) => {
+        trigger.addEventListener('click', (event) => {
+          const targetEl = resolveTargetElement(trigger);
+          if (!targetEl) return;
+
+          event.preventDefault();
+          scrollToTargetSection(targetEl);
+        });
+      });
+
+      // Interactive feedback for the Logout confirmation button
+      const logoutBtn = document.getElementById('confirm-logout-btn');
+      if (logoutBtn) {
+        logoutBtn.addEventListener('click', () => {
+          logoutBtn.textContent = 'Signed Out Safely';
+          logoutBtn.disabled = true;
+          if (statusPill) {
+            statusPill.textContent = 'Session ended safely.';
+            statusPill.classList.add('visible');
+          }
+        });
+      }
+    })();
+  </script>
