+    (function () {
+      const nav = document.querySelector('nav');
+      const navLinks = Array.from(document.querySelectorAll('nav a[href^="#"]'));
+      const sections = navLinks
+        .map((link) => {
+          const id = link.getAttribute('href').slice(1);
+          return document.getElementById(id);
+        })
+        .filter(Boolean);
+
+      function setActiveSection(activeId) {
+        navLinks.forEach((link) => {
+          const isMatch = link.getAttribute('href') === '#' + activeId;
+          link.classList.toggle('active', isMatch);
+          if (isMatch) {
+            link.setAttribute('aria-current', 'location');
+          } else {
+            link.removeAttribute('aria-current');
+          }
+        });
+      }
+
+      function updateActiveOnScroll() {
+        if (!sections.length) return;
+
+        const navHeight = nav ? nav.offsetHeight : 70;
+        const scrollPosition = window.scrollY;
+        const viewportHeight = window.innerHeight;
+        const docHeight = document.documentElement.scrollHeight;
+
+        // If scrolled to the very bottom of the page, highlight the last section
+        if (scrollPosition + viewportHeight >= docHeight - 10) {
+          setActiveSection(sections[sections.length - 1].id);
+          return;
+        }
+
+        // Probe line slightly below the sticky navbar
+        const probeLine = scrollPosition + navHeight + Math.min(140, viewportHeight * 0.25);
+
+        let currentSectionId = sections[0].id;
+        for (const section of sections) {
+          const rect = section.getBoundingClientRect();
+          const sectionTop = rect.top + scrollPosition;
+          if (probeLine >= sectionTop) {
+            currentSectionId = section.id;
+          }
+        }
+
+        setActiveSection(currentSectionId);
+      }
+
+      // Click handler for immediate highlight feedback
+      navLinks.forEach((link) => {
+        link.addEventListener('click', () => {
+          const targetId = link.getAttribute('href').slice(1);
+          if (targetId) {
+            setActiveSection(targetId);
+          }
+        });
+      });
+
+      window.addEventListener('scroll', updateActiveOnScroll, { passive: true });
+      window.addEventListener('resize', updateActiveOnScroll);
+      window.addEventListener('hashchange', () => {
+        const hashId = window.location.hash.replace('#', '');
+        if (hashId && sections.some((s) => s.id === hashId)) {
+          setActiveSection(hashId);
+        }
+      });
+
+      // Initialize active section on load
+      if (window.location.hash) {
+        const hashId = window.location.hash.replace('#', '');
+        if (sections.some((s) => s.id === hashId)) {
+          setActiveSection(hashId);
+        } else {
+          updateActiveOnScroll();
+        }
+      } else {
+        updateActiveOnScroll();
+      }
+    })();
