+            const totalTravel = viewportHeight + rect.height;
+            const rawProgress = (viewportHeight - rect.top) / totalTravel;
+            const progress = Math.max(0, Math.min(1, rawProgress));
+            const visual = animatedSections[index];
+
+            let opacity = 0;
+            let scale = 0.92;
+            let translateY = 30;
+            let blur = 6;
+
