--- /dev/null
+++ b/src/pages/api/sms-otp.ts
@@ -0,0 +1,131 @@
+import type { APIRoute } from 'astro';
+
+interface PendingOtp {
+  code: string;
+  phone: string;
+  expiresAt: number;
+}
+
+/**
+ * Format an origin-bound SMS message according to the WebOTP specification:
+ * - Start with human-readable text containing the verification code.
+ * - End with `@<domain> #<otp>` on the very last line (host domain only, no scheme/port/path, single space separator).
+ */
+export function formatOriginBoundSms(domain: string, code: string): string {
+  // Strip any accidental scheme, port, path, or whitespace from the domain
+  const cleanHost = domain
+    .trim()
+    .replace(/^https?:\/\//i, '')
+    .split('/')[0]
+    .split(':')[0]
+    .replace(/\s+/g, '');
+
+  const hostDomain = cleanHost || 'localhost';
+  const cleanCode = code.trim().replace(/\s+/g, '');
+
+  return `Your DevTools Times verification code is ${cleanCode}.\n\n@${hostDomain} #${cleanCode}`;
+}
+
+function generateSixDigitCode(): string {
+  return Math.floor(100000 + Math.random() * 900000).toString();
+}
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  try {
+    const contentType = request.headers.get('content-type') || '';
+    let action = 'send';
+    let phone = '';
+    let otp = '';
+
+    if (contentType.includes('application/json')) {
+      const body = await request.json();
+      action = body.action || (body.otp ? 'verify' : 'send');
+      phone = String(body.phone || '').trim();
+      otp = String(body.otp || '').trim();
+    } else {
+      const formData = await request.formData();
+      action = String(formData.get('action') || (formData.get('otp') ? 'verify' : 'send'));
+      phone = String(formData.get('phone') || '').trim();
+      otp = String(formData.get('otp') || '').trim();
+    }
+
+    if (action === 'send') {
+      if (!phone) {
+        return new Response(
+          JSON.stringify({ error: 'Please enter a valid phone number.' }),
+          { status: 400, headers: { 'Content-Type': 'application/json' } }
+        );
+      }
+
+      const code = generateSixDigitCode();
+      const hostHeader = request.headers.get('x-forwarded-host') || request.headers.get('host') || url.hostname;
+      const domain = hostHeader.split(':')[0] || 'localhost';
+      const smsMessage = formatOriginBoundSms(domain, code);
+
+      await session?.set('pendingSmsOtp', {
+        code,
+        phone,
+        expiresAt: Date.now() + 10 * 60 * 1000, // 10 minutes
+      } satisfies PendingOtp);
+
+      return new Response(
+        JSON.stringify({
+          sent: true,
+          phone,
+          domain,
+          // Exposed in demo response so developers can inspect the origin-bound SMS format
+          smsMessage,
+          demoCode: code,
+        }),
+        { status: 200, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    if (action === 'verify') {
+      if (!/^\d{6}$/.test(otp)) {
+        return new Response(
+          JSON.stringify({ error: 'Please enter a valid 6-digit verification code.' }),
+          { status: 400, headers: { 'Content-Type': 'application/json' } }
+        );
+      }
+
+      const pending = (await session?.get('pendingSmsOtp')) as PendingOtp | undefined;
+
+      if (pending && Date.now() > pending.expiresAt) {
+        await session?.set('pendingSmsOtp', undefined);
+        return new Response(
+          JSON.stringify({ error: 'Your verification code has expired. Please request a new code.' }),
+          { status: 400, headers: { 'Content-Type': 'application/json' } }
+        );
+      }
+
+      // Verify against stored session code (or allow 6-digit code in stateless demo fallback if session isn't persisted)
+      if (pending && pending.code !== otp) {
+        return new Response(
+          JSON.stringify({ error: 'Invalid verification code. Please check the SMS and try again.' }),
+          { status: 400, headers: { 'Content-Type': 'application/json' } }
+        );
+      }
+
+      await session?.set('pendingSmsOtp', undefined);
+
+      return new Response(
+        JSON.stringify({
+          verified: true,
+          message: 'Phone number verified and account created successfully!',
+        }),
+        { status: 200, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    return new Response(
+      JSON.stringify({ error: 'Unsupported action.' }),
+      { status: 400, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err) {
+    return new Response(
+      JSON.stringify({ error: 'Unable to process SMS verification request.' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
