+import type { APIRoute } from 'astro';
+
+const PHONE_REGEX = /^\+?[0-9\s\-()]{7,20}$/;
+
+export function normalizePhoneNumber(phone: string): string {
+  const trimmed = phone.trim();
+  const hasPlus = trimmed.startsWith('+');
+  const digits = trimmed.replace(/\D/g, '');
+  return hasPlus ? `+${digits}` : digits;
+}
+
+export function isValidPhoneNumber(phone: string): boolean {
+  if (!phone || !PHONE_REGEX.test(phone.trim())) {
+    return false;
+  }
+  const digits = phone.replace(/\D/g, '');
+  return digits.length >= 7 && digits.length <= 15;
+}
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  try {
+    const body = await request.json();
+    const rawPhone = typeof body?.phone === 'string' ? body.phone : '';
+
+    if (!isValidPhoneNumber(rawPhone)) {
+      return new Response(
+        JSON.stringify({
+          error: 'Invalid phone number. Please enter a valid mobile phone number.',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const normalizedPhone = normalizePhoneNumber(rawPhone);
+    const code = '123456';
+    const host = request.headers.get('host')?.split(':')[0] || url.hostname || 'localhost';
+
+    // WebOTP standard origin-bound one-time code SMS format
+    const smsMessage = `Your DevTools Times verification code is ${code}.\n\n@${host} #${code}`;
+
+    if (session) {
+      await session.set('otpVerification', {
+        phone: normalizedPhone,
+        code,
+        sentAt: Date.now(),
+        verified: false,
+      });
+    }
+
+    return new Response(
+      JSON.stringify({
+        success: true,
+        phone: normalizedPhone,
+        message: `Verification code sent via SMS to ${rawPhone.trim()}.`,
+        smsFormat: smsMessage,
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch {
+    return new Response(
+      JSON.stringify({
+        error: 'Failed to process phone verification request.',
+      }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};
