@@ -0,0 +1,89 @@
+import type { APIRoute } from 'astro';
+import { isValidPhoneNumber, normalizePhoneNumber } from './send-otp';
+
+const OTP_REGEX = /^\d{6}$/;
+
+export function extractOtpFromText(input: string): string {
+  if (!input) return '';
+  const trimmed = input.trim();
+  // Match WebOTP origin-bound format: @domain #123456
+  const hashMatch = trimmed.match(/#(\d{6})\b/);
+  if (hashMatch) {
+    return hashMatch[1];
+  }
+  // Match standalone 6-digit passcode in an SMS message
+  const sixDigitMatch = trimmed.match(/\b(\d{6})\b/);
+  if (sixDigitMatch) {
+    return sixDigitMatch[1];
+  }
+  return trimmed.replace(/\D/g, '').slice(0, 6);
+}
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const body = await request.json();
+    const rawPhone = typeof body?.phone === 'string' ? body.phone : '';
+    const rawCode = typeof body?.otp === 'string' ? body.otp : typeof body?.code === 'string' ? body.code : '';
+    const code = extractOtpFromText(rawCode);
+
+    if (!isValidPhoneNumber(rawPhone)) {
+      return new Response(
+        JSON.stringify({
+          error: 'Please provide a valid phone number.',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    if (!OTP_REGEX.test(code)) {
+      return new Response(
+        JSON.stringify({
+          error: 'Invalid one-time passcode. Please enter the 6-digit numeric code sent via SMS.',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const normalizedPhone = normalizePhoneNumber(rawPhone);
+
+    if (session) {
+      const existing = await session.get('otpVerification');
+      await session.set('otpVerification', {
+        ...(existing || {}),
+        phone: normalizedPhone,
+        code,
+        verified: true,
+        verifiedAt: Date.now(),
+      });
+    }
+
+    return new Response(
+      JSON.stringify({
+        success: true,
+        verified: true,
+        phone: normalizedPhone,
+        message: 'Phone number and one-time passcode verified successfully.',
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch {
+    return new Response(
+      JSON.stringify({
+        error: 'Failed to verify one-time passcode.',
+      }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};

