+       * into exact epoch nanoseconds as a BigInt without using floating-point math.
+       */
+      function parseUtcTimestampToEpochNs(tsInput) {
+        if (typeof tsInput === 'bigint') {
+          return tsInput;
+        }
+        if (typeof tsInput === 'number') {
+          return BigInt(Math.trunc(tsInput));
+        }
+        const str = String(tsInput).trim();
+        if (/^\d+$/.test(str)) {
+          return BigInt(str);
+        }
+
+        // Prefer Temporal.Instant if available in the runtime
+        if (typeof Temporal !== 'undefined' && Temporal.Instant) {
+          try {
+            return Temporal.Instant.from(str).epochNanoseconds;
+          } catch (_) {
+            // Fallback to regex parser below
+          }
+        }
+
+        const isoRegex = /^(\d{4})-(\d{2})-(\d{2})[T\s](\d{2}):(\d{2}):(\d{2})(?:\.(\d{1,9}))?(Z|[+-]\d{2}:?\d{2})$/i;
+        const match = str.match(isoRegex);
+        if (!match) {
+          throw new Error('Invalid UTC nanosecond timestamp format: ' + str);
+        }
+
+        const year = Number(match[1]);
+        const month = Number(match[2]);
+        const day = Number(match[3]);
+        const hour = Number(match[4]);
+        const minute = Number(match[5]);
+        const second = Number(match[6]);
+        const fracRaw = (match[7] || '').padEnd(9, '0').slice(0, 9);
+        const tzRaw = match[8].toUpperCase();
+
+        // Date.UTC up to whole seconds is an exact integer well within Number.MAX_SAFE_INTEGER
+        const wholeSecondsMs = Date.UTC(year, month - 1, day, hour, minute, second);
+        let epochSeconds = BigInt(wholeSecondsMs) / 1000n;
+
+        if (tzRaw !== 'Z') {
+          const sign = tzRaw[0] === '-' ? -1n : 1n;
+          const cleanOffset = tzRaw.slice(1).replace(':', '');
+          const offHours = BigInt(cleanOffset.slice(0, 2));
+          const offMinutes = BigInt(cleanOffset.slice(2, 4));
+          const offsetSeconds = sign * (offHours * 3600n + offMinutes * 60n);
+          epochSeconds -= offsetSeconds;
+        }
+
+        const subsecondNs = BigInt(fracRaw);
+        return epochSeconds * 1000000000n + subsecondNs;
+      }
+
+      /**
+       * Formats an exact epoch nanosecond BigInt back into a canonical ISO-8601 UTC string
+       * with 9 fractional digits (YYYY-MM-DDTHH:mm:ss.nnnnnnnnnZ).
+       */
+      function formatEpochNsToUtcIso(epochNsBigInt) {
+        const nsPerSec = 1000000000n;
+        let sec = epochNsBigInt / nsPerSec;
+        let remNs = epochNsBigInt % nsPerSec;
+        if (remNs < 0n) {
+          sec -= 1n;
+          remNs += nsPerSec;
+        }
+        const dateSec = new Date(Number(sec * 1000n));
+        const isoPrefix = dateSec.toISOString().slice(0, 19); // YYYY-MM-DDTHH:mm:ss
+        const fracStr = remNs.toString().padStart(9, '0');
+        return `${isoPrefix}.${fracStr}Z`;
+      }
+
+      /**
+       * Formats a nanosecond interval (BigInt) into exact decimal milliseconds,
+       * decomposed units (s / ms / μs / ns), and exact total nanoseconds.
+       */
+      function formatNanosecondInterval(deltaNs) {
+        const isNegative = deltaNs < 0n;
+        const absNs = isNegative ? -deltaNs : deltaNs;
+        const signPrefix = isNegative ? '-' : '+';
+
+        const wholeMs = absNs / 1000000n;
+        const remNsAfterMs = absNs % 1000000n;
+        const decimalMs = `${isNegative ? '-' : ''}${wholeMs.toString()}.${remNsAfterMs.toString().padStart(6, '0')} ms`;
+
+        const sec = absNs / 1000000000n;
+        const ms = (absNs % 1000000000n) / 1000000n;
+        const us = (absNs % 1000000n) / 1000n;
+        const ns = absNs % 1000n;
+
+        const parts = [];
+        if (sec > 0n) parts.push(`${sec}s`);
+        if (ms > 0n || sec > 0n) parts.push(`${ms}ms`);
+        if (us > 0n || ms > 0n || sec > 0n) parts.push(`${us}μs`);
+        parts.push(`${ns}ns`);
+
+        return {
+          deltaNs,
+          deltaNsString: absNs.toString(),
+          decimalMs,
+          humanBreakdown: `${signPrefix}${parts.join(' ')}`,
+          exactLabel: `${decimalMs} (${absNs.toLocaleString('en-US')} ns)`
+        };
+      }
+
+      /**
+       * Sorts out-of-order coffee order events chronologically using exact BigInt nanosecond
+       * arithmetic and calculates consecutive intervals without losing sub-millisecond precision.
+       */
+      function sortAndMeasureCoffeeOrderEvents(rawEvents) {
+        const indexed = rawEvents.map((evt, idx) => {
+          const epochNs = parseUtcTimestampToEpochNs(evt.timestamp);
+          return {
+            ...evt,
+            arrivalOrder: idx + 1,
+            epochNs,
+            canonicalTimestamp: formatEpochNsToUtcIso(epochNs)
+          };
+        });
