+              ...evt,
+              chronologicalRank: 1,
+              intervalNs: 0n,
+              intervalFormatted: null
+            };
+          }
+          const prevEvt = sorted[sortedIdx - 1];
+          const deltaNs = evt.epochNs - prevEvt.epochNs;
+          return {
+            ...evt,
+            chronologicalRank: sortedIdx + 1,
+            intervalNs: deltaNs,
+            intervalFormatted: formatNanosecondInterval(deltaNs)
+          };
+        });
