+          ? enriched[enriched.length - 1].epochNs - enriched[0].epochNs
+          : 0n;
+        const minIntervalNs = intervalsNs.length > 0
+          ? intervalsNs.reduce((min, v) => (v < min ? v : min), intervalsNs[0])
+          : 0n;
+        const maxIntervalNs = intervalsNs.length > 0
+          ? intervalsNs.reduce((max, v) => (v > max ? v : max), intervalsNs[0])
+          : 0n;
+        const meanIntervalNs = intervalsNs.length > 0
+          ? totalSpanNs / BigInt(intervalsNs.length)
+          : 0n;
