+        return {
+          rawEvents: indexed,
+          sortedEvents: enriched,
+          stats: {
+            eventCount: enriched.length,
+            intervalCount: intervalsNs.length,
+            totalSpan: formatNanosecondInterval(totalSpanNs),
+            minInterval: formatNanosecondInterval(minIntervalNs),
+            maxInterval: formatNanosecondInterval(maxIntervalNs),
+            meanInterval: formatNanosecondInterval(meanIntervalNs)
+          }
+        };
+      }
+
+      function renderTelemetryBatch(rawBatch) {
+        const result = sortAndMeasureCoffeeOrderEvents(rawBatch);
+
+        const emptyState = document.getElementById('telemetry-empty-state');
+        const resultsContainer = document.getElementById('telemetry-results');
+        const summaryContainer = document.getElementById('telemetry-summary');
+        const sortedTbody = document.getElementById('sorted-events-tbody');
+        const rawTbody = document.getElementById('raw-events-tbody');
+
+        if (emptyState) emptyState.style.display = 'none';
+        if (resultsContainer) resultsContainer.style.display = 'block';
+
+        summaryContainer.innerHTML = `
+          <div class="summary-card">
+            <div class="label">Events Sorted</div>
+            <div class="value">${result.stats.eventCount} events</div>
+          </div>
+          <div class="summary-card">
+            <div class="label">Total Elapsed Window</div>
+            <div class="value" data-testid="total-span">${result.stats.totalSpan.decimalMs}</div>
+            <div class="mono" style="font-size:0.75rem; color:#6d4c41;">${result.stats.totalSpan.deltaNsString} ns</div>
+          </div>
+          <div class="summary-card">
+            <div class="label">Min Consecutive Δt</div>
+            <div class="value" data-testid="min-interval">${result.stats.minInterval.decimalMs}</div>
+            <div class="mono" style="font-size:0.75rem; color:#6d4c41;">${result.stats.minInterval.deltaNsString} ns (${result.stats.minInterval.humanBreakdown})</div>
+          </div>
+          <div class="summary-card">
+            <div class="label">Max Consecutive Δt</div>
+            <div class="value" data-testid="max-interval">${result.stats.maxInterval.decimalMs}</div>
+            <div class="mono" style="font-size:0.75rem; color:#6d4c41;">${result.stats.maxInterval.deltaNsString} ns</div>
+          </div>
+          <div class="summary-card">
+            <div class="label">Mean Consecutive Δt</div>
+            <div class="value" data-testid="mean-interval">${result.stats.meanInterval.decimalMs}</div>
+            <div class="mono" style="font-size:0.75rem; color:#6d4c41;">${result.stats.meanInterval.deltaNsString} ns</div>
+          </div>
+        `;
+
+        sortedTbody.innerHTML = result.sortedEvents.map((evt) => {
+          const intervalHtml = evt.intervalFormatted
+            ? `<span class="interval-pill" data-interval-ns="${evt.intervalFormatted.deltaNsString}">+${evt.intervalFormatted.decimalMs} (${evt.intervalFormatted.deltaNsString} ns | ${evt.intervalFormatted.humanBreakdown})</span>`
+            : `<span class="badge" data-interval-ns="0">0.000000 ms (0 ns — Baseline)</span>`;
+
+          return `
+            <tr data-event-id="${evt.eventId}" data-epoch-ns="${evt.epochNs.toString()}">
+              <td><strong>${evt.chronologicalRank}</strong></td>
+              <td>#${evt.arrivalOrder}</td>
+              <td class="mono">${evt.orderId}</td>
+              <td><span class="badge">${evt.service}</span> <small style="color:#6d4c41;">(${evt.region})</small></td>
+              <td class="mono">${evt.eventType}</td>
+              <td>${evt.item}</td>
+              <td class="mono">${evt.canonicalTimestamp}</td>
+              <td>${intervalHtml}</td>
+            </tr>
+          `;
+        }).join('');
+
+        rawTbody.innerHTML = result.rawEvents.map((evt) => `
+          <tr>
+            <td>#${evt.arrivalOrder}</td>
+            <td class="mono">${evt.orderId}</td>
+            <td><span class="badge">${evt.service}</span></td>
+            <td class="mono">${evt.eventType}</td>
+            <td class="mono">${evt.timestamp}</td>
+          </tr>
+        `).join('');
+
+        return result;
+      }
+
+      // Expose utilities on window for programmatic inspection if needed
+      window.DailyGrindTelemetry = {
+        INITIAL_EVENT_BATCH,
+        parseUtcTimestampToEpochNs,
+        formatEpochNsToUtcIso,
+        formatNanosecondInterval,
+        sortAndMeasureCoffeeOrderEvents,
+        renderTelemetryBatch
