+    (function () {
+      const STORAGE_KEY = 'dailyGrindPreferenceOn';
+      const toggleInput = document.getElementById('preference-toggle');
+      const statusBadge = document.getElementById('preference-status');
+      const preferenceSection = document.getElementById('preference-section');
+
+      function applyPreference(isOn) {
+        const stateStr = isOn ? 'on' : 'off';
+        toggleInput.checked = isOn;
+        toggleInput.setAttribute('aria-checked', String(isOn));
+        toggleInput.setAttribute('data-state', stateStr);
+        statusBadge.textContent = isOn ? 'On' : 'Off';
+        statusBadge.setAttribute('data-state', stateStr);
+        preferenceSection.setAttribute('data-state', stateStr);
+        document.body.setAttribute('data-preference', stateStr);
+        document.body.classList.toggle('dark-mode', isOn);
+        document.body.classList.toggle('preference-on', isOn);
+      }
+
+      try {
+        const saved = localStorage.getItem(STORAGE_KEY);
+        if (saved === 'true' || saved === 'on') {
+          applyPreference(true);
+        } else {
+          applyPreference(false);
+        }
+      } catch (e) {
+        applyPreference(false);
+      }
+
+      toggleInput.addEventListener('change', function () {
+        const isOn = Boolean(toggleInput.checked);
+        applyPreference(isOn);
+        try {
+          localStorage.setItem(STORAGE_KEY, String(isOn));
+        } catch (e) {
+          // Ignore storage errors in restricted environments
+        }
+      });
+
