+  <script>
+    (function () {
+      const menuSection = document.getElementById('coffee-menu');
+      if (!menuSection) return;
+
+      const tabsWrapper = document.getElementById('menu-tabs-wrapper');
+      const tabBar = document.getElementById('coffee-tablist');
+      const prevBtn = document.getElementById('tab-scroll-prev');
+      const nextBtn = document.getElementById('tab-scroll-next');
+      const tabs = Array.from(tabBar.querySelectorAll('[role="tab"]'));
+      const panels = Array.from(menuSection.querySelectorAll('[role="tabpanel"]'));
+
+      function updateOverflowIndicators() {
+        if (!tabBar || !tabsWrapper) return;
+        const maxScrollLeft = tabBar.scrollWidth - tabBar.clientWidth;
+        const isOverflowing = maxScrollLeft > 2;
+        const canScrollLeft = tabBar.scrollLeft > 4;
+        const canScrollRight = tabBar.scrollLeft < maxScrollLeft - 4;
+
+        tabsWrapper.classList.toggle('is-overflowing', isOverflowing);
+        tabsWrapper.classList.toggle('can-scroll-left', isOverflowing && canScrollLeft);
+        tabsWrapper.classList.toggle('can-scroll-right', isOverflowing && canScrollRight);
+
+        if (prevBtn) prevBtn.disabled = !canScrollLeft;
+        if (nextBtn) nextBtn.disabled = !canScrollRight;
+      }
+
+      function scrollTabIntoCenter(tab) {
+        if (!tabBar || !tab) return;
+        const tabBarRect = tabBar.getBoundingClientRect();
+        const tabRect = tab.getBoundingClientRect();
+        const currentScroll = tabBar.scrollLeft;
+        const offset = (tabRect.left - tabBarRect.left) - (tabBarRect.width / 2) + (tabRect.width / 2);
+        const targetScroll = Math.max(0, Math.min(tabBar.scrollWidth - tabBar.clientWidth, currentScroll + offset));
+
+        if (typeof tabBar.scrollTo === 'function') {
+          tabBar.scrollTo({ left: targetScroll, behavior: 'smooth' });
+        } else {
+          tabBar.scrollLeft = targetScroll;
+        }
+      }
+
+      function activateTab(nextTab, { focus = false, scroll = true } = {}) {
+        if (!nextTab) return;
+        const targetPanelId = nextTab.getAttribute('aria-controls');
+
+        tabs.forEach((tab) => {
+          const isSelected = tab === nextTab;
+          tab.setAttribute('aria-selected', isSelected ? 'true' : 'false');
+          tab.setAttribute('tabindex', isSelected ? '0' : '-1');
+        });
+
+        panels.forEach((panel) => {
+          const isMatch = panel.id === targetPanelId;
+          panel.classList.toggle('is-active', isMatch);
+          if (isMatch) {
+            panel.removeAttribute('hidden');
+          } else {
+            panel.setAttribute('hidden', '');
+          }
+        });
+
+        if (focus) {
+          nextTab.focus({ preventScroll: true });
+        }
+        if (scroll) {
+          scrollTabIntoCenter(nextTab);
+        }
+      }
+
+      tabs.forEach((tab) => {
+        tab.addEventListener('click', () => {
+          activateTab(tab, { focus: false, scroll: true });
+        });
+      });
+
+      tabBar.addEventListener('keydown', (event) => {
+        const currentIndex = tabs.indexOf(document.activeElement);
+        if (currentIndex === -1) return;
+
+        let nextIndex = null;
+        if (event.key === 'ArrowRight') {
+          nextIndex = (currentIndex + 1) % tabs.length;
+        } else if (event.key === 'ArrowLeft') {
+          nextIndex = (currentIndex - 1 + tabs.length) % tabs.length;
+        } else if (event.key === 'Home') {
+          nextIndex = 0;
+        } else if (event.key === 'End') {
+          nextIndex = tabs.length - 1;
+        }
+
+        if (nextIndex !== null) {
+          event.preventDefault();
+          activateTab(tabs[nextIndex], { focus: true, scroll: true });
+        }
+      });
+
+      if (prevBtn) {
+        prevBtn.addEventListener('click', () => {
+          const step = Math.max(160, Math.round(tabBar.clientWidth * 0.65));
+          tabBar.scrollBy({ left: -step, behavior: 'smooth' });
+        });
+      }
+
+      if (nextBtn) {
+        nextBtn.addEventListener('click', () => {
+          const step = Math.max(160, Math.round(tabBar.clientWidth * 0.65));
+          tabBar.scrollBy({ left: step, behavior: 'smooth' });
+        });
+      }
