diff --git a/src/components/ArticleTranslationControl.tsx b/src/components/ArticleTranslationControl.tsx
new file mode 100644
index 0000000..37e0063
--- /dev/null
+++ b/src/components/ArticleTranslationControl.tsx
@@ -0,0 +1,329 @@
+import React, { useState, useEffect } from 'react';
+import {
+  SUPPORTED_LANGUAGES,
+  isTranslatorApiSupported,
+  isLanguageDetectorSupported,
+  checkLanguagePairAvailability,
+  createTranslatorWithMonitor,
+  detectSourceLanguage,
+  translateElementsInScope,
+  restoreElementsInScope,
+  collectTranslatableElements,
+} from '../utils/translator';
+
+interface ArticleTranslationControlProps {
+  scopeSelector?: string;
+  compact?: boolean;
+  defaultSourceLanguage?: string;
+  defaultTargetLanguage?: string;
+  label?: string;
+}
+
+export default function ArticleTranslationControl({
+  scopeSelector,
+  compact = false,
+  defaultSourceLanguage = 'en',
+  defaultTargetLanguage = 'es',
+  label = 'On-Device Translation',
+}: ArticleTranslationControlProps) {
+  const [apiSupported, setApiSupported] = useState<boolean | null>(null);
+  const [detectorSupported, setDetectorSupported] = useState<boolean>(false);
+  const [sourceLanguage, setSourceLanguage] = useState<string>(defaultSourceLanguage);
+  const [targetLanguage, setTargetLanguage] = useState<string>(defaultTargetLanguage);
+  const [availability, setAvailability] = useState<TranslatorAvailability | 'checking'>('checking');
+  const [isTranslating, setIsTranslating] = useState<boolean>(false);
+  const [downloadProgress, setDownloadProgress] = useState<number | null>(null);
+  const [translationProgress, setTranslationProgress] = useState<{ completed: number; total: number } | null>(null);
+  const [activeTranslatedLang, setActiveTranslatedLang] = useState<string | null>(null);
+  const [errorMessage, setErrorMessage] = useState<string | null>(null);
+  const [detectedConfidence, setDetectedConfidence] = useState<number | null>(null);
+
+  useEffect(() => {
+    const supported = isTranslatorApiSupported();
+    setApiSupported(supported);
+    setDetectorSupported(isLanguageDetectorSupported());
+  }, []);
+
+  useEffect(() => {
+    if (apiSupported === null) return;
+    if (!apiSupported) {
+      setAvailability('unavailable');
+      return;
+    }
+
+    let cancelled = false;
+    setAvailability('checking');
+    setErrorMessage(null);
+
+    checkLanguagePairAvailability(sourceLanguage, targetLanguage).then((status) => {
+      if (!cancelled) {
+        setAvailability(status);
+      }
+    });
+
+    return () => {
+      cancelled = true;
+    };
+  }, [apiSupported, sourceLanguage, targetLanguage]);
+
+  const getScopeRoot = (): ParentNode => {
+    if (typeof document === 'undefined') return null as unknown as ParentNode;
+    if (scopeSelector) {
+      const el = document.querySelector(scopeSelector);
+      if (el) return el;
+    }
+    return document;
+  };
+
+  const handleAutoDetect = async () => {
+    setErrorMessage(null);
+    const root = getScopeRoot();
+    if (!root) return;
+
+    const elements = collectTranslatableElements(root);
+    const sample = elements
+      .slice(0, 4)
+      .map((el) => el.textContent?.trim() ?? '')
+      .filter((t) => t.length > 0)
+      .join(' ');
+
+    if (sample.length < 15) {
+      setErrorMessage('Not enough text on page to accurately detect language.');
+      return;
+    }
+
+    const result = await detectSourceLanguage(sample, sourceLanguage, (pct) => {
+      setDownloadProgress(pct);
+    });
+    setDownloadProgress(null);
+
+    if (result.detectedLanguage) {
+      const matched = SUPPORTED_LANGUAGES.find(
+        (l) => l.code.toLowerCase() === result.detectedLanguage.toLowerCase(),
+      );
+      if (matched) {
+        setSourceLanguage(matched.code);
+        setDetectedConfidence(Math.round(result.confidence * 100));
+      }
+    }
+  };
+
+  const handleSwapLanguages = () => {
+    const prevSource = sourceLanguage;
+    setSourceLanguage(targetLanguage);
+    setTargetLanguage(prevSource);
+    setErrorMessage(null);
+  };
+
+  const handleTranslate = async () => {
+    if (!apiSupported) return;
+    setErrorMessage(null);
+
+    if (sourceLanguage === targetLanguage) {
+      handleRestore();
+      return;
+    }
+
+    const root = getScopeRoot();
+    if (!root) return;
+
+    try {
+      setIsTranslating(true);
+      setDownloadProgress(null);
+      setTranslationProgress(null);
+
+      // Must be triggered directly inside this user click gesture handler so downloadable models can be fetched
+      const translator = await createTranslatorWithMonitor(
+        sourceLanguage,
+        targetLanguage,
+        (pct) => {
+          setDownloadProgress(pct);
+        },
+      );
+
+      setDownloadProgress(null);
+      setAvailability('available');
+
+      await translateElementsInScope(root, translator, targetLanguage, (completed, total) => {
+        setTranslationProgress({ completed, total });
+      });
+
+      setActiveTranslatedLang(targetLanguage);
+    } catch (err: any) {
+      setErrorMessage(
+        err?.message || 'Unable to translate content with the on-device Translator API.',
+      );
+    } finally {
+      setIsTranslating(false);
+      setDownloadProgress(null);
+      setTranslationProgress(null);
+    }
+  };
+
+  const handleRestore = () => {
+    const root = getScopeRoot();
+    if (!root) return;
+    restoreElementsInScope(root);
+    setActiveTranslatedLang(null);
+    setErrorMessage(null);
+  };
+
+  const isUnsupported = apiSupported === false || availability === 'unavailable';
+
+  return (
+    <div
+      className={
+        compact
+          ? 'flex flex-wrap items-center gap-2 text-xs bg-amber-50/70 border border-amber-200 rounded-md px-2.5 py-1.5'
+          : 'bg-amber-50/60 border border-amber-200 rounded-lg p-3.5 my-4 shadow-xs'
+      }
+      data-translation-control={compact ? 'compact' : 'article'}
+    >
+      <div className="flex items-center gap-1.5 font-semibold text-gray-800">
+        <svg
+          xmlns="http://www.w3.org/2000/svg"
+          fill="none"
+          viewBox="0 0 24 24"
+          strokeWidth={1.75}
+          stroke="currentColor"
+          className="w-4 h-4 text-amber-700 shrink-0"
+          aria-hidden="true"
+        >
+          <path
+            strokeLinecap="round"
+            strokeLinejoin="round"
+            d="m10.5 21 5.25-11.25L21 21m-9-3h7.5M3 5.621a48.474 48.474 0 0 1 6-.371m0 0c1.12 0 2.233.038 3.334.114M9 5.25V3m3.334 2.364C11.176 10.658 7.69 15.08 3 17.502m9.334-12.138c.896.061 1.785.147 2.666.257m-4.589 8.495a18.023 18.023 0 0 1-3.827-5.802"
+          />
+        </svg>
+        <span>{label}</span>
+        {!compact && availability !== 'checking' && (
+          <span
+            className={`text-[11px] font-medium px-2 py-0.5 rounded-full ${
+              availability === 'available'
+                ? 'bg-green-100 text-green-800'
+                : availability === 'downloadable' || availability === 'downloading'
+                  ? 'bg-amber-100 text-amber-800'
+                  : 'bg-gray-200 text-gray-600'
+            }`}
+          >
+            {availability === 'available'
+              ? 'Model ready'
+              : availability === 'downloadable'
+                ? 'Model downloadable'
+                : availability === 'downloading'
+                  ? 'Downloading model...'
+                  : 'Unsupported'}
+          </span>
+        )}
+      </div>
+
+      <div className="flex flex-wrap items-center gap-2 mt-1 sm:mt-0">
+        <label className="flex items-center gap-1 text-xs text-gray-700">
+          <span className="sr-only">Source Language</span>
+          <select
+            aria-label="Source language"
+            value={sourceLanguage}
+            onChange={(e) => {
+              setSourceLanguage(e.target.value);
+              setDetectedConfidence(null);
+            }}
+            disabled={isTranslating || apiSupported === false}
+            className="bg-white border border-gray-300 text-gray-800 text-xs rounded px-2 py-1 focus:outline-none focus:ring-2 focus:ring-amber-400 disabled:opacity-60"
+          >
+            {SUPPORTED_LANGUAGES.map((lang) => (
+              <option key={`src-${lang.code}`} value={lang.code}>
+                From: {lang.label}
+              </option>
+            ))}
+          </select>
+        </label>
+
+        <button
+          type="button"
+          onClick={handleSwapLanguages}
+          disabled={isTranslating || apiSupported === false}
+          title="Swap source and target languages"
+          aria-label="Swap source and target languages"
+          className="p-1 rounded border border-gray-300 bg-white text-gray-600 hover:text-amber-700 hover:border-amber-400 disabled:opacity-50"
+        >
+          ⇄
+        </button>
+
+        <label className="flex items-center gap-1 text-xs text-gray-700">
+          <span className="sr-only">Target Language</span>
+          <select
+            aria-label="Target language"
+            value={targetLanguage}
+            onChange={(e) => setTargetLanguage(e.target.value)}
+            disabled={isTranslating || apiSupported === false}
+            className="bg-white border border-gray-300 text-gray-800 text-xs rounded px-2 py-1 focus:outline-none focus:ring-2 focus:ring-amber-400 disabled:opacity-60"
+          >
+            {SUPPORTED_LANGUAGES.map((lang) => (
+              <option key={`tgt-${lang.code}`} value={lang.code}>
+                To: {lang.label}
+              </option>
+            ))}
+          </select>
+        </label>
+
+        {detectorSupported && !compact && (
+          <button
+            type="button"
+            onClick={handleAutoDetect}
+            disabled={isTranslating}
+            className="text-xs px-2 py-1 rounded border border-gray-300 bg-white text-gray-700 hover:bg-gray-50 disabled:opacity-50"
+          >
+            Detect language
+            {detectedConfidence !== null ? ` (${detectedConfidence}%)` : ''}
+          </button>
+        )}
+
+        <button
+          type="button"
+          onClick={handleTranslate}
+          disabled={isTranslating || isUnsupported || sourceLanguage === targetLanguage}
+          className="bg-amber-600 hover:bg-amber-700 text-white text-xs font-semibold px-3 py-1 rounded transition-colors disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer"
+        >
+          {isTranslating
+            ? downloadProgress !== null
+              ? `Downloading (${downloadProgress}%)...`
+              : translationProgress
+                ? `Translating (${translationProgress.completed}/${translationProgress.total})...`
+                : 'Translating...'
+            : availability === 'downloadable'
+              ? 'Download & Translate'
+              : 'Translate'}
+        </button>
+
+        {activeTranslatedLang && (
+          <button
+            type="button"
+            onClick={handleRestore}
+            disabled={isTranslating}
+            className="bg-white border border-gray-300 hover:bg-gray-100 text-gray-700 text-xs font-medium px-2.5 py-1 rounded transition-colors cursor-pointer"
+          >
+            Show Original
+          </button>
+        )}
+      </div>
+
+      {apiSupported === false && (
+        <p className="text-xs text-gray-600 w-full mt-1" role="status">
+          Client-side translation is currently unsupported in this browser (requires Chrome 138+ or Edge 148+ with Built-in AI).
+        </p>
+      )}
+
+      {apiSupported === true && availability === 'unavailable' && (
+        <p className="text-xs text-amber-800 w-full mt-1" role="status">
+          This language pair is currently unavailable for on-device translation on this device.
+        </p>
+      )}
+
+      {errorMessage && (
+        <p className="text-xs text-red-700 w-full mt-1" role="alert">
+          {errorMessage}
+        </p>
+      )}
+    </div>
+  );
+}
