+  return typeof self !== 'undefined' && 'LanguageDetector' in self && Boolean(self.LanguageDetector);
+}
+
+export async function checkLanguagePairAvailability(
+  sourceLanguage: string,
+  targetLanguage: string,
+): Promise<TranslatorAvailability> {
+  if (!isTranslatorApiSupported() || !self.Translator) {
+    return 'unavailable';
+  }
+  if (sourceLanguage === targetLanguage) {
+    return 'available';
+  }
+  try {
+    const options: TranslatorLanguageOptions = { sourceLanguage, targetLanguage };
+    return await self.Translator.availability(options);
+  } catch {
+    return 'unavailable';
+  }
+}
+
+export async function createTranslatorWithMonitor(
+  sourceLanguage: string,
+  targetLanguage: string,
+  onProgress?: (percent: number) => void,
+): Promise<TranslatorInstance> {
+  if (!isTranslatorApiSupported() || !self.Translator) {
+    throw new Error('Client-side Translator API is not supported in this browser.');
+  }
