+
+export async function detectSourceLanguage(
+  sampleText: string,
+  fallbackLanguage = 'en',
+  onProgress?: (percent: number) => void,
+): Promise<{ detectedLanguage: string; confidence: number }> {
+  if (!isLanguageDetectorSupported() || !self.LanguageDetector || sampleText.trim().length < 15) {
+    return { detectedLanguage: fallbackLanguage, confidence: 1 };
+  }
+
+  try {
+    const availability = await self.LanguageDetector.availability();
+    if (availability === 'unavailable') {
+      return { detectedLanguage: fallbackLanguage, confidence: 1 };
+    }
+
+    const detector = await self.LanguageDetector.create({
+      monitor(m) {
+        m.addEventListener('downloadprogress', (e) => {
+          const pct = Math.round((e.loaded || 0) * 100);
+          onProgress?.(pct);
+        });
+      },
+    });
+
+    const results = await detector.detect(sampleText);
+    if (results && results.length > 0 && results[0].detectedLanguage) {
+      return {
+        detectedLanguage: results[0].detectedLanguage,
+        confidence: results[0].confidence,
+      };
+    }
+  } catch {
+    // Graceful fallback to default source language if detection fails
+  }
+
+  return { detectedLanguage: fallbackLanguage, confidence: 1 };
+}
