+      if (blocks.length > 0) {
+        blocks.forEach(addEl);
+        return;
+      }
+    }
+    addEl(el);
+  });
+
+  return elements;
+}
+
+export async function translateElementsInScope(
+  root: ParentNode,
+  translator: TranslatorInstance,
+  targetLanguage: string,
+  onItemProgress?: (completed: number, total: number) => void,
+): Promise<number> {
+  const elements = collectTranslatableElements(root);
+  const total = elements.length;
+  let completed = 0;
+
+  // Apply lang attribute to root container(s) and elements for accessibility
+  if (root instanceof HTMLElement) {
+    if (!originalLangStore.has(root)) {
+      originalLangStore.set(root, root.getAttribute('lang'));
+    }
+    root.setAttribute('lang', targetLanguage);
+  } else {
+    document.querySelectorAll<HTMLElement>('[data-translatable-container]').forEach((container) => {
+      if (!originalLangStore.has(container)) {
+        originalLangStore.set(container, container.getAttribute('lang'));
+      }
+      container.setAttribute('lang', targetLanguage);
+    });
+  }
+
+  for (const el of elements) {
+    if (!originalTextStore.has(el)) {
+      originalTextStore.set(el, el.textContent ?? '');
+    }
+    if (!originalLangStore.has(el)) {
+      originalLangStore.set(el, el.getAttribute('lang'));
+    }
+
+    const sourceText = originalTextStore.get(el) ?? '';
+    if (sourceText.trim().length > 0) {
+      const translated = await translator.translate(sourceText);
+      el.textContent = translated;
+      el.setAttribute('lang', targetLanguage);
+      el.setAttribute('data-translated-lang', targetLanguage);
+    }
