+    completed += 1;
+    onItemProgress?.(completed, total);
+  }
+
+  return completed;
+}
+
+export function restoreElementsInScope(root: ParentNode = document): void {
+  const elements = collectTranslatableElements(root);
+
+  for (const el of elements) {
+    const original = originalTextStore.get(el);
+    if (original !== undefined) {
+      el.textContent = original;
+    }
+    const origLang = originalLangStore.get(el);
+    if (origLang === null || origLang === undefined) {
+      el.removeAttribute('lang');
+    } else {
+      el.setAttribute('lang', origLang);
+    }
+    el.removeAttribute('data-translated-lang');
+  }
+
+  if (root instanceof HTMLElement) {
+    const origLang = originalLangStore.get(root);
+    if (origLang === null || origLang === undefined) {
+      root.removeAttribute('lang');
+    } else {
+      root.setAttribute('lang', origLang);
+    }
+  } else {
