+        return await win.translation.createDetector(opts);
+      },
+    };
+  }
+  return null;
+}
+
+export function collectTranslatableElements(root: ParentNode = document): HTMLElement[] {
+  const elements = new Set<HTMLElement>();
+
+  // 1. Explicit data-translatable elements (headlines, summaries, captions, categories, etc.)
+  root.querySelectorAll<HTMLElement>('[data-translatable]').forEach((el) => {
+    elements.add(el);
+  });
+
+  // 2. Article prose body leaf blocks (paragraphs, headings, list items, blockquotes)
+  root.querySelectorAll<HTMLElement>('.prose p, .prose h1, .prose h2, .prose h3, .prose h4, .prose li, .prose blockquote').forEach((el) => {
+    elements.add(el);
+  });
+
+  return Array.from(elements).filter((el) => {
+    const text = el.innerText?.trim() || el.textContent?.trim();
+    return Boolean(text && text.length > 0);
+  });
+}
+
+interface Props {
+  variant?: 'header' | 'article';
+}
+
+export default function TranslationControl({ variant = 'header' }: Props) {
+  const [targetLang, setTargetLang] = useState<string>('en');
+  const [sourceLang, setSourceLang] = useState<string>('en');
+  const [detectedLang, setDetectedLang] = useState<string | null>(null);
+  const [status, setStatus] = useState<'idle' | 'checking' | 'downloading' | 'translating' | 'translated' | 'error'>('idle');
+  const [availabilityState, setAvailabilityState] = useState<string>('unknown');
+  const [progress, setProgress] = useState<TranslationProgress | null>(null);
+  const [translatedCount, setTranslatedCount] = useState<number>(0);
+  const [totalCount, setTotalCount] = useState<number>(0);
+  const [errorMessage, setErrorMessage] = useState<string | null>(null);
+  const [engineSupported, setEngineSupported] = useState<boolean>(true);
+  const abortControllerRef = useRef<AbortController | null>(null);
+
+  // Sync state across multiple instances (header vs article bar)
+  useEffect(() => {
+    const savedTarget = sessionStorage.getItem('dtt_target_lang');
+    const savedSource = sessionStorage.getItem('dtt_source_lang');
+    if (savedSource) setSourceLang(savedSource);
+    if (savedTarget && savedTarget !== 'en') {
+      setTargetLang(savedTarget);
+    }
+
+    const TranslatorAPI = getTranslatorGlobal();
+    setEngineSupported(Boolean(TranslatorAPI));
+
+    // Try detecting source language from page content if LanguageDetector API is present
+    const detectPageLanguage = async () => {
+      const DetectorAPI = getLanguageDetectorGlobal();
+      if (!DetectorAPI) return;
+      try {
+        const avail = typeof DetectorAPI.availability === 'function' ? await DetectorAPI.availability() : 'available';
+        if (avail === 'unavailable' || avail === 'no') return;
+        const detector = await DetectorAPI.create();
+        const sampleEl = document.querySelector<HTMLElement>('[data-translatable="headline"], .prose p, [data-translatable="title"]');
+        const sampleText = sampleEl?.innerText?.trim();
+        if (sampleText && sampleText.length > 10 && typeof detector.detect === 'function') {
+          const results = await detector.detect(sampleText);
+          if (Array.isArray(results) && results.length > 0 && results[0].detectedLanguage) {
+            setDetectedLang(results[0].detectedLanguage);
+          }
+        }
+      } catch {
+        // Ignore detection errors silently
+      }
+    };
+
+    detectPageLanguage();
+  }, []);
+
+  // Check language pair availability when source/target changes
+  useEffect(() => {
+    const checkAvailability = async () => {
+      if (targetLang === sourceLang) {
+        setAvailabilityState('original');
+        return;
+      }
+      const TranslatorAPI = getTranslatorGlobal();
+      if (!TranslatorAPI) {
+        setEngineSupported(false);
+        setAvailabilityState('unavailable');
+        return;
+      }
+      setEngineSupported(true);
+      try {
+        if (typeof TranslatorAPI.availability === 'function') {
+          const avail = await TranslatorAPI.availability({
+            sourceLanguage: sourceLang,
+            targetLanguage: targetLang,
+          });
+          setAvailabilityState(avail || 'available');
+        } else {
+          setAvailabilityState('available');
+        }
+      } catch {
+        setAvailabilityState('unavailable');
+      }
+    };
+    checkAvailability();
+  }, [sourceLang, targetLang]);
+
+  const restoreOriginalContent = useCallback(() => {
+    if (abortControllerRef.current) {
+      abortControllerRef.current.abort();
+      abortControllerRef.current = null;
+    }
+    const elements = collectTranslatableElements(document);
+    elements.forEach((el) => {
+      const orig = originalTextsMap.get(el) ?? el.getAttribute('data-original-html');
+      if (orig !== null && orig !== undefined) {
+        el.innerHTML = orig;
+        el.removeAttribute('data-translated-lang');
+      }
+    });
+    document.documentElement.lang = 'en';
+    setStatus('idle');
+    setProgress(null);
+    setErrorMessage(null);
+    setTranslatedCount(0);
+  }, []);
+
+  const performTranslation = useCallback(
+    async (srcLang: string, tgtLang: string) => {
+      if (tgtLang === srcLang || tgtLang === 'en') {
+        restoreOriginalContent();
+        return;
+      }
+
+      if (abortControllerRef.current) {
+        abortControllerRef.current.abort();
+      }
+      const controller = new AbortController();
+      abortControllerRef.current = controller;
+
+      setErrorMessage(null);
+      setProgress(null);
+
+      const elements = collectTranslatableElements(document);
+      if (elements.length === 0) {
+        setStatus('idle');
+        return;
+      }
+
+      // Snapshot original HTML before modifying
+      elements.forEach((el) => {
+        if (!originalTextsMap.has(el)) {
+          originalTextsMap.set(el, el.innerHTML);
+        }
+        if (!el.hasAttribute('data-original-html')) {
+          el.setAttribute('data-original-html', el.innerHTML);
+        }
+      });
+
+      setTotalCount(elements.length);
+      setTranslatedCount(0);
+
+      const TranslatorAPI = getTranslatorGlobal();
+      if (!TranslatorAPI) {
+        setEngineSupported(false);
+        setStatus('error');
+        setErrorMessage(
+          'On-device Translator API (window.Translator) is not available in this browser. Enable Chrome Built-in AI Translation API to translate articles on-device.'
+        );
+        return;
+      }
+
+      try {
+        setStatus('checking');
+        let avail = 'available';
+        if (typeof TranslatorAPI.availability === 'function') {
+          avail = await TranslatorAPI.availability({
+            sourceLanguage: srcLang,
+            targetLanguage: tgtLang,
+          });
+          setAvailabilityState(avail);
+        }
+
+        if (avail === 'unavailable' || avail === 'no') {
+          setStatus('error');
+          setErrorMessage(`On-device translation model for ${srcLang.toUpperCase()} → ${tgtLang.toUpperCase()} is unavailable.`);
+          return;
+        }
+
+        if (avail === 'downloadable' || avail === 'downloading' || avail === 'after-download') {
+          setStatus('downloading');
+        } else {
+          setStatus('translating');
+        }
+
+        const translator = await TranslatorAPI.create({
+          sourceLanguage: srcLang,
+          targetLanguage: tgtLang,
+          signal: controller.signal,
+          monitor(m: any) {
+            if (m && typeof m.addEventListener === 'function') {
+              m.addEventListener('downloadprogress', (e: any) => {
+                setStatus('downloading');
+                setProgress({
+                  loaded: typeof e.loaded === 'number' ? e.loaded : 0,
+                  total: typeof e.total === 'number' && e.total > 0 ? e.total : 1,
+                });
+              });
+            }
+          },
+        });
+
+        if (controller.signal.aborted) return;
+
+        setStatus('translating');
+        setProgress(null);
+
+        let completed = 0;
+        for (const el of elements) {
+          if (controller.signal.aborted) return;
+
+          // Get clean original text to translate
+          const origHtml = originalTextsMap.get(el) ?? el.getAttribute('data-original-html') ?? el.innerHTML;
+          const tempDiv = document.createElement('div');
+          tempDiv.innerHTML = origHtml;
+          const rawText = (tempDiv.textContent || tempDiv.innerText || '').trim();
+
+          if (!rawText) {
+            completed++;
+            setTranslatedCount(completed);
+            continue;
+          }
+
+          const cacheKey = `${srcLang}:${tgtLang}:${rawText}`;
+          let translatedText = memoryCache.get(cacheKey);
+
+          if (!translatedText) {
+            if (typeof translator.translate === 'function') {
+              translatedText = await translator.translate(rawText, { signal: controller.signal });
+            } else if (typeof translator.translateStreaming === 'function') {
+              const stream = translator.translateStreaming(rawText, { signal: controller.signal });
+              let chunks = '';
+              for await (const chunk of stream) {
+                chunks = chunk;
+                el.textContent = chunks;
+              }
+              translatedText = chunks;
+            }
+            if (translatedText) {
+              memoryCache.set(cacheKey, translatedText);
+            }
+          }
+
+          if (controller.signal.aborted) return;
+
+          if (translatedText) {
+            el.textContent = translatedText;
+            el.setAttribute('data-translated-lang', tgtLang);
+          }
+
+          completed++;
+          setTranslatedCount(completed);
+        }
+
+        document.documentElement.lang = tgtLang;
+        setStatus('translated');
+        setAvailabilityState('available');
+
+        if (typeof translator.destroy === 'function') {
+          translator.destroy();
+        }
+      } catch (err: any) {
+        if (err?.name === 'AbortError') return;
+        setStatus('error');
+        setErrorMessage(err?.message || 'Failed to translate page content with on-device model.');
+      }
+    },
+    [restoreOriginalContent]
+  );
+
+  // Listen to global language synchronization events between Header & Article controls and Astro page transitions
+  useEffect(() => {
+    const handleSyncEvent = (e: Event) => {
+      const detail = (e as CustomEvent).detail;
+      if (!detail) return;
+      const { source, target, triggerTranslate } = detail;
+      if (source) setSourceLang(source);
+      if (target) setTargetLang(target);
+      if (triggerTranslate) {
+        performTranslation(source || sourceLang, target);
+      }
+    };
+
+    const handlePageLoad = () => {
+      const savedTarget = sessionStorage.getItem('dtt_target_lang') || 'en';
+      const savedSource = sessionStorage.getItem('dtt_source_lang') || 'en';
+      setSourceLang(savedSource);
+      setTargetLang(savedTarget);
+      if (savedTarget !== 'en' && variant === 'header') {
+        performTranslation(savedSource, savedTarget);
+      }
+    };
+
+    window.addEventListener('dtt:translate-sync', handleSyncEvent);
+    document.addEventListener('astro:page-load', handlePageLoad);
+    return () => {
+      window.removeEventListener('dtt:translate-sync', handleSyncEvent);
+      document.removeEventListener('astro:page-load', handlePageLoad);
+    };
+  }, [performTranslation, sourceLang, variant]);
+
+  const handleLanguageSelect = (newTarget: string) => {
+    setTargetLang(newTarget);
+    sessionStorage.setItem('dtt_target_lang', newTarget);
+    sessionStorage.setItem('dtt_source_lang', sourceLang);
+
+    // Notify other TranslationControl instances on the page
+    window.dispatchEvent(
+      new CustomEvent('dtt:translate-sync', {
+        detail: { source: sourceLang, target: newTarget, triggerTranslate: false },
+      })
+    );
+
+    performTranslation(sourceLang, newTarget);
+  };
+
+  const handleReset = () => {
+    handleLanguageSelect('en');
+  };
+
+  if (variant === 'article') {
+    return (
+      <div
+        className="my-4 p-3.5 bg-amber-50/70 border border-amber-200 rounded-lg flex flex-wrap items-center justify-between gap-3 text-sm"
+        data-translation-control="article"
+      >
+        <div className="flex items-center space-x-2.5">
+          <span className="inline-flex items-center justify-center w-8 h-8 rounded-full bg-amber-400/20 text-amber-900 font-semibold">
+            <svg xmlns="http://www.w3.org/2000/svg" className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
+              <path strokeLinecap="round" strokeLinejoin="round" d="m10.5 21 5.25-11.25L21 21m-9-3h7.5M3 5.621a48.474 48.474 0 0 1 6-.371m0 0c1.12 0 2.233.038 3.334.114M9 5.25V3m3.334 2.364C11.176 10.658 7.69 15.08 3 17.502m9.334-12.138c.896.061 1.785.147 2.666.257m-4.589 8.495a18.023 18.023 0 0 1-3.827-5.802" />
+            </svg>
+          </span>
+          <div>
+            <div className="font-semibold text-gray-900 flex items-center gap-2">
+              <span>On-Device Article Translation</span>
+              <span className="text-[11px] uppercase tracking-wider px-2 py-0.5 rounded-full bg-amber-200/70 text-amber-900 font-bold">
+                Browser AI
+              </span>
+            </div>
+            <p className="text-xs text-gray-600">
+              Translate this article and related teasers privately in your browser{detectedLang ? ` (Detected: ${detectedLang.toUpperCase()})` : ''}.
+            </p>
+          </div>
+        </div>
+
+        <div className="flex flex-wrap items-center gap-2">
+          <label htmlFor="article-translate-select" className="sr-only">
+            Target language
+          </label>
+          <select
+            id="article-translate-select"
+            aria-label="Translate article to language"
+            value={targetLang}
+            onChange={(e) => handleLanguageSelect(e.target.value)}
+            disabled={status === 'downloading' || status === 'translating'}
+            className="bg-white border border-gray-300 text-gray-800 text-xs font-medium rounded-md px-2.5 py-1.5 focus:outline-none focus:ring-2 focus:ring-amber-400"
+          >
+            {SUPPORTED_LANGUAGES.map((lang) => (
+              <option key={lang.code} value={lang.code}>
+                {lang.flag} {lang.label}
+              </option>
+            ))}
+          </select>
+
+          {targetLang !== 'en' && status !== 'translating' && status !== 'downloading' && (
+            <button
+              type="button"
+              onClick={() => performTranslation(sourceLang, targetLang)}
+              className="bg-amber-500 hover:bg-amber-600 text-white text-xs font-semibold px-3 py-1.5 rounded-md transition-colors cursor-pointer"
+            >
+              Translate
+            </button>
+          )}
+
+          {targetLang !== 'en' && (
+            <button
+              type="button"
+              onClick={handleReset}
+              className="text-xs text-gray-700 hover:text-gray-900 underline px-2 py-1 cursor-pointer"
+            >
+              Show Original
+            </button>
+          )}
+        </div>
+
+        {(status !== 'idle' || errorMessage) && (
+          <div className="w-full pt-2 border-t border-amber-200/60 flex items-center justify-between text-xs">
+            {status === 'checking' && <span className="text-amber-800">Checking on-device language model availability...</span>}
+            {status === 'downloading' && (
+              <div className="flex items-center gap-2 w-full">
+                <span className="text-amber-800 font-medium whitespace-nowrap">
+                  Downloading on-device language pack...
+                </span>
+                <div className="w-full bg-amber-200 rounded-full h-1.5 overflow-hidden">
+                  <div
+                    className="bg-amber-600 h-1.5 transition-all duration-200"
+                    style={{
+                      width: `${progress ? Math.min(100, Math.round((progress.loaded / progress.total) * 100)) : 30}%`,
+                    }}
+                  />
+                </div>
+              </div>
+            )}
+            {status === 'translating' && (
+              <span className="text-amber-900 font-medium">
+                Translating on-device ({translatedCount}/{totalCount} segments)...
+              </span>
+            )}
+            {status === 'translated' && (
+              <span className="text-green-800 font-medium">
+                ✓ Translated to {SUPPORTED_LANGUAGES.find((l) => l.code === targetLang)?.label || targetLang.toUpperCase()} on-device ({translatedCount} segments)
+              </span>
+            )}
+            {status === 'error' && errorMessage && (
+              <span className="text-red-700 font-medium" role="alert">
+                {errorMessage}
+              </span>
+            )}
+          </div>
+        )}
+      </div>
+    );
+  }
+
+  // Header compact control
+  return (
+    <div className="inline-flex items-center space-x-1.5 relative" data-translation-control="header">
+      <div className="flex items-center bg-gray-100 hover:bg-gray-200/80 border border-gray-300 rounded px-2 py-1 transition-colors">
+        <svg
+          xmlns="http://www.w3.org/2000/svg"
+          className="w-4 h-4 text-gray-700 mr-1.5 flex-shrink-0"
+          fill="none"
+          viewBox="0 0 24 24"
+          stroke="currentColor"
+          strokeWidth={2}
+          aria-hidden="true"
+        >
+          <path
+            strokeLinecap="round"
+            strokeLinejoin="round"
+            d="m10.5 21 5.25-11.25L21 21m-9-3h7.5M3 5.621a48.474 48.474 0 0 1 6-.371m0 0c1.12 0 2.233.038 3.334.114M9 5.25V3m3.334 2.364C11.176 10.658 7.69 15.08 3 17.502m9.334-12.138c.896.061 1.785.147 2.666.257m-4.589 8.495a18.023 18.023 0 0 1-3.827-5.802"
+          />
+        </svg>
+        <label htmlFor="header-translate-select" className="sr-only">
+          Translate articles and teasers
+        </label>
+        <select
+          id="header-translate-select"
+          aria-label="Translate articles and teasers"
+          value={targetLang}
+          onChange={(e) => handleLanguageSelect(e.target.value)}
+          disabled={status === 'downloading' || status === 'translating'}
+          className="bg-transparent text-xs font-semibold text-gray-800 focus:outline-none cursor-pointer pr-1"
+          title="On-device article & teaser translation"
+        >
+          {SUPPORTED_LANGUAGES.map((lang) => (
+            <option key={lang.code} value={lang.code}>
+              {lang.flag} {lang.label}
+            </option>
+          ))}
+        </select>
+
+        {status === 'downloading' || status === 'translating' || status === 'checking' ? (
+          <span
+            className="ml-1.5 inline-block w-3.5 h-3.5 border-2 border-amber-500 border-t-transparent rounded-full animate-spin"
+            title={
+              status === 'downloading'
+                ? 'Downloading language pack...'
+                : `Translating (${translatedCount}/${totalCount})...`
+            }
+          />
+        ) : status === 'translated' && targetLang !== 'en' ? (
+          <button
+            type="button"
+            onClick={handleReset}
+            title="Restore original language"
+            aria-label="Restore original language"
+            className="ml-1.5 text-[10px] bg-amber-400/30 hover:bg-amber-400/50 text-amber-950 font-bold px-1.5 py-0.5 rounded cursor-pointer"
+          >
+            Reset
+          </button>
+        ) : null}
+      </div>
+
+      {status === 'error' && errorMessage && (
+        <span
+          className="text-[11px] text-red-600 font-medium max-w-[220px] truncate"
+          title={errorMessage}
+          role="status"
+        >
+          {!engineSupported ? 'Translator API unavailable' : 'Translation failed'}
+        </span>
+      )}
+    </div>
+  );
+}
