+  --teaser-btn-hover-bg: #f3f4f6;
+  --teaser-btn-hover-border: #9ca3af;
+}
+
+/* Featured (prominent) section semantic context */
+.section-featured,
+[data-context="featured"],
+[data-section-context="featured"],
+[data-variant="featured"],
