+    classifyLink,
+    validateReturnToUrl,
+    createSandboxOriginValidator,
+    handleSandboxedWidgetMessage,
+    resetSandboxOriginPin,
+    checkSameOriginWithFallback,
+    checkSameSiteWithFallback,
+  });
+}
+
+function initDailyGrindSecurity() {
+  if (typeof document === 'undefined') return;
+
+  const orderStatusEl = document.getElementById('order-message-status');
+  const redirectStatusEl = document.getElementById('redirect-validation-status');
+  const widgetIframe = document.getElementById('loyalty-sandbox-widget');
+  const widgetStatusEl = document.getElementById('sandbox-widget-status');
+
+  // 1. Annotate and classify all links on the page (same-site vs. external)
+  const links = document.querySelectorAll('a[href]');
+  links.forEach((anchor) => {
+    const classification = classifyLink(anchor);
+    anchor.dataset.linkSite = classification;
+    if (classification === 'external') {
+      anchor.setAttribute('rel', 'noopener noreferrer');
+      anchor.setAttribute('target', '_blank');
+    }
+  });
+
+  // 2. Validate same-site redirect URL (?returnTo=...) on load and via interactive form
+  const params = new URLSearchParams(window.location.search);
+  const returnToParam = params.get('returnTo');
+  if (returnToParam !== null && redirectStatusEl) {
+    const safeRedirect = validateReturnToUrl(returnToParam);
+    if (safeRedirect) {
+      redirectStatusEl.textContent = `Verified same-site redirect: ${safeRedirect}`;
+      redirectStatusEl.dataset.valid = 'true';
+    } else {
+      redirectStatusEl.textContent = 'Blocked untrusted or cross-site redirect URL.';
+      redirectStatusEl.dataset.valid = 'false';
+    }
+  }
+
+  const redirectForm = document.getElementById('redirect-check-form');
+  const redirectInput = document.getElementById('redirect-url-input');
+  if (redirectForm && redirectInput && redirectStatusEl) {
+    redirectForm.addEventListener('submit', (e) => {
+      e.preventDefault();
+      const candidate = redirectInput.value.trim();
+      const safeRedirect = validateReturnToUrl(candidate);
+      if (safeRedirect) {
+        redirectStatusEl.textContent = `Allowed same-site redirect: ${safeRedirect}`;
+        redirectStatusEl.dataset.valid = 'true';
+      } else {
+        redirectStatusEl.textContent = `Rejected unsafe or cross-site URL: ${candidate}`;
+        redirectStatusEl.dataset.valid = 'false';
+      }
+    });
+  }
+
+  // 3. Listen for cross-window messages from trusted ordering origin or pinned sandboxed widget
+  window.addEventListener('message', (event) => {
+    // Check if message is from the trusted ordering origin
+    if (isTrustedOrderingOrigin(event)) {
+      if (orderStatusEl) {
+        const item =
+          typeof event.data === 'object' && event.data !== null && typeof event.data.item === 'string'
+            ? event.data.item
+            : 'Order update received';
+        orderStatusEl.textContent = `Verified ordering message: ${item}`;
+        orderStatusEl.dataset.verifiedOrigin = 'true';
+      }
+      return;
+    }
+
+    // Check if message is from the pinned sandboxed widget
+    const expectedWindow = widgetIframe ? widgetIframe.contentWindow : null;
+    if (expectedWindow && handleSandboxedWidgetMessage(event, expectedWindow)) {
+      if (widgetStatusEl) {
+        const msgType =
+          typeof event.data === 'object' && event.data !== null && typeof event.data.type === 'string'
+            ? event.data.type
+            : 'message';
+        const points =
+          typeof event.data === 'object' && event.data !== null && typeof event.data.points === 'number'
+            ? ` (${event.data.points} pts)`
+            : '';
+        widgetStatusEl.textContent = `Accepted widget ${msgType}${points} from pinned sandboxed origin.`;
+        widgetStatusEl.dataset.pinned = 'true';
+      }
+      return;
+    }
+
+    // Reject untrusted origins or unpinned sandboxed iframes
+    if (event.data && typeof event.data === 'object' && event.data.source === 'sandbox-widget') {
