+        widgetStatusEl.dataset.pinned = 'false';
+      }
+    } else if (orderStatusEl) {
+      orderStatusEl.textContent = 'Rejected message from untrusted origin.';
+      orderStatusEl.dataset.verifiedOrigin = 'false';
+    }
+  });
+}
