+  if (contentType.includes('application/json')) {
+    try {
+      return JSON.parse(bodyText);
+    } catch {
+      return {};
+    }
+  }
+  const params = new URLSearchParams(bodyText);
+  return Object.fromEntries(params.entries());
+}
+
+async function handleSignupSubmission(req, res) {
+  const bodyText = await readRequestBody(req);
+  const contentType = req.headers['content-type'] || '';
+  const fields = parseSubmittedFields(contentType, bodyText);
+
+  const fullName = String(fields['full-name'] || fields.name || '').trim();
+  const submittedEmail = String(fields.email || '').trim();
+  const rawToken = String(fields.token || '').trim();
+
+  // Atomically read and delete the single-use nonce from server-side session state
+  const expectedNonce = consumeSessionNonce(req);
+  // Fresh session + nonce for any subsequent form render
+  const { sessionId, nonce: nextNonce } = getOrCreateSession(req);
+  const expectedAudience = getRpOrigin(req);
+
+  let verifiedViaEvp = false;
+
+  if (rawToken && expectedNonce) {
+    try {
+      await verifyEmailVerificationToken({
+        rawToken,
+        submittedEmail,
+        expectedNonce,
+        expectedAudience,
+      });
+      // Fast path: email ownership is cryptographically verified; skip OTP email.
+      verifiedViaEvp = true;
+    } catch (err) {
+      // Log token verification failures before falling back to standard email verification.
+      console.error('Email verification token check failed:', err);
+    }
+  }
+
+  const responsePayload = verifiedViaEvp
+    ? {
+        ok: true,
+        status: 'verified',
+        verificationMethod: 'evp',
+        email: submittedEmail,
+        name: fullName,
+        nextNonce,
+        message: `Welcome to Daily Grind Rewards! Your email (${submittedEmail}) was confirmed directly by your browser—your account is active with 50 bonus stars.`,
+      }
+    : {
+        ok: true,
+        status: 'pending_verification',
+        verificationMethod: 'email_fallback',
+        email: submittedEmail,
+        name: fullName,
+        nextNonce,
+        message: `Almost there! We sent a traditional verification code to ${submittedEmail} to finish activating your Daily Grind Rewards account.`,
+      };
+
+  const acceptsJson = (req.headers.accept || '').includes('application/json');
+  res.setHeader(
+    'Set-Cookie',
+    `dg_session=${encodeURIComponent(sessionId)}; HttpOnly; Secure; SameSite=Lax; Path=/`
+  );
+  res.setHeader('Cache-Control', 'no-store');
+
+  if (acceptsJson || contentType.includes('application/json')) {
+    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+    res.end(JSON.stringify(responsePayload));
+    return;
+  }
+
+  // Standard HTML form fallback response
+  const htmlTemplate = await fs.readFile(path.join(__dirname, 'index.html'), 'utf-8');
+  const rendered = htmlTemplate
+    .replaceAll('SERVER_GENERATED_PER_FORM_NONCE', nextNonce)
+    .replace(
+      '<!-- SERVER_SIGNUP_STATUS -->',
+      `<div class="signup-banner" role="status">${responsePayload.message}</div>`
+    );
