new file mode 100644
index 0000000..4b5d7f0
--- /dev/null
+++ b/server.js
@@ -0,0 +1,224 @@
+import { randomBytes } from "node:crypto";
+import { readFileSync } from "node:fs";
+import { dirname, join } from "node:path";
+import { fileURLToPath, pathToFileURL } from "node:url";
+import express from "express";
+import { verifyEmailToken, verifyEmailVerificationToken } from "./verify.js";
+
+const __dirname = dirname(fileURLToPath(import.meta.url));
+const INDEX_HTML_PATH = join(__dirname, "index.html");
+
+export const DEFAULT_STATIC_NONCE = "d8f4a9b2c1e763059a4b8c2d1e0f7a6b";
+
+// In-memory stores for session nonces and registered rewards accounts
+export const sessions = new Map();
+export const validNonces = new Map([
+  [DEFAULT_STATIC_NONCE, { renderedAt: Date.now() - 60_000 }],
+]);
+export const accounts = new Map();
+
+function parseCookies(cookieHeader = "") {
+  const cookies = {};
+  for (const pair of cookieHeader.split(";")) {
+    const idx = pair.indexOf("=");
+    if (idx > 0) {
+      const key = pair.slice(0, idx).trim();
+      const val = pair.slice(idx + 1).trim();
+      cookies[key] = decodeURIComponent(val);
+    }
+  }
+  return cookies;
+}
+
+export function createSessionNonce() {
+  const sessionId = randomBytes(16).toString("hex");
+  const nonce = randomBytes(16).toString("base64url");
+  const renderedAt = Date.now();
+  const sessionData = { sessionId, nonce, renderedAt };
+  sessions.set(sessionId, sessionData);
+  validNonces.set(nonce, { sessionId, renderedAt });
+  return sessionData;
+}
+
+export const app = express();
+
+app.use(express.json());
+app.use(express.urlencoded({ extended: true }));
+
+// Serve homepage with a fresh session-bound cryptographic nonce injected into the form
+function serveHomepage(req, res) {
+  const { sessionId, nonce } = createSessionNonce();
+  res.setHeader(
+    "Set-Cookie",
+    `dg_session=${encodeURIComponent(sessionId)}; Path=/; HttpOnly; SameSite=Lax`
+  );
+
+  const rawHtml = readFileSync(INDEX_HTML_PATH, "utf8");
+  const renderedHtml = rawHtml.replaceAll(DEFAULT_STATIC_NONCE, nonce);
+  res.type("html").send(renderedHtml);
+}
+
+app.get("/", serveHomepage);
+app.get("/index.html", serveHomepage);
+
+// Endpoint to retrieve or refresh a session-bound nonce via JSON
+app.get(["/api/nonce", "/nonce"], (req, res) => {
+  const { sessionId, nonce, renderedAt } = createSessionNonce();
+  res.setHeader(
+    "Set-Cookie",
+    `dg_session=${encodeURIComponent(sessionId)}; Path=/; HttpOnly; SameSite=Lax`
+  );
+  res.status(200).json({ nonce, renderedAt });
+});
+
+// Server verification & rewards account registration handler
+async function handleVerifyAndRegister(req, res) {
+  const body = req.body ?? {};
+  const submittedEmail =
+    body.email ?? body["email-address"] ?? body.emailAddress ?? "";
+  const rawToken =
+    body.token ??
+    body["email-verification-token"] ??
+    body.evt ??
+    body.presentationToken ??
+    body.vp_token ??
+    "";
+  const customerName =
+    body.name ?? body["full-name"] ?? body.fullName ?? "Coffee Lover";
+
+  const cookies = parseCookies(req.headers.cookie);
+  const sessionData = cookies.dg_session ? sessions.get(cookies.dg_session) : undefined;
+
+  const host = req.get("host");
+  const expectedAudiences = new Set();
+  if (process.env.RP_ORIGIN) expectedAudiences.add(process.env.RP_ORIGIN);
+  if (req.headers.origin) expectedAudiences.add(req.headers.origin);
+  if (host) {
+    expectedAudiences.add(`${req.protocol}://${host}`);
+    expectedAudiences.add(`https://${host}`);
+    expectedAudiences.add(`http://${host}`);
+  }
+
+  const verificationResult = await verifyEmailVerificationToken(
+    rawToken,
+    submittedEmail,
+    {
+      nonce: sessionData?.nonce,
+      renderedAt: sessionData?.renderedAt,
+      validNonces,
+      expectedAudience: Array.from(expectedAudiences),
+    }
+  );
+
+  const prefersHtml =
+    req.accepts(["json", "html"]) === "html" &&
+    !req.is("application/json");
+
+  if (!verificationResult.verified) {
+    if (prefersHtml) {
+      return res
+        .status(400)
+        .type("html")
+        .send(`<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <title>Verification Failed | The Daily Grind</title>
+</head>
+<body style="font-family: sans-serif; padding: 2rem; color: #3e2723; background: #fafafa;">
+  <h1>Email Confirmation Could Not Be Completed</h1>
+  <p>${verificationResult.error || "Unable to verify browser email token."}</p>
+  <p><a href="/">Return to The Daily Grind Homepage</a></p>
+</body>
+</html>`);
+    }
+
+    return res.status(400).json({
+      ok: false,
+      verified: false,
+      error: verificationResult.error,
+    });
+  }
+
+  // Consume one-time session nonce to prevent replay attacks
+  const usedNonce = verificationResult.kbJwtDecodedPayload?.nonce;
+  if (usedNonce && usedNonce !== DEFAULT_STATIC_NONCE) {
+    validNonces.delete(usedNonce);
+  }
+  if (sessionData?.sessionId) {
+    sessions.delete(sessionData.sessionId);
+  }
+
+  const normalizedEmail = verificationResult.email.toLowerCase();
+  const account = {
+    name: String(customerName).trim() || "Coffee Lover",
+    email: verificationResult.email,
+    emailVerified: true,
+    verificationMethod: "browser-evp",
+    issuer: verificationResult.issuer,
+    points: 100,
+    createdAt: new Date().toISOString(),
+  };
+  accounts.set(normalizedEmail, account);
+
+  if (prefersHtml) {
+    return res
+      .status(200)
+      .type("html")
+      .send(`<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <title>Rewards Account Confirmed | The Daily Grind</title>
+</head>
+<body style="font-family: sans-serif; padding: 2rem; color: #3e2723; background: #fafafa;">
+  <h1>Welcome to Daily Grind Rewards!</h1>
+  <p>Your email address <strong>${account.email}</strong> was cryptographically confirmed by your browser (${account.issuer}) with no OTP or magic link required.</p>
+  <p>Welcome Bonus: <strong>${account.points} Beans</strong> added to your account.</p>
+  <p><a href="/">Back to Homepage</a></p>
+</body>
+</html>`);
+  }
+
+  return res.status(200).json({
+    ok: true,
+    verified: true,
+    email: verificationResult.email,
+    email_verified: true,
+    issuer: verificationResult.issuer,
+    evtJwtDecodedPayload: verificationResult.evtJwtDecodedPayload,
+    kbJwtDecodedPayload: verificationResult.kbJwtDecodedPayload,
+    account,
+    message:
+      "Email address confirmed directly via browser Email Verification Protocol without OTP or magic link.",
+  });
+}
+
+app.post(
+  [
+    "/api/verify-email",
+    "/verify-email",
+    "/api/register",
+    "/register",
+    "/api/signup",
+    "/signup",
+    "/rewards/signup",
+    "/api/rewards/signup",
+  ],
+  handleVerifyAndRegister
+);
+
+app.use(express.static(__dirname));
+
+export { verifyEmailToken, verifyEmailVerificationToken };
+
+const isMain =
+  process.argv[1] &&
+  import.meta.url === pathToFileURL(process.argv[1]).href;
+
+if (isMain) {
+  const port = Number(process.env.PORT) || 11222;
+  app.listen(port, () => {
+    console.log(`The Daily Grind server listening on http://localhost:${port}`);
+  });
+}
diff --git a/verify.js b/verify.js
new file mode 100644
index 0000000..3678eec
--- /dev/null
+++ b/verify.js
@@ -0,0 +1,322 @@
+import { createHash } from "node:crypto";
+import { resolveTxt as dnsResolveTxt } from "node:dns/promises";
+import {
+  createLocalJWKSet,
+  createRemoteJWKSet,
+  decodeJwt,
+  decodeProtectedHeader,
+  importJWK,
+  jwtVerify,
+} from "jose";
+
+/**
+ * Verifies an Email Verification Protocol (EVP) SD-JWT+KB token (<EVT>~<KB-JWT>)
+ * submitted by the browser via autocomplete="email-verification-token" or the
+ * emailverified event without sending a one-time passcode or magic link email.
+ *
+ * Implements the 5-step verification pipeline:
+ * 1. Parse the SD-JWT+KB token and validate JOSE protected headers (evt+jwt & kb+jwt)
+ * 2. Validate expected payload claims (email_verified, email, nonce, aud, iat/exp)
+ * 3. Validate Key Binding (sd_hash SHA-256 base64url digest & cnf.jwk signature)
+ * 4. Verify DNS TXT record delegation (_email-verification.<domain> -> iss=...)
+ * 5. Discover the issuer (/.well-known/email-verification) and verify the EVT signature via JWKS
+ *
+ * @param {string} rawToken - Raw token string (<evtJwt>~<kbJwt>)
+ * @param {string} submittedEmail - Email address submitted in the registration form
+ * @param {Object} [session] - Session and verification options
+ * @param {string} [session.nonce] - Expected cryptographic nonce bound to the form session
+ * @param {Set<string>|Map<string, any>} [session.validNonces] - Optional collection of issued nonces
+ * @param {string|string[]} [session.expectedAudience] - Expected Relying Party origin(s) (aud)
+ * @param {number} [session.renderedAt] - Timestamp (ms) when the form/nonce was rendered
+ * @param {Function} [session.resolveTxt] - Optional DNS TXT resolver override
+ * @param {Function} [session.fetchImpl] - Optional fetch implementation override
+ * @returns {Promise<{
+ *   verified: boolean,
+ *   email?: string,
+ *   issuer?: string,
+ *   evtJwtDecodedPayload?: Object,
+ *   kbJwtDecodedPayload?: Object,
+ *   error?: string
+ * }>}
+ */
+export async function verifyEmailVerificationToken(rawToken, submittedEmail, session = {}) {
+  try {
+    if (!rawToken || typeof rawToken !== "string") {
+      return { verified: false, error: "Missing or invalid email verification token." };
+    }
+    if (!submittedEmail || typeof submittedEmail !== "string" || !submittedEmail.includes("@")) {
+      return { verified: false, error: "Missing or invalid email address." };
+    }
+
+    // -------------------------------------------------------------------------
+    // STEP 1: Parse the SD-JWT+KB token (<evtJwt>~<kbJwt>)
+    // -------------------------------------------------------------------------
+    const parts = rawToken.trim().split("~");
+    if (parts.length < 2) {
+      return { verified: false, error: "Malformed SD-JWT+KB token: missing '~' separator." };
+    }
+
+    const evtJwt = parts[0];
+    const kbJwt = parts[parts.length - 1];
+    const middleDisclosures = parts.slice(1, -1).filter(Boolean);
+    if (!evtJwt || !kbJwt || middleDisclosures.length > 0) {
+      return { verified: false, error: "Invalid SD-JWT+KB token structure." };
+    }
+
+    const evtHeader = decodeProtectedHeader(evtJwt);
+    const kbHeader = decodeProtectedHeader(kbJwt);
+
+    if (evtHeader.typ !== "evt+jwt") {
+      return {
+        verified: false,
+        error: `Invalid EVT header typ: expected "evt+jwt", got "${evtHeader.typ}".`,
+      };
+    }
+    if (kbHeader.typ !== "kb+jwt") {
+      return {
+        verified: false,
+        error: `Invalid KB-JWT header typ: expected "kb+jwt", got "${kbHeader.typ}".`,
+      };
+    }
+
+    const evtClaims = decodeJwt(evtJwt);
+    const kbClaims = decodeJwt(kbJwt);
+
+    // -------------------------------------------------------------------------
+    // STEP 2: Validate expected values & constraints
+    // -------------------------------------------------------------------------
+    if (evtClaims.email_verified !== true) {
+      return {
+        verified: false,
+        error: "Email is not marked as verified (email_verified !== true) in EVT.",
+      };
+    }
+
+    const normalizedSubmittedEmail = submittedEmail.trim().toLowerCase();
+    const normalizedTokenEmail = String(evtClaims.email || "").trim().toLowerCase();
+    if (!normalizedTokenEmail || normalizedTokenEmail !== normalizedSubmittedEmail) {
+      return {
+        verified: false,
+        error: "Email claim in EVT does not match the submitted email address.",
+      };
+    }
+
+    // Validate session nonce
+    const tokenNonce = kbClaims.nonce;
+    if (!tokenNonce || typeof tokenNonce !== "string") {
+      return { verified: false, error: "Missing nonce claim in Key-Binding JWT." };
+    }
+
+    let nonceValid = false;
+    let renderedAt = session?.renderedAt;
+
+    if (session?.nonce && tokenNonce === session.nonce) {
+      nonceValid = true;
+    } else if (session?.validNonces instanceof Map && session.validNonces.has(tokenNonce)) {
+      nonceValid = true;
+      const entry = session.validNonces.get(tokenNonce);
+      if (entry && typeof entry.renderedAt === "number" && !renderedAt) {
+        renderedAt = entry.renderedAt;
+      }
+    } else if (session?.validNonces instanceof Set && session.validNonces.has(tokenNonce)) {
+      nonceValid = true;
+    }
+
+    if (!nonceValid) {
+      return { verified: false, error: "Invalid or expired session nonce in Key-Binding JWT." };
+    }
+
+    // Validate audience (aud)
+    if (!kbClaims.aud || typeof kbClaims.aud !== "string") {
+      return { verified: false, error: "Missing aud claim in Key-Binding JWT." };
+    }
+
+    const expectedAudiences = Array.isArray(session?.expectedAudience)
+      ? session.expectedAudience.filter(Boolean)
+      : session?.expectedAudience
+        ? [session.expectedAudience]
+        : session?.aud
+          ? [session.aud]
+          : [];
+
+    if (expectedAudiences.length > 0) {
+      const normalizeOrigin = (u) => String(u).replace(/\/+$/, "").toLowerCase();
+      const actualAud = normalizeOrigin(kbClaims.aud);
+      const matchesAud = expectedAudiences.some((exp) => normalizeOrigin(exp) === actualAud);
+      if (!matchesAud) {
+        return { verified: false, error: `Audience mismatch in KB-JWT: got "${kbClaims.aud}".` };
+      }
+    }
+
+    // Validate timestamps (iat / exp)
+    if (typeof kbClaims.iat === "number" && renderedAt) {
+      if (kbClaims.iat < Math.floor(renderedAt / 1000)) {
+        return {
+          verified: false,
+          error: "KB-JWT was issued before the form session was rendered.",
+        };
+      }
+    }
+
+    const nowSec = Math.floor(Date.now() / 1000);
+    if (typeof evtClaims.exp === "number" && evtClaims.exp <= nowSec) {
+      return { verified: false, error: "EVT token has expired." };
+    }
+
+    // -------------------------------------------------------------------------
+    // STEP 3: Validate Key Binding (sd_hash & holder cnf.jwk signature)
+    // -------------------------------------------------------------------------
+    const expectedSdHash = createHash("sha256")
+      .update(`${evtJwt}~`)
+      .digest("base64url");
+
+    if (!kbClaims.sd_hash || kbClaims.sd_hash !== expectedSdHash) {
+      return { verified: false, error: "sd_hash mismatch between EVT and Key-Binding JWT." };
+    }
+
+    const holderJwk = evtClaims.cnf?.jwk;
+    if (!holderJwk || typeof holderJwk !== "object") {
+      return { verified: false, error: "Missing holder public key (cnf.jwk) in EVT payload." };
+    }
+
+    const holderKey = await importJWK(holderJwk, kbHeader.alg);
+    await jwtVerify(kbJwt, holderKey, {
+      typ: "kb+jwt",
+      ...(expectedAudiences.length > 0 ? { audience: expectedAudiences } : {}),
+    });
+
+    // -------------------------------------------------------------------------
+    // STEP 4: Verify DNS TXT record delegation (_email-verification.<domain>)
+    // -------------------------------------------------------------------------
+    const domain = normalizedSubmittedEmail.split("@").pop();
+    const resolveTxt = session?.resolveTxt || dnsResolveTxt;
+
+    let rawRecords;
+    try {
+      rawRecords = await resolveTxt(`_email-verification.${domain}`);
+    } catch {
+      return {
+        verified: false,
+        error: `Failed to resolve _email-verification.${domain} DNS TXT record.`,
+      };
+    }
+
+    const records = (rawRecords || [])
+      .map((chunks) => (Array.isArray(chunks) ? chunks.join("") : String(chunks)).trim())
+      .filter((r) => r.startsWith("iss="));
+
+    if (records.length !== 1) {
+      return {
+        verified: false,
+        error: `Invalid or missing _email-verification.${domain} DNS TXT record.`,
+      };
+    }
+
+    const rawIssuer = records[0].slice(4).trim();
+    const expectedIssuerUrl =
+      rawIssuer.startsWith("https://") || rawIssuer.startsWith("http://")
+        ? rawIssuer.replace(/\/+$/, "")
+        : `https://${rawIssuer.replace(/\/+$/, "")}`;
+
+    if (evtClaims.iss !== expectedIssuerUrl) {
+      return {
+        verified: false,
+        error: `EVT issuer "${evtClaims.iss}" does not match DNS delegated issuer "${expectedIssuerUrl}".`,
+      };
+    }
+
+    // -------------------------------------------------------------------------
+    // STEP 5: Discover issuer metadata & verify EVT signature via JWKS
+    // -------------------------------------------------------------------------
+    const fetchFn = session?.fetchImpl || globalThis.fetch;
+    const discoveryUrl = new URL("/.well-known/email-verification", expectedIssuerUrl).toString();
+
+    const metaRes = await fetchFn(discoveryUrl);
+    if (!metaRes || !metaRes.ok) {
+      return {
+        verified: false,
+        error: `Failed to fetch issuer metadata from ${discoveryUrl}.`,
+      };
+    }
+
+    const meta = await metaRes.json();
+    if (meta.issuer && meta.issuer !== expectedIssuerUrl) {
+      return {
+        verified: false,
+        error: "Issuer metadata mismatch in /.well-known/email-verification.",
+      };
+    }
+    if (!meta.jwks_uri) {
+      return {
+        verified: false,
+        error: "Missing jwks_uri in issuer /.well-known/email-verification metadata.",
+      };
+    }
+
+    const verifyOptions = {
+      issuer: expectedIssuerUrl,
+      typ: "evt+jwt",
+      ...(Array.isArray(meta.signing_alg_values_supported) &&
+      meta.signing_alg_values_supported.length > 0
+        ? { algorithms: meta.signing_alg_values_supported }
+        : {}),
+    };
+
+    // Fetch JWKS via fetchFn so custom/mocked fetch implementations and
+    // keys omitting 'kid' work seamlessly, falling back to createRemoteJWKSet
+    const jwksRes = await fetchFn(new URL(meta.jwks_uri).toString());
+    if (jwksRes && jwksRes.ok) {
+      const jwksData = await jwksRes.json();
+      try {
+        const localJwks = createLocalJWKSet(jwksData);
+        await jwtVerify(evtJwt, localJwks, verifyOptions);
+      } catch (localErr) {
+        // Fallback: iterate keys manually in case 'kid' or 'alg' is omitted in JWKS entry
+        if (Array.isArray(jwksData?.keys) && jwksData.keys.length > 0) {
+          let verifiedWithKey = false;
+          let lastKeyErr = localErr;
+          for (const jwkEntry of jwksData.keys) {
+            try {
+              const key = await importJWK(jwkEntry, evtHeader.alg);
+              await jwtVerify(evtJwt, key, verifyOptions);
+              verifiedWithKey = true;
+              break;
+            } catch (err) {
+              lastKeyErr = err;
+            }
+          }
+          if (!verifiedWithKey) {
+            throw lastKeyErr;
+          }
+        } else {
+          throw localErr;
+        }
+      }
+    } else {
+      const remoteJwks = createRemoteJWKSet(new URL(meta.jwks_uri));
+      await jwtVerify(evtJwt, remoteJwks, verifyOptions);
+    }
+
+    return {
+      verified: true,
+      email: evtClaims.email,
+      issuer: expectedIssuerUrl,
+      evtJwtDecodedPayload: evtClaims,
+      kbJwtDecodedPayload: kbClaims,
+    };
+  } catch (err) {
+    return {
+      verified: false,
+      error: err instanceof Error ? err.message : "Email verification token validation failed.",
+    };
+  }
+}
+
+/**
+ * Boolean wrapper around verifyEmailVerificationToken matching the standard
+ * verifyEmailToken(rawToken, submittedEmail, session) signature.
+ */
+export async function verifyEmailToken(rawToken, submittedEmail, session = {}) {
+  const result = await verifyEmailVerificationToken(rawToken, submittedEmail, session);
+  return result.verified;
+}

