+      img: this.shadowRoot.getElementById('card-img'),
+      categoryBadge: this.shadowRoot.getElementById('category-badge'),
+      roastBadge: this.shadowRoot.getElementById('roast-badge'),
+      favBtn: this.shadowRoot.getElementById('fav-btn'),
+      title: this.shadowRoot.getElementById('card-title'),
+      price: this.shadowRoot.getElementById('card-price'),
+      desc: this.shadowRoot.getElementById('card-desc'),
+      notes: this.shadowRoot.getElementById('card-notes'),
+      origin: this.shadowRoot.getElementById('card-origin'),
+      caffeine: this.shadowRoot.getElementById('card-caffeine'),
+      orderBtn: this.shadowRoot.getElementById('order-btn'),
+      detailsLink: this.shadowRoot.getElementById('details-link'),
+    };
+
+    this.#els.favBtn.addEventListener('click', () => {
+      this.favorited = !this.favorited;
+      this.dispatchEvent(
+        new CustomEvent('coffee-favorite', {
+          bubbles: true,
+          composed: true,
+          detail: {
+            name: this.name,
