+    const roast = this.roast;
+    const notes = this.getAttribute('notes') ?? 'Rich cocoa, toasted almond';
+    const origin = this.getAttribute('origin') ?? 'Latin America & East Africa';
+    const caffeine = this.getAttribute('caffeine') ?? '150mg (12 oz)';
+    const href = this.getAttribute('href') ?? '/menu';
+    const image =
+      this.getAttribute('image') ??
+      'https://images.unsplash.com/photo-1509042239860-f550ce710b93?auto=format&fit=crop&w=600&q=80';
