+    this.#els.title.textContent = itemName;
+    this.#els.price.textContent = formattedPrice;
+    this.#els.desc.textContent = this.description;
+    this.#els.categoryBadge.textContent = category;
+    this.#els.roastBadge.textContent = `${roast} Roast`;
+    this.#els.notes.textContent = notes;
+    this.#els.origin.textContent = origin;
+    this.#els.caffeine.textContent = caffeine;
+
+    if (this.#els.img.getAttribute('src') !== image) {
+      this.#els.img.setAttribute('src', image);
+    }
+    this.#els.img.setAttribute('alt', imageAlt);
