+      this.#els.filterBtns.forEach((b) => {
+        b.setAttribute('aria-pressed', String(b.dataset.filter === 'all'));
+      });
+      this.#applyFilters();
+      this.#els.searchInput.focus();
+    });
+
+    this.#els.slot.addEventListener('slotchange', () => {
+      this.#applyFilters(false);
+    });
+
+    this.addEventListener('coffee-favorite', (e) => {
+      const { name, favorited } = e.detail;
+      this.#els.status.textContent = favorited
+        ? `Added ${name} to your saved favorites.`
+        : `Removed ${name} from your saved favorites.`;
+      if (this.#activeFilter === 'favorites') {
