+
+    this.#els = {
+      form: this.shadowRoot.getElementById('brew-form'),
+      method: this.shadowRoot.getElementById('brew-method'),
+      cups: this.shadowRoot.getElementById('cups-range'),
+      cupsDisplay: this.shadowRoot.getElementById('cups-display'),
+      outCoffee: this.shadowRoot.getElementById('out-coffee'),
+      outWater: this.shadowRoot.getElementById('out-water'),
+      outGrind: this.shadowRoot.getElementById('out-grind'),
+      outTime: this.shadowRoot.getElementById('out-time'),
+      outTip: this.shadowRoot.getElementById('out-tip'),
+    };
+
+    this.#els.form.addEventListener('input', () => this.#updateRecipe());
+  }
+
+  connectedCallback() {
+    this.#updateRecipe();
+  }
+
+  #updateRecipe() {
+    const methodKey = this.#els.method.value || 'pour-over';
+    const preset = BREW_PRESETS[methodKey] || BREW_PRESETS['pour-over'];
+    const cups = Number(this.#els.cups.value) || 2;
+    const strengthEl = this.shadowRoot.querySelector('input[name="strength"]:checked');
+    const strength = strengthEl ? strengthEl.value : 'balanced';
+
+    const strengthAdjust = strength === 'bold' ? -1.5 : strength === 'mellow' ? 1.5 : 0;
+    const effectiveRatio = Math.max(6, preset.ratio + strengthAdjust);
+
+    // 1 cup = 177.5 ml (6 fl oz)
+    const waterMl = Math.round(cups * 177.5);
+    const coffeeGrams = Math.round(waterMl / effectiveRatio);
+
+    this.#els.cupsDisplay.textContent = String(cups);
+    this.#els.outCoffee.textContent = `${coffeeGrams}g`;
+    this.#els.outWater.textContent = `${waterMl}ml`;
+    this.#els.outGrind.textContent = preset.grind;
