+
+    this.#els = {
+      visitsSlider: this.shadowRoot.getElementById('visits-slider'),
+      visitsVal: this.shadowRoot.getElementById('visits-val'),
+      reusableCup: this.shadowRoot.getElementById('reusable-cup'),
+      monthlyBeans: this.shadowRoot.getElementById('monthly-beans'),
