+  addItem(coffeeData) {
+    this._checkedOut = false;
+    const key = `${coffeeData.id}-${coffeeData.size || '12oz'}-${coffeeData.customization || 'default'}`;
+    const existing = this._items.find((i) => i.key === key);
+    if (existing) {
+      existing.qty += 1;
+    } else {
+      this._items.push({
+        key,
+        id: coffeeData.id,
+        name: coffeeData.name,
+        size: coffeeData.size || '12oz',
