+/* ==========================================================================
+   Register Custom Elements & Wire Up Page-Level Orchestration
+   ========================================================================== */
+const COMPONENT_REGISTRY = [
+  ['dg-navbar', DgNavbar],
+  ['dg-hero', DgHero],
+  ['dg-coffee-card', DgCoffeeCard],
+  ['dg-coffee-menu', DgCoffeeMenu],
+  ['dg-brew-finder', DgBrewFinder],
+  ['dg-coffee-modal', DgCoffeeModal],
+  ['dg-cart-drawer', DgCartDrawer],
+  ['dg-footer', DgFooter],
+];
+
+COMPONENT_REGISTRY.forEach(([tag, ctor]) => {
+  if (!customElements.get(tag)) {
+    customElements.define(tag, ctor);
+  }
+});
+
+/**
+ * Automatically wire custom element events across the document once ready.
+ */
+function initDailyGrindApp() {
+  const navbar = document.querySelector('dg-navbar');
+  const menu = document.querySelector('dg-coffee-menu');
+  const modal = document.querySelector('dg-coffee-modal');
+  const cartDrawer = document.querySelector('dg-cart-drawer');
+  const toastRegion = document.getElementById('dg-live-toast');
+
+  const announce = (msg) => {
+    if (!toastRegion) return;
+    toastRegion.textContent = msg;
+    toastRegion.classList.add('visible');
+    clearTimeout(toastRegion._hideTimer);
+    toastRegion._hideTimer = setTimeout(() => {
+      toastRegion.classList.remove('visible');
+    }, 2800);
+  };
+
+  document.addEventListener('dg-view-details', (e) => {
+    if (modal && e.detail) {
+      modal.open(e.detail);
+    }
+  });
+
+  document.addEventListener('dg-add-to-cart', (e) => {
+    if (cartDrawer && e.detail) {
+      cartDrawer.addItem(e.detail);
+      announce(`Added ${e.detail.size || '12oz'} ${e.detail.name} to your order bag.`);
+    }
+  });
+
+  document.addEventListener('dg-open-cart', () => {
+    cartDrawer?.open();
+  });
+
+  document.addEventListener('dg-cart-updated', (e) => {
+    if (navbar && e.detail) {
+      navbar.cartCount = e.detail.totalCount;
+    }
+  });
+
+  document.addEventListener('dg-filter-request', (e) => {
+    if (menu && e.detail) {
+      menu.filterByCategory(e.detail.category);
+      menu.scrollIntoView({ behavior: 'smooth', block: 'start' });
+    }
+  });
+}
+
+if (document.readyState === 'loading') {
+  document.addEventListener('DOMContentLoaded', initDailyGrindApp);
+} else {
+  initDailyGrindApp();
+}
+
+export {
+  DgNavbar,
+  DgHero,
+  DgCoffeeCard,
+  DgCoffeeMenu,
+  DgBrewFinder,
+  DgCoffeeModal,
+  DgCartDrawer,
+  DgFooter,
+};
