+  };
+
+  useWebMCP<Record<string, never>, unknown>({
+    name: 'get_current_article_details',
+    description: 'Extract metadata, full text content, word count, reading time, and related articles for the article currently displayed on the page. Use when the user asks questions about or wants a summary of the current article.',
+    inputSchema: EMPTY_SCHEMA,
+    annotations: READONLY_ANNOTATIONS,
+    execute() {
+      const bodyEl = getArticleBodyElement();
+      const bodyText = bodyEl?.innerText?.trim() ?? '';
+      const words = bodyText ? bodyText.split(/\s+/).filter(Boolean).length : 0;
+      const headings = bodyEl
+        ? Array.from(bodyEl.querySelectorAll('h1, h2, h3, h4')).map(h => h.textContent?.trim() ?? '').filter(Boolean)
+        : [];
+      return {
+        slug: article.slug,
+        title: article.title,
+        summary: article.summary,
+        author: article.author,
+        date: article.date,
+        category: article.category,
+        estimatedReadingTimeMinutes: article.readingTime ?? Math.max(1, Math.ceil(words / 200)),
+        wordCount: words,
+        headings,
+        content: bodyText,
+        Bookmarked: isBookmarked,
+        relatedArticles: article.relatedArticles.map(rel => ({
+          ...rel,
+          url: `${import.meta.env.BASE_URL}articles/${rel.slug}`,
+        })),
+      };
+    },
+  });
+
+  useWebMCP<Record<string, never>, unknown>({
+    name: 'bookmark_current_article',
+    description: 'Toggle the bookmark state of the currently viewed article in the user\'s reading list. Use when the user asks to bookmark, save, or unbookmark the current article.',
+    inputSchema: EMPTY_SCHEMA,
+    annotations: MUTATE_ANNOTATIONS,
+    async execute(_input, { signal }) {
+      try {
+        const response = await fetch(`${import.meta.env.BASE_URL}api/reading-list.json`, {
+          method: 'POST',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify({ slug: article.slug }),
+          signal,
+        });
+        if (!response.ok) {
+          return { error: `Failed to update reading list (status ${response.status})` };
+        }
+        const data = await response.json();
+        const updatedList: string[] = Array.isArray(data?.readingList) ? data.readingList : [];
+        const nowBookmarked = updatedList.includes(article.slug);
+        setIsBookmarked(nowBookmarked);
+        window.dispatchEvent(new CustomEvent('reading-list-updated', { detail: { readingList: updatedList } }));
+        setStatusMessage(nowBookmarked ? 'Saved to reading list' : 'Removed from reading list');
+        return {
+          slug: article.slug,
+          title: article.title,
+          action: nowBookmarked ? 'bookmarked' : 'removed',
+          bookmarked: nowBookmarked,
+          readingList: updatedList,
+        };
+      } catch (err) {
+        if (signal.aborted) {
+          throw err;
+        }
+        return { error: err instanceof Error ? err.message : String(err) };
+      }
+    },
+  });
+
+  useWebMCP<Record<string, never>, unknown>({
+    name: 'copy_article_citation',
+    description: 'Generate a formatted citation and canonical link for the current article and copy it to the clipboard if permitted. Use when the user wants to cite, reference, or share a link to the current article.',
+    inputSchema: EMPTY_SCHEMA,
+    annotations: READONLY_ANNOTATIONS,
+    async execute() {
+      const url = typeof window !== 'undefined' ? window.location.href : `${import.meta.env.BASE_URL}articles/${article.slug}`;
+      const citation = `${article.author}. "${article.title}." The DevTools Times, ${article.date}. ${url}`;
+      let copiedToClipboard = false;
+      if (typeof navigator !== 'undefined' && navigator.clipboard?.writeText) {
+        try {
+          await navigator.clipboard.writeText(citation);
+          copiedToClipboard = true;
+        } catch {
+          copiedToClipboard = false;
+        }
+      }
+      setStatusMessage('Citation ready');
+      return {
+        citation,
+        url,
+        title: article.title,
+        author: article.author,
+        date: article.date,
+        copiedToClipboard,
+      };
+    },
+  });
+
+  useWebMCP<{ phrase?: string }, unknown>({
+    name: 'find_in_current_article',
+    description: 'Search for a phrase or keyword within the current article body, return matching excerpts, and scroll the first matching paragraph into view. Use when the user wants to locate specific mentions inside the article.',
+    inputSchema: HIGHLIGHT_SCHEMA,
+    annotations: READONLY_ANNOTATIONS,
+    execute(input) {
+      const phrase = typeof input?.phrase === 'string' ? input.phrase.trim() : '';
+      if (!phrase) {
+        return { error: 'Pass a non-empty phrase to find in the article.' };
+      }
+      const bodyEl = getArticleBodyElement();
+      if (!bodyEl) {
+        return { error: 'Article content element not found on page.' };
+      }
+
+      const blocks = Array.from(bodyEl.querySelectorAll<HTMLElement>('p, li, h2, h3, h4, blockquote'));
+      const lowerPhrase = phrase.toLowerCase();
+      const matchingBlocks: HTMLElement[] = [];
+      const excerpts: string[] = [];
+
+      blocks.forEach(block => {
+        block.style.removeProperty('background-color');
+        block.style.removeProperty('outline');
+        const text = block.innerText || block.textContent || '';
+        if (text.toLowerCase().includes(lowerPhrase)) {
+          matchingBlocks.push(block);
+          excerpts.push(text.trim());
+        }
+      });
+
+      if (matchingBlocks.length > 0) {
+        const first = matchingBlocks[0];
+        first.style.backgroundColor = 'rgba(245, 158, 11, 0.2)';
+        first.style.outline = '2px solid #f59e0b';
+        first.scrollIntoView({ behavior: 'smooth', block: 'center' });
+        setStatusMessage(`Found ${matchingBlocks.length} match${matchingBlocks.length === 1 ? '' : 'es'} for "${phrase}"`);
+      } else {
+        setStatusMessage(`No matches in article for "${phrase}"`);
+      }
+
+      return {
+        phrase,
+        matchCount: matchingBlocks.length,
+        excerpts,
+      };
+    },
+  });
+
+  if (!statusMessage) {
+    return null;
+  }
+
+  return (
+    <div className="text-xs text-amber-800 bg-amber-50 border border-amber-200 rounded px-2.5 py-1 inline-flex items-center gap-2" role="status" aria-live="polite">
+      <span>{statusMessage}</span>
+      <button
+        type="button"
+        onClick={() => setStatusMessage(null)}
+        aria-label="Dismiss status"
+        className="text-amber-700 hover:text-amber-900 font-bold"
+      >
+        ×
+      </button>
+    </div>
+  );
+}
