@@ -0,0 +1,187 @@
+import React, { useState, useEffect } from 'react';
+import { useWebMCP } from 'use-webmcp-tool';
+
+export interface CatalogArticle {
+  slug: string;
+  title: string;
+  summary: string;
+  author: string;
+  date: string;
+  category: string;
+  readingTime?: number;
+  tags?: string[];
+}
+
+interface Props {
+  articles: CatalogArticle[];
+  categories: string[];
+}
+
+const BROWSE_SCHEMA = {
+  type: 'object',
+  properties: {
+    category: {
+      type: 'string',
+      description: 'Category name to filter articles by, e.g., science, lifestyle, sports, Media, Politics.',
+    },
+    query: {
+      type: 'string',
+      description: 'Keyword to filter articles by title, summary, or author.',
+    },
+    sortBy: {
+      type: 'string',
+      enum: ['newest', 'oldest', 'reading_time_asc', 'reading_time_desc'],
+      default: 'newest',
+      description: 'Sort order for the returned articles.',
+    },
+    limit: {
+      type: 'number',
+      minimum: 1,
+      maximum: 50,
+      default: 10,
+      description: 'Maximum number of articles to return.',
+    },
+  },
+} as const;
+
+const DETAILS_BY_SLUG_SCHEMA = {
+  type: 'object',
+  properties: {
+    slug: {
+      type: 'string',
+      description: 'Slug identifier of the article to inspect.',
+    },
+  },
+  required: ['slug'],
+} as const;
+
+const READONLY_ANNOTATIONS = {
+  readOnlyHint: true,
+} as const;
+
+const SORT_ORDERS = ['newest', 'oldest', 'reading_time_asc', 'reading_time_desc'] as const;
+
+export default function GlobalArticleTools({ articles: initialArticles, categories }: Props) {
+  const [articles, setArticles] = useState<CatalogArticle[]>(initialArticles);
+
+  useEffect(() => {
+    if (initialArticles.length > 0) {
+      setArticles(initialArticles);
+    }
+  }, [initialArticles]);
+
+  useWebMCP<
+    {
+      category?: string;
+      query?: string;
+      sortBy?: string;
+      limit?: number;
+    },
+    unknown
+  >({
+    name: 'browse_articles_catalog',
+    description: 'Browse, filter, and sort The DevTools Times article catalog by category, keyword, or reading time. Use when the user wants to explore available articles, filter by section, or find quick reads.',
+    inputSchema: BROWSE_SCHEMA,
+    annotations: READONLY_ANNOTATIONS,
+    execute(input) {
+      const category = typeof input?.category === 'string' ? input.category.trim() : '';
+      const query = typeof input?.query === 'string' ? input.query.trim() : '';
+      const sortBy = typeof input?.sortBy === 'string' ? input.sortBy : 'newest';
+      const limit = typeof input?.limit === 'number' && Number.isFinite(input.limit)
+        ? Math.min(50, Math.max(1, Math.floor(input.limit)))
+        : 10;
+
+      if (!SORT_ORDERS.includes(sortBy as (typeof SORT_ORDERS)[number])) {
+        return {
+          error: `Unsupported sortBy value "${sortBy}".`,
+          supportedSortOrders: SORT_ORDERS,
+        };
+      }
+
+      if (category && !categories.some(c => c.toLowerCase() === category.toLowerCase())) {
+        return {
+          error: `Category "${category}" not found.`,
+          availableCategories: categories,
+        };
+      }
+
+      let filtered = [...articles];
+
+      if (category) {
+        const lowerCat = category.toLowerCase();
+        filtered = filtered.filter(a => a.category.toLowerCase() === lowerCat);
+      }
+
+      if (query) {
+        const lowerQuery = query.toLowerCase();
+        filtered = filtered.filter(
+          a =>
+            a.title.toLowerCase().includes(lowerQuery) ||
+            a.summary.toLowerCase().includes(lowerQuery) ||
+            a.author.toLowerCase().includes(lowerQuery)
+        );
+      }
+
+      filtered.sort((a, b) => {
+        if (sortBy === 'oldest') {
+          return new Date(a.date).getTime() - new Date(b.date).getTime();
+        }
+        if (sortBy === 'reading_time_asc') {
+          return (a.readingTime ?? 5) - (b.readingTime ?? 5);
+        }
+        if (sortBy === 'reading_time_desc') {
+          return (b.readingTime ?? 5) - (a.readingTime ?? 5);
+        }
+        return new Date(b.date).getTime() - new Date(a.date).getTime();
+      });
+
+      const sliced = filtered.slice(0, limit);
+
+      return {
+        totalMatches: filtered.length,
+        returnedCount: sliced.length,
+        availableCategories: categories,
+        articles: sliced.map(a => ({
+          slug: a.slug,
+          title: a.title,
+          summary: a.summary,
+          author: a.author,
+          date: a.date,
+          category: a.category,
+          readingTimeMinutes: a.readingTime ?? 5,
+          url: `${import.meta.env.BASE_URL}articles/${a.slug}`,
+        })),
+      };
+    },
+  });
+
+  useWebMCP<{ slug?: string }, unknown>({
+    name: 'get_article_metadata_by_slug',
+    description: 'Look up metadata, summary, author, category, and reading time for a specific article by its slug. Use when the user asks about a specific article from any page.',
+    inputSchema: DETAILS_BY_SLUG_SCHEMA,
+    annotations: READONLY_ANNOTATIONS,
+    execute(input) {
+      const slug = typeof input?.slug === 'string' ? input.slug.trim() : '';
+      if (!slug) {
+        return {
+          error: 'Pass an article slug.',
+          availableSlugs: articles.map(a => a.slug),
+        };
+      }
+      const found = articles.find(a => a.slug.toLowerCase() === slug.toLowerCase());
+      if (!found) {
+        return {
+          error: `Article "${slug}" not found.`,
+          availableSlugs: articles.map(a => a.slug),
+        };
+      }
+      return {
+        ...found,
+        readingTimeMinutes: found.readingTime ?? 5,
+        url: `${import.meta.env.BASE_URL}articles/${found.slug}`,
+      };
+    },
+  });
+
+  return null;
+}
