+import React, { useState, useEffect } from 'react';
+import {
+  registerModelContextTools,
+  unregisterModelContextTools,
+  type WebMCPToolDefinition,
+} from '../utils/webmcp';
+
+interface ArticleToolsProps {
+  slug: string;
+  title: string;
+  summary: string;
+  author: string;
+  date: string;
+  category: string;
+  readingTime?: number;
+  initialIsBookmarked: boolean;
+}
+
+type FontSize = 'sm' | 'base' | 'lg' | 'xl';
+type ThemeMode = 'light' | 'sepia' | 'dark';
+
+export default function ArticleTools({
+  slug,
+  title,
+  summary,
+  author,
+  date,
+  category,
+  readingTime,
+  initialIsBookmarked,
+}: ArticleToolsProps) {
+  const [fontSize, setFontSize] = useState<FontSize>('base');
+  const [theme, setTheme] = useState<ThemeMode>('light');
+  const [highlightedTerm, setHighlightedTerm] = useState<string>('');
+  const [highlightCount, setHighlightCount] = useState<number>(0);
+  const [isBookmarked, setIsBookmarked] = useState<boolean>(initialIsBookmarked);
+  const [statusMessage, setStatusMessage] = useState<string | null>(null);
+
+  const applyReadingPreferences = (newFontSize?: FontSize, newTheme?: ThemeMode) => {
+    const targetFontSize = newFontSize || fontSize;
+    const targetTheme = newTheme || theme;
+    if (newFontSize) setFontSize(newFontSize);
+    if (newTheme) setTheme(newTheme);
+
+    const proseEl = document.querySelector('article .prose') as HTMLElement | null;
+    const articleEl = document.querySelector('article') as HTMLElement | null;
+
+    if (proseEl) {
+      proseEl.classList.remove('prose-sm', 'prose-base', 'prose-lg', 'prose-xl');
+      proseEl.classList.add(`prose-${targetFontSize}`);
+    }
+
+    if (articleEl) {
+      articleEl.classList.remove(
+        'bg-white',
+        'bg-amber-50',
+        'bg-gray-900',
+        'text-gray-900',
+        'text-amber-950',
+        'text-gray-100',
+        'rounded-lg',
+        'transition-colors'
+      );
+      if (targetTheme === 'sepia') {
+        articleEl.classList.add('bg-amber-50', 'text-amber-950', 'rounded-lg', 'transition-colors');
+        if (proseEl) proseEl.classList.remove('prose-invert');
+      } else if (targetTheme === 'dark') {
+        articleEl.classList.add('bg-gray-900', 'text-gray-100', 'rounded-lg', 'transition-colors');
+        if (proseEl) proseEl.classList.add('prose-invert');
+      } else {
+        articleEl.classList.add('bg-white', 'text-gray-900', 'transition-colors');
+        if (proseEl) proseEl.classList.remove('prose-invert');
+      }
+    }
+
+    return { fontSize: targetFontSize, theme: targetTheme };
+  };
+
+  const clearHighlightsInDom = () => {
+    const proseEl = document.querySelector('article .prose');
+    if (!proseEl) return;
+    const marks = proseEl.querySelectorAll('mark[data-webmcp-highlight]');
+    marks.forEach((mark) => {
+      const parent = mark.parentNode;
+      if (parent) {
+        parent.replaceChild(document.createTextNode(mark.textContent || ''), mark);
+        parent.normalize();
+      }
+    });
+  };
+
+  const highlightTextInDom = (term: string): number => {
+    clearHighlightsInDom();
+    const trimmed = term.trim();
+    if (!trimmed) {
+      setHighlightedTerm('');
+      setHighlightCount(0);
+      return 0;
+    }
+
+    const proseEl = document.querySelector('article .prose');
+    if (!proseEl) return 0;
+
+    const escaped = trimmed.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
+    const regex = new RegExp(`(${escaped})`, 'gi');
+    let matchCount = 0;
+
+    const walker = document.createTreeWalker(proseEl, NodeFilter.SHOW_TEXT, {
+      acceptNode(node) {
+        if (!node.parentElement) return NodeFilter.FILTER_REJECT;
+        const tag = node.parentElement.tagName.toLowerCase();
+        if (tag === 'script' || tag === 'style' || tag === 'mark') {
+          return NodeFilter.FILTER_REJECT;
+        }
+        return regex.test(node.textContent || '')
+          ? NodeFilter.FILTER_ACCEPT
+          : NodeFilter.FILTER_SKIP;
+      },
+    });
+
+    const textNodes: Text[] = [];
+    let currentNode = walker.nextNode();
+    while (currentNode) {
+      textNodes.push(currentNode as Text);
+      currentNode = walker.nextNode();
+    }
+
+    textNodes.forEach((textNode) => {
+      const text = textNode.textContent || '';
+      const parts = text.split(regex);
+      if (parts.length > 1 && textNode.parentNode) {
+        const fragment = document.createDocumentFragment();
+        parts.forEach((part) => {
+          if (part.toLowerCase() === trimmed.toLowerCase()) {
+            const mark = document.createElement('mark');
+            mark.setAttribute('data-webmcp-highlight', 'true');
+            mark.className = 'bg-amber-300 text-gray-900 px-0.5 rounded';
+            mark.textContent = part;
+            fragment.appendChild(mark);
+            matchCount++;
+          } else if (part) {
+            fragment.appendChild(document.createTextNode(part));
+          }
+        });
+        textNode.parentNode.replaceChild(fragment, textNode);
+      }
+    });
+
+    setHighlightedTerm(trimmed);
+    setHighlightCount(matchCount);
+    return matchCount;
+  };
+
+  const getArticleStatsAndContent = () => {
+    const proseEl = document.querySelector('article .prose');
+    const bodyText = proseEl ? (proseEl.textContent || '').trim() : '';
+    const words = bodyText ? bodyText.split(/\s+/).filter(Boolean) : [];
+    const wordCount = words.length;
+    const characterCount = bodyText.length;
+    const headings = proseEl
+      ? Array.from(proseEl.querySelectorAll('h1, h2, h3, h4')).map((h) => (h.textContent || '').trim())
+      : [];
+    const calculatedReadingTimeMinutes = Math.max(1, Math.ceil(wordCount / 200));
+
+    return {
+      slug,
+      title,
+      summary,
+      author,
+      date,
+      category,
+      wordCount,
+      characterCount,
+      estimatedReadingTimeMinutes: readingTime || calculatedReadingTimeMinutes,
+      calculatedReadingTimeMinutes,
+      headings,
+      content: bodyText,
+      url: window.location.href,
+    };
+  };
+
+  const copyCitation = async (format: 'apa' | 'mla' | 'chicago' | 'markdown' | 'url' = 'apa') => {
+    const url = window.location.href;
+    const pubYear = new Date(date).getFullYear() || new Date().getFullYear();
+    let citation = '';
+
+    switch (format) {
+      case 'mla':
+        citation = `${author}. "${title}." The DevTools Times, ${date}, ${url}.`;
+        break;
+      case 'chicago':
+        citation = `${author}. "${title}." The DevTools Times (${date}). ${url}.`;
+        break;
+      case 'markdown':
+        citation = `[${title}](${url}) by ${author} (${date}) — ${summary}`;
+        break;
+      case 'url':
+        citation = url;
+        break;
+      case 'apa':
+      default:
+        citation = `${author}. (${pubYear}). ${title}. The DevTools Times. Retrieved from ${url}`;
+        break;
+    }
+
+    try {
+      if (navigator.clipboard && navigator.clipboard.writeText) {
+        await navigator.clipboard.writeText(citation);
+      }
+    } catch {
+      // Clipboard API may fail without user gesture in some contexts
+    }
+
+    setStatusMessage(`Copied ${format.toUpperCase()} citation`);
+    setTimeout(() => setStatusMessage(null), 3000);
+    return { format, citation, url };
+  };
+
+  const toggleArticleBookmark = async () => {
+    const response = await fetch(`${import.meta.env.BASE_URL}api/reading-list.json`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ slug }),
+    });
+    const data = await response.json();
+    const bookmarked = (data.readingList || []).includes(slug);
+    setIsBookmarked(bookmarked);
+    window.dispatchEvent(
+      new CustomEvent('reading-list-updated', { detail: { readingList: data.readingList } })
+    );
+    return {
+      slug,
+      isBookmarked: bookmarked,
+      readingList: data.readingList,
+    };
+  };
+
+  useEffect(() => {
+    const handleSync = (e: Event) => {
+      const customEvent = e as CustomEvent<{ readingList?: string[] }>;
+      if (customEvent.detail?.readingList) {
+        setIsBookmarked(customEvent.detail.readingList.includes(slug));
+      }
+    };
+    window.addEventListener('reading-list-updated', handleSync);
+    return () => window.removeEventListener('reading-list-updated', handleSync);
+  }, [slug]);
+
+  useEffect(() => {
+    const tools: WebMCPToolDefinition[] = [
+      {
+        name: 'get_current_article_details',
+        title: 'Get Current Article Details & Metrics',
+        description:
+          'Extract full text content, metadata (title, author, date, category, summary), section headings, word count, and reading time metrics for the current article.',
+        inputSchema: {
+          type: 'object',
+          properties: {
+            includeFullText: {
+              type: 'boolean',
+              description: 'Whether to include the full plain-text body of the article (default: true).',
+            },
+          },
+        },
+        annotations: { readOnlyHint: true },
+        execute: async (args: { includeFullText?: boolean } = {}) => {
+          const stats = getArticleStatsAndContent();
+          if (args.includeFullText === false) {
+            const { content, ...rest } = stats;
+            return rest;
+          }
+          return stats;
+        },
+      },
+      {
+        name: 'highlight_article_text',
+        title: 'Highlight Text in Article',
+        description:
+          'Highlight all occurrences of a keyword or phrase within the current article body, or clear existing highlights if an empty query is provided.',
+        inputSchema: {
+          type: 'object',
+          properties: {
+            term: {
+              type: 'string',
+              description: 'The keyword or phrase to highlight in the article text. Pass an empty string to clear highlights.',
+            },
+          },
+          required: ['term'],
+        },
+        execute: async ({ term }: { term: string }) => {
+          const matches = highlightTextInDom(term || '');
+          return {
+            term,
+            matchesHighlighted: matches,
+            message: term
+              ? `Highlighted ${matches} occurrence(s) of "${term}".`
+              : 'Cleared all highlights in the article.',
+          };
+        },
+      },
+      {
+        name: 'set_article_reading_preferences',
+        title: 'Set Article Reading Preferences',
+        description:
+          'Adjust the client-side typography font size (sm, base, lg, xl) and color theme (light, sepia, dark) of the current article view.',
+        inputSchema: {
+          type: 'object',
+          properties: {
+            fontSize: {
+              type: 'string',
+              enum: ['sm', 'base', 'lg', 'xl'],
+              description: 'Font size scale for the article body.',
+            },
+            theme: {
+              type: 'string',
+              enum: ['light', 'sepia', 'dark'],
+              description: 'Color theme for reading the article.',
+            },
+          },
+        },
+        execute: async ({ fontSize: fs, theme: th }: { fontSize?: FontSize; theme?: ThemeMode }) => {
+          const updated = applyReadingPreferences(fs, th);
+          return {
+            status: 'updated',
+            preferences: updated,
+          };
+        },
+      },
+      {
+        name: 'cite_or_share_article',
+        title: 'Cite or Share Current Article',
+        description:
+          'Generate a formatted citation (APA, MLA, Chicago, Markdown, or direct URL) for the current article and copy it to the clipboard.',
+        inputSchema: {
+          type: 'object',
+          properties: {
+            format: {
+              type: 'string',
+              enum: ['apa', 'mla', 'chicago', 'markdown', 'url'],
+              description: 'The citation or share format to generate (default: "apa").',
+            },
+          },
+        },
+        execute: async ({ format = 'apa' }: { format?: 'apa' | 'mla' | 'chicago' | 'markdown' | 'url' } = {}) => {
+          return await copyCitation(format);
+        },
+      },
+      {
+        name: 'bookmark_current_article',
+        title: 'Bookmark Current Article',
+        description:
+          'Toggle the current article in the user reading list (add if not bookmarked, or remove if already bookmarked).',
+        inputSchema: {
+          type: 'object',
+          properties: {},
+        },
+        execute: async () => {
+          return await toggleArticleBookmark();
+        },
+      },
+    ];
+
+    registerModelContextTools(tools);
+    return () => {
+      unregisterModelContextTools(tools.map((t) => t.name));
+    };
+  }, [slug, title, summary, author, date, category, readingTime, fontSize, theme]);
+
+  return (
+    <div
+      className="bg-gray-50 border border-gray-200 rounded-md p-3 mb-6 text-xs text-gray-700 flex flex-wrap items-center justify-between gap-3"
+      aria-label="Article Client Utilities"
+    >
+      <div className="flex flex-wrap items-center gap-2">
+        <span className="font-semibold text-gray-800">Reader Utilities:</span>
+        <div className="inline-flex rounded border border-gray-300 bg-white overflow-hidden">
+          {(['sm', 'base', 'lg', 'xl'] as FontSize[]).map((size) => (
+            <button
+              key={size}
+              type="button"
+              onClick={() => applyReadingPreferences(size, undefined)}
+              className={`px-2 py-1 uppercase font-medium transition-colors ${
+                fontSize === size ? 'bg-amber-400 text-gray-900' : 'text-gray-600 hover:bg-gray-100'
+              }`}
+              title={`Set font size to ${size}`}
+            >
+              {size}
+            </button>
+          ))}
+        </div>
+
+        <div className="inline-flex rounded border border-gray-300 bg-white overflow-hidden">
+          {(['light', 'sepia', 'dark'] as ThemeMode[]).map((mode) => (
+            <button
+              key={mode}
+              type="button"
+              onClick={() => applyReadingPreferences(undefined, mode)}
+              className={`px-2 py-1 capitalize font-medium transition-colors ${
+                theme === mode ? 'bg-amber-400 text-gray-900' : 'text-gray-600 hover:bg-gray-100'
+              }`}
+              title={`Set reading theme to ${mode}`}
+            >
+              {mode}
+            </button>
+          ))}
+        </div>
+
+        <button
+          type="button"
+          onClick={() => copyCitation('apa')}
+          className="px-2.5 py-1 rounded border border-gray-300 bg-white hover:bg-gray-100 font-medium text-gray-700"
+        >
+          Cite (APA)
+        </button>
+      </div>
+
+      <form
+        toolname="highlight_in_article_form"
+        tooldescription="Highlight matching keywords or phrases within the current article text."
+        toolautosubmit="true"
+        onSubmit={(e) => {
+          e.preventDefault();
+          const nativeEvent = e.nativeEvent as SubmitEvent;
+          const formData = new FormData(e.currentTarget);
+          const term = String(formData.get('term') ?? highlightedTerm).trim();
+          const count = highlightTextInDom(term);
+          if (nativeEvent.agentInvoked && typeof nativeEvent.respondWith === 'function') {
+            nativeEvent.respondWith(
+              Promise.resolve({
+                term,
+                matchesHighlighted: count,
+              })
+            );
+          }
+        }}
+        className="flex items-center gap-1.5"
+      >
+        <input
+          type="text"
+          name="term"
+          placeholder="Highlight in article..."
+          toolparamdescription="Keyword or phrase to highlight in the current article body"
+          value={highlightedTerm}
+          onChange={(e) => {
+            setHighlightedTerm(e.target.value);
+            highlightTextInDom(e.target.value);
+          }}
+          className="px-2 py-1 border border-gray-300 rounded bg-white text-gray-800 focus:outline-none focus:ring-1 focus:ring-amber-400"
+        />
+        {highlightedTerm && (
+          <span className="text-gray-500 font-medium">
+            {highlightCount} {highlightCount === 1 ? 'match' : 'matches'}
+          </span>
+        )}
+      </form>
+
+      {statusMessage && (
+        <span className="text-amber-700 font-medium" role="status">
+          {statusMessage}
+        </span>
+      )}
+    </div>
+  );
+}
