+export interface WebMCPToolDefinition {
+  name: string;
+  title?: string;
+  description: string;
+  inputSchema?: Record<string, any>;
+  annotations?: {
+    readOnlyHint?: boolean;
+    destructiveHint?: boolean;
+    idempotentHint?: boolean;
+    openWorldHint?: boolean;
+  };
+  execute: (args: any, client?: any) => Promise<any> | any;
+}
+
+export interface ModelContextInterface {
+  registerTool?: (tool: WebMCPToolDefinition, options?: { signal?: AbortSignal }) => Promise<void> | void;
+  unregisterTool?: (name: string) => Promise<void> | void;
+  provideContext?: (context: { tools: WebMCPToolDefinition[] }) => Promise<void> | void;
+  clearContext?: () => Promise<void> | void;
+  getTools?: () => Promise<WebMCPToolDefinition[]> | WebMCPToolDefinition[];
+  executeTool?: (nameOrTool: string | WebMCPToolDefinition, args?: any) => Promise<any>;
+}
+
+const activeToolsRegistry = new Map<string, WebMCPToolDefinition>();
+const activeControllers = new Map<string, AbortController>();
+
+function createFallbackModelContext(): ModelContextInterface {
+  return {
+    registerTool(tool: WebMCPToolDefinition, options?: { signal?: AbortSignal }) {
+      activeToolsRegistry.set(tool.name, tool);
+      if (options?.signal) {
+        options.signal.addEventListener('abort', () => {
+          activeToolsRegistry.delete(tool.name);
+        });
+      }
+    },
+    unregisterTool(name: string) {
+      activeToolsRegistry.delete(name);
+    },
+    provideContext(context: { tools: WebMCPToolDefinition[] }) {
+      activeToolsRegistry.clear();
+      if (Array.isArray(context?.tools)) {
+        for (const tool of context.tools) {
+          activeToolsRegistry.set(tool.name, tool);
+        }
+      }
+    },
+    clearContext() {
+      activeToolsRegistry.clear();
+    },
+    getTools() {
+      return Array.from(activeToolsRegistry.values());
+    },
+    async executeTool(nameOrTool: string | WebMCPToolDefinition, args: any = {}) {
+      const name = typeof nameOrTool === 'string' ? nameOrTool : nameOrTool?.name;
+      const tool = activeToolsRegistry.get(name);
+      if (!tool) {
+        throw new Error(`Tool "${name}" is not registered.`);
+      }
+      return await tool.execute(args);
+    },
+  };
+}
+
+export function getModelContextTargets(): ModelContextInterface[] {
+  if (typeof window === 'undefined') return [];
+
+  const targets: ModelContextInterface[] = [];
+  const nav = window.navigator as Navigator & { modelContext?: ModelContextInterface };
+  const doc = window.document as Document & { modelContext?: ModelContextInterface };
+
+  if (nav.modelContext) {
+    targets.push(nav.modelContext);
+  }
+  if (doc.modelContext && doc.modelContext !== nav.modelContext) {
+    targets.push(doc.modelContext);
+  }
+
+  if (targets.length === 0) {
+    const fallback = createFallbackModelContext();
+    try {
+      Object.defineProperty(nav, 'modelContext', {
+        value: fallback,
+        writable: true,
+        configurable: true,
+      });
+    } catch {
+      (nav as any).modelContext = fallback;
+    }
+    try {
+      Object.defineProperty(doc, 'modelContext', {
+        value: fallback,
+        writable: true,
+        configurable: true,
+      });
+    } catch {
+      (doc as any).modelContext = fallback;
+    }
+    targets.push(fallback);
+  }
+
+  return targets;
+}
+
+export function registerModelContextTools(tools: WebMCPToolDefinition[]): void {
+  if (typeof window === 'undefined') return;
+  const targets = getModelContextTargets();
+
+  for (const tool of tools) {
+    // Abort any previous controller for the same tool name to avoid duplicate registration errors
+    const prevController = activeControllers.get(tool.name);
+    if (prevController) {
+      prevController.abort();
+      activeControllers.delete(tool.name);
+    }
+
+    const controller = new AbortController();
+    activeControllers.set(tool.name, controller);
+    activeToolsRegistry.set(tool.name, tool);
+
+    for (const target of targets) {
+      try {
+        if (typeof target.unregisterTool === 'function') {
+          try {
+            target.unregisterTool(tool.name);
+          } catch {
+            // Ignore if not previously registered
+          }
+        }
+        if (typeof target.registerTool === 'function') {
+          target.registerTool(tool, { signal: controller.signal });
+        }
+      } catch (err) {
+        console.warn(`WebMCP: Failed to register tool "${tool.name}":`, err);
+      }
+    }
+  }
+}
+
+export function unregisterModelContextTools(toolNames: string[]): void {
+  if (typeof window === 'undefined') return;
+  const targets = getModelContextTargets();
+
+  for (const name of toolNames) {
+    const controller = activeControllers.get(name);
+    if (controller) {
+      controller.abort();
+      activeControllers.delete(name);
+    }
+    activeToolsRegistry.delete(name);
+
+    for (const target of targets) {
+      try {
+        if (typeof target.unregisterTool === 'function') {
+          target.unregisterTool(name);
+        }
+      } catch {
+        // Ignore if already unregistered
+      }
+    }
+  }
+}
+
+export function getRegisteredTools(): WebMCPToolDefinition[] {
+  return Array.from(activeToolsRegistry.values());
+}
